/* ÇEVİRİ sq · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("sq","olay",{
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemia e murtajës në Stamboll dhe zhvendosja e sarajit në Edrene", "70c7a163"], "d": ["Sipas zërit 'Stamboll' të Enciklopedisë së Islamit të TDV-së, popullimi i shpejtë dhe i dendur i qytetit herë pas here përgatiti terrenin për përhapjen e sëmundjeve epidemike; gjatë epidemisë së murtajës së vitit 1466, saraji dhe dinjitarët e shtetit u tërhoqën përkohësisht në Edrene. Popullsia e qytetit pësoi humbje serioze në epidemi të tilla.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasani i jep fund Shtetit Karakojunlu", "ef68399e"], "d": ["Sipas zërit për Uzun Hasanin në Enciklopedinë Islame të TDV-së, sundimtari akkojunlu Uzun Hasani e mundi dhe e vrau sundimtarin karakojunlu Xhihan Shahun në krahinën Bingöl-Sancak më 12 rebiulahir 872 / 10 nëntor 1467; djali i Xhihan Shahut, Hasan Aliu, u mund në Merend në shtator 1468, u vra para Hemedanit në prill-maj 1469, dhe Shtetit Karakojunlu iu dha fund përfundimisht. Tokat kaluan nën sundimin akkojunlu; në dhjetëvjeçarin pasues shteti do të zgjerohej deri në brendësi të Iranit.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Hapja për mësim e medreseve Sahn-i Seman", "021f2a83"], "d": ["Sipas zërit 'Sahn-i Seman' të Enciklopedisë së Islamit të TDV-së, këto tetë medrese, të krijuara në kuadër të kompleksit (kylie) të Fatihut, u projektuan si institucioni arsimor i nivelit më të lartë të kohës dhe përbënë majën e hierarkisë së ilmijes osmane. Të qenit myderris dhe diplomimi prej këtej, në shekujt pasues u konsideruan shkalla më prestigjioze e karrierës si kadi e myderris.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Përfundimi i Sarajit Topkapë (Saraj-i Xhedid)", "d2db6323"], "d": ["Sipas zërit 'Saraji Topkapë' të Enciklopedisë së Islamit të TDV-së, burimet e kohës ndryshojnë për datat e fillimit dhe përfundimit të ndërtimit; sipas datës 883 (1478) në mbishkrimin e Bab-i Humajunit, ndërtimi, i nisur me urdhër të Fatihut ndoshta më 1465, deri në këtë vit ishte përfunduar në masë të madhe dhe saraji zuri vendin e qendrës shtetërore në sarajin e vjetër. Kështu padishahu u shpërngul në rezidencën e re, që për tri shekuj do të ishte zemra administrative dhe ceremoniale e shtetit.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Hipja në fron e Bajazitit II në Stamboll", "9b686d04"], "d": ["Sipas zërit 'Bajaziti II' të Enciklopedisë së Islamit të TDV-së, shehzade Bajaziti, sanxhakbe i Amasjas, me lajmin e vdekjes së të atit erdhi shpejt në Stamboll dhe hipi në fron; me mbështetjen e jeniçerëve ia kaloi nisjes së vëllait të tij Xhemit nga Konja. Gjatë hipjes në fron jeniçerëve iu shpërnda bakshishi i zakonshëm i hipjes në fron (xhulus bahshishi). Ky ndryshim në fron ndezi edhe fitilin e luftës mes dy vëllezërve.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Xhem Sulltani shpall veten sulltan në Bursë", "b355168a"], "d": ["Sipas zërit 'Xhem Sulltan' të Enciklopedisë së Islamit të TDV-së, Xhemi, që arriti në Bursë përmes Karamanit, shtiu në dorë qytetin, e shpalli veten sulltan dhe urdhëroi të lexohej hytbeja në emrin e tij. Ky sundim i shkurtër mori fund kur forcat e dërguara nga vëllai i madh Bajaziti II e mundën Xhemin në Jenishehir. Pas disfatës, Xhemi u detyrua të ikte drejt Egjiptit.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Ekzekutimi i Gedik Ahmet Pashës", "6d75a58c"], "d": ["Sipas zërit 'Gedik Ahmet Pasha' të Enciklopedisë së Islamit të TDV-së, pashai, i njohur për fushatën e Otrantos dhe për postin e vezirit të madh, për shkak të qëndrimit në çështjen e Xhem Sulltanit dhe shqetësimit për ndikimin e tij, u ekzekutua në Edrene me urdhër të Bajazitit II. Vdekja e një prej komandantëve më me përvojë të kohës së Fatihut pati jehonë të gjerë në saraj.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Krijimi i shtypshkronjës së parë në Stamboll", "04475930"], "d": ["Sipas zërit 'Shtypshkronja' (Matbaa) të Enciklopedisë së Islamit të TDV-së, vëllezërit David dhe Samuel ibn Nahmias, emigrantë hebrenj të ardhur nga Spanja, themeluan në Stamboll shtypshkronjën e parë që shtypte me shkronja hebraike. Kjo u shënua si nisma e parë e një shtypshkronje që vepronte në tokat osmane; ndërsa shtypja në turqisht me shkronja arabe do të bëhej e mundur shumë më vonë, në shekullin XVIII.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Shah Ismaili merr Tabrizin: themelimi i Shtetit Safavid", "014d81e6"], "d": ["Sipas zërave për safavidët dhe akkojunlutë në Enciklopedinë Islame të TDV-së, shehu i ri i teqesë së Erdebilit, Ismaili, me ushtrinë që krijoi nga muridët kizilbashë të Anadollit, i shkaktoi sulltanit akkojunlu Elvendit një disfatë të rëndë në krahinën e Nahçivanit; Elvendi iku në Dijarbekir, Ismaili hyri në Tabriz, hipi në fron dhe e shpalli shiizmin e dymbëdhjetë imamëve medhheb zyrtar. Kështu u mbyllën si sundimi akkojunlu, ashtu edhe periudha e bejliqeve pas-ilhanide të rajonit; u themelua Shteti Safavid, që do të zgjaste tre shekuj.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Tërmeti i 'Kiametit të Vogël' në Stamboll", "53e3b1d6"], "d": ["Sipas zërit 'Stamboll' të Enciklopedisë së Islamit të TDV-së, tërmeti i fortë që goditi qytetin, në kohën e vet u përmend në popull si 'Kiameti i Vogël'; pati dëme të rënda në mure, xhami e shumë ndërtesa dhe humbje të shumta jetësh. Me urdhër të Bajazitit II, në qytet u nis një mobilizim i gjerë për riparime e ndërtime.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Fillimi i kryengritjes së Shahkulut", "3d9a4a90"], "d": ["Sipas zërit 'Shahkulu Baba Tekeli' të Enciklopedisë së Islamit të TDV-së, Shahkulu, i ushqyer nga propaganda safavide, në viset e Tekes mblodhi rreth vetes një masë të gjerë turkmene dhe nisi një kryengritje të madhe me karakter fetaro-shoqëror. Kryengritja, si një nga krizat më serioze të sigurisë së brendshme të kohës, e tronditi thellë autoritetin qendror të shtetit.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Vdekja e Bajazitit II në rrugën për Dimotikë", "c46e98c9"], "d": ["Padishahu i mëparshëm, që pasi hoqi dorë nga froni u largua nga Stambolli për të shkuar në qytetin e lindjes, Dimotikë, duke udhëtuar me një vig-karrocë (tahtërevan) që mundte të bënte vetëm 5-6 km në ditë, u sëmur në fshatin Abalar pranë Çorlusë dhe vdiq më 25 rebiulevel 918 (10 qershor 1512). Enciklopedia e Islamit e TDV-së e konsideron shumë të dyshimtë shkakun e vdekjes; sipas disa burimeve vendëse e të huaja, trajtohet mundësia që të ketë qenë helmuar. Kështu, pas një sundimi tridhjetë e një vjeçar, humbi jetën padishahu i tetë nga prejardhja e Osman Gaziut.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Ekzekutimi i shehzade Ahmetit me urdhër të Selimit Javuz", "65abb2f2"], "d": ["Sipas zërit 'Selimi I' të Enciklopedisë së Islamit të TDV-së, shehzade Ahmeti, i preferuari i të atit Bajazitit II dhe rivali kryesor për fronin, në luftën që nisi pas hipjes në fron të vëllait Selim u thye në fushën e Jenishehirit dhe, teksa ikte nga fusha e betejës, u kap dhe u vra. Me këtë ngjarje, Selimi i dha fund në masë të madhe rivalitetit për fron mes vëllezërve dhe nipërve të tij.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Ibrahim Pasha u emërua vezir i madh", "9c94c1e3"], "d": ["Sipas zërit 'Ibrahim Pasha, Makbul' të Enciklopedisë së Islamit të TDV-së, Ibrahim Pasha, i ngritur nga posti i has odabashit te bejlerbejllëku i Rumelisë dhe po atë ditë te posti i vezirit të madh, u bë sadrazam më 13 shaban 929 (27 qershor 1523). Ky ishte një emërim i paparë, me kalim drejtpërdrejt nga shërbimi i sarajit në postin e vezirit të madh, dhe tregonte afërsinë e jashtëzakonshme të Ibrahim Pashës me Sulejmanin Ligjvënës.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hajredin Pasha u emërua kapudan pasha", "a0ff6bab"], "d": ["Sipas zërit 'Barbaros Hajredin Pasha' të Enciklopedisë së Islamit të TDV-së, Hajredin Pasha, i njohur për sukseset në Algjeri, më 6 prill 1534 u thirr në Stamboll dhe u emërua kapudan pasha dhe bejlerbe i Ishujve të Detit të Mesëm (Cezayir-i Bahr-i Sefid). Ky emërim konsiderohet fillimi i riorganizimit të flotës osmane dhe i institucionalizimit të fuqisë detare në Mesdhe.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rustem Pasha u bë për herë të parë vezir i madh", "ddfcc014"], "d": ["Sipas zërit 'Rustem Pasha' të Enciklopedisë së Islamit të TDV-së, pasi Hadëm Sulejman Pasha u shkarkua për shkak të një mosmarrëveshjeje me një vezir, më 17 ramazan 951 (2 dhjetor 1544) Rustem Pasha u emërua vezir i madh. Rustem Pasha, afërsia e të cilit me sarajin u rrit falë martesës me Mihrimah Sulltanin, me këtë detyrë u bë një nga burrat e shtetit më me ndikim të kohës së Sulejmanit Ligjvënës.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebussuud Efendiu u bë shejhulislam", "11ed04f8"], "d": ["Sipas zërit 'Ebussuud Efendi' të Enciklopedisë së Islamit të TDV-së, Ebussuud Efendiu, që për tetë vjet kishte qenë kazasker i Rumelisë, në shaban 952 (tetor 1545) u emërua shejhulislam dhe në këtë detyrë qëndroi njëzet e tetë vjet e njëmbëdhjetë muaj. Ebussuud Efendiu, i njohur për fetvatë që i përshtatën kanunnametë e Sulejmanit Ligjvënës me të drejtën sheriatike, luajti rol vendimtar në formësimin e institucioneve juridike dhe arsimore të kohës së vet.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Vdiq Barbaros Hajredin Pasha", "3378a0bf"], "d": ["Sipas zërit 'Barbaros Hajredin Pasha' të Enciklopedisë së Islamit të TDV-së, pas një sëmundjeje të shkurtër, më 6 xhumadelula 953 (5 korrik 1546) vdiq në Stamboll. Vdekja e Barbarosit, i varrosur në tyrben ngjitur me medresenë që kishte ndërtuar vetë në Beshiktash, u pa si mbyllja e një epoke në epërsinë mesdhetare që kishte ngritur flota osmane.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Filloi ndërtimi i xhamisë Sulejmanije dhe i kompleksit të saj", "101ec36f"], "d": ["Sipas zërit 'Xhamia dhe kompleksi Sulejmanije' të Enciklopedisë së Islamit të TDV-së, kompleksi, themeli i të cilit u hodh më 1550 nën drejtimin e kryearkitektit Mimar Sinan, u projektua si një kompleks i madh shoqëror, i përbërë, pranë xhamisë, nga medrese, spital (darushshifa), imaret dhe bibliotekë. Ndërtimi ishte një nga programet më të mëdha ndërtimore që simbolizonin fuqinë e sundimit të Sulejmanit Ligjvënës dhe zhvillimin urban të Stambollit.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Filloi një valë e re murtaje në Stamboll dhe rrethinat", "547d6bf6"], "d": ["Sipas zërit 'Taun' (murtaja) të Enciklopedisë së Islamit të TDV-së, një nga epidemitë e shekullit XVI që goditën botën islame u përjetua në vitet 1552-1566 dhe pati efekt veçanërisht në Stamboll, Anadoll, Rumeli, Egjipt dhe Afrikën Veriore. Rrugët tregtare në zgjerim dhe lëvizshmëria në rritje e popullsisë përmenden mes faktorëve që e lehtësuan përhapjen e sëmundjeve epidemike në periudhën më të fuqishme të perandorisë.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmet Pasha u emërua vezir i madh", "a7d7748e"], "d": ["Sipas zërit 'Kara Ahmet Pasha' të Enciklopedisë së Islamit të TDV-së, Kara Ahmet Pasha, që shërbente si vezir i dytë, pas shkarkimit të befasishëm të vezirit të madh në detyrë, më 27 sheval 960 (5 tetor 1553) u ngrit në postin e vezirit të madh. Ky ndryshim përkon me të njëjtat ditë të ekzekutimit të shehzade Mustafait dhe shënon një periudhë kur ekuilibrat e pushtetit brenda sarajit ndryshonin shpejt duar.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["U ekzekutua kapedani i flotës Piri Reis", "3b2ad7a0"], "d": ["Sipas zërit 'Piri Reis' të Enciklopedisë së Islamit të TDV-së, kur në Egjipt arritën akuzat se, teksa hiqte rrethimin e Hormuzit, në këmbim të ryshfetit kishte plaçkitur pasuritë e myslimanëve dhe e kishte braktisur ushtrinë në fushën e betejës, detari dhe hartografi i famshëm u ekzekutua në Kajro në fund të vitit 960 (fundi i vitit 1553). Vdekja e Piri Reisit, pasuria e të cilit u konfiskua, vlerësohet si pasojë e rivalitetit mes pashallarëve në politikën detare të kohës në Basrë dhe në Oqeanin Indian.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pasha u ekzekutua, Rustem Pasha u bë sërish vezir i madh", "9a85076a"], "d": ["Sipas zërave për Rustem Pashën dhe Kara Ahmed Pashën në Enciklopedinë Islame të TDV-së, në vend të Kara Ahmed Pashës, i cili u ekzekutua papritur gjatë mbledhjes së divanit më 13 dhulkade 962 (29 shtator 1555), me mbështetjen e Hyrrem dhe Mihrimah Sulltaneve, po atë ditë Rustem Pasha u emërua për herë të dytë vezir i madh. Prapaskena e ngjarjes është lënë e paqartë në burime dhe vlerësohet se ajo ishte pasojë e intrigave të pallatit.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Vdiq Hyrrem Sulltan", "1ae998b5"], "d": ["Sipas zërit për Hyrrem Sulltanen në Enciklopedinë Islame të TDV-së, Hyrrem Sulltan, e cila si haseki sulltane e Kanuniut kishte gëzuar për vite të tëra ndikim të madh në pallat, vdiq në Stamboll më 26 xhemaziulahir 965 (15 prill 1558) dhe u varros në tyrben e saj në kompleksin e Xhamisë Sulejmanije. Vdekja e Hyrrem Sulltanes, e cila pas vdekjes së Valide Sulltan Hafsës më 1534 e kishte forcuar autoritetin e saj mbi haremin, zhduku edhe faktorin balancues që pengonte rivalitetin për fron mes bijve të saj, Bajazitit dhe Selimit.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Mehmet Pashë Sokoli u ngrit në postin e vezirit të madh", "896391a2"], "d": ["Sipas zërit për Mehmet Pashë Sokolin në Enciklopedinë Islame të TDV-së, pas vdekjes së Semiz Ali Pashës më 30 dhulkade 972 (29 qershor 1565), Mehmet Pashë Sokoli, i cili u ngrit në postin e vezirit të madh, u bë veziri i fundit i madh i Kanuniut dhe, duke e vazhduar këtë detyrë edhe pas tij, në kohën e Selimit II dhe të Muratit III, u bë një nga vezirët e mëdhenj me shërbimin më të gjatë në historinë osmane.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selimi II arriti në Stamboll dhe hipi në fron", "0289ef97"], "d": ["Pas vdekjes së Sulltan Sulejman Kanuniut në Sigetvar, Mehmet Pashë Sokoli e mbajti lajmin të fshehtë për javë të tëra, që të mos prishej rendi. Sipas Enciklopedisë Islame të TDV-së, Selaniku jep si datë të ardhjes së Selimit në Stamboll 15 rebiulevel 974 (30 shtator 1566), ndërsa shumica e historianëve bashkëkohës e pranojnë si të saktë 9 rebiulevelin (24 shtator). Vdekja e Kanuniut u shpall zyrtarisht në Beograd vetëm më 24-25 tetor 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Flota e rindërtuar nga Kylyç Ali Pasha u lëshua në det", "d0fc9f48"], "d": ["Pas disfatës së rëndë në Lepanto (7 tetor 1571), gjatë gjithë dimrit në arsenale u ndërtuan anije. Sipas Enciklopedisë Islame të TDV-së, më 1 safer 980 (13 qershor 1572) flota e re, e përbërë nga 250 galera dhe rreth 300 anije të lehta me rrema të reisëve vullnetarë, u lëshua në det si demonstrim force.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Mehmet Pashë Sokoli ra viktimë e një atentati dhe u vra", "6ffa8dec"], "d": ["Mehmet Pashë Sokoli, i cili kishte qenë vezir i madh për katërmbëdhjetë vjet nën tre padishahë, u vra me thikë më 20 shaban 987 (12 tetor 1579) nga një dervish që iu afrua në divanin e pasdites në sarajin e tij, sikur donte t'i dorëzonte një lutje. Sipas Enciklopedisë Islame të TDV-së, diskutohet nëse atentati mund të lidhet me hakmarrjen për Hamza Baliun, shehun e ekzekutuar të Hamzavive.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Ahdnameja e parë tregtare me Anglinë — anglezëve iu dhanë kapitulacione", "59c8e3ee"], "d": ["Përfaqësuesi anglez William Harborne, i dërguar në Stamboll në tetor 1578, me mbështetjen e Mehmet Pashë Sokolit dhe Hoxha Sadedin Efendiut mori nga Murati III një ahdname të vitit 1580. Me këtë ahdname tregtarët anglezë fituan të drejtën të përfitonin në të njëjtën shkallë nga privilegjet tregtare (kapitulacionet) që më parë u ishin njohur francezëve dhe venedikasve. Mbretëresha Elizabeta I dhe Murati III shkëmbyen letra, dhe mes dy shteteve u vendos edhe një marrëdhënie zyrtare. Menjëherë pas këtyre privilegjeve, më 1581 në Londër u themelua Levant Company; deri më 1825 anglezët e zhvilluan tregtinë e tyre në rajon nëpërmjet kësaj kompanie.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Observatori i Stambollit u rrënua me hatt-i humajun", "3bc0c78c"], "d": ["Nën ndikimin e fetvasë se observatorët u sillnin fatkeqësi vendeve dhe të kundërshtimit në pallat, me një hatt-i humajun të datës 4 dhulhixhe 987 (22 janar 1580), Observatori i Stambollit u rrënua së bashku me të gjitha instrumentet që kishte brenda. Sipas Enciklopedisë Islame të TDV-së, ky ishte fundi i institucionit jetëshkurtër që kishte themeluar Takijudin er-Rasidi.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Filloi dasma e synetisë së shehzade Mehmetit në Atmejdan", "c2926d5d"], "d": ["Djali i Muratit III, shehzade Mehmeti, u bë synet me ceremoni madhështore që filluan më 6 xhemaziulevel 990 (29 maj 1582) dhe zgjatën pesëdhjetë e gjashtë deri pesëdhjetë e shtatë ditë. Sipas Enciklopedisë Islame të TDV-së, festimet e organizuara në Atmejdan ishin një nga kremtimet më të shkëlqyera të pallatit në atë periudhë.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Vdiq Nurbanu Valide Sulltan", "77d0a577"], "d": ["Nëna e Muratit III, Nurbanu Sulltan, vdiq më 22 dhulkade 991 (7 dhjetor 1583). Sipas Enciklopedisë Islame të TDV-së, si valide sulltan ajo kishte mbajtur letërkëmbim me oborret e Venedikut dhe të Francës, dhe senati i Venedikut po atë vit kishte pranuar t'i dërgonte, si shpërblim për shërbimet e saj, një dhuratë me vlerë 2000 florinj venedikas.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Për shkak të akçes së zhvlerësuar shpërtheu Ngjarja e Bejlerbeut", "db2f2e61"], "d": ["Kur shteti i kreu pagesat me akçe, të cilave u kishte ulur përmbajtjen e argjendit, spahinjtë dhe jeniçerët rrethuan pallatin dhe ngritën një kryengritje të përgjakshme që hyri në histori me emrin Ngjarja e Bejlerbeut. Sipas zërit për Abdylkadir Shejhi Efendiun në Enciklopedinë Islame të TDV-së, për shkak të kësaj ngjarjeje shejhulislami u shkarkua nga detyra.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmeti III hipi në fron, nëntëmbëdhjetë shehzade u mbytën", "2cd9a8c5"], "d": ["Mehmeti III, pas vdekjes së të atit, Muratit III, arriti në Stamboll të premten, më 16 xhemaziulevel 1003 (27 janar 1595), dhe hipi në fron. Sipas Enciklopedisë Islame të TDV-së, po atë natë u mbytën nëntëmbëdhjetë shehzade, katër prej tyre të rritur (Mustafai, Bajaziti, Osmani dhe Abdullahu); ky ishte vëllavrasja me numrin më të madh viktimash në historinë osmane.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safije Sulltan fitoi ndikim si valide sulltan", "000bec21"], "d": ["Safije Sulltan, bashkëshortja e Muratit III dhe nëna e Mehmetit III, me ardhjen e djalit në fron u ngrit, me titullin valide sulltan, në një pozitë vendimtare në politikën e pallatit. Sipas Enciklopedisë Islame të TDV-së, në këtë periudhë ndikimi që buronte nga haremi arriti deri në ndërhyrje të drejtpërdrejtë në punët e shtetit.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Nën presionin e jeniçerëve, Mehmeti III doli personalisht në fushatë", "d3c50656"], "d": ["Megjithë kundërshtimin e vezirit të madh Damad Ibrahim Pasha, nën presionin e jeniçerëve, Mehmeti III u nis në fushatë nga Stambolli më 20 qershor 1596, si padishahu i parë pas Sulltan Sulejman Kanuniut që vihej personalisht në krye të ushtrisë. Sipas Enciklopedisë Islame të TDV-së, kjo nënkuptonte ringjalljen e traditës së vjetër të gazasë.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Epidemia e murtajës që kishte filluar në vitet 1570 vazhdonte të prekte Stambollin", "eb4ca37a"], "d": ["Sipas zërit për murtajën (taun) në Enciklopedinë Islame të TDV-së, epidemia që filloi në vitet 1570 vazhdoi të ndihej deri në fillim të shekullit XVII dhe goditi në radhë të parë Stambollin, si edhe Anadollin, Ballkanin, Egjiptin dhe Afrikën e Veriut. Periudhat e epidemisë përbënin një kërcënim kronik që e ndërpriste shpesh jetën e pallatit dhe të qytetit.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Vdiq Karajazëxhë Abdylhalimi, lëvizja kryengritëse u dobësua", "876ca7a6"], "d": ["Karajazëxhë Abdylhalimi, i cili u tërhoq i plagosur pas disfatës së rëndë që pësoi më 12 gusht 1601 në Sepetli, afër Elbistanit, vdiq në vitin 1010 hixhri (1602). Sipas Enciklopedisë Islame të TDV-së, lajmi i vdekjes arriti në Stamboll në ramazan të vitit 1010 (shkurt-mars 1602); burimet shënojnë se diskutohet nëse ai vdiq nga plaga apo u vra nga vetë njerëzit e tij.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Fundi de facto i traditës së vëllavrasjes", "9046c607"], "d": ["Ahmeti I, kur hipi në fron, ndryshe nga padishahët e mëparshëm, nuk urdhëroi vrasjen e vëllait të tij, shehzade Mustafait, por ia fali jetën; ky vendim konsiderohet fillimi i pranimit de facto, në sistemin osman të trashëgimisë, të parimit ekber-ershed (trashëgimi i anëtarit më të moshuar dhe më të aftë). Zëri \"Mustafa I\" i Enciklopedisë Islame të TDV-së transmeton se pas kësaj date Mustafai bëri në pallat një jetë të mbyllur. Kjo praktikë u dha fund de facto vrasjeve me rastin e ardhjes në fron, që kishin vazhduar prej shekujsh.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["U vu themeli i Xhamisë së Sulltan Ahmetit", "1683262f"], "d": ["Me urdhër të Ahmetit I, në Atmejdan u vu me ceremoni themeli i xhamisë që do ta ndërtonte arkitekti Sedefqar Mehmed Aga. Sipas zërit \"Xhamia dhe kompleksi i Sulltan Ahmetit\" të Enciklopedisë Islame të TDV-së, ndërtesa u bë objekt kritikash në atë kohë edhe sepse ishte xhamia e parë e madhe sulltanore e ndërtuar drejtpërdrejt nga arka e shtetit, pa pasur pas ndonjë fitore pushtimi. Kompleksi u projektua që, bashkë me xhaminë, të përfshinte edhe medresenë, imaretin dhe tyrben.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Vrasja e Osmanit të Ri nga jeniçerët (Haile-i Osmanije)", "324f6582"], "d": ["Jeniçerët dhe spahinjtë, të cilët u ngritën në kryengritje për shkak të thashethemeve se sulltani, nën pretekstin e haxhit, planifikonte të dilte nga Stambolli dhe të shpërndante ocakun e jeniçerëve, e rrëzuan Osmanin II nga froni dhe e mbytën në burgjet e Jedikulesë. Sipas zërit \"Osman II\" të Enciklopedisë Islame të TDV-së, kjo ngjarje është rasti i parë në historinë osmane kur një padishah u vra hapur nga një kryengritje ushtarake dhe shkaktoi një çarje të thellë në marrëdhëniet mes dinastisë dhe ushtrisë. Orët e tij të fundit kaluan kështu: kur përpjekja për t'u strehuar në sarajin e agait të jeniçerëve, Ali Agait, nuk dha rezultat, padishahu, sipas shprehjes së TDV-së, 'në mënyrë të mjerueshme, me kokë zbuluar dhe me veshje të rrëmujshme', u hipur mbi një kalë të rëndomtë dhe mes fyerjesh të rënda u çua fillimisht në Orta Xhami, ku ndodhej Mustafai I, dhe po atë ditë pasdite në Jedikule; sipas disa historianëve, për të vërtetuar vdekjen e tij, iu prenë veshi dhe hunda dhe iu treguan nënës së Mustafait I. Pas ngjarjes, Mustafai I u ul në fron për herë të dytë. Kjo ngjarje, e njohur si 'Haile-i Osmanije' (tragjedia e Osmanit), e prishi përgjithmonë ekuilibrin mes pallatit dhe ocakut dhe nisi debatet për legjitimitetin që do të vazhdonin gjatë gjithë shekullit.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Ulja e Mustafait I në fron për herë të dytë", "34a0b29a"], "d": ["Pas vrasjes së Osmanit të Ri nga jeniçerët, meqë në dinasti nuk kishte anëtar tjetër mashkull të rritur, Mustafai I u ul në fron për herë të dytë. Sipas zërit \"Mustafa I\" të Enciklopedisë Islame të TDV-së, edhe ky sundim i dytë, njësoj si i pari, kaloi pa qenë ai në gjendje t'i drejtonte realisht punët e shtetit, dhe qeverisja mbeti në duart e vezirëve dhe të valide sulltanes. Kjo periudhë, që zgjati katërmbëdhjetë muaj, mori fund më 1623 me ardhjen në fron të Muratit IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Zjarri i Xhibalit", "3e42fb08"], "d": ["Zjarri që shpërtheu në Xhibali dhe u përhap me shpejtësi nën ndikimin e erës shkrumboi një pjesë të madhe të Stambollit; sipas zërit \"Stambolli\" të Enciklopedisë Islame të TDV-së, burimet e kohës transmetojnë se u dogjën mijëra shtëpi. Lidhja e zjarrit me ndërtimet prej druri të banesave dhe me pirjen e duhanit u bë arsyetimi i drejtpërdrejtë për ndalimin e rreptë të duhanit dhe të kafeneve, që Murati IV do ta shpallte pak më vonë. Fatkeqësia ishte vetëm një nga zjarret e mëdha që përsëriteshin në Stambollin e asaj kohe.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Ndalimi i duhanit dhe i kafeneve nga Murati IV", "5dd71297"], "d": ["Pas Zjarrit të Xhibalit, nga shqetësimi për zjarret dhe rendin publik, Murati IV ndaloi pirjen e duhanit dhe kafenetë; ndaj atyre që nuk i bindeshin ndalimit u zbatuan dënime të rënda, përfshirë dënimin me vdekje. Sipas zërit \"Murad IV\" të Enciklopedisë Islame të TDV-së, padishahu ndoqi një politikë kaq të rreptë disipline të brendshme, saqë për të kontrolluar ndalimin shëtiste vetë, i maskuar, nëpër rrugët e qytetit. Këto masa të ashpra vlerësohen si pjesë e përpjekjes së Muratit IV për të rivendosur autoritetin qendror.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Epidemi murtaje në Stamboll", "f33f58c5"], "d": ["Në kohën e Muratit IV, Stambolli u trondit nga një epidemi e rëndë murtaje që preku një pjesë të konsiderueshme të popullsisë; tregtia brenda qytetit dhe jeta e përditshme u penguan për muaj të tërë. Zëri \"Stambolli\" i Enciklopedisë Islame të TDV-së shënon se epidemitë e përsëritura të shekullit XVII ndikuan seriozisht në ekuilibrin demografik të qytetit. Gjatë periudhës së epidemisë, pallati dhe shtresa e lartë u shpërngulën për një farë kohe në kopshtet dhe pavionet jashtë qytetit.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Fluturimi me krahë i Hezarfen Ahmed Çelebiut (sipas gojëdhënës)", "df474c04"], "d": ["Sipas gojëdhënës që transmeton Evlija Çelebiu, Hezarfen Ahmed Çelebiu, duke u hedhur nga Kulla e Gallatës me krahë që i kishte bërë vetë, arriti të fluturonte me planim deri në Yskydar; megjithëse saktësia historike është e diskutueshme, ai u bë simbol i imagjinatës teknike. Padishahu, i cili në fillim e shpërbleu Hezarfenin, më vonë, për shkak të jehonës që pati ngjarja, e internoi në Algjeri.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Xhinxhi Hoxha Hysejn Efendi fiton ndikim në pallat", "41d21572"], "d": ["Hysejn Efendiu, një shërues me fryrje e lutje, i thirrur në pallat për të mjekuar shqetësimet shpirtërore të padishahut Ibrahim, brenda një kohe të shkurtër fitoi besimin e padishahut dhe u ngrit deri në postin e kazaskerit të Anadollit. Sipas zërit \"Hüseyin Efendi, Cinci Hoca\" të Enciklopedisë Islame të TDV-së, ai e përdori këtë ndikim për të grumbulluar pasuri dhe për të ndërhyrë në ngjarjet politike të kohës. Pas vdekjes së Ibrahimit u shkarkua nga të gjitha detyrat dhe më 1648 u ekzekutua.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Ekzekutimi i Kemankesh Mustafa Pashës", "0ecc8030"], "d": ["Kemankesh Mustafa Pasha, vezir i madh që nga koha e Muratit IV, i cili me reformat financiare i siguroi arkës një tepricë të konsiderueshme, u ekzekutua me mbytje pasi rivalët e tij në pallat ndikuan te Ibrahimi dhe pasi u akuzua se kishte nxitur një kryengritje jeniçerësh. Sipas zërit \"Kemankeş Mustafa Paşa\" të Enciklopedisë Islame të TDV-së, ekzekutimi i tij u krye më 21 dhulkade 1053 / 31 janar 1644: Kemankesh Kara Mustafa Pasha u mbyt nga xhelati Kara Ali në Çarshinë e Hoxha Pashës dhe u varros në tyrben e vet në Çarshëkapë. Vdekja e tij përmendet si shembull domethënës i paqëndrueshmërisë së postit të vezirit të madh në atë periudhë dhe i dha fund periudhës së shkurtër të reformave të rrepta.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Vendimi i divanit për fushatën e Kretës dhe nisja e flotës", "9076827e"], "d": ["Në Divan-i Humajun u vendos të ndërmerrej një fushatë e madhe kundër ishullit të Kretës, që i përkiste Venedikut, dhe flota osmane nën komandën e kapudan-i derjasë u nis nga Stambolli drejt Kretës. Sipas zërit \"Girit\" (Kreta) të Enciklopedisë Islame të TDV-së, ky vendim përbënte fillimin politik të një periudhe të gjatë rrethimesh dhe luftërash që do të zgjaste rreth njëzet e pesë vjet. Nisja e fushatës, si ndërmarrja më e madhe e politikës së jashtme në kohën e Ibrahimit, kishte shkaktuar debate të gjera mes burrave të shtetit.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Ardhja në fron e Mehmetit IV në moshën shtatëvjeçare", "a197a3bc"], "d": ["Menjëherë pas rrëzimit të Ibrahimit, djali i tij Mehmed, vetëm shtatë vjeç, u ul në fron dhe u bë padishah me titullin Mehmeti IV. Sipas zërit \"Mehmed IV\" të Enciklopedisë Islame të TDV-së, ardhja në fron në një moshë kaq të vogël e ashpërsoi luftën për ndikim në pallat mes gjyshes së tij, Kosem Sulltanes, dhe nënës, Turhan Sulltanes. Kjo luftë për pushtet do të përfundonte më 1651 me vrasjen e Kosem Sulltanes.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Reforma e buxhetit të balancuar e Tarhunxhu Ahmed Pashës", "376fc7f2"], "d": ["Veziri i madh Tarhunxhu Ahmed Pasha, për të kapërcyer krizën financiare të shkaktuar nga vitet e gjata të luftës, zbatoi një program të rreptë kursimi që përfshinte edhe shpenzimet e pallatit dhe përgatiti buxhetin e parë të balancuar të njohur në historinë osmane (projekti i Tarhunxhiut). Sipas zërit \"Tarhuncu Ahmed Paşa\" të Enciklopedisë Islame të TDV-së, kjo reformë i siguroi arkës një tepricë të konsiderueshme, por shkaktoi pakënaqësi të gjerë në rrethet e pallatit dhe në burokracinë e lartë. Kjo pakënaqësi do të përfundonte një vit më vonë me ekzekutimin e vetë atij.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Ngjarja e Rrapit (Vaka-i Vakvakije)", "4c6ed90f"], "d": ["Sipas zërit për Ngjarjen e Rrapit në Enciklopedinë Islame të TDV-së, jeniçerët dhe spahinjtë, të kthyer pa pagesë nga fushata e Kretës, u ngritën në kryengritje në Stamboll dhe kërkuan ekzekutimin e burrave të shtetit që i akuzonin për korrupsion. Propozimi i vezirit të madh Zurnazen Mustafa Pasha për konfiskim e internim nuk u pranua; fillimisht u ekzekutuan tre zyrtarë, pastaj rreth tridhjetë burra shteti, dhe kufomat e tyre u varën në rrapat e sheshit të Sulltan Ahmetit. Për këtë arsye ngjarja u quajt Ngjarja e Rrapit.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Emërimi i Mehmed Pashë Qyprilliut vezir i madh me pranim të kushtëzuar", "3a6b7f8f"], "d": ["Sipas zërit për Mehmed Pashë Qyprilliun në Enciklopedinë Islame të TDV-së, Mehmed Pashë Qyprilliu, rreth tetëdhjetë vjeç, e mori vulën vetëm pasi ia pranuan Valide Turhan Sulltanes dhe Mehmetit IV kushtet e rënda që u kishte paraqitur — të mos i ndërhynin në emërime dhe të mos u besonin fjalëve kundër tij. Ai nisi detyrën më 26 dhulkade 1066 në vend të Bojnuegri Mehmed Pashës dhe iu përvesh me ashpërsi rivendosjes së disiplinës shtetërore.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Shtypja e lëvizjes së Kadizadelinjve nga Mehmed Pashë Qyprilliu", "5ec3ce84"], "d": ["Sipas zërit për Kadizadelinjtë në Enciklopedinë Islame të TDV-së, sapo mori detyrën, Mehmed Pashë Qyprilliu trajtoi konfliktin fetar mes rrethit të Kadizade Mehmed Efendiut dhe ndjekësve të tarikateve. Pasi u këshillua me ulematë, ai nxori ferman për ekzekutimin e krerëve të lëvizjes, Ustuvani Mehmed Efendiut, Turk Ahmetit dhe Divane Mustafait, por dënimi u kthye në internim dhe të tre u dërguan në Qipro; kështu mori fund faza e dytë e lëvizjes.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Zjarr i madh në Stamboll: djegia e Agakapisë", "b9253b66"], "d": ["Sipas zërit për Agakapinë në Enciklopedinë Islame të TDV-së, në zjarrin e madh që shpërtheu në korrik 1660, në kohën e Mehmetit IV, Agakapia, selia zyrtare e agait të jeniçerëve, u dogj tërësisht dhe më pas u rindërtua. Ky zjarr ishte një nga zjarret e mëdha të qytetit që goditën vazhdimisht Stambollin e asaj kohe.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Emërimi i Fazil Ahmed Pashë Qyprilliut vezir i madh", "c1999b5c"], "d": ["Sipas zërit për Fazil Ahmed Pashë Qyprilliun në Enciklopedinë Islame të TDV-së, pas vdekjes së të atit, Mehmed Pashë Qyprilliut, ai u emërua vezir i madh më 8 rebiulevel 1072 (1 nëntor 1661). Ndryshe nga i ati, Fazil Ahmed Pasha njihej si njeri me natyrë të butë, fetar dhe mbrojtës i dijetarëve e artistëve; gjatë më shumë se pesëmbëdhjetë vjetëve si vezir i madh themeloi biblioteka dhe institucione bamirësie në Stamboll dhe në tokat e pushtuara.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Emërimi i Vani Mehmed Efendiut predikues i Xhamisë së Re dhe mësues i padishahut", "7ea6aaae"], "d": ["Sipas zërit për Mehmed Efendiun, Vani, në Enciklopedinë Islame të TDV-së, Vani Mehmed Efendiu, i cili u ftua në Stamboll kur Fazil Ahmed Pashë Qyprilliu u bë vezir i madh dhe iu paraqit Mehmetit IV, brenda një kohe të shkurtër fitoi interesimin e afërt të padishahut. Më 1665 u emërua predikues i Xhamisë së Re dhe mësues i padishahut, duke u bërë një nga klerikët më me ndikim të pallatit.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Emërimi i Kara Mustafa Pashës së Merzifonit vezir i madh", "3d1e836c"], "d": ["Sipas zërit për Kara Mustafa Pashën e Merzifonit në Enciklopedinë Islame të TDV-së, pas vdekjes së Fazil Ahmed Pashës, ai u emërua vezir i madh më 28 shaban 1087 (5 nëntor 1676). Dhëndër dhe i rritur i familjes Qyprilliu, Merzifonlliu, me përvojë të gjatë në qeverisje, u bë një nga vezirët e mëdhenj më të fuqishëm dhe më me ndikim të Mehmetit IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Vdekja e Vani Mehmed Efendiut në internim", "cda714aa"], "d": ["Sipas zërit për Mehmed Efendiun, Vani, në Enciklopedinë Islame të TDV-së, Vani Mehmed Efendiu, i cili konsiderohet një nga personat kryesorë që ia mbushën mendjen padishahut për fushatën e Vjenës, pas përfundimit të saj me disfatë ra në mosmirënjohje nën presionin e opinionit publik dhe u internua në kasabanë Kestel të Bursës. Vdiq atje më 14 dhulkade 1096 (12 tetor 1685) dhe u varros në hyrje të xhamisë që kishte ndërtuar vetë.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Emërimi i Fazil Mustafa Pashë Qyprilliut vezir i madh dhe reformat e tij financiare", "b048570e"], "d": ["Sipas zërit për Fazil Mustafa Pashë Qyprilliun në Enciklopedinë Islame të TDV-së, Fazil Mustafa Pasha, i emëruar vezir i madh më 11 muharrem 1101 (25 tetor 1689), e riorganizoi mënyrën e mbledhjes së xhizjes sipas parimeve të sheriatit, luftoi inflacionin e shkaktuar nga mangëri dhe e forcoi arkën e shtetit duke kaluar burime nga institucionet e pallatit. Përveç kësaj, e përforcoi administratën e provincave me zyrtarë të besueshëm dhe themeloi këshilla vendore të ngjashme me divanin qendror.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Hyrja në fuqi e sistemit të malikanes", "316b8426"], "d": ["Sipas zërit për malikanen në Enciklopedinë Islame të TDV-së, në çerekun e fundit të shekullit XVII, rritja e shpenzimeve të luftës dhe pakësimi i të ardhurave për shkak të humbjeve territoriale e futën arkën e shtetit në një krizë të rëndë financiare. Me sistemin e malikanes, që hyri në fuqi në vitin 1106 hixhri (1695), sipërmarrësve të taksave iu njoh e drejta për të mbledhur për gjithë jetën një taksë të caktuar, duke u krijuar kështu një nxitje për ruajtjen e prodhimit në vend të shfrytëzimit afatshkurtër.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Ardhja në fron e Mustafait II", "b53656c7"], "d": ["Sipas zërit për Mustafain II në Enciklopedinë Islame të TDV-së, Mustafai II, i cili hipi në fron në moshën tridhjetë e një vjeç, e shpalli sundimin e vet pa pritur pëlqimin e vezirit të madh dhe të shejhulislamit; ceremonia e ngjeshjes së shpatës u bë disa ditë më vonë në Xhaminë e Vjetër. Padishahu, që hipi në fron në një periudhë luftërash në shumë fronte pas disfatës së Vjenës, u bë sulltani i fundit në historinë osmane që doli personalisht në fushatë.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Emërimi i Fejzullah Efendiut për herë të dytë shejhulislam", "1cf14cff"], "d": ["Sipas zërit për Fejzullah Efendiun, Sejid, në Enciklopedinë Islame të TDV-së, pas ardhjes në fron të Mustafait II, ai u emërua për herë të dytë shejhulislam më 11 sheval 1106 (25 maj 1695). Gjatë kësaj periudhe të detyrës, që zgjati mbi tetë vjet, ndikimi i tij mbi padishahun u rrit gjithnjë e më shumë.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Fejzullah Efendiu i ngre djemtë e tij në poste të larta; grumbullohet pakënaqësia", "a6398280"], "d": ["Sipas zërit për Fejzullah Efendiun, Sejid, në Enciklopedinë Islame të TDV-së, shejhulislami siguroi nga Mustafai II një ferman të paparë, sipas të cilit djali i tij, Fetullah Efendiu, do të bëhej shejhulislam pas tij, dhe i vendosi të afërmit e vet në moshë të re në poste të larta. Këto praktika shkaktuan pakënaqësi të gjerë te klasa e ilmijes, ushtria dhe populli i Stambollit dhe, duke u bashkuar me thashethemet se kryeqyteti do të zhvendosej në Edrene, përgatitën terrenin për Ngjarjen e Edrenesë të vitit 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Fillimi i Ngjarjes së Edrenesë", "5a106458"], "d": ["Sipas zërit \"Edirne Vak'ası\" (Ngjarja e Edrenesë) të TDV-së, lëvizja që filloi me kryengritjen e ushtarëve që nuk i merrnin rrogat (ulufe) u shndërrua shpejt në një rebelim të gjerë, ku morën pjesë jeniçerët, nxënësit e medreseve, zejtarët dhe populli. Objektivi kryesor i kryengritjes ishte shejhulislami Fejzullah Efendi, për të cilin thuhej se ndërhynte tepër në punët e shtetit. Një turmë prej rreth 60.000 vetësh marshoi nga Stambolli drejt Edrenesë.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Periudha e vezirit të madh Nevshehirli Damad Ibrahim Pasha", "8d627a6f"], "d": ["Sipas zërit \"Damad İbrâhim Paşa, Nevşehirli\" të TDV-së, gjatë bisedimeve të paqes që po zhvilloheshin me Austrinë, ai u emërua vezir i madh më 8 xhemaziulahir 1130 (9 maj 1718) dhe, sapo u emërua, iu kushtua bisedimeve që do t'i jepnin fund luftës; dy muaj më pas u nënshkrua Traktati i Pozharevcit (21 korrik 1718). Sipas shprehjes së TDV-së, ai 'dëshironte të merrej me çështjet shoqërore e financiare dhe ëndërronte një periudhë paqeje që do t'i bënte të harroheshin luftërat që prej vitesh përfundonin me disfatë'. Me reformat në financa uli pagat e ushtarëve dhe krijoi një tepricë të konsiderueshme në arkën e shtetit. Vezirllëku i tij i madh, që do të zgjaste dymbëdhjetë vjet, formoi kornizën politike të periudhës që mban emrin e saj (Epoka e Tulipanëve).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Themelimi i Ocakut të Tulumbaxhinjve", "f58b0d97"], "d": ["Sipas zërit \"Tulumbacı\" të TDV-së, pas suksesit që Gerçek Davudi, i kthyer nga fushata e Moresë e vitit 1715, tregoi me pompë (tulumba) në zjarret e Stambollit, veziri i madh Nevshehirli Damad Ibrahim Pasha e ngarkoi të themelonte një ocak zyrtar zjarrfikësish. Ocaku, i themeluar në Kazermën e Axhemi Ogllanëve me gjashtë oficerë dhe pesëdhjetë ushtarë, arriti në 150 vetë më 1724 dhe në 461 vetë më 1755. Davudi qëndroi në krye të ocakut deri në vdekjen e tij më 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Ndërtimi i Pavionit të Sadabadit", "aec9c65e"], "d": ["Sipas zërit \"Sâdâbâd\" të TDV-së, në brigjet e përroit të Kaghithanesë u ndërtua një kompleks i gjerë argëtimi e shëtitjeje, i përbërë nga një pavion i frymëzuar nga arkitektura e pallateve franceze, kanale, çezma dhe kioska. Sadabadi, që u bë vendi më i preferuar i argëtimit i asaj kohe, u përjetësua në vjershat e poetit Nedim. Kompleksi u shkatërrua në masë të madhe gjatë Kryengritjes së Patrona Halilit më 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Forcat ruse marrin Derbendin: fushata e Pjetrit I në Detin Kaspik", "c2b269f9"], "d": ["Ndërsa Shteti Safavid ishte zhytur në trazira të brendshme nga pushtimi afgan, cari rus Pjetri I u nis në fushatë për të shtënë në dorë tokat iraniane në bregun e Detit Kaspik; qyteti bregdetar i Derbendit iu dorëzua forcave ruse pa ndonjë rezistencë të konsiderueshme. Sipas zërit për Derbendin në Enciklopedinë Islame të TDV-së, ky pushtim ishte fillimi i një sundimi të përkohshëm rus që do të zgjaste trembëdhjetë vjet; edhe Shteti Osman, duke përfituar nga e njëjta rrëmujë, u drejtua drejt pjesës perëndimore të Kaukazit. Ushtria kishte dalë nga Astrahani me rrugë detare në gjirin e Agrahanit dhe prej andej kishte marshuar me tokë përgjatë bregut, përmes Tarkusë; shamhali i Tarkusë e priti Pjetrin dhe hyri nën nënshtetësinë ruse.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Shfuqizimi i shamhallëkut të Tarkusë: administrim i drejtpërdrejtë rus", "b0f029c6"], "d": ["Shamhali i Tarkusë Adil-Girej, i cili më 1722 e kishte pritur Pjetrin dhe kishte hyrë nën nënshtetësinë ruse, u ngrit në kryengritje më 1725; në vjeshtën e 1725-s Jeropkini e rrënoi Tarkunë, shamhali u arrestua në mes të majit 1726 dhe u internua, dhe shamhallëku u shfuqizua. Tarku dhe rrethinat mbetën nën administrim të drejtpërdrejtë rus deri në Traktatin e Gjanxhës të vitit 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Lejohet Ibrahim Myteferika të themelojë shtypshkronjë", "0659dd0a"], "d": ["Sipas zërit \"İbrâhim Müteferrika\" të TDV-së, me fermanin e Ahmetit III dhe me fetvanë e shejhulislamit Jenishehirli Abdullah Efendi u lejua themelimi i shtypshkronjës së parë turke. Shtypshkronja filloi punën në lagjen Javuzselim të Stambollit. Deri në vdekjen e tij më 1747, Myteferika botoi shtatëmbëdhjetë vepra në njëzet e tre vëllime.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Përfundimi i librit të parë të shtypur, fjalorit Vankulu", "684700e8"], "d": ["Sipas zërit \"İbrâhim Müteferrika\" të TDV-së, vepra e parë e shtypshkronjës, përkthimi turqisht i Sihahut të el-Xheuheriut (Fjalori Vankulu), përfundoi në fillim të vitit 1729. Ky ishte libri i parë i shtypur me shkronja arabe në tokat osmane dhe konsiderohet fillimi i historisë së shtypshkrimit turk.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Ekzekutimi i Nevshehirli Damad Ibrahim Pashës", "50c64341"], "d": ["Sipas zërit \"Damad İbrâhim Paşa, Nevşehirli\" të TDV-së, kufoma e vezirit të madh, që u vra në pallat gjatë Kryengritjes së Patrona Halilit, u tërhoq zvarrë nëpër rrugët e Stambollit dhe u braktis pranë Çezmës së Ahmetit III në sheshin e Sulltan Ahmetit. Kështu, vezirllëku i tij dymbëdhjetëvjeçar dhe Epoka e Tulipanëve morën fund në mënyrë të përgjakshme.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Heqja dorë e Ahmetit III nga froni dhe ardhja në fron e Mahmudit I", "a43f5d40"], "d": ["Sipas zërit \"Mahmud I\" të TDV-së, përballë presionit të kryengritësve, Ahmeti III, pasi siguroi garanci për veten dhe fëmijët e tij, hoqi dorë nga froni dhe vetë e uli në fron nipin e tij, shehzade Mahmudin. Mahmudi I, i cili u ul në fron me këshillën e xhaxhait \"merri vetë në dorë punët e shtetit dhe mos i beso askujt\", si hap të parë u përpoq të thyente ndikimin e grupit kryengritës që e kishte hipur në fron.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Reformimi i korpusit të artilerisë nga Humbaraxhi Ahmed Pasha", "ea3a7c64"], "d": ["Sipas zërit \"Humbaracı\" të TDV-së, Ahmed Pasha, oficer me origjinë franceze që kishte përqafuar Islamin, në kohën e vezirit të madh Hekimogllu Ali Pasha iu përvesh reformimit sipas modelit evropian të organizatës së humbaraxhinjve me pagesë (ulufe). Ai krijoi një strukturë të re prej 601 vetësh, të varur drejtpërdrejt nga veziri i madh: 300 me rrogë dhe 301 me timar. Me teknologjinë e kohës urdhëroi prodhimin e 100 mortajave dhe 50.000 gjyleve.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Themelimi i Hendesehanes (shembulli i parë i shkollës së inxhinierisë)", "a77ed1f3"], "d": ["Sipas zërit \"Mahmud I\" të TDV-së, Humbaraxhi Ahmed Pasha themeloi në Yskydar Hendesehanen, që quhej edhe Humbarahane, dhe u dha nxënësve të zgjedhur mes shërbëtorëve të pallatit dhe bostanxhinjve një arsim ushtarak të bazuar në matematikë dhe gjeometri. Ky institucion konsiderohet shembulli i parë i shkollave të inxhinierisë që do të zhvilloheshin në periudhën pasuese.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Traktati i Gjanxhës: Derbendi dhe Bakuja i kthehen Iranit", "ff19d531"], "d": ["Rusia, që kërkonte aleancë me Iranin kundër kërcënimit osman, me Traktatin e Gjanxhës ia ktheu Iranit nën komandën e Nadir Hanit (që ende nuk e kishte marrë titullin shah) qytetet bregdetare të Kaspikut që i kishte mbajtur për trembëdhjetë vjet. Sipas zërit për Derbendin në Enciklopedinë Islame të TDV-së, kjo tërheqje ishte pasojë e faktit se Rusia nuk donte të luftonte njëkohësisht në dy fronte në jug (osman dhe iranian), dhe ajo e përforcoi prestigjin ushtarak të Nadirit, që pak vite më vonë do t'i hapte rrugën për të hipur në fron. Me këtë tërheqje edhe Tarki (Tarku), nën administrim rus, kaloi në anën iraniane (në hartë përdoret data e Gjanxhës). Me këtë tërheqje kalojnë në anën iraniane edhe Saljani dhe Shaburani, që ishin nën administrim rus (burimi nuk jep ditë të veçantë për vendbanimet, në hartë përdoret data e Gjanxhës — përafrim i deklaruar).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Nadir Shahu hipi në fron në fushën e Muganit: fundi de facto i dinastisë safavide", "4f640979"], "d": ["Sipas zërit për Nadir Shahun në Enciklopedinë Islame të TDV-së, kurultai prej rreth njëzet mijë vetësh, i mbledhur në fushën e Muganit, kërkoi me këmbëngulje që ai të vihej në krye të Iranit; Nadiri e pranoi ofertën me kusht që të braktisej kuptimi ekstrem shiit, shkak i luftërave mes safavidëve dhe osmanëve, dhe të përqafohej medhhebi i matur xhaferi, dhe më 24 sheval 1148 (8 mars 1736) hipi në fron me titullin Nadir Shah. Kjo nënkuptonte se dinastia dyshekullore safavide mori fund de facto dhe u themelua dinastia e afsharëve.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Fillimi i epidemisë së murtajës në Stamboll", "9fa82b56"], "d": ["Sipas zërit \"Tâun\" të TDV-së, epidemia e murtajës që veproi në botën islame ndërmjet viteve 1739-1743 goditi në këtë periudhë edhe Stambollin. Zëri vë në dukje se epidemitë e shekullit XVIII kishin ecuri relativisht më të lehtë se ato të shekujve të mëparshëm. Ndër periudhat e epidemive përmenden edhe vitet 1713, 1719, 1728-1729 dhe 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Zjarri i Hoxhapashës", "321c7d0d"], "d": ["Sipas zërit \"Fatma Sultan Camii\" të TDV-së, zjarri i Hoxhapashës që shpërtheu natën shkatërroi Babialinë dhe rrethinat e saj; mendohet se nga ky zjarr u dëmtua edhe Xhamia e Fatma Sulltanes në atë zonë. Kjo fatkeqësi, një nga zjarret e mëdha që goditën Stambollin në kohën e Osmanit III, shkaktoi dëme të rënda në qendrën tregtare dhe administrative të qytetit.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Periudha e vezirit të madh Koxha Ragip Mehmed Pasha", "a1846910"], "d": ["Ragip Pasha, i njohur si poet dhe diplomat, u emërua vezir i madh nga Osmani III (pas vdekjes së Osmanit III në tetor 1757 vazhdoi detyrën dhe mori vulë të re nga Mustafai III). Gjatë Luftës Shtatëvjeçare ndoqi një politikë të jashtme të ekuilibruar që e mbajti Shtetin Osman jashtë përplasjeve në Evropë. Gjatë gjashtë viteve si vezir i madh u kushtoi rëndësi edhe veprimtarive kulturore, siç ishte themelimi i bibliotekave.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Vdekja e Ragip Pashës", "6bc19323"], "d": ["Ragip Pasha vdiq pas gjashtë vjetësh si vezir i madh. Me vdekjen e tij mori fund vezirllëku i madh më jetëgjatë dhe më i ekuilibruar i periudhës së Mustafait III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Tërmeti i madh i Stambollit dhe shembja e Xhamisë së Fatihut", "2475b4dc"], "d": ["Sipas zërit \"Fâtih Camii ve Külliyesi\" të TDV-së, në tërmetin e madh të vitit 1766 kupola kryesore e xhamisë u shemb tërësisht dhe muret pësuan dëme të pariparueshme. Rindërtimi, që filloi më 1767 me urdhër të Mustafait III, nën drejtimin e arkitektëve Sarim Ibrahim Efendi dhe Izzet Mehmed Bej, përfundoi më 1771 sipas një projekti të ri, të ndryshëm nga plani i vjetër.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Përpjekja jetëshkurtër për një shkollë artilerie nën drejtimin e baronit de Tott", "4192260c"], "d": ["Sipas zërit \"Mühendishâne-i Bahrî-i Hümâyun\" të TDV-së, dështimet në luftën osmano-ruse të vitit 1768 nxorën në pah nevojën për arsim teknik ushtarak; shkolla jetëshkurtër e artilerisë, e hapur me kontributin e oficerit francez baron de Tott, filloi punën në tetor 1772, por mbeti pa efekt. Kjo përpjekje konsiderohet paraprijëse e Mühendishâne-i Bahrî-i Hümâyun (Shkolla Perandorake e Inxhinierisë Detare), që do të themelohej më 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selimi III hipi në fron", "00d046d9"], "d": ["Pas vdekjes së Abdulhamidit I, në fron hipi nipi i tij, Selimi III. Sipas zërit për Selimin III në Enciklopedinë Islame të TDV-së, padishahu i ri, që qysh si shehzade ishte i interesuar për reformimin sipas ushtrive evropiane, pak kohë pas ardhjes në fron nisi të porosiste përgatitjen e një programi rrënjësor përtëritjeje. Pas disa vitesh ky program do të njihej me emrin Nizam-i Xhedid.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Filloi përgatitja e programit reformues Nizam-i Xhedid", "eff78a68"], "d": ["Selimi III urdhëroi përgatitjen e një programi të gjerë përtëritjeje në përputhje me memorandumet (lajiha) që u kërkoi burrave të shtetit dhe ekspertëve të huaj. Sipas zërit për Nizam-i Xhedidin në Enciklopedinë Islame të TDV-së, ky program nuk u kufizua vetëm me krijimin e një ushtrie të re; u shndërrua në një lëvizje të gjerë reformash që përfshinte edhe financat, administratën e provincave dhe diplomacinë. Gjatë pesëmbëdhjetë viteve pasuese programi do të gjente si përkrahës, ashtu edhe kundërshtarë.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["U themeluan ambasada të përhershme në kryeqytetet evropiane", "2e9dc8a1"], "d": ["Për herë të parë në historinë e Shtetit Osman, Selimi III dërgoi në qendrat e mëdha evropiane ambasadorë të përhershëm me detyrë të vazhdueshme. Sipas zërit për ambasadorin (elçi) në Enciklopedinë Islame të TDV-së, ky hap i dha diplomacisë osmane, që deri atëherë zhvillohej vetëm me delegacione të përkohshme dhe të njëhershme, një organizim të qëndrueshëm. Detyra kryesore e ambasadave të reja ishte të informonin rregullisht Stambollin për zhvillimet politike dhe ushtarake në Evropë.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["U themelua arka Irad-i Xhedid", "ae5c8ce2"], "d": ["Për të përballuar shpenzimet e ushtrisë së Nizam-i Xhedidit dhe të programit të reformave u themelua një arkë e veçantë. Sipas zërit për eshamin në Enciklopedinë Islame të TDV-së, ndër të ardhurat e arkës së re përfshiheshin shfrytëzimi i drejtpërdrejtë nga shteti i disa mukatave dhe vënia nën kontroll e shitjes së eshamit. Ky rregullim ishte një përpjekje për të krijuar një burim të ri jashtë sistemit tradicional financiar.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Filloi kryengritja e Kabakçi Mustafait", "b98eee17"], "d": ["Pakënaqësia e grumbulluar kundër Nizam-i Xhedidit shpërtheu me kryengritjen e ushtarëve jamakë nën udhëheqjen e Kabakçi Mustafait. Sipas zërit për Kryengritjen e Kabakçiut në Enciklopedinë Islame të TDV-së, kryengritësit brenda një kohe të shkurtër morën kontrollin në Stamboll dhe kërkuan kokat e burrave të shtetit përkrahës të Nizam-i Xhedidit. Brenda pak ditësh kryengritja përfundoi me rrëzimin nga froni të Selimit III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selimi III u rrëzua nga froni", "ff2c30ec"], "d": ["Nën presionin e kryengritjes së Kabakçi Mustafait, me fetva të marrë nga shejhulislami, Selimi III u rrëzua nga froni. Sipas zërit për Selimin III në Enciklopedinë Islame të TDV-së, ky vendim shënoi fundin de facto të periudhës së reformave që kishte zgjatur tetëmbëdhjetë vjet; edhe ushtria e Nizam-i Xhedidit u shpërbë brenda një kohe të shkurtër. Selimi filloi të mbahej nën mbikëqyrje në Pallatin Topkapi.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafai IV hipi në fron", "8f1ac86c"], "d": ["Menjëherë pas rrëzimit të Selimit III nga froni, nipi i tij, Mustafai IV, u shpall padishah. Sipas zërit për Mustafain IV në Enciklopedinë Islame të TDV-së, padishahu i ri e filloi sundimin nën ndikimin e rrethve kundërshtare të Nizam-i Xhedidit që përkrahën kryengritjen. Kjo periudhë e shkurtër ishte një fazë paqëndrueshmërie, ku autoriteti qendror u dobësua tej mase.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pasha hyri në Stamboll me ushtrinë e tij", "0cad3dea"], "d": ["Ajani i Ruses, Alemdar Mustafa Pasha, mbërriti para Stambollit me ushtrinë e tij me qëllim që ta rikthente Selimin III në fron. Sipas zërit për Alemdar Mustafa Pashën në Enciklopedinë Islame të TDV-së, hyrjen e tij në qytet e priti vetë Mustafai IV; por brenda pak ditësh raporti i forcave brenda pallatit do të ndryshonte tërësisht. Kjo hyrje nisi zinxhirin e ngjarjeve që përfunduan si me vdekjen e Selimit, ashtu edhe me një ardhje të re në fron.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selimi III u vra", "e452f5f6"], "d": ["Ditën kur Alemdar Mustafa Pasha mori në kontroll Babialinë, me urdhër të Mustafait IV, Selimi III u vra në pallat. Sipas zërit për Selimin III në Enciklopedinë Islame të TDV-së, ky ishte një vendim i marrë për të penguar përpjekjen për ta rikthyer në fron një padishah të rrëzuar. Vdekja e Selimit përfundoi po atë ditë me hipjen në fron të Mahmudit.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmudi II hipi në fron", "661c1974"], "d": ["Pas vrasjes së Selimit III, Mahmudi, i mbetur anëtari i vetëm mashkull i dinastisë, hipi në fron me mbështetjen e Alemdar Mustafa Pashës. Sipas zërit për Mahmudin II në Enciklopedinë Islame të TDV-së, padishahu i ri i kaloi muajt e parë të sundimit nën kujdestarinë e Alemdarit, që e kishte hipur në fron, dhe në përpjekje për të rivendosur ekuilibrin mes ajanëve dhe qendrës. Kjo periudhë u bë fillimi i procesit të reformave rrënjësore të njëzet viteve pasuese.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["U krijua ushtria Sekban-i Xhedid", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasha urdhëroi krijimin e një ushtrie të re, të pajisur sipas modelit evropian, në vend të Nizam-i Xhedidit të shpërbërë. Sipas zërit për Sekban-i Xhedidin në Enciklopedinë Islame të TDV-së, kjo forcë, e përbërë nga tre regjimente, u pa nga jeniçerët si kërcënim i drejtpërdrejtë dhe vetëm pak muaj pas krijimit u zhduk në një kryengritje jeniçerësh.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Rënia e Brailës — çarja e parë e madhe në vijën e Danubit", "ee519321"], "d": ["Në luftën me Rusinë që filloi më 1806, kështjella e Brailës në bregun verior të Danubit u rrethua dhe u bombardua nga forcat ruse nën komandën e kontit Kaminski. Brenda ndodheshin 4100 këmbësorë, 1100 kalorës dhe 260 topa; për shkak të mungesës së ushqimit kështjella iu dorëzua gjeneralit Essen. Kështu u hap skaji verior i vijës mbrojtëse të Danubit.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Dorëzimi i Ruses — humbet edhe bregu jugor i Danubit", "084062e8"], "d": ["Ruseja i rezistoi rrethimit të gjatë e të përgjakshëm të ushtrisë ruse nën komandën e kontit Kaminski; u dorëzua me kusht që garnizoni dhe popullsia civile ta linin qytetin të sigurt. Rënia e qytetit-kështjellë më të fortë në bregun jugor të Danubit e ktheu rrjedhën e luftës në favor të Rusisë.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["U krijua Ocaku i Eshkinxhinjve", "67c56759"], "d": ["Mahmudi II urdhëroi krijimin e një njësie të re me ushtarë të zgjedhur brenda ocakut të jeniçerëve, që do të stërviteshin sipas modelit evropian. Sipas zërit për Ocakun e Eshkinxhinjve në Enciklopedinë Islame të TDV-së, njësia nisi stërvitjen më 12 qershor 1826, por jeniçerët e panë këtë si fundin e ocakut të tyre. Kryengritja që shpërtheu tre ditë më vonë i dha fund edhe jetës së shkurtër të Ocakut të Eshkinxhinjve.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["U krijua Asakir-i Mansure-i Muhammedije", "14b84a7e"], "d": ["Menjëherë pas shfuqizimit të Ocakut të Jeniçerëve, Mahmudi II urdhëroi krijimin në vend të tij të një ushtrie të re të rregullt, të stërvitur sipas modelit evropian. Sipas zërit për Asakir-i Mansure-i Muhammedije në Enciklopedinë Islame të TDV-së, kjo ushtri, ndryshe nga përpjekjet e mëparshme, u bë një institucion i qëndrueshëm me sistemin e gradave, programin e stërvitjes dhe sistemin e pagave. Në vitet pasuese ushtria do të shndërrohej në ushtrinë Nizamije të periudhës së Tanzimatit.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["U mbyll tarikati bektashian", "f7d9a367"], "d": ["Njëkohësisht me shfuqizimin e Ocakut të Jeniçerëve, u ndalua edhe tarikati bektashian, i njohur për lidhjet fetare me ocakun. Sipas zërit për bektashizmin në Enciklopedinë Islame të TDV-së, disa shehë teqesh të vogla u ekzekutuan, ndërsa shehu i dergahut të Haxhi Bektashit u internua në Amasja dhe teqetë iu kaluan në administrim nakshibendinjve. Pavarësisht këtij goditjeje të rëndë, tarikati e vazhdoi fshehurazi organizimin e vet.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Ngjarja e freskores — preteksti i pushtimit", "e949001e"], "d": ["Gjatë një takimi të tensionuar për shkak të mospagimit të borxhit të vjetër të drithit që Franca i kishte Algjerisë, deji Hysejn e goditi konsullin francez Deval me freskoren që mbante në dorë. Kjo ngjarje, që lindi nga një mosmarrëveshje borxhi, u bë preteksti zyrtar i pushtimit që do të fillonte tre vjet më vonë.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Bllokada franceze e bregdetit të Algjerisë — rrethim trevjeçar", "d0ba97a5"], "d": ["Pas ngjarjes së freskores, Franca vuri nën bllokadë bregdetin e Algjerisë. Bllokada zgjati tre vjet; tregtia detare dhe burimet e të ardhurave të ocakut u shteruan, dhe aftësia e tij për të rezistuar u gërrye para se të fillonte pushtimi.", "79d27be2"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Rënia e dytë e Brailës — cari Nikolla para kështjellës", "eb6a8741"], "d": ["Braila, që iu kthye osmanëve më 1812 dhe u rifortifikua në vitet 1817-1818, u rrethua në prill, kur brenda kishte 4000 roja dhe 278 topa. Komandanti i saj, Ebubekir Pasha, ngriti një vijë të re mbrojtjeje; cari Nikolla I erdhi vetë para kështjellës në fund të majit. Qyteti u pushtua nga rusët, por me Traktatin e Edrenesë do të kthehej dhe do t'i lihej principatës së Vllahisë.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Fesi shpallet mbulesë zyrtare e kokës", "f55be4eb"], "d": ["Mahmudi II bëri një ndryshim rrënjësor në veshjen e nëpunësve dhe ushtarëve dhe në vend të çallmës shpalli fesin si mbulesë zyrtare të kokës. Sipas zërit për fesin në Enciklopedinë Islame të TDV-së, ky vendim u shpall me një hatt-i humajun dhe u vu në zbatim bashkë me reformat e stilit perëndimor të Asakir-i Mansure-i Muhammedijes. Ndryshimi nënkuptonte edhe fundin e hierarkisë tradicionale të veshjes.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Ahiska i lëshohet Rusisë — humbet qendra e ejaletit të Çëlldërit", "e2e00b2a"], "d": ["Ahiska, që ishte nën sundimin osman që nga Beteja e Çëlldërit e vitit 1578 dhe shërbente si qendër e ejaletit të Çëlldërit, iu lëshua Rusisë me Traktatin e Edrenesë, të nënshkruar në fund të luftës së viteve 1828-1829. Humbja e qytetit shkaktoi pikëllim të thellë te populli dhe u bë temë e shumë vajtimeve. Me këtë ngjarje Rusisë i kaluan Ahëlqeleku, Zazalo dhe Ts'q'altbila (rajoni Ahiska–Ahëlqelek).", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Zbarkimi në Sidi Ferruc — ushtria franceze në tokën e Algjerisë", "33327553"], "d": ["Pas bllokadës trevjeçare, ushtria franceze e zbarkimit nën komandën e Comte de Bourmont zbarkoi ushtarë në gjirin e Sidi Ferrucit, në perëndim të Algjerit. Forcat që përparuan drejt qytetit e thyen vijën e mbrojtjes brenda tri javësh; më 4 korrik ra Kështjella e Perandorit, që dominonte qytetin, dhe të nesërmen deji Hysejn u dorëzua.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Internimi i dej Hysejnit — fundi de facto i ocakut të Algjerisë", "e122403b"], "d": ["Sipas kushteve të dorëzimit, deji i fundit i Algjerisë, Hysejni, u nxor nga qyteti bashkë me familjen dhe thesarin e tij dhe u dërgua në Napoli. Kështu mori fund administrimi i ocakut, që më 1519 iu nënshtrua Selimit I (Javuz) dhe për treqind vjet ishte baza detare osmane më e fuqishme e Mesdheut.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Tërheqja e ushtrisë ruse nga Vllahia dhe Moldavia — fundi i pushtimit gjashtëvjeçar", "efdb0275"], "d": ["Në luftën osmano-ruse të viteve 1828-1829 rusët kishin pushtuar Vllahinë dhe Moldavinë dhe, edhe pas Traktatit të Edrenesë, nuk u tërhoqën derisa të paguhej dëmshpërblimi i luftës. Kur në janar 1834 dëmshpërblimi u ul në pesë milionë, forcat ruse i liruan Dy Principatat dhe për to u emëruan vojvodë të rinj. Sovraniteti osman u kthye në letër, por Rusia e ruajti ndikimin që kishte vendosur me Rregulloren Organike.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["U krijua organizata Redif-i Asakir-i Mansure", "15947493"], "d": ["Organizata Redif, si forcë rezervë që do të mbështeste Asakir-i Mansure-i Muhammedijen, u krijua me rregulloren e datës 8 korrik 1834. Sipas zërit për Redifin në Enciklopedinë Islame të TDV-së, nën drejtimin e seraskerit Koxha Husrev Pasha, në kazatë e provincave u formuan batalione me rreth nga një mijë e katërqind vetë. Organizata ishte projektuar që të mbështeste edhe sigurinë vendore, pa u marrë në shërbim të përhershëm.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["U themelua Ministria e Punëve të Jashtme", "750c6c7d"], "d": ["Mahmudi II shfuqizoi postin e Reisulkutabit, që drejtonte punët e jashtme, dhe në vend të tij themeloi Ministrinë e Punëve të Jashtme (Harixhije Nezareti). Sipas zërit për Harixhije Nezaretin në Enciklopedinë Islame të TDV-së, ministri i parë i ministrisë së re u emërua Mehmed Akif Pasha, dhe institucioni nisi punën në sarajin e ambasadorit në Vjenë, Rifat Bej. Ky rregullim shënoi fillimin e drejtimit të politikës së jashtme osmane sipas parimit modern ministror.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["U themelua Mexhlis-i Vala-i Ahkam-i Adlije", "69db056e"], "d": ["Mahmudi II urdhëroi themelimin e Mexhlis-i Vala-i Ahkam-i Adlije si këshill të lartë ku do të shqyrtoheshin ligjet dhe rregulloret që do të përgatiteshin. Sipas zërit për Mexhlis-i Vala-i Ahkam-i Adlije në Enciklopedinë Islame të TDV-së, këshilli nisi punën efektivisht më 31 mars 1838, dhe pothuajse të gjitha reformat pasuese të Tanzimatit u përgatitën dhe u kontrolluan përmes këtij organi. Institucioni u bë një nga qendrat më të rëndësishme të burokracisë moderne osmane.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Sulmi i befasishëm në Sinop", "5947e93f"], "d": ["Flota ruse e Detit të Zi, nën komandën e admiralit Nakhimov, sulmoi befas, pa shpallje lufte, flotën osmane të ankoruar në portin e Sinopit; u mbytën dymbëdhjetë anije, mbi dy mijë ushtarë ranë dëshmorë dhe komandanti i flotës, Osman Pasha, u zu rob. Sipas zërit për Sinopin në Enciklopedinë Islame të TDV-së, gjatë sulmit edhe në qytet u dogjën shtatë mesxhide, dy mektebe, 247 shtëpi dhe 170 dyqane, dhe humbën jetën pesë civilë myslimanë e gjashtëmbëdhjetë të krishterë. Ngjarja, që bëri jehonë në opinionin evropian si 'fatkeqësia e Sinopit', u bë shkasi i drejtpërdrejtë që brenda pak muajsh Anglia dhe Franca të hynin në luftë në krah të osmanëve.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["U botua Tasvir-i Efkar", "506c98e2"], "d": ["Tasvir-i Efkar, që e nxirrte Shinasi, filloi të botohej si gazeta e katërt turqisht pas Takvim-i Vekaji, Xheride-i Havadis dhe Terxhuman-i Ahval. Sipas zërit \"Tasvîr-i Efkâr\" të TDV-së, gjatë periudhës së Namik Kemalit, që më vonë mori kryeredaktorinë, gazeta u bë zëdhënëse e lëvizjes së Osmanëve të Rinj.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["U themelua Shoqëria e Osmanëve të Rinj", "335fb02d"], "d": ["Intelektualët osmanë që ikën në Evropë nën nismën e Mustafa Fazil Pashës u organizuan me emrin Turqia e Re, me një statut prej trembëdhjetë nenesh. Sipas zërit \"Yeni Osmanlılar Cemiyeti\" të TDV-së, grupi nxori në Paris, Londër dhe Gjenevë gazeta si Muhbir dhe Hürriyet dhe përhapi kërkesën për qeverisje kushtetuese.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["U themelua Shura-i Devlet (Këshilli i Shtetit)", "b863b306"], "d": ["Mexhlis-i Ahkam-i Adlije u nda në dysh dhe u krijuan Shura-i Devlet, që merrej me punët administrative, dhe Divan-i Ahkam-i Adlije, që shqyrtonte çështjet gjyqësore. Sipas zërit \"Şûrâ-yı Devlet\" të TDV-së, kryetari i parë i institucionit, që mori si model Conseil d'État francez, u emërua Mit'hat Pasha; qëllimi ishte ndarja e pushteteve ligjvënës, ekzekutiv dhe gjyqësor.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Doli iradeja për themelimin e Darylfynunit", "513704bf"], "d": ["Me iradenë që përgatitën veziri i madh Ali Pasha dhe ministri i arsimit Safvet Pasha, Darylfynuni u themelua zyrtarisht; mësimet e para, megjithatë, kishin filluar më herët, më 1863. Sipas zërit \"Darülfünun\" të TDV-së, institucioni nisi efektivisht mësimin në shkurt 1870, nën drejtimin e Hoxha Tahsin Efendiut, me degët e filozofisë dhe letërsisë, të shkencave natyrore dhe të drejtësisë.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Filluan punimet për Mexhelen (Mecelle-i Ahkâm-ı Adliyye)", "8abdcbee"], "d": ["Shoqëria e Mexheles, e themeluar nën kryesinë e Ahmed Xhevdet Pashës, kryetar i Divan-i Ahkam-i Adlijes, nisi përgatitjen e një kodi civil të bazuar në fikhun hanefi. Sipas zërit \"Mecelle-i Ahkâm-ı Adliyye\" të TDV-së, pjesa e fundit e veprës, që përbëhet nga gjashtëmbëdhjetë libra dhe 1851 nene, përfundoi më 15 shtator 1876 dhe hyri në fuqi; ajo konsiderohet forma e parë e kodifikuar e së drejtës islame.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["U vu në skenë \"Atdheu ose Silistra\", Namik Kemali u internua", "3861284c"], "d": ["Kur drama me temë patriotike e Namik Kemalit u vu në skenë në Teatrin Gedikpasha, shikuesit u derdhën në rrugë duke brohoritur \"Rroftë atdheu, rroftë Kemali\". Sipas zërit \"Nâmık Kemal\" të TDV-së, qeveria u tremb nga kjo manifestim, mbylli gazetën Ibret dhe më 6 prill 1873 e internoi Namik Kemalin pa gjyq në Qipro (Famagustë).", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdylazizi vdiq në rrethana të dyshimta", "85816692"], "d": ["Abdylazizi, i cili pas rrëzimit nga froni u transferua me dëshirën e vet në Pallatin Ferije (1 qershor 1876), më 4 qershor u gjet në dhomën e tij me venat e kyçeve të dorës të prera. Një komision prej nëntëmbëdhjetë mjekësh, ku bënin pjesë edhe mjekë të ambasadave, përgatiti një raport me shprehje të paqarta; më 6 qershor vdekja u shpall në gazeta si vetëvrasje. Hetimi që urdhëroi Abdylhamidi II arriti në përfundimin se vdekja nuk ishte vetëvrasje, por vrasje, dhe të akuzuarit u gjykuan më 1881 në Gjykatën e Jëlldëzit; çështja është e diskutueshme edhe sot në historiografi.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Shkarkimi nga posti i vezirit të madh dhe internimi i Mit'hat Pashës", "b5247b06"], "d": ["Veziri i madh Mit'hat Pasha, arkitekti i Kanun-i Esasit, gjashtë javë pas shpalljes së tij u shkarkua nga Abdylhamidi II dhe brenda një nate u internua jashtë vendit. Sipas zërit për Mit'hat Pashën në Enciklopedinë Islame të TDV-së, shkarkimi lidhet me shqetësimin e padishahut për dispozitat e kushtetutës që ia kufizonin kompetencat. Pasha shkoi fillimisht në Napoli dhe pastaj në qytete të ndryshme të Evropës.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abdylazizi bin Saud ua merr rashididëve Riadin", "75eb8830"], "d": ["Abdylazizi i ri nga dinastia Saud, që dhjetë vjet më parë ishte internuar në Kuvajt, me një repart të vogël sulmoi befas Riadin, vrau zëvendësqeveritarin (kajmakam) e Al Rashidit (Shammar) dhe e shtiu në dorë qytetin. Sipas zërit për Riadin në Enciklopedinë Islame të TDV-së, dobësimi gjithnjë e më i madh i rashididëve dhe pamundësia e tyre për të dërguar përforcime në qytet e lehtësuan suksesin e këtij sulmi; ngjarja konsiderohet çasti i themelimit të Shtetit të Dytë Saudit, që gjatë tridhjetë viteve pasuese do të formonte bërthamën e Arabisë Saudite të sotme.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Hyrja e Ushtrisë së Veprimit në Stamboll", "41c8304c"], "d": ["Ushtria e Veprimit (Hareket Ordusu), që u nis nga Selaniku dhe përbëhej kryesisht nga njësi të lidhura me Itihad ve Terakkin, hyri në Stamboll për të shtypur kryengritjen e 31 marsit. Sipas zërit për Ushtrinë e Veprimit në Enciklopedinë Islame të TDV-së, komandën e saj e mori Mahmud Shevket Pasha, ndërsa shef i shtabit ishte kolagasi Mustafa Kemal. Pas përleshjeve të shkurtra, rendi u rivendos në qytet.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Shpërndarja e Mexhlis-i Mebusanit të fundit osman", "2b709269"], "d": ["Pas pushtimit zyrtar të Stambollit nga forcat e Antantës dhe arrestimit të shumë deputetëve, Mexhlis-i Mebusani nuk mundi më të punonte dhe u shpërnda zyrtarisht me iradenë e Mehmetit VI. Sipas zërit për Mexhlis-i Mebusanin në Enciklopedinë Islame të TDV-së, kjo shpërndarje simbolizoi fundin de facto të traditës së parlamentit kushtetues osman. Mbyllja e tij e përforcoi nevojën për mbledhjen e një kuvendi të ri kombëtar në Ankara.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Hapja e Kuvendit të Madh Kombëtar të Turqisë", "6eab539d"], "d": ["Pas shpërndarjes së Mexhlis-i Mebusanit në Stamboll, deputetët u mblodhën në Ankara dhe hapën Kuvendin e Madh Kombëtar të Turqisë, ndërsa Mustafa Kemal Pasha u zgjodh kryetar i kuvendit. Sipas zërit për Kuvendin e Madh Kombëtar të Turqisë në Enciklopedinë Islame të TDV-së, kuvendi pati një karakter të jashtëzakonshëm, duke përqendruar te vetja si pushtetin ligjvënës, ashtu edhe atë ekzekutiv. Kjo hapje ishte pikë kthese, me të cilën qendra politike dhe institucionale e luftës kombëtare u zhvendos në Ankara. Me këtë ngjarje, 124 vendbanime (rajonet e Turqisë që nuk ishin nën pushtim), përfshirë Konjën, Sivasin, Kajserin, Eskishehirin, Erzurumin, Trabzonin, Samsunin, Dijarbekirin, Vanin, Malatjan, Denizlin dhe Isparten, kaluan nën administrimin e qeverisë së Kuvendit të Madh Kombëtar.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Pushtimi i kështjellës së Izvornikut (Zvornikut)", "657c465a"], "d": ["Kështjella e Izvornikut në brigjet e Drinës u pushtua nga osmanët më 1460. Sipas Enciklopedisë Islame të TDV-së, për shkak të pozitës së favorshme administrative e ushtarake, fillimisht u bë qendër kazaje, më 1480 u shndërrua në qendër të sanxhakut me të njëjtin emër dhe më 1491, e fortifikuar me mure guri, u bë një qendër e rëndësishme administrative e tregtare me gjashtë xhami, tetë teqe dhe hamame.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Vdekja e Kasim Hanit, hipja në fron e Danjal Hanit (Hanati i Kasimit)", "522fd0fd"], "d": ["Pas vdekjes së themeluesit të hanatit, Kasim Hanit, në vitin 873/1468, në vendin e tij erdhi djali i tij Danjali; Danjali sundoi deri më 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Beteja detare e Diut — epërsia portugeze në Oqeanin Indian", "1778d347"], "d": ["Flota e mbështetur nga memlukët e Melik Ajazit, që e qeveriste rajonin në emër të Sulltanatit të Guxharatit, pësoi një disfatë të rëndë në ujërat para Diut përballë flotës së guvernatorit të përgjithshëm portugez Francisco de Almeida, i cili po përpiqej të ngrinte bazë furnizimi në këto brigje. Kjo disfatë i siguroi Portugalisë epërsi të qëndrueshme detare në Oqeanin Indian dhe e theu fuqinë detare memluko-guxharate; konsiderohet fillimi i pabarazisë së forcave që përbën sfondin e përplasjes për Detin e Kuq dhe Oqeanin Indian (mbrojtja e Xhidës, rrethimi i Diut më 1538), të cilën osmanët e trashëguan pas vitit 1517.", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Kryengritja e Kalender Shahut", "f60f6ca4"], "d": ["Nën ndikimin e vështirësive financiare në Anadoll, pakënaqësisë nga rregullimet e reja administrative dhe propagandës safavide, rreth Kalender Shahut u mblodhën fise të mëdha turkmene si Çiçekli, Akça Koyunlu, Masadli dhe Bozoklu, bashkë me grupet e mbetura nga kryengritja e mëparshme e Baba Zunnunit, duke arritur një forcë prej rreth tridhjetë mijë vetësh. Kryengritësit fillimisht mundën bejlerbeun e Rumit; kur veziri i madh Makbul Ibrahim Pasha mblodhi ushtarë dhe u premtoi të drejtat, mbështetja për Kalenderin u shkri, kryengritja u shtyp rreth Elbistanit, dhe Kalender Shahu me Veli Dundarin u vranë në qershor 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Pushtimi i Shehrizorit — marrja e kështjellës Zalm", "4320d9b8"], "d": ["Gjatë fushatës së Sulejmanit Kanuni në Nahçivan, bejlerbeu i Bagdadit, Osman Pasha, ishte ngarkuar të merrte krahinën e Shehrizorit; pas vdekjes së tij, Baltaxhi Mehmed Pasha, i bërë bejlerbej i Bagdadit, rrethoi dhe mori kështjellën qendrore të rajonit, Zalmin, më 22 gusht 1554 (23 ramazan 961). Kështu pellgu i Shehrizorit në shpatin perëndimor të Zagrosit hyri nën administrimin osman dhe u sigurua lidhja mes Bagdadit dhe Kurdistanit; rajoni fillimisht u bë sanxhak dhe iu dha Murad Beut. Më 1563 bejlerbeu Muzafer Pasha ndërtoi kështjellën e Gulanberit si qendër të re të ejaletit; kështjella do të rrënohej më 1623 me urdhër të Shah Abasit dhe do të rindërtohej më 1638 në kohën e Husrev Pashës.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Kalimi i sundimtarit të Hanatit të Kasimit në krishterim dhe heqja e tij nga hanati", "a1a8eeb9"], "d": ["Sundimtari në krye të hanatit mori emrin 'Semen (Simeon)' dhe u bë i krishterë; rusët, duke marrë parasysh reagimin e nënshtetasve myslimanë, e hoqën nga hanati. Pak më vonë ky person u shpall nga Ivani i Tmerrshëm sundimtar nominal në Moskë me titullin 'princi i madh i carit dhe i Rusisë' (1575) — ndërthurja më e goditëse mes Hanatit të Kasimit dhe fronit të Moskës.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Sanxhaku i Fezanit i bashkohet Tripolit (Libi) — Murzuku dhe udhëkryqi i karvaneve të Saharasë", "2e6554a4"], "d": ["Si pasojë e presionit të bejlerbellëkut të Tripolit, Fezani, udhëkryqi i karvaneve të Saharasë, me qendër Murzukun, e pranoi nënshtetësinë osmane. Sipas zërit për Fezanin në Enciklopedinë Islame të TDV-së, dinastia Evlad Muhamed, që qeveriste rajonin, u la e lirë në punët e brendshme me kusht që të paguante rregullisht taksa; Fezani u organizua si sanxhak i varur nga ejaleti i Tripolit, i marrë më 1551. Kështu tregtia e skllevërve, arit dhe deveve në vijën Tripoli-Murzuk-Bornu hyri nën kontrollin osman. Ky administrim i tërthortë do t'u kalonte më 1711 karamanlinjve, ndërsa më 1842 organizimit të drejtpërdrejtë si kaza.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Nahçivani dhe Ordubadi hyjnë nën administrimin osman", "24d939b3"], "d": ["Pasi më 1583 u mor Revani dhe u bë qendër bejlerbellëku, forcat që zbritën drejt juglindjes përgjatë luginës së Arasit i lidhën Nahçivanin dhe Ordubadin me administrimin osman; të dy qytetet u bënë sanxhaqe të ejaletit të sapokrijuar të Revanit. Sipas zërit për Nahçivanin në Enciklopedinë Islame të TDV-së, administrimi i parë i qëndrueshëm osman në qytet u vendos gjatë kësaj lufte — në fushatën e Nahçivanit të vitit 1553 qyteti ishte marrë, por vetëm ishte plaçkitur e braktisur. Kështu u hap rruga ushtarake mes Revanit dhe Tabrizit dhe në shtator të po atij viti u mundësua hyrja në Tabriz. Shah Abasi do ta rimerrte Nahçivanin më 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Kryengritja e Deli Hasan Pashës dhe qetësimi i saj me bejlerbellëkun e Bosnjës", "144f3f2d"], "d": ["Pas vdekjes më 1602 të udhëheqësit xhelali Karajazëxhë Abdylhalimit, vëllai i tij Deli Hasani, që u vu në krye të lëvizjes, duke përfituar nga liria e veprimit që luftërat e vazhdueshme me Austrinë u jepnin grupeve xhelali, pushtoi Kytahjan dhe marshoi mbi Afjonkarahisar. Në këtë periudhë, kur shteti përballej njëkohësisht me frontet e Austrisë dhe Iranit, çështja u zgjidh 'me të butë': Deli Hasanit iu dha grada pashë dhe bejlerbellëku i Bosnjës, dhe lëvizjes kryengritëse iu dha fund zyrtarisht më 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Marrja e qytetit të Kasimit nga forcat ruse, Uraz Muhamed Hani", "b3f0bd34"], "d": ["Si pasqyrim i Kohës së Trazirave (Smuta) në Rusi, forcat ruse rrethuan dhe morën qytetin e Kasimit dhe vranë me shpatë shumicën e banorëve. Uraz Muhamedi në krye të hanatit ishte shënjestruar sepse kishte përkrahur Dmitrin e Rremë II; vitin pasues (1610) u vra edhe vetë nga një komplot.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Humbja e kështjellës së Azovit në favor të kozakëve të Donit", "ba068b2f"], "d": ["Kozakët e Donit e shtinë në dorë kështjellën e Azovit, të cilën e rrethuan më 21 prill 1637, dy muaj më vonë; kështjella, porta verilindore e Detit të Zi dhe çelësi i tregtisë së Donit, doli për herë të parë nga dora osmane. Sipas zërit për Azovin në Enciklopedinë Islame të TDV-së, kozakët e morën kështjellën më 1637, më 1641 i rezistuan rrethimit të madh tremujor nën komandën e Deli Husein Pashës dhe e liruan kështjellën vetëm më 1642, me ardhjen e khanit të Krimesë, Mehmed Giraj. Shteti atëherë ishte i zënë me frontin e Bagdadit; fakti që kështjella nuk mundi të mbahej për pesë vjet është çarja e parë në cilësinë e Detit të Zi si 'liqen osman'.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Rimarrja e Limnosit dhe Samotrakës", "c445553b"], "d": ["Pas çlirimit të Tenedosit më 31 gusht 1657, Mehmed Pashë Qyprilliu e drejtoi flotën nga veriu dhe rimori Limnosin dhe Samotrakën, që Venediku i kishte mbajtur për gjashtëmbëdhjetë muaj. Sipas zërit për Limnosin në Enciklopedinë Islame të TDV-së, ishulli kishte kaluar në duart e Venedikut në korrik 1656 dhe u rimor në nëntor 1657. Kështu bllokada venedikase në hyrje të ngushticës së Çanakalasë u thye tërësisht dhe rruga e drithit për në Stamboll u sigurua sërish; ky është fitimi më konkret i vitit të parë të vezirit të madh, i ardhur me kompetenca të jashtëzakonshme.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Humbja e Kninit në favor të Venedikut — ra kështjella kufitare 166-vjeçare e Dalmacisë", "252406b7"], "d": ["Në luftën me shumë fronte që u hap pas disfatës së Vjenës të vitit 1683, forcat venedikase përparuan në brendësi të Dalmacisë. Knini, i rrethuar nga gjenerali i Dalmacisë Girolamo Cornaro, u dorëzua nga bejlerbeu Mehmed Pasha pas një rrethimi dymbëdhjetëditor. Knini ishte kështjella kyçe e vijës kufitare të Dalmacisë, që Gazi Husrev Beu e kishte pushtuar më 1522 dhe që mbeti 166 vjet në duart osmane; humbja e tij ia hapi rajonin në masë të madhe Venedikut.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Rimarrja e Basrës nga pushtimi iranian", "5b10c5c1"], "d": ["Basra, që Sadik Hani, vëllai i Kerim Han Zendit, e kishte shtënë në dorë më 1776, u lirua kur pas vdekjes së Kerim Hanit më 2 mars 1779 në Iran filloi lufta për fron; Sadik Hani u kthye në Iran me pretendim për sundim. Qyteti, pasi mbeti për pak kohë në duart e fisit Muntefik, hyri sërish nën administrimin osman. Ish-mytesellimi Sulejman Aga, i kthyer nga Shirazi, kërkoi guvernatorllëkun e Basrës dhe, me emrin Sulejman Pasha i Madh, u bë guvernator i Basrës, Bagdadit dhe Shehrizorit. Tregtia e Gjirit u kthye nën kontrollin osman; gjatë viteve të pushtimit një pjesë e tregtisë kishte kaluar në Kuvajt dhe që nga viti 1778 edhe posta e shkretëtirës nisej prej andej.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Vdekja e Timur Shahut, hipja në fron e Zaman Shahut (Shteti Durrani)", "c3effdb2"], "d": ["Me vdekjen e Timur Shahut, i cili për më shumë se njëzet vjet e kishte konsoliduar vendin nga brenda, tre vëllezërit, guvernatorë të Kandaharit, Heratit dhe Kabulit, u përleshën për fronin; guvernatori i Kabulit, Zaman Shahu, që mbante kryeqytetin, u bë shah më 20 maj 1793. Kjo krizë trashëgimie është fillimi de facto i procesit të copëtimit të dinastisë.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — shfuqizimi i sistemit tradicional kapu në Hawai", "0b10e1d8"], "d": ["Gjashtë muaj pas vdekjes së Kamehameha I, mbreti i ri Liholiho, me mbështetjen e nënës së tij Kaʻahumanu, e shkeli me vetëdije ndalimin që burrat dhe gratë të hanin veç (ʻaikapu). Ky veprim, i njohur si 'ʻAi Noa' (ngrënia e lirë), i dha fund zyrtarisht sistemit tradicional fetar-juridik kapu; tempujt e vjetër (heiau) në ishuj u shkatërruan brenda pak kohe. Është çarja më e madhe fetare-politike para ardhjes së misionarëve perëndimorë (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protokolli i Londrës — njohja e pavarësisë së Greqisë", "4c7b4b72"], "d": ["Protokolli që Anglia, Franca dhe Rusia nënshkruan në Londër e tejkaloi autonominë e parashikuar nga Traktati i Edrenesë dhe e njohu Greqinë si shtet TË PAVARUR. Dispozitat: gadishulli i Moresë, Atika, Eubea dhe ishujt Ciklade iu lanë shtetit të ri; kufiri u vizatua në vijën Arta-Volos; u vendos t'i paguhej Shtetit Osman një dëmshpërblim; forma e qeverisjes së shtetit u përcaktua si 'monarki e pavarur'. Ky është shteti I PARË i pavarur që u shkëput nga perandoria dhe krijoi precedentin juridik për pavarësitë ballkanike të mëvonshme. Greqisë, pavarësia e së cilës u njoh me Protokollin e Londrës, iu përfshinë ishujt Ciklade (Naksos, Tinos, Santorini, Paros, Milos, Siros, Mikonos etj.).", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah bin Reshidi mori emiratin e Hailit — themelimi i dinastisë Shammar (rashidide)", "fb513b8a"], "d": ["Kur më 1818 forcat e Mehmed Ali Pashës rrëzuan Dirijen, rajoni i Xhebel Shammarit doli nga sundimi saud dhe emirati mbeti në duart e familjes Ibn Ali. Abdullah bin Reshidi, që e përkrahte rivendosjen e sundimit osman, bashkë me vëllain e tij Ubejdin fitoi më 1835 luftën kundër familjes Ibn Ali, mori emiratin e Hailit dhe vendosi sundimin e dinastisë rashidide.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["U shpall kushtetuta e parë e shkruar e Hawait", "401a8a1d"], "d": ["U shpall kushtetuta e parë e plotë e shkruar e mbretërisë; ky dokument, që kufizonte pushtetin e mbretit dhe krijonte një kuvend përfaqësues, e shndërroi Hawain në monarki kushtetuese.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Kushtetuta e Bajonetës — u cunguan kompetencat e mbretit Kalākaua", "4953363b"], "d": ["Një grup i armatosur milicie e kërcënoi mbretin Kalākaua dhe e detyroi të nënshkruante një kushtetutë të re që ia cungonte në masë të madhe kompetencat mbretërore; dokumenti njihet si 'Kushtetuta e Bajonetës' (Bayonet Constitution) dhe faktikisht e vuri fronin nën kontrollin e elitës së kolonëve të bardhë.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Vdekja e George Tupou I, hipja në fron e George Tupou II (Tonga)", "b56e2b32"], "d": ["Me vdekjen e mbretit themelues George Tupou I, në fron hipi stërnipi i tij George Tupou II; ceremonia e kurorëzimit u bë më 17 mars 1893 në Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Zelanda e Re u bë vendi i parë vetëqeverisës që u dha grave të drejtën e votës", "0d277cde"], "d": ["Me ligjin e ri zgjedhor të nënshkruar nga guvernatori lord Glasgow, Zelanda e Re u bë vendi i parë vetëqeverisës në botë që u dha grave të drejtën e votës në zgjedhjet parlamentare.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["U shpall Republika e Hawait", "4346bd5d"], "d": ["Komplotistët që më 1893 rrëzuan mbretëreshën Liliuokalani e shndërruan qeverinë e përkohshme në një republikë zyrtare; Sanford Dole u shpall president. Ky regjim i ndërmjetëm zgjati deri në aneksimin nga SHBA-të më 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["Kufijtë e Zelandës së Re u zgjeruan duke përfshirë Ishujt Cook dhe Niuen", "d0370a33"], "d": ["Kufijtë e Zelandës së Re u zgjeruan duke përfshirë Ishujt Cook (Rarotonga, Aitutaki dhe ishujt jugorë, si edhe Ishujt Cook Veriorë) dhe Niuen; këta ishuj u bënë territore të varura nga Zelanda e Re.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Vdekja e George Tupou II, hipja në fron e Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II vdiq nga tuberkulozi; vajza e tij 18-vjeçare, Sālote, u shpall mbretëreshë të nesërmen, ndërsa ceremonia e kurorëzimit u bë më 11 tetor 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Traktati i Sevrës — teksti i copëtimit të perandorisë", "64980d7b"], "d": ["Teksti që qeveria osmane nënshkroi me shtetet e Antantës dhe që faktikisht e likuidonte perandorinë. Dispozitat: Traka Lindore dhe rajoni i Izmirit iu lanë Greqisë; në Anadollin Lindor u parashikuan një Armeni e pavarur dhe një Kurdistan autonom; Siria iu la Francës, ndërsa Iraku dhe Palestina Anglisë si mandat; Ngushticat iu dorëzuan një komisioni ndërkombëtar; ushtria u kufizua në 50.700 vetë, kapitulacionet u rikthyen dhe financat u vunë nën kontrollin e Antantës. Kuvendi i Madh Kombëtar në Ankara NUK E NJOHU KURRË traktatin dhe i shpalli nënshkruesit tradhtarë të atdheut; teksti nuk hyri në fuqi dhe më 1923 në vend të tij erdhi Lozana. Kjo është arsyeja pse ai nuk ka pasqyrim në hartë — Sevra juridikisht nuk u zbatua kurrë.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Ushtria e Kuqe hyri në qytetin e Buharasë — emiri i fundit Alim Han u largua nga froni", "f8f5bfcf"], "d": ["Ushtria e Kuqe hyri në qytetin e Buharasë më 2 shtator 1920 dhe emiri i fundit mangit Alim Hani u largua nga froni. Emiri u tërhoq në lindje të vendit, në Dushanbe, dhe për gjysmë viti e drejtoi prej andej luftën kundër sovjetikëve; Ushtria e Kuqe e mori Dushanbenë më 21 shkurt 1921, emiri kaloi më në lindje dhe prej andej në Afganistan. Hanati u shfuqizua zyrtarisht më 6 tetor 1920 (shih Republikën Popullore Sovjetike të Buharasë).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["U shpall Republika Popullore Sovjetike e Buharasë", "ef579627"], "d": ["Pasi Ushtria e Kuqe më 28-31 gusht 1920 shkatërroi Emiratin e Buharasë dhe e detyroi emirin Alim Han të ikte në Buharanë Lindore, u shpall Republika Popullore Sovjetike e Buharasë nën kryesinë e Fejzullah Hoxhajevit.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["Republika Popullore Tannu Tuva shpalli pavarësinë", "8710ea3d"], "d": ["Pavarësia u shpall nën udhëheqjen e Partisë Popullore Revolucionare të Tuvës; neni i parë i kushtetutës së parë thoshte se shteti vepronte 'në marrëdhëniet ndërkombëtare nën protektoratin e Rusisë Sovjetike'. Me këtë ngjarje Kyzyli (Bellocarski, Tannu-Tuva) i kaloi Republikës Popullore Tannu-Tuva.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Republika Popullore Sovjetike e Buharasë miratoi kushtetutën e re", "fb17bf39"], "d": ["U miratua një kushtetutë e re që, ndryshe nga kushtetuta ruse e vitit 1918, lejonte pronën private mbi tokën dhe mjetet e prodhimit dhe u jepte të drejtën e votës edhe jo-proletarëve (me përjashtim të të afërmve të emirit të rrëzuar dhe pronarëve të mëdhenj të tokave).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Shndërrimi në Republikë Socialiste Sovjetike të Horezmit", "14a1d26f"], "d": ["Vendi ndryshoi emrin dhe statusin dhe u bë Republika Socialiste Sovjetike e Horezmit; struktura administrative-juridike u riorganizua sipas sistemit sovjetik.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["Qeveria e Tannu Tuvës nisi faktikisht detyrën", "22ea1516"], "d": ["Qeveria e formuar pas mbledhjes së parë të partisë në shkurt 1922 nisi faktikisht detyrën.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["U mblodh Kurultai i parë i Madh i Tannu Tuvës", "80fe15f2"], "d": ["U mblodh Kurultai i parë i Madh (Kuvendi Popullor) i vendit; kjo është mbledhja e parë e madhe përfaqësuese në procesin e institucionalizimit të shtetit.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Fundi i RSS-së së Horezmit dhe i Republikës Popullore Sovjetike të Buharasë me delimitimin kombëtar — themelimi i RSS-ve të Uzbekistanit dhe Turkmenistanit", "e8c8ab4f"], "d": ["Me vendimin sovjetik për 'delimitimin kombëtar' (natsionalno-territorialnoe razmezhevanie), Republika Socialiste Sovjetike e Horezmit dhe Republika Popullore Sovjetike e Buharasë u shfuqizuan; tokat e tyre u ndanë mes Republikave Socialiste Sovjetike të sapokrijuara të Uzbekistanit dhe Turkmenistanit (lindja e Hivës Uzbekistanit, perëndimi Turkmenistanit). Zëri `harizm` i TDV-së: 'Më 1924 pjesët lindore të Hanatit të Hivës iu lanë Republikës Socialiste Sovjetike të Uzbekistanit, ndërsa ana perëndimore Republikës Socialiste Sovjetike të Turkmenistanit.' — jep vetëm vitin.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Shitja e Alaijes sulltanit memluk Barsbaj", "c8bd35f2"], "d": ["Alaija, që karamanoglu Mexhdyddin Mahmud Beu e kishte shtënë në dorë më 1293, ishte bërë një bejlik i veçantë i qeverisur nga një degë e Karamanëve; Ibn Batuta shënon më 1333 se administrimi ishte në duart e karamanoglu Jusuf Beut. Karaman b. Savxhi Beu më 1427 ia shiti qytetin sulltanit memluk Barsbaj për pesë mijë florinj ari dhe Alaija hyri nën administrimin memluk. Kështu ky port kyç i Mesdheut u bë, në duart e memlukëve, pengesë në rrugën osmane drejt jugut; kur Gedik Ahmed Pasha e rrethoi më 1471, beu i fundit, Këlëçarslani, e dorëzoi qytetin.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Marrja e Tabarkës nga gjenovezët — fundi i privilegjit të koraleve të Lomellinëve", "b1f33eb5"], "d": ["Pas traktatit që Karli V bëri me beun e Tunizisë më 1544, familja gjenoveze Lomellini u vendos në ishullin Tabarka dhe për dyqind vjet e mbajti privilegjin e koraleve; ishulli mbeti një postë tregtare e krishterë në mes të Tunizisë osmane. Kur Ali Pasha nga dinastia husainide mori vesh përpjekjen e familjes për ta shitur ishullin, dërgoi forca dhe më 12 qershor 1741 e shtiu në dorë; rreth një mijë e pesëqind të krishterë u transferuan në Tunis. Pas kësaj date Tabarka hyri nën administrimin e ocakut të Tunizisë.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Beteja e Piramidave dhe marrja e Kajros nga francezët", "3ddd6b96"], "d": ["Napoleoni marshoi nga Aleksandria drejt jugut përgjatë Nilit dhe më 21 korrik 1798 në Imbaba, përballë Gizës, u përball me kalorësinë mameluke të Murad Beut. Këmbësoria franceze në formacion katror i theu sulmet e kalorësisë; ushtria mameluke u shpërnda dhe dy ditë më vonë Kajro u dorëzua pa rezistencë. Murad Beu u tërhoq në Egjiptin e Epërm, Ibrahim Beu në Siri. Francezët ngritën në Kajro një divan dhe u përpoqën ta drejtonin administrimin përmes ulemave; në tetor 1798 dhe në mars 1800 shpërthyen dy kryengritje të mëdha në Kajro.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Rrethimi i Akrës nga Napoleoni — ndalimi i fushatës në Siri", "d2a947ad"], "d": ["Duke dashur të shpërndante forcat që osmanët po përgatisnin për të rimarrë Egjiptin, Napoleoni në fillim të vitit 1799 marshoi drejt Sirisë; mori Arishin më 18 shkurt, Jafën në mars dhe më 18 mars 1799 rrethoi Akrën. Mbrojtja e Xhezar Ahmed Pashës dhe mbështetja nga deti e admiralit anglez Sidney Smith e thyen rrethimin për dy muaj; meqë topat e rrethimit u kapën në det, muret nuk mundën të kapërceheshin. Napoleoni u tërhoq në maj dhe kjo disfatë u bë pika më e largët e pushtimit francez.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Themelimi i shtetit të emir Abdylkadirit — centralizimi i rezistencës në Algjerinë Perëndimore", "9e482383"], "d": ["Rezistenca e shpërndarë pas rënies së Algjerit u mblodh rreth Abdylkadirit të ri, djalit të shehut kadiri Muhjiddinit; më 22 nëntor 1832, pranë Muaskarit, krerët e fiseve i dhanë betimin e besnikërisë si 'emir el-muminin'. Struktura që ngriti nuk ishte aleancë fisesh, por shtet i rregullt: kishte punishte monedhash, fabrikë baruti, rend taksash dhe një kryeqytet në Tagdempt. Me Traktatin e Tafnës të vitit 1837 Franca e njohu zyrtarisht sundimin e tij. Abdylkadiri nuk kërkoi mbrojtjen e osmanëve, por sovranitetin e sulltanit të Marokut, Abdurrahmanit; pra këto toka pas vitit 1832 nuk janë nën nënshtetësi osmane. Më 23 dhjetor 1847 ai u dorëzua, dhe po atë vit edhe Shteti Osman shpalli fundin e të drejtave të veta mbi Algjerinë.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Rënia e Konstantinës — fundi i bejlikut të Algjerisë Lindore", "159fed36"], "d": ["Pas rënies së Algjerit më 1830, bejlerbellëku lindor nuk u shpërbë: beu i fundit, Ahmedi, vazhdoi administrimin e vet në Konstantinë dhe shpalli se vepronte në emër të osmanëve. Fushata e parë franceze e vitit 1836 përfundoi me disfatë; fushata e dytë e rrethoi qytetin më 6 tetor 1837, komandanti Damrémont vdiq nga zjarri i topave më 12 tetor, dhe më 13 tetor u kapërcyen muret dhe qyteti u mor rrugë më rrugë. Ahmed Beu u tërhoq në male dhe u dorëzua vetëm më 1848. Kjo datë është mbarimi de facto i administrimit osmano-turk treqindvjeçar në lindje të Algjerisë.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Pushtimi i rajonit të Takës dhe themelimi i Kasalasë", "cc3e0631"], "d": ["Sundimtari i Sudanit, Ahmed Pasha Ebu Vidan, më 1840 e vuri nën administrimin egjiptian rajonin e Takës mes lumenjve Atbara dhe Gash dhe themeloi qytetin e Kasalasë si seli ushtarake. Qyteti u bë qendër mudirijeti që kontrollonte rrugën e karvaneve mes Senarit dhe Suakinit dhe brezin kufitar me Abisininë.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Pushtimi francez i Muaskarit (Mascara) — humbja e kryeqytetit të Abdylkadirit", "bd363c05"], "d": ["Me ardhjen e Bugeaud-it në guvernatorllëk më 1841, strategjia franceze ndryshoi: në vend që të mbaheshin në bregdet, të pushtonin një nga një qytetet e brendshme. Kolonat lëvizëse që dolën nga Orani, Mostaganemi dhe Medea morën qendrat e shtetit të rregullt të Abdylkadirit; më e rëndësishmja ishte Muaskari, një kryeqytet i vërtetë me punishte monedhash, fabrikë baruti dhe depo drithi. Pas kësaj emiri hoqi dorë nga ngritja e një qendre të qëndrueshme dhe e shndërroi ushtrinë në kampin nomad të quajtur 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Pushtimi i luginës së Chelifit dhe i Tenesit — themelimi i Orléansville-it", "e1eeeb68"], "d": ["Për të ndjekur Abdylkadirin, francezët në prill 1843 themeluan në mes të luginës së Chelifit një qytet të ri me emrin Orléansville; po atë vit u pushtua edhe porti bregdetar i Tenesit. Kështu korridori i brendshëm mes Algjerit dhe Oranit hyri nën kontrollin francez dhe rezistenca në malet e Dahrës u rrethua. Më 16 maj të po atij viti kampi nomad i Abdylkadirit, 'smala', u gjet rastësisht dhe u shpërnda.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Ngritja e kampit të fortifikuar të Sidi Bel Abbesit", "fb33ec29"], "d": ["Më 12 qershor 1843 Bugeaud i dha gjeneralit Bedeau urdhrin të ngrinte në Sidi Bel Abbes një kamp të fortifikuar me hendek e mure; ndërtimi filloi më 18 qershor dhe në nëntor të po atij viti një batalion i Legjionit të Huaj u vendos aty. Kampi u bë bazë e përhershme që kontrollonte fushën e brendshme mes Oranit dhe Tlemcenit.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Kalimi i Nedromës dhe i brezit kufitar me Marokun nën kontrollin francez", "61d821f3"], "d": ["Pas tërheqjes së Abdylkadirit në Marok më 1843, Nedroma në veriperëndim të Tlemcenit dhe bregdeti i Trarës hynë nën kontrollin francez. Beteja e Islyt, më 14 gusht 1844, e shpartalloi ushtrinë marokene, dhe kufiri mes dy vendeve u vizatua me Konventën e Lalla Maghnias të 18 marsit 1845; Nedroma mbeti në anën algjeriane të kësaj vije.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Rënia e Laghouatit — hapja e portës së Saharasë", "b161b32c"], "d": ["Gjenerali Pélissier, me një forcë prej gjashtë mijë vetësh, rrethoi Laghouatin më 21 nëntor 1852, dhe më 4 dhjetor qyteti ra me një sulm të përgjakshëm. Laghouati ishte qytet-oazë që mbante kalimin mes Tellit dhe Saharasë; rënia e tij ua hapi francezëve rrugët e karvaneve të shkretëtirës dhe përgatiti rrugën që brenda një viti konfederata e Mzabit të detyrohej të paguante taksë.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Aneksimi i rajonit të Bogosit (Kerenit) nga Egjipti", "b2ab83ce"], "d": ["Werner Munzinger Pasha, guvernator i vilajetit 'Sudani Lindor dhe Bregdeti i Detit të Kuq' që hidivi Ismail e kishte krijuar në bregun perëndimor të Detit të Kuq, më 1872 i bashkoi Egjiptit rajonin e Bogosit, ku jetonte populli bilen, dhe qendrën e tij, Kerenin. Ky ishte përparimi më i qëndrueshëm i Egjiptit në buzë të pllajës abisinase dhe nisi me Abisininë një mosmarrëveshje kufitare që zgjati dymbëdhjetë vjet.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Aneksimi i Sulltanatit të Darfurit nga Egjipti — Zubejr Pasha hyri në El Fasher", "f41268ed"], "d": ["Zubejr Rahmet Pasha, i fuqizuar nga tregtia e fildishit dhe skllevërve, me forcat e tij të armatosura me pushkë Remington, më 25 tetor 1874 shpërndau ushtrinë fur në Manawashi; sulltan Ibrahimi vdiq në betejë. Më 2 nëntor Zubejri hyri në El Fasher pa përleshje dhe sundimi i dinastisë Keira, që kishte zgjatur që nga viti 1603, mori fund de facto. Kështu Darfuri iu bashkua provincave sudaneze të Egjiptit të Mehmed Ali Pashës së Kavallës; por rezistenca e familjes Keira në male vazhdoi deri më 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Aneksimi i oazave të Mzabit (Ghardaia)", "9372959f"], "d": ["Qytetet ibadite të Mzabit më 1852 kishin pranuar t'i paguanin taksë Francës, por kishin ruajtur administrimin e brendshëm; tridhjetë vjet më pas, më 1882, rajoni iu bashkua drejtpërdrejt territorit francez dhe Ghardaia u lidh me administratën ushtarake. Kështu mori fund juridikisht edhe brezi i fundit autonom i Saharasë veriore.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Bombardimi i Aleksandrisë dhe zbarkimi anglez", "18d57bf8"], "d": ["Kur lëvizja e oficerëve nën udhëheqjen e Urabi Pashës e vuri hidivin nën kontroll, Anglia ndërhyri me pretekstin e sigurisë së rrugës së Suezit. Flota e admiralit Seymour bombardoi më 11-12 korrik 1882 fortifikimet bregdetare të Aleksandrisë; pas zjarrit dhe plaçkitjes në qytet, më 15 korrik trupat angleze zbarkuan në tokë. Shteti Osman nuk mundi ta pengonte këtë operacion në një vilajet ku juridikisht ishte sovran, dhe la pa përgjigje edhe ftesën për të marrë pjesë në ndërhyrje. Kështu u hodh hapi i parë i një pushtimi që do të zgjaste tridhjetë e dy vjet.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Beteja e Tel el-Kebirit — shpartallimi i ushtrisë së Urabiut", "8e38fecf"], "d": ["Wolseley i zbarkoi forcat në Ismailije përmes Kanalit të Suezit, i marshoi nëpër shkretëtirë dhe në agimin e 13 shtatorit 1882 sulmoi befas llogoret egjiptiane në Tel el-Kebir; beteja përfundoi brenda një ore. Urabiu u dorëzua të nesërmen dhe kalorësia angleze hyri në Kajro po atë ditë. Pas kësaj date punët financiare, ushtarake dhe të jashtme të Egjiptit kaluan faktikisht nën kontrollin anglez; sovraniteti osman, megjithatë, vazhdoi juridikisht deri më 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Konventa e La Marsas — plotësimi i protektoratit mbi Tunizinë", "71338640"], "d": ["Traktati i Bardos (Kasr Said) i 12 majit 1881 ia kishte lënë Francës punët e jashtme të Tunizisë, por administrimin e brendshëm beut; dy vjet më vonë, Konventa e La Marsas, e nënshkruar më 8 qershor 1883, vuri edhe reformat financiare e administrative nën kontrollin francez dhe e plotësoi protektoratin. Shteti Osman e ruajti pretendimin për sovranitet mbi Tunizinë dhe nuk e njohu kurrë pushtimin, por nuk mundi të ndërmerrte ndonjë kundërveprim konkret. Kështu Tunizia, ocak osman që nga viti 1574, hyri zyrtarisht nën protektoratin francez.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Disfata e Shejkanit — asgjësimi i ushtrisë së Hicks Pashës", "a0e08986"], "d": ["Hicks Pasha, oficer anglez në pension, i dërguar nga Kajro në krye të një force egjiptiane prej rreth dhjetë mijë vetësh, duke përparuar pa ujë e pa udhërrëfyes nëpër shkretëtirën e Kordofanit, më 5 nëntor 1883 u rrethua në Shejkan nga forcat mahdiste dhe ushtria u asgjësua pothuajse tërësisht. Kjo disfatë ia theu shtyllën kurrizore administrimit egjiptian në Sudan: brenda një muaji u dorëzuan Darfuri dhe Bahr el-Ghazali dhe i tërë Kordofani kaloi te Mahdiu. Rruga drejt rënies së Kartumit fillon këtu.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Kalimi i Darfurit në duart e forcave mahdiste — dorëzimi i Slatin Pashës", "6d8992d4"], "d": ["Guvernatori i përgjithshëm i Darfurit, Slatin Pasha, që nga viti 1882 përballej me kryengritjen mahdiste të fisit Rizeikat; duke menduar se ushtarët e tij ia ngarkonin disfatat faktit që ishte i krishterë, më 1883 u bë haptazi mysliman dhe mori emrin Abdylkadir. Pas asgjësimit të ushtrisë së Hicks Pashës në Kordofan në nëntor 1883, rezistenca humbi kuptimin dhe më 23 dhjetor 1883 ai iu dorëzua emirit Madibbo. Brenda pak kohe edhe karakollet e vogla egjiptiane në Darfur ndoqën të njëjtën rrugë; administrimi dhjetëvjeçar turko-egjiptian mori fund. Me këtë ngjarje Xhebel Marra (Darfur) kaloi nën administrimin e shtetit mahdist.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Zejla dhe bregdeti somalez kalojnë nën administrimin anglez", "1d649502"], "d": ["Kur kryengritja mahdiste shembi garnizonet egjiptiane në Sudan dhe në Detin e Kuq, Kajro u detyrua të lironte postat e veta të largëta në bregdetin abisinas. Administrata angleze në Aden më 1884 zbarkoi ushtarë në Zejla dhe Berbera; vitin pasues, me traktatet e protektoratit të nënshkruara me krerët e fiseve somaleze, u themelua Somalia Britanike. Kështu Zejla, e varur nga ejaleti i Habeshit që prej vitit 1559, doli nga duart.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Dorëzimi i garnizonit të Fasherit te mahdistët", "68f0760d"], "d": ["Edhe pas dorëzimit të Slatinit më 23 dhjetor 1883, garnizoni egjiptian në kështjellën e Fasherit vazhdoi të rezistonte. Gjatë rrethimit shtatëditor garnizoni humbi puset dhe më 15 janar 1884 u dorëzua; armët u dorëzuan dhe kështjella u kaloi mahdistëve.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Traktati Hewett (i Aduas) — Bogosi i lihet Abisinisë", "0de1b701"], "d": ["Kur kryengritja mahdiste rrethoi garnizonet egjiptiane në Sudan, Anglia, për të siguruar ndihmën e Abisinisë, më 3 qershor 1884 nënshkroi në Adua një traktat me Johannesin IV. Neni i dytë i traktatit ia kthente Bogosin Abisinisë, e cila në këmbim hapte rrugën për evakuimin e garnizoneve të rrethuara përmes Massauas. Kështu Kereni doli nga administrimi dymbëdhjetëvjeçar egjiptian; pesë vjet më vonë rajoni do t'i bashkohej Eritresë italiane.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Rimarrja e Dongolës — fillimi i fushatës përgjatë Nilit", "f63aa14f"], "d": ["Pas disfatës së italianëve në Adua, Anglia e marshoi ushtrinë egjiptiane nën komandën e Kitchener-it drejt jugut përgjatë Nilit. Ndërsa hekurudha përparonte në shkretëtirë, problemi i furnizimit u zgjidh dhe vilajeti i Dongolës u rimor më 23 shtator 1896. Këtu mori fund administrimi njëmbëdhjetëvjeçar mahdist; fushata do të vazhdonte edhe dy vjet derisa të arrinte në Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Beteja e Omdurmanit — rrënimi i shtetit mahdist", "28dff7b2"], "d": ["Ushtria anglo-egjiptiane e Kitchener-it, e pajisur me artileri dhe mitralozë, më 2 shtator 1898 para Omdurmanit shpartalloi brenda pak orësh forcat e halifit Abdullah et-Taishi. Të nesërmen u hy në Kartum dhe në pallatin ku trembëdhjetë vjet më parë ishte vrarë Gordoni u ngrit flamuri. Ra kryeqyteti i shtetit mahdist; halifi u vra në operacionin e ndjekjes në fund të vitit 1899. Sundimi de facto ndërron duar në këtë datë — ndërsa 19 janari 1899 është data e marrëveshjes që krijoi kornizën juridike të administrimit. Me këtë disfatë të shtetit mahdist, Darfuri (El Fasher, Nyala, Xhenejna, Kutum etj.) i kaloi Sulltanatit të Darfurit të rithemeluar nga Ali Dinari.", "ad27827a"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Zbarkimi italian në Tobruk — pushtimi i parë në Tripolitani", "44780018"], "d": ["Italia shpalli luftë më 29 shtator 1911, dhe flota e saj më 25-26 shtator vuri bregdetin nën bllokadë. Operacioni i parë tokësor u krye më 8 tetor në Tobruk: garnizoni i vogël osman u tërhoq në brendësi dhe porti u pushtua pa përleshje. Tobruku ishte porti osman më i afërt me kufirin egjiptian; rënia e tij hapi krahun lindor të Barkas dhe lehtësoi marshimin e forcave italiane drejt perëndimit përgjatë bregdetit.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Dorëzimi i qytetit të Tripolit te italianët", "785091ad"], "d": ["Tripoli u dorëzua më 9 tetor 1911 pas tri ditësh bombardimi. Forcat osmane, në vend që ta mbronin qytetin, zgjodhën të tërhiqeshin në Azizije dhe Garjan dhe të organizonin rezistencën në brendësi; kjo rezistencë, ku morën pjesë Enver Beu dhe Mustafa Kemal Beu, i mbylli italianët në rripin bregdetar deri në fund të luftës. Pra, megjithëse qyteti ra, brendësia e vilajetit mbeti nën kontrollin osman.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Humbja e Dernës me zbarkimin italian", "f014c741"], "d": ["Pas Tobrukut erdhi radha e portit të dytë të Barkas, Dernës; qyteti u pushtua më 16 tetor 1911. Pllaja rreth Dernës ishte zona ku tarikati senusi ishte më i përqendruar, dhe muxhahidët e mbledhur me thirrjen për xhihad të shehut Ahmed Sherif i mbajtën italianët të rrethuar rreth portit. Pushtimi mbeti i kufizuar te qyteti dhe nuk mundi kurrë të shtrihej në prapatokë.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Zbarkimi italian në Bengazi — humbja e qendrës së sanxhakut të Barkas", "f9183c40"], "d": ["Qendra e Barkas, Bengazi, u pushtua më 21 tetor 1911 me zbarkimin e katërt dhe më të rëndësishëm në bregdet. Kështu, tri javë pas shpalljes së luftës, Italia mbante të gjitha portet e mëdha të vilajetit të Tripolitanisë (Tripolin, Tobrukun, Dernën, Bengazin), por nuk mundi të hynte në prapatokën e asnjërit. Viti i mbetur i luftës kaloi me përparime pa rezultat nga këto katër pika bregdetare drejt brendësisë.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Dekreti i njëanshëm i aneksimit nga Italia", "cfe3f9c2"], "d": ["Ndërsa lufta vazhdonte, më 5 nëntor 1911 Italia nxori një dekret dhe shpalli se kishte aneksuar Tripolitaninë dhe Barkan. Shteti Osman nuk e njohu këtë dhe lufta vazhdoi edhe një vit; aneksimi fitoi vlefshmëri juridike vetëm me Traktatin e Ushisë të 18 tetorit 1912. Prandaj dekreti nuk e ndryshon ngjyrën osmane në hartë — zotërimi juridik deri më 1912 u takon osmanëve, ndërsa kontrolli italian tregohet si pushtim me vija.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Marrja e Këprühisarit dhe përgatitja për themelimin e Jenishehirit", "39abff03"], "d": ["Duke u marrë kalatë e qafave midis Bursës dhe Iznikut, u hodh themeli i shtabit të përparuar që do t'i rrethonte të dy qytetet.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Themelimi i Jenishehirit", "d3275837"], "d": ["Për të drejtuar rrethimet e Bursës dhe të Iznikut u themelua ngulimi-garnizon i parë i rregullt osman; Orhan Gaziu lindi këtu.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Rrethimi i parë i Iznikut dhe pushtimi i Marmaraxhëkut", "cdca2349"], "d": ["Izniku u rrethua për herë të parë, por nuk u mor (pushtimi përfundimtar më 1331); në këtë kohë u mor kalaja e afërt e Marmaraxhëkut.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Fushata e njësive katalane në Anadoll", "4fd940d5"], "d": ["Kompania katalane, të cilën Bizanti e kishte marrë me pagesë për të ndalur përparimin turk, ndonëse arriti suksese të përkohshme, nuk mundi t'i bënte të qëndrueshme; me tërheqjen e saj përparimi i bejliqeve kufitare u përshpejtua.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Kose Mihali bëhet mysliman dhe i bashkohet Osmanëve", "ca0d86e1"], "d": ["Tekfuri i Harmankajasë, Kose Mihali, u bë mysliman së bashku me kalanë dhe njerëzit e tij dhe iu bashkua Osman Gaziut; u bë komandanti i parë osman me origjinë bizantine.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Beu merr de fakto administrimin", "6dadbefc"], "d": ["Për shkak të pleqërisë dhe sëmundjes së Osman Gaziut, drejtimi dhe komandimi de fakto i rrethimit të Bursës dhe i fushatave kaloi te i biri, Orhan Beu (hipja zyrtare në fron është në vitin 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Marrja e Mudanjas", "0a623368"], "d": ["Duke u marrë Mudanja, porti i Bursës, u pre lidhja e qytetit me detin; rrethimi i Bursës hyri në fazën e mbytjes.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Kalimi i Akjazës dhe i ishullit Imrali në duart osmane (data mungon te burimi)", "380c60ce"], "d": ["Akjaza, në kohën e Osman Beut (në vitet pas fushatës së 1305-s), u bë shënjestër e sulmeve osmane; viti i saktë i marrjes nuk dihet. Se kur u mor ishulli Imrali nuk gjendet në asnjë burim. Kufiri i vitit 1324 në hartë është vlerë zëvendësuese.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koxha pushtoi Kandërën dhe rrethinat", "341bb97e"], "d": ["Akça Koxha, një nga bejlerët kufitarë të Orhan Gaziut, ndërsa nga shtabi i tij në perëndim të liqenit Sapanxha bënte sulme në krahinën e Izmitit, rreth vitit 1326 mori Kandërën dhe rrethinat e saj. Izmiti ishte ende në duart e Bizantit; qyteti do të binte vetëm në vitin 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Bashkimi i Jallovës dhe i Karamürselit", "133cb07a"], "d": ["Këtë vit Jallova me rrethinat, në bregun jugor të gjirit të Izmitit, kaloi në duart e turqve; brezi bregdetar iu dha si timar nga Orhan Beu Karamürsel Gaziut.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koxha mori Ajdosin dhe kështjellën e Samandërës", "ce4daa8a"], "d": ["Pas marrjes së Kandërës, Akça Koxha, së bashku me Konuralpin dhe Gazi Abdurrahmanin, mori kalanë e Ajdosit pranë Kartalit, pastaj kështjellën e Samandërës në veri të saj; krahina e Samandërës iu dha si pronë. Akça Koxha vdiq në vitin 1328 pranë Kandërës; bejliku kufitar i krahinës iu dha shehzade Muratit.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Aleanca osmano-ajdëno-saruhane", "9df6bb74"], "d": ["Tri bejliqe vepruan bashkë kundër Bizantit; flota e Umur Beut të Ajdënit, me sulmet e saj në brigjet e Trakës, e rraskapiti Bizantin nga një front i dytë.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Pushtimi i Gemlikut (Kios)", "66fc4bcd"], "d": ["Gemliku (Kios), qytet bregdetar në gjirin e Gemlikut që hapet në Marmara, kaloi në duart osmane. Kur Bursa u dorëzua në vitin 1326, tekfuri i qytetit ishte dërguar me familjen në Gemlik; pra, në 1326 Gemliku ishte ende në duart e Bizantit. Për Armutlunë nuk u gjet datë më vete; ajo lidhet me zinxhirin e Gemlikut.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Martesa Orhan Gazi – Teodora: aleanca me Bizantin", "9b67a590"], "d": ["Orhan Gaziu, që në luftën për fronin bizantin mbështeste Kantakuzenin, u martua me të bijën e tij, Teodorën; kjo aleancë u mundësoi forcave osmane ta njihnin nga afër Rumelinë.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Marrja e Ankarasë", "49bf1f6d"], "d": ["Ankaraja, nën administrimin e ahive, hyri nën sundimin osman; u hap rruga e Anadollit Qendror. Vende të tjera që u bashkuan në të njëjtën datë: Sivrihisar, Çankëri.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Përparimi në Trakë në kohën e Sulejman Pashës: Malkara, Ipsala dhe Tekirdagu", "fb31cf02"], "d": ["Pas krijimit të krye-urës në Galipoli, Sulejman Pasha, duke dalë nga gadishulli drejt veriut, pushtoi hap pas hapi fushën midis bregut të Marmarasë dhe grykës së Maricës. Kështu Malkara, Ipsala dhe Rodosçuku (Tekirdagu) formuan një korridor të pandërprerë që lidhte Galipolin me luginën e Maricës. Pa u krijuar ky korridor nuk mund të marshohej mbi Edrene; përparimin, që u ndal me vdekjen e papritur të shehzadesë në vitin 1357, do ta vazhdonin Lala Shahini dhe Haxhi Ilbeu.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Rrëmbimi i shehzade Halilit", "b52ac3d7"], "d": ["Halili, djali i vogël i Orhan Gaziut, u rrëmbye nga piratë nga Foça; kriza e shpërblesës i mbajti të zëna për vite marrëdhëniet osmano-bizantine.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Prerja e rrugëve të ndihmës për Edrenenë: kalatë e Çorlusë, Lüleburgazit, Babaeskit dhe Keshanit", "8e8ad485"], "d": ["Pasi u shpëtua Halili, shehzade Murati, që e rifilloi operacionin e pushtimit, për ta izoluar Edrenenë nga ndihma që mund të vinte nga jashtë, i dërgoi akënxhinjtë deri përpara Stambollit. U morën kalatë e Çorlusë, Lüleburgazit dhe Babaeskit në rrugën Stamboll-Edrene, si dhe Keshani në udhëkryqin e Trakës Jugore. Dorëzimi i Edrenesë erdhi pasi u plotësua kjo unazë rrethimi.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Marrja e Dimotikës — hapja e luginës së Maricës", "b59aee83"], "d": ["U mor Dimotika, kalaja kyçe e luginës së Maricës; kështu u hap rruga që çonte në pushtimin e Edrenesë. Pa u plotësuar korridori nga Galipoli drejt veriut nuk ishte e mundur të marshohej mbi Edrene, prandaj në radhën e pushtimeve të Rumelisë kalaja vjen para Edrenesë. Qyteti për ca kohë u bë shtabi i padishahëve në Rumeli. Forcat që morën Dimotikën më pas vunë nën kontroll të gjithë krahinën e Maricës së Mesme, së bashku me kështjella të vogla si Kuleli Burgazi (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Humbja e Galipolit (Kryqëzata e Savojës)", "00e7e415"], "d": ["Flota e Amadeos së Savojës, kushëririt të perandorit bizantin, mori Galipolin dhe ia dorëzoi Bizantit; krye-ura osmane në Rumeli për dhjetë vjet u drejtua nga ana përballë e ngushticës. Vendbanime të tjera që u humbën në të njëjtën datë: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Beteja e Çirmenit — kontrolli i luginës së Maricës", "cd738d8d"], "d": ["Ushtria e bejlerëve serbë u shpartallua në një sulm nate; bejlerët lokalë serbë/bullgarë në Maqedoni dhe në Rodope filluan t'u paguanin njëri pas tjetrit haraç Osmanëve — jo pushtim i drejtpërdrejtë, por fillimi i një vale vasalizimi. Në rrëfimin osman kjo betejë njihet edhe me emrin «Sërpsëndëgë» dhe tregohet si sulmi i natës që Haxhi Ilbeu bëri në vitin 1364 kundër ushtrisë kryqtare që vinte për të rimarrë Edrenenë; TDV vëren se kjo datë është e gabuar dhe se të dy rrëfimet i përkasin të njëjtës betejë.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Pushtimi i Filipopojës dhe i Stara Zagorës", "e780c9ae"], "d": ["U morën Filipopoja, në rrjedhën e sipërme të luginës së Maricës, dhe Stara Zagora në veri të saj; carati bullgar u bë haraçpagues. Itinerari Tatarpazarxhik–Ihtiman midis Filipopojës dhe Sofjes mbeti në duart e bejlerëve lokalë që u vasalizuan pas Çirmenit. Vendbanime të tjera që u humbën në të njëjtën datë: Haskovo (Hasköj), Klokotnica.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizanti vasal: Joani V në ushtrinë e Muratit I (pasojë e fitores së Çirmenit të vitit 1371)", "13ffe568"], "d": ["Sipas TDV-së, pas fitores së Çirmenit (Maricës) më 26 shtator 1371, Perandoria Bizantine kishte njohur sovranitetin osman, kishte pranuar të paguante haraç dhe të shërbente në ushtrinë osmane, duke rënë në gjendjen e një shteti vasal. Me këtë detyrim perandori Joani V iu bashkua në vitin 1373 ushtrisë së Muratit I; ndërkohë i biri, Androniku IV, që e kishte lënë në Stamboll, së bashku me shehzade Savxhë Beun në Bursë, u ngritën kundër etërve të tyre.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Rimarrja e Galipolit", "5f96c0a5"], "d": ["Androniku IV, që në grindjen për fronin bizantin mori mbështetjen osmane, në këmbim e ktheu Galipolin; ura midis Rumelisë dhe Anadollit u rivendos. Vende të tjera që u bashkuan në të njëjtën datë: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Prika e Germijanit: bashkimi i Kytahjas", "d6a6fe61"], "d": ["Në martesën e Devletshah Hatunit, vajzës së Sulejman Shahut të Germijanëve, me Bajazidin Jëlldërëm, Kytahja, Simavi, Tavshanliu dhe Egrigëzi i kaluan Osmanëve si prikë — shembull klasik i zgjerimit pa luftë. Vende të tjera që u bashkuan në të njëjtën datë: Afjon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Blerja e vendit të Hamidit: bashkimi i Ispartës", "4a1b6047"], "d": ["Hysejn Beu Hamidogllu ia shiti Muratit I, me para në dorë, një pjesë të bejlikut të tij (Akshehir-Bejshehir-Isparta); pjesa tjetër e vendit të Hamidit do të aneksohej nga Jëlldërëmi në vitin 1391. Vendbanime të tjera që u humbën në të njëjtën datë: Ishakli.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Pushtimi i Serezit", "d4d28b60"], "d": ["U mor Serezi, kyçi i Maqedonisë Lindore; Selaniku hyri në unazën e rrethimit. Vija Qystendil–Petriç–Nevrokop–Drama midis Sofjes dhe Serezit në këtë datë nuk ishte bashkuar ende drejtpërdrejt; me radhë, midis viteve 1370-1383 u bë vasale dhe pas 1383 kaloi në administrim të drejtpërdrejtë. Vendbanime të tjera që u humbën në të njëjtën datë: Gjevgjeli (Gevgelija), Kilkis (Avrathisar).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Pushtimi i Sofjes", "96d5f01f"], "d": ["U vunë nën kontroll qafat perëndimore të maleve të Ballkanit; në këtë datë, meqë Serezi mbahej që nga viti 1383, tokat Trakë-Maqedoni formonin një tërësi të pandërprerë.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Pushtimi i Nishit", "77f5d632"], "d": ["Me marrjen e Nishit, kyçit të luginës së Moravës, despotati serb hyri nën kërcënim të drejtpërdrejtë.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Dorëzimi i parë i Selanikut", "96010ee9"], "d": ["Pas bllokadës së gjatë qyteti u dorëzua (në vitin 1403 do t'i kthehej Bizantit, kurse në 1430 do të pushtohej përfundimisht). Vende të tjera që u bashkuan në të njëjtën datë: Kavalla. Vendbanime të tjera që u humbën në të njëjtën datë: Lagkadas (Lanzaka), Praviște (Eleftheroupoli).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidnameja osmano-gjenoveze — ripërtëritja e traktatit të vitit 1352", "be11d17a"], "d": ["Me ambasadorët gjenovezë që erdhën nga Pera u ripërtëri marrëveshja tregtare e vitit 1352, e mbetur nga koha e Orhan Gaziut; u rivendosën taksat midis dy shteteve, trajtimi i robërve dhe tregtia e lirë. Kjo konsiderohet ahidnameja e parë zyrtarisht e njohur e miqësisë dhe e tregtisë midis Osmanëve dhe gjenovezëve — jo aleancë ushtarake, por marrëveshje krejtësisht tregtare.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Fushata bullgare e Çandarli Ali Pashës: marrja e Shumenit dhe e Rusesë", "2781c3a9"], "d": ["Kalatë e Caratit Bullgar përgjatë Danubit u morën në dorëzim në një fushatë të vetme; nuk duhet ngatërruar me disfatën e po atij viti në Bilecë të Bosnjës — ky ishte një sukses i njëkohshëm në një front tjetër. Tërnova dhe Vidini ishin qendrat e fundit bullgare që mbaheshin ende.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Disfata e Bilecës", "89ba0a64"], "d": ["Forca e akënxhinjve që u drejtua për në Bosnjë ra në pritë në Bilecë dhe u asgjësua; ky pengesë e parë e madhe në Ballkan i dha zemër aleancës që do të shkonte në Kosovë.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Aneksimi i bejliqeve të Anadollit Perëndimor: Saruhan, Ajdën, Menteshe", "dcc33b71"], "d": ["Tri bejliqe u bashkuan njëherësh: Manisa, qendra e Saruhanëve; Ajdëni, qendra e Ajdënoglluve (përfshirë Kalanë e Sipërme të Izmirit, kurse porti/kalaja e poshtme ishte ende te kalorësit e Shën Gjonit — deri më 1402); Mugla-Milas, qendra e Mentesheoglluve, përfshirë brezin bregdetar Datça-Bodrum-Marmaris-Fethije. Brigjet e Egjeut u bashkuan për herë të parë nën një dorë. Vende të tjera që u bashkuan në të njëjtën datë: Sëke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Aneksimi i vendit të Tekesë: bashkimi i Antalisë", "fdbeee5c"], "d": ["Vendi i Tekesë në bregun e Mesdheut iu bashkua tokave osmane. Tekeogllutë janë një degë e shkëputur nga Hamidogllutë: Felekuddin Dundar Beu ia kishte lënë vëllait të tij, Junus Beut, Antalinë që kishte pushtuar dhe rreth vitit 1321 ishte krijuar një bejlik i veçantë. Prandaj Antalia me rrethinat në hartë, pas vitit 1321, paraqiten me ngjyrën e Tekeoglluve e jo të Hamidoglluve. Bejliku u rikrijua pas Betejës së Ankarasë dhe u likuidua përfundimisht vetëm në vitin 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Pushtimi i Shkupit", "9e5a1af5"], "d": ["U mor qendra e Maqedonisë së Vardarit; Shkupi u bë një nga qendrat kryesore kufitare të Rumelisë.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Aneksimi i Kastamonusë", "876330ba"], "d": ["U likuidua dega e Kastamonusë e Xhandaroglluve; dega e Sinopit vazhdoi si vasale. Vende të tjera që u bashkuan në të njëjtën datë: Bartën, Safranbolu, Akçakoxha, Devrek, Eflani, Eregli i Detit të Zi, Tosja.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Rënia e Tërnovës — aneksimi i Bullgarisë", "ff666977"], "d": ["Ra kryeqyteti i caratit bullgar; Bullgaria hyri drejtpërdrejt nën administrimin osman. Vende të tjera që u bashkuan në të njëjtën datë: Plevna, Lovec (Lofça), Gabrovë.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Kalaja e Lovecit (Lofça) u kaloi Osmanëve", "a55e87a0"], "d": ["Lovec, një nga kalatë e carit bullgar Ivan Shishman, në fushatën e vitit 1393, kur ra Tërnova, iu bashkua tokave osmane së bashku me provincat e tjera të Shishmanit. Burimi nuk flet prerë: «mendohet» se pushtimi ndodhi këtë vit.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Bashkimi i Dobruxhës", "478e36f2"], "d": ["U bashkuan tokat e Dobruxhës që shtriheshin deri në deltën e Danubit. Vende të tjera që u bashkuan në të njëjtën datë: Silistra, Konstancë, Babadag (Babadagu), Balçik, Hërshova (Hârșova), Tulça (Tulcea), Mangalia (Mangalya), Isakça (Isaccea), Tutrakan, Maçin, Kyçyk Kajnarxha.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Zbritja në Thesali", "8bec60dd"], "d": ["Fusha e Thesalisë me qendër Larisën (Jenishehir) u mor nën administrimin osman. Vende të tjera që u bashkuan në të njëjtën datë: Trikalla, Lamia (Izdin).", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Beteja e Rovines — fushata e Vllahisë", "343ae7a9"], "d": ["Pas betejës së përgjakshme me përfundim të diskutueshëm kundër vojvodës së Vllahisë, Mirçea, Vllahia pranoi t'u paguante haraç Osmanëve; u vendos rendi i vasalitetit në veri të Danubit.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Pushtimi i Nikopojës", "b9791717"], "d": ["Pas betejës së Rovines të vitit 1395 kundër vllehëve, Bajazidi Jëlldërëm mori kalanë e Nikopojës në bregun e Danubit; disa kronika anonime bullgare shënojnë se pushtimi u krye më 3 qershor 1395. Data e pushtimit nuk është e vetme në burime: zëri i Enciklopedisë Islame të TDV-së për Betejën e Nikopojës shkruan se Bajazidi e mori Silistrën dhe Nikopojën në një fushatë në Danub të vitit 1394. Kalaja do të rrethohej në Kryqëzatën e njohur të vitit 1396, por nuk do të binte. Vende të tjera që u bashkuan në të njëjtën datë: Ohër.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Kalaja e Nikopojës u kaloi Osmanëve", "327012c9"], "d": ["Pas sulmit të befasishëm të Rovines, Bajazidi Jëlldërëm mori Nikopojën; cari bullgar Ivan Shishman, që rrinte atje si vasal osman, u mënjanua. Në atlas Nikopoja shënohet që nga kjo ditë si kaluar nga Carati Bullgar te Osmanët.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Ndërtimi i Anadolu Hisarit", "aa259b00"], "d": ["Për të mbështetur bllokadën e Stambollit, në bregun anadollak të Bosforit u ndërtua Güzelcehisar (Anadolu Hisari) — hapi i parë i përhershëm i kontrollit të ngushticës.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Aneksimi i Vidinit", "ee1ae44b"], "d": ["Pas fitores së Nikopojës u aneksua edhe principata e fundit bullgare, ajo e Vidinit.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Aneksimi i parë i Karamanit", "3cf07876"], "d": ["Me fitoren e Akçajit, tokat e Karamanëve iu bashkuan për herë të parë Osmanëve (në Interregnum do të rikrijohej).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Bashkimi i brigjeve të Xhanikut: Samsuni", "af9c40fa"], "d": ["Në boshllëkun që u krijua kur Kadi Burhanedini ra rob te akkojunlu Karajylyk Osman Beu, Bajazidi Jëlldërëm fillimisht e lidhi me administrimin osman krahinën e Xhanikut në bregun e Detit të Zi. Kështu Samsuni me rrethinat u bë porti i parë i dinastisë në Detin e Zi. Vija e brendshme Sivas-Tokat-Kajseri do të bashkohej dy javë më vonë, me shpërbërjen de fakto të Shtetit të Kadi Burhanedinit.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Marrja e Malatjas", "7cb6ae16"], "d": ["U mor Malatja në kufirin memluk — një nga hapat që e shtuan tensionin me Timurin.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timuri mori Malatjan dhe ia la Karajylyk Osmanit — kur Timuri u tërhoq, Dulkadirogllutë e rimorën", "ad2ce7d8"], "d": ["Bajazidi Jëlldërëm, Malatjan që e kishte marrë në vitin 1399, ia kishte lënë Nasreddin Mehmedit Dulkadirogllu dhe ishte kthyer në Bursë. Timuri, që hyri në Anadoll në vitin 1400, mori fillimisht Sivasin e Elbistanin e pastaj Malatjan; qyteti me rrethinat u plaçkit dhe administrimi iu la Karajylyk Osmanit, që ishte pranë Timurit. Kur Timuri u largua nga krahina, Dulkadirogllutë e sunduan përsëri Malatjan; kështu sundimi osman mori fund para Ankarasë.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Traktati midis Sulejman Çelebiut dhe Bizantit: kthimi i Selanikut", "cc503cc2"], "d": ["Sulejman Çelebiu, që gjatë Interregnumit sundonte Rumelinë, duke u marrë vesh me Bizantin dhe me shtetet latine, ia lëshoi Bizantit Selanikun dhe brigjet e Detit të Zi deri në Mesemvri (TDV fetret-devri: Traktati i Galipolit, shkurt 1403) — në hartë Igneada, Rezve dhe Ahtopoli i kalojnë Bizantit; në hartë Selaniku në këtë datë del nga Osmanët.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Disfata detare e Galipolit (Venedik)", "b71d4d68"], "d": ["Flota venedikase e mundi rëndë flotën osmane përpara Galipolit; u bë ngjarja që tregoi kufijtë e detarisë osmane të periudhës së hershme.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Kryengritja e Mustafait të Rremë", "0ec43138"], "d": ["Mustafa Çelebiu, që pretendonte se ishte djali i Jëlldërëmit, me mbështetjen e Bizantit u shpall sulltan në Rumeli; Murati II e shtypi kryengritjen në vitin 1422 dhe urdhëroi ekzekutimin e rivalit.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Rrethimi i Stambollit nga Murati II", "4b9d9fba"], "d": ["Si kundërpërgjigje ndaj mbështetjes bizantine për Mustafain e Rremë, Murati II e rrethoi Stambollin; rrethimi u hoq kur vëllai i tij, Mustafai i Vogël, u nxit të ngrihej në Anadoll.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Dorëzimi i Selanikut Venedikut", "bfa6c4a0"], "d": ["Guvernatori bizantin, nën presionin osman, ia dorëzoi qytetin Venedikut; filloi grindja osmano-venedikase që do të zgjaste shtatë vjet.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Rianeksimi i bejliqeve të Anadollit Perëndimor: Menteshe dhe Ajdën", "aca30a48"], "d": ["Dy bejliqet egjeane të rikrijuara gjatë Interregnumit iu bashkuan përfundimisht tokave osmane në kohën e Muratit II. Sipas zërit të TDV-së për Mentesheogllutë, Murati II e mori vendin e Mentesheut në vitin 827 (1424) dhe i burgosi të dy vëllezërit në krye të bejlikut. Sipas zërit për Ajdënogllutë, bejlerbeu i Anadollit, Hamza Beu, urdhëroi kapjen dhe ekzekutimin e Xhunejd Beut, që kishte dalë sërish nga bindja, së bashku me familjen (829/1425-26) dhe vendi i Ajdënit u kaloi Osmanëve. Kalorësit e Shën Gjonit, që që nga viti 1344 mbanin kalanë portuale të Izmirit, ia kishin lëshuar atë Timurit në vitin 1402 dhe krahina ishte kthyer nën kontrollin e Ajdënoglluve; me këtë aneksim edhe ajo iu bashkua Osmanëve. Vendi i Tekesë (Antalia) nuk është objekt i këtij zëri: Tekeogllutë ishin likuiduar veçmas në vitin 1423. Kurse Germijani do të bashkohej në vitin 1429 me testament.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Aneksimi i Germijanit me testament", "9eb86b77"], "d": ["Beu i Germijanit, Jakubi II, që vdiq pa fëmijë, ia la me testament vendin e tij Osmanëve — shembulli i aneksimit pa luftë që ka hyrë në librat shkollorë. Vende të tjera që u bashkuan në të njëjtën datë: Karahisar-i Sahib (Afjon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Pushtimi përfundimtar i Selanikut", "bc021768"], "d": ["Qyteti nën administrimin venedikas u mor me sulm; porti i dytë i madh i Rumelisë u bë përfundimisht osman. Vende të tjera që u bashkuan në të njëjtën datë: Kasandra (Kesendire).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Dorëzimi i Janinës", "ee45cb52"], "d": ["Janina, qendra e Epirit, u dorëzua me marrëveshje.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Marrja e parë e Smederevës", "c11ca17d"], "d": ["Me një rrethim tremujor u mor kryeqyteti i despotatit serb dhe Serbia u aneksua për herë të parë (me Traktatin Edrene-Seged të vitit 1444 do të kthehej).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Rrethimi i Beogradit (i pasuksesshëm)", "3e05f425"], "d": ["Rrethimi i parë i madh i Beogradit, që zgjati gjashtë muaj, nuk dha rezultat; kalaja mbeti për tetëdhjetë vjet kyçi përpara përparimit osman.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Disfata e Zlaticës (İzladi) — 'Fushata e Gjatë'", "97df1466"], "d": ["Ushtria që Huniadi futi në Ballkan në mes të dimrit kaloi Nishin dhe Sofjen dhe arriti deri në Zlaticë; mbrojtja osmane mezi qëndroi. Kjo atmosferë disfate solli në tryezë paqen Edrene-Seged.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Traktati Edrene-Seged", "0aa4e0de"], "d": ["Paqe dhjetëvjeçare: despotati serb u kthye, Danubi u pranua si kufi. Prishja e traktatit brenda disa muajsh me nxitjen e papatit çoi në katastrofën e Varnës.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Kthimi i Smederevës dhe i kalave serbe Serbisë", "cda3cf9e"], "d": ["Dispozita e Traktatit Edrene-Seged u vu në zbatim: më 15 gusht 1444, Murati II ia ktheu Gjuragj Brankoviqit Smederevën me njëzet e katër kalatë e saj të rëndësishme dhe me tokat e tjera serbe të pushtuara (TDV semendire); edhe Nishi (TDV nis), Alacahisari (Krushevci) (TDV alacahisar), Piroti (TDV sehirkoy) dhe Prishtina (TDV pristine) iu lanë serbëve. Vidini, meqë nuk ishte tokë serbe, nuk hyri në kthim — ky është burimi i humbjes së tokave në veriperëndim që shihet në hartë rreth fitores së Varnës; pas disa muajsh, me disfatën e Varnës, traktati do të mbetej gjithsesi i pavlefshëm.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisari përfundoi — 'Prerësi i Ngushticës'", "480e8a76"], "d": ["Me hisarin, i përfunduar sipas burimeve me një ndërtim jashtëzakonisht të shpejtë që zgjati katër-pesë muaj, kontrolli i Bosforit kaloi tërësisht te Osmanët; rruga e ndihmës për Stambollin nga Deti i Zi u mbyll. Konsiderohet hapi i parë de fakto i rrethimit.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Filloi rrethimi i Stambollit", "8af50742"], "d": ["Ushtria u vendos përpara mureve; në rrethimin që do të zgjaste 54 ditë, topat gjigantë për herë të parë u përdorën në mënyrë sistematike kundër mureve të një kryeqyteti.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Anijet u zbritën në Bririn e Artë (Haliç) nga toka", "4f2ba07c"], "d": ["Nga flota, që nuk mund të hynte në Bririn e Artë të mbyllur me zinxhir, rreth 70 anije u kaluan me slita të lyera me vaj përmes kodrave të Gallatës dhe brenda një nate u lëshuan në Bririn e Artë; mbrojtja u nda në dy fronte.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Pushtimi i Athinës", "4f0f1bb2"], "d": ["Dukati i Athinës mori fund; në Akropol u ngrit flamuri osman. Vende të tjera që u bashkuan në të njëjtën datë: Tebë (İstefe), Livadhja.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Aneksimi i Serbisë (rënia e Smederevës)", "75fd0a62"], "d": ["Smedereva, kryeqyteti i despotatit serb, u dorëzua; Serbia u bë sanxhak osman.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Pushtimi i Moresë", "7d5a3c18"], "d": ["Despotati i Moresë u likuidua; gadishulli (përveç kështjellave venedikase) hyri nën administrimin osman.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Bashkimi i Sinopit", "e03c2739"], "d": ["Sinopi i Xhandaroglluve u dorëzua pa luftë; u hap rruga për fushatën e Trapezundës. Vende të tjera që u bashkuan në të njëjtën datë: Kastamonu, Bartën, Safranbolu. Zëri i TDV-së për Xhandarogllutë përmend edhe Bolun, Eflanin dhe Tosjan ndër tokat e bejlikut të Xhandaroglluve të aneksuara në vitin 1461; në atlas këto tri vende shënohen që nga kjo ditë si kaluar nga Xhandarogllutë te Osmanët. Vendbanime të tjera që u humbën në të njëjtën datë: Eregli i Detit të Zi, Devrek, Akçakoxha (tokë e Xhandaroglluve).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Rënia e Mbretërisë së Bosnjës — fushata e Fatihut në Bosnjë", "5362e3f2"], "d": ["Mbreti i fundit boshnjak Stjepan Tomašević (1461-1463), duke u mbështetur te ndihma e Perëndimit, kur refuzoi të paguante haraç u konsiderua se kishte dalë nga statusi i sundimtarit vartës dhe ushtria nën komandën e Sulltan Mehmetit Fatih e likuidoi Mbretërinë e Bosnjës në një fushatë. Mbreti u kap dhe u ekzekutua, mbretëria u zhduk dhe në krahinë u krijua sanxhaku i Bosnjës. Megjithatë, rënia e mbretërisë nuk është e njëjtë me pushtimin e Bosnjës. Administrimi osman ekzistonte në fushë prej pesëmbëdhjetë vjetësh — Hodidjedi dhe fusha e Sarajit ishin marrë në vitin 1448, dhe bejliku kufitar i Isa Beut ishte krijuar në mes të mbretërisë. Pushtimi nuk përfundoi as në vitin 1463: Foça u mor në 1465, Livno në 1469, Dukati i Hercegovinës në 1483, banati i Srebrenicës në 1512, kurse Jajca dhe Banja Luka në veri vetëm pas Mohaçit, në 1528 — pas vitit 1463 hungarezët kishin krijuar në veri të Bosnjës një banat që qëndroi gjashtëdhjetë e pesë vjet. Vendi që në këtë datë ndërron dorë drejtpërdrejt është Travniku; kurse Jajca në këtë datë kaloi jo te Osmanët, por te Hungaria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Aneksimi përfundimtar i Karamanit", "f1dcecaa"], "d": ["Tokat qendrore të Karamanëve u bashkuan përfundimisht; përçarjet e brendshme zgjatën deri në vitet 1470. Vende të tjera që u bashkuan në të njëjtën datë: Nigde, Mostar, Bejshehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Pushtimi i Eubesë (Eğriboz)", "5c97daf3"], "d": ["Ra Eubeja (Negroponti), baza kryesore e Venedikut në Egje.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Aneksimi i Alanjas, Anamurit dhe Silifkes (Içel)", "a0b9d461"], "d": ["Brezi bregdetar i Içelit që i përkiste Karamanëve (i gjithë bregu i Mesdheut midis Antalisë dhe Mersinit) u bashkua me fushatën detare të Gedik Ahmed Pashës; Alanja ishte e rëndësishme me arsenalin e saj strategjik të trashëguar nga periudha selxhuke.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Aneksimi i Novgorodit nga Moska", "bed87170"], "d": ["Dukaindi i madh Ivani III hoqi kambanën simbolike të kuvendit popullor (veçe) të Novgorodit, i zëvendësoi drejtuesit vendorë me guvernatorët e vet dhe de fakto e lidhi qytetin me Moskën; Novgorodi pushoi së qeni republikë e pavarur. Toka e Novgorodit shtrihej nga Deti Baltik deri në Detin e Bardhë dhe në Urale. Në atlas Novgorodi shënohet që nga kjo ditë si kaluar nga Republika e Novgorodit te Moska.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Traktati i Stambollit — Shqipëria dhe Shkodra", "b09652f7"], "d": ["Lufta 16-vjeçare osmano-venedikase mori fund; Shkodra dhe brigjet e Shqipërisë mbetën te Osmanët. Vende të tjera që u bashkuan në të njëjtën datë: Lemnos, Samos, Ai Strati (Bozbaba).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Zbarkimi në Otranto", "7916b89d"], "d": ["Forcat osmane që zbarkuan në bregun e Pulias (Apulia) rrethuan dhe morën kalanë e Otrantos; meqë në qytet u hy me luftë, një pjesë e parisë që rezistonte u ekzekutua dhe një pjesë u zu rob. Tradita kishtare i përkujton të vdekurit si 'dëshmorët e Otrantos', rreth 800 veta; TDV ia atribuon propagandës kishtare zmadhimin e kësaj shifre. U mbajt vetëm kalaja në skaj të gadishullit Salento me rrethinën e saj të ngushtë; tokat e tjera të Mbretërisë së Napolit në vijën Taranto-Brindisi-Leçe nuk dolën nga duart — kjo krye-urë e hapur drejt Italisë do të zgjaste një vit.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evakuimi i Otrantos", "37371bb0"], "d": ["Garnizoni i Otrantos, që pas vdekjes së Sulltan Mehmetit Fatih (3 maj 1481) nuk kishte më shpresë për përforcime, përballë rrethimit të princit trashëgimtar të Napolit, Alfonsit, e evakuoi kalanë me marrëveshje; kështu e vetmja krye-urë osmane në Itali u humb pas një viti.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Pushtimi i Modonit dhe i Koronit", "38b608c4"], "d": ["U morën Modoni dhe Koroni, 'dy sytë' e Venedikut në More.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Pushtimi i Durrësit", "1f231b98"], "d": ["Gjatë luftës osmano-venedikase 1499-1503, forcat nën komandën e Mehmed Beut morën Durrësin, portin e fundit të madh shqiptar të Venedikut në Adriatik. Me këtë pushtim, pas Shkodrës (1479) dhe Vlorës (1417), i gjithë brezi bregdetar i Shqipërisë hyri nën kontrollin osman.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Bashkimi i Anadollit Lindor", "e0cb8f8f"], "d": ["Pas Çalldiranit u bashkuan Dijarbekiri me rrethinat; bejliqet kurde u lidhën me Osmanët përmes Idris Bitlisiut.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Pushtimi i Kalasë së Varadinit (Petrovaradin)", "abf392a5"], "d": ["Ushtria që doli në fushatën e Mohaçit kaloi nga Beogradi në tokat hungareze; fillimisht u morën lagjet e jashtme të Varadinit dhe pas një rrethimi katërmbëdhjetëditor ra edhe kalaja. Kanuniu urdhëroi të mos digjeshin fshatrat gjatë rrugës, sepse tashmë konsideroheshin tokë osmane.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Dorëzimi i Budës pas Mohaçit — dy mbretër për fronin hungarez", "9d3568a0"], "d": ["Çelësat e qytetit iu paraqitën sulltanit, i cili pas fitores së Mohaçit marshoi drejt Budës, më 11 shtator 1526; por Kanuniu nuk e mbajti Budën dhe e tërhoqi ushtrinë. Në Hungarinë e mbetur pa mbret, fisnikët zgjodhën dy mbretër të ndryshëm: më 10 nëntor 1526 János Szapolyai, më 17 dhjetor 1526 Ferdinandin I Habsburg. Ferdinandi e mori Budën në gusht 1527. Vendosja e Szapolyait në Budë si mbret nën mbrojtjen osmane do të bëhej me fushatën e vitit 1529 (shih zërin e 1529-s), kurse administrimi i drejtpërdrejtë osman do të vendosej në vitin 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai u zgjodh mbret i Hungarisë — Osmanët ia njohën mbretërinë me kusht vartësie", "32bc6baf"], "d": ["Në fronin hungarez, të mbetur bosh me vdekjen e mbretit në Mohaç, një pjesë e fisnikëve zgjodhi vojvodën e Transilvanisë, János Szapolyai; Szapolyai u kurorëzua në Székesfehérvár (İstolni Belgrad). Osmanët, që e liruan Budën, për ta mbajtur krahinën si tampon, ia njohën Szapolyait mbretërinë me kusht që të ishte vartës i tyre. Në hartë vendet që i përkisnin Szapolyait duken që nga kjo datë si vartëse të Osmanëve.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinandi I u shpall mbret i Hungarisë — Hungaria Perëndimore dhe Veriore i kalon kurorës habsburge", "b3910a2f"], "d": ["Arkiduka habsburg Ferdinand, duke u mbështetur te martesa e motrës së tij me Lajoshin II, pretendoi të drejtën mbi fronin hungarez dhe u shpall mbret nga një pjesë e fisnikëve. Kështu Hungaria u nda midis dy mbretërve; pjesa perëndimore dhe veriore njohu Ferdinandin. Fisnikët kroatë e zgjodhën atë veçmas në fillim të vitit 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Grindja e dy mbretërve: Estergomi nën mbrojtjen habsburge, Segedini te Szapolyai", "da92dee5"], "d": ["Estergomi, që nga viti 1526 kalonte nga dora e njërit mbret te tjetri, pasi kryepeshkopi u largua në veri me arkivin dhe thesarin, hyri nën mbrojtjen habsburge. Që nga po ai vit deri në 1541, Segedini mbeti nën sundimin e Szapolyait.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Populli i Peçit kaloi në anën e Szapolyait", "3fc4e7f2"], "d": ["Peçi, që në vitin 1528 kishte marrë privilegje nga Ferdinandi, pas pak kohe kaloi në anën e Szapolyait; mbreti János qëndroi për ca kohë në qytet në vitin 1533. Me rënien e Budës në vitin 1541, qyteti u kthye përsëri në anën e Ferdinandit.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Pushtimi i Tripolit", "8c659986"], "d": ["Tripoli u mor nga kalorësit e Shën Gjonit; pjesa qendrore e bregut të Afrikës Veriore u bë osmane. Vende të tjera që u bashkuan në të njëjtën datë: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Pushtimi i Temeshvarit", "e9fd4995"], "d": ["Duke u marrë krahina e Banatit, u krijua Bejlerbejllëku i Temeshvarit.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Pushtimi përfundimtar i Tunisit", "7bbd11bc"], "d": ["Tunisi nën kontrollin spanjoll-hafsid hyri përfundimisht nën administrimin osman; vija e Afrikës Veriore u plotësua. Vende të tjera që u bashkuan në të njëjtën datë: Kajruani, Gabesi, Sfaksi.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Pushtimi i Kanizhës", "0c7b6aa3"], "d": ["Në Luftën e Gjatë u mor Kanizha; vitin pasues mbrojtja e Tirjaki Hasan Pashës u bë legjendare.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Filloi fushata e Ujvarit — Fazil Ahmed Pasha marshoi nga Edrenea kundër Austrisë", "306a86db"], "d": ["Pasi Austria sulmoi Transilvaninë dhe mori kalatë e Székelyhídit dhe të Kolojvarit (Kluzh), Stambolli vendosi fushatë kundër Habsburgëve. Veziri i madh Kyprylyzade Fazil Ahmed Pasha u nis nga Edrenea më 13 prill 1663. Në Beograd erdhi kërkesa e Austrisë për paqe, por në dy bisedimet në Osijek kushtet osmane u refuzuan. Edhe në këshillimin në Budë si objektiv u caktua Ujvari.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Pushtimi i Ujvarit", "ce289470"], "d": ["U mor Ujvari (Nové Zámky), kalaja kyçe e Hungarisë Veriore; shprehja 'i fortë si një turk përpara Ujvarit' hyri në gjuhët evropiane. Pas Ujvarit, edhe Nitra dhe Léva u dorëzuan pas një rezistence të shkurtër; të dyja i rimori De Souches në pranverën e vitit 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Rimarrja e Moresë", "9b6460f1"], "d": ["Moreja, që në Karlovc iu la Venedikut, u rimor njëherësh. Vende të tjera që u bashkuan në të njëjtën datë: Patra, Lepanto (İnebahtı).", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Humbja e dytë e Beogradit — rrethimi i princit Eugjen", "6a194354"], "d": ["Pas disfatës së Varadinit dhe humbjes së Temeshvarit, princi Eugjen rrethoi Beogradin; pasi u mund edhe ushtria ndihmëse që vinte për ta shpëtuar qytetin, kalaja u dorëzua. Kështu qyteti, që pas Karlovcit ishte rimarrë në vitin 1690, humbi përsëri dhe vija mbrojtëse e Danubit u shemb. Beogradi do të mund të rimerrej vetëm njëzet e dy vjet më vonë, me Traktatin e Beogradit të vitit 1739. Vendbanime të tjera që u humbën në të njëjtën datë: Smedereva. Atlasi gjithashtu u shënon Habsburgëve që nga kjo ditë rrethinat e Hisarxhëkut (Grocka) dhe të Jagodinës (Jagodina) (data e krahinës; dita në nivel vendi mungon te burimi, përafërsi e deklaruar); kurse Mehádia kalon te Habsburgët me datën 27 gusht 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Rënia e Oçakovit (Özi)", "90a67a6c"], "d": ["Oçakovi, kalaja kyçe në veri të Detit të Zi, ra në duart e Rusisë me një sulm të përgjakshëm; popullsia e qytetit u kalua në tehun e shpatës.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Traktati i Bukureshtit — humbja e Besarabisë", "932da4d6"], "d": ["Me traktatin që i dha fund luftës ruse 1806-1812, lindja e Prutit (Besarabia) iu la Rusisë. Vendbanime të tjera që u humbën në të njëjtën datë: Akkerman, Kilia, Hotin, Bender, Izmail. Atlasi gjithashtu i konsideron Kishinjevin (Chișinău), Bălți-n, Kahulin (Cahul) dhe Orhein, brenda Besarabisë, si kaluar po atë ditë nga Moldavia (vasale osmane) te Rusia. Edhe Soroka (Soroca) po atë ditë kalon te Rusia.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Traktati i Edrenesë", "b3a8fe4c"], "d": ["Në fund të luftës gjatë së cilës ushtria ruse hyri në Edrene, u humb delta e Danubit; autonomia/pavarësia e Greqisë u pranua de fakto. Vendbanime të tjera që u humbën në të njëjtën datë: Braila, Anapa, Ahëska. Edhe pse traktati i ktheu tokat, nuk i dha fund menjëherë pushtimit: Vllahia-Moldavia dhe Silistra, derisa të paguhej dëmshpërblimi i luftës, mbetën si peng nën administrimin rus — kjo është arsyeja pse në hartë këto vende duken të pushtuara edhe pas vitit 1829. Me këtë traktat mori fund edhe pretendimi osman i së drejtës mbi Çerkezinë (Majkop) dhe bregun çerkez (Soçi, Tuapse); bregu më pas i kaloi Rusisë (Soçi dhe Tuapse 1838).", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Fermani i autonomisë për Serbinë — knjazëria e trashëgueshme dhe kushti i garnizonit", "6a5d901d"], "d": ["Hatt-i humajuni, i nxjerrë në përputhje me dispozitën e Traktatit të Edrenesë për Serbinë, e njohu Millosh Obrenoviqin si knjaz të trashëgueshëm dhe e bëri Serbinë principatë autonome, të lirë në punët e brendshme e të lidhur me Osmanët në ato të jashtme. Dispozitat: knjazëria do të kalonte nga ati te i biri, taksa vjetore do të paguhej si shumë e prerë, kuvendi serb do të krijonte administrimin e vet të brendshëm, kisha do të ishte autonome; në këmbim, në kalatë e Beogradit, Smederevës, Shabacit, Bëgyrdelenit dhe Fethylislamit do të mbeteshin garnizone osmane. Kjo strukturë e dyfishtë zgjati deri në tërheqjen e garnizoneve në vitin 1867. Në hartë qyteti i Beogradit në këtë datë i bashkohet Serbisë autonome; kalaja Kalemegdan paraqitet deri më 1867 me garnizon osman.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Dorëzimi i Qipros nën administrimin anglez", "423da3ee"], "d": ["Si shpërblim për aleancën kundër kërcënimit rus, administrimi i Qipros iu kalua Anglisë; juridikisht mbeti tokë osmane. Vendbanime të tjera që u humbën në të njëjtën datë: Nikosia, Famagusta, Kirenia, Limasoli, Larnaka (Tuzla), Pafosi, Morfu (Güzelyurt), Akrotiri, Episkopi, Dhekelia (Dikelya); pra i gjithë ishulli.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Dorëzimi i Thesalisë Greqisë", "ac614d24"], "d": ["Në përputhje me vendimet e Kongresit të Berlinit, Thesalia dhe rrethinat e Artës iu dorëzuan Greqisë. Vendbanime të tjera që u humbën në të njëjtën datë: Arta, Larisa (Jenishehir), Trikalla, Lamia (Izdin). Me këtë dorëzim Volosi, Kalambaka dhe Karditsa (Thesali) kaluan te Greqia.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Bashkimi i Rumelisë Lindore me Bullgarinë", "ee43f137"], "d": ["Vilajeti autonom i Rumelisë Lindore u lidh me Bullgarinë me një grusht shteti; Porta e Lartë e pranoi faktin e kryer. Me këtë bashkim e gjithë Rumelia Lindore (Stara Zagora, Tatarpazarxhiku, Slliveni, Haskova, Burgasi, Ajtosi, Elhova) kaloi te Principata e Bullgarisë.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Beteja Fushore e Domokosë", "9c6f29a5"], "d": ["Në luftën osmano-greke të vitit 1897 ushtria korri një fitore vendimtare në Domoko; me presionin diplomatik, fitimi territorial mbeti i kufizuar.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomia për Kretën", "2e764881"], "d": ["Megjithëse lufta osmano-greke përfundoi me fitoren osmane, Anglia, Rusia, Franca dhe Italia më 18 dhjetor 1897 shpallën autonominë e Kretës; ishulli do të ishte vilajet neutral dhe autonom nën sovranitetin osman. Pas 6 nëntorit 1898 flamuri turk nuk u ngrit më në Kandia dhe në Kisamo; me marrjen e detyrës nga princi Gjergj, i biri i mbretit grek, si komisar i jashtëzakonshëm më 22 dhjetor 1898, Kreta de fakto doli nga administrimi osman (zyrtarisht u shkëput më 1913). Vendbanime të tjera që u humbën në të njëjtën datë: Kandia (Kretë), Hania.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Pavarësia e Bullgarisë dhe aneksimi i Bosnjës", "393feaa4"], "d": ["Në rrëmujën e Mbretërisë Kushtetuese, Bullgaria shpalli pavarësinë dhe Austro-Hungaria aneksoi Bosnjë-Hercegovinën. Me këtë shpallje të gjitha tokat e Principatës së Bullgarisë (Varna, Shumeni, Ruseja, Burgasi, Slliveni etj.) u bënë Mbretëria e pavarur e Bullgarisë.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Rimarrja e Edrenesë", "536e5599"], "d": ["Në Luftën e Dytë Ballkanike ushtria kaloi Maricën dhe e rimori Edrenenë pa luftë. Vende të tjera që u bashkuan në të njëjtën datë: Kërklareli, Tekirdag.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Fitorja e Kut el-Amarës", "98b972bc"], "d": ["Divizioni anglez i rrethuar në Kut u dorëzua me komandantin dhe 13 mijë ushtarë — një nga fitoret më të mëdha osmane të Luftës së Parë Botërore.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Humbja e Bagdadit", "2c18a816"], "d": ["Bagdadi, 383 vjet osman, i kaloi ushtrisë angleze. Vendbanime të tjera që u humbën në të njëjtën datë: Qerbela, Këzëlrubat.", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Humbja e Jerusalemit", "94067617"], "d": ["Jerusalemi, 401 vjet osman, u dorëzua pa mundur të mbrohej.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Humbja e Damaskut", "ed177b68"], "d": ["Me shembjen e frontit të Palestinës, Damasku u zbraz; administrimi osman katërshekullor në Siri mori fund. Vendbanime të tjera që u humbën në të njëjtën datë: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Dorëzimi i Medinës", "76b505f6"], "d": ["72 ditë pas armëpushimit, rezistenca e Fahredin Pashës, 'Tigrit të Shkretëtirës', mori fund me vullnetin e padishahut; njësia e fundit osmane në Hixhaz dorëzoi armët.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Pushtimi i Izmirit", "e32e5e77"], "d": ["Ushtria greke zbarkoi në Izmir; rezistenca që nisi me plumbin e parë ndezi fitilin e Luftës Nacionale. Kurse Ajdëni u pushtua më 27 maj 1919 (zë më vete).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Pushtimi zyrtar i Stambollit", "a8e98ada"], "d": ["Forcat e Antantës pushtuan zyrtarisht Stambollin, Kuvendi i Deputetëve u shpërnda; deputetët u drejtuan për në Ankara.", "09ed005b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1284-01-01:0":{"b": ["Kontea e Shampanjës, me martesën e Zhanës I me Filipin IV, iu lidh kurorës franceze: Troja (bashkë me Meaux-në)", "cae2654d"], "d": ["Me martesën e konteshës së Shampanjës dhe mbretëreshës së Navarrës, Zhanës I, me trashëgimtarin e fronit francez Filipin (IV) (1284), kryeqyteti i Shampanjës, Troyes, iu bashkua tokave të kurorës; për Meaux-në Treccani thotë po atë vit (1284) 'kaloi te mbreti i Francës'. Aneksimi zyrtar i kontesë është në vitin 1314, me hipjen në fron të Luigjit X (titullatura t).", "03072856"]},
"OLAYLAR_FRANSA_KONTROL_1027:1305-01-01:0":{"b": ["Konti i Flandrës ia la mbretit francez Filipit IV Flandrën Valone (Lille, Douai, Béthune): Lille", "a4746f27"], "d": ["Pjesa 'franceze' (valone) e Kontesë së Flandrës — kastelanitë e Douai-së, Béthune-s dhe Lille-s — iu dha mbretit francez në vitin 1305 (dorëzimi përfundimtar 1320); në vitin 1369 ato i morën dukët e Burgonjës me anë martese.", "fa06bb72"]},
"OLAYLAR_FRANSA_KONTROL_1027:1312-01-01:0":{"b": ["Në Lion u vendos epërsia e mbretit francez: Filipi IV (i Bukuri), me Traktatin e Vienne-s, mori Lionin, feud perandorak", "60ea68d8"], "d": ["Në Lion, që nga viti 1032 feud i perandorit gjerman, ku pushteti faktik ndahej midis kryepeshkopit dhe kontëve të Forez-it, në vitin 1312 u vendos epërsia e mbretit francez Filipit IV; që nga kjo datë qyteti konsiderohet i Francës.", "74a8638d"]},
"OLAYLAR_FRANSA_KONTROL_1027:1314-11-29:0":{"b": ["Filipi IV vdiq; Luigji X (Kokëforti) u bë mbret i Francës", "10fd76ef"], "d": ["Filipi IV vdiq më 29 nëntor 1314; djali i tij Luigji X hipi në fronin e Francës (ai ishte tashmë që nga viti 1305 mbret i Navarrës).", "3aa6f8e3"]},
"OLAYLAR_FRANSA_KONTROL_1027:1317-01-09:0":{"b": ["Filipi V u kurorëzua në Reims (pasi ishte regjent pas vdekjes së Luigjit X, me vdekjen e nipit Gjon I e kishte shpallur veten mbret)", "3b50d3fc"], "d": ["Luigji X vdiq më 5 korrik 1316; regjenti Filipi V, pas Gjonit I, djalit të lindur pas vdekjes së babait që vdiq 4 ditë pas lindjes, e shpalli veten mbret dhe u kurorëzua në Reims më 9 janar 1317. Dita e shpalljes mungon te burimi; atlasi merr ditën e kurorëzimit.", "5e0b5084"]},
"OLAYLAR_FRANSA_KONTROL_1027:1322-01-03:0":{"b": ["Filipi V vdiq; Karli IV u bë mbret i Francës", "a0b9abda"], "d": ["Filipi V vdiq në Longchamp natën e 2 janarit 1322; vëllai i tij Karli IV hipi në fron.", "a4efde24"]},
"OLAYLAR_FRANSA_KONTROL_1027:1328-05-29:0":{"b": ["Filipi VI (Valua) u kurorëzua në Reims: nisi dinastia Valua", "a9595d82"], "d": ["Kur Karli IV vdiq në shkurt 1328 pa lënë trashëgimtar mashkull, Filipi i Valuasë u bë regjent; më 29 maj 1328 u kurorëzua në Reims dhe nisi dinastinë Valua. Pretendimi i mbretit anglez Eduardit III nga ana e nënës është një nga shkëndijat e Luftës Njëqindvjeçare.", "aca69718"]},
"OLAYLAR_FRANSA_KONTROL_1027:1348-06-09:0":{"b": ["Mbretëresha e Napolit Xhovana ia shiti Avinjonin papës Klementit VI", "ecd3d028"], "d": ["Në cilësinë e konteshës së Provancës, mbretëresha e Napolit Xhovana më 9 qershor 1348 ia shiti papës Klementit VI qytetin e Avinjonit për 80.000 florinë; qyteti deri në vitin 1791 mbeti eksklavë e Papatit. Regjistrimi i vendbanimit e kishte këtë kufi; mungonte zëri.", "682eb4f6"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-04-18:0":{"b": ["Filipi VI e bleu Montpellier-në nga mbreti i Majorkës", "05d06418"], "d": ["Më 18 prill 1349 u miratua shitja nga mbreti i Majorkës Jaume III e të drejtave të tij mbi Montpellier te mbreti francez Filipi VI; Montpellier kaloi te kurora franceze.", "302b9de1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-07-16:0":{"b": ["Humbert II ia dorëzoi Dofinenë nipit të mbretit të Francës: Grenobli", "a8d8a248"], "d": ["Më 30 mars 1349 u lidh traktati i Romans-it midis Humbertit II dhe mbretit francez; më 16 korrik 1349 në Lion, me aktin 'Transport du Dauphiné à la France', tokat dhe titulli i Dofinesë iu lanë Karlit (nipit të mbretit francez Filipit VI). Që nga ky çast, 'Dauphin' u bë titulli i trashëgimtarit të fronit francez.", "c129d1f5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1350-08-22:0":{"b": ["Filipi VI vdiq; Gjoni II (i Miri) u bë mbret i Francës", "3eb96ab5"], "d": ["Filipi VI vdiq më 22 gusht 1350 në Nogent-le-Roi; djali i tij Gjoni II hipi në fron.", "ed19aa83"]},
"OLAYLAR_FRANSA_KONTROL_1027:1360-10-24:0":{"b": ["Traktati i Kalesë: u miratuan kushtet e Brétigny-së, Puatuja dhe Akuitania iu dorëzuan Anglisë: Puatje", "8e13271f"], "d": ["Marrëveshja paraprake e Brétigny-së e 8 majit 1360 u miratua në Kale më 24 tetor 1360: Puatuja, Saintonge, Aunis, Agenais, Périgord, Limousin, Quercy, Angoumois dhe Rouergue iu lanë Anglisë. Limozha, La Rochelle-ja dhe Puatje në atlas kalojnë në këtë ditë te Anglia.", "278ddde1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1388-09-28:0":{"b": ["Nica iu dorëzua kontit të Savojës Amedeo VII ('dédition' e Nicës te Savoja)", "3af46844"], "d": ["Gjatë grindjes për trashëgiminë midis trashëgimtarëve anzhuinë të Provancës, Nica dhe rrethinat (Kontea e Nicës) më 28 shtator 1388 hynë nën sundimin e kontit të Savojës Amedeo VII; Nica deri në vitin 1860 (përveç pushtimeve franceze) mbeti te dinastia Savojë/Sardinjë. Atlasi e kishte tashmë këtë kufi; mungonte zëri.", "04a5e558"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-05-21:0":{"b": ["Traktati i Troyes-it: Henri V u bë regjent dhe trashëgimtar i Francës, Shampanja hyri nën administratën anglo-burgonje: Troja", "21c6f014"], "d": ["Traktati i nënshkruar në Troyes më 21 maj 1420 midis Karlit VI dhe mbretit anglez Henrit V e bëri Henrin V regjent dhe trashëgimtar të fronit të Francës; delfini Karl (Karli VII) u përjashtua nga trashëgimia. Traktati nuk dorëzon toka; Shampanja (Troyes, Reims) nga kjo datë deri në 1429 mbeti nën administratën anglo-burgonje ('Franca lankasteriane') dhe atlasi këtë administratë e ngjyros me identitetin e Anglisë.", "e9351409"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-05-21:1":{"b": ["Traktati i Troyes-it: Henri V u bë regjent dhe trashëgimtar i Francës, Shampanja hyri nën administratën anglo-burgonje: Reimsi", "5d0dea46"], "d": ["Traktati i nënshkruar në Troyes më 21 maj 1420 midis Karlit VI dhe mbretit anglez Henrit V e bëri Henrin V regjent dhe trashëgimtar të fronit të Francës; delfini Karl (Karli VII) u përjashtua nga trashëgimia. Traktati nuk dorëzon toka; Shampanja (Troyes, Reims) nga kjo datë deri në 1429 mbeti nën administratën anglo-burgonje ('Franca lankasteriane') dhe atlasi këtë administratë e ngjyros me identitetin e Anglisë.", "e9351409"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-12-01:0":{"b": ["Henri V hyri në Paris: nisi regjimi anglo-burgonj", "126d50cb"], "d": ["Pas Traktatit të Troyes-it (21 maj 1420), në dhjetor 1420 Parisi hyri nën sundimin anglo-burgonj; qyteti deri në prill 1436 u administrua në emër të Henrit VI. Vendbanime të tjera që u humbën në të njëjtën datë: Sèvres, Fontainebleau, Saint-Germain-en-Laye, Versaja, Neuilly-sur-Seine (rrethinat e Parisit).", "0fb14bbf"]},
"OLAYLAR_FRANSA_KONTROL_1027:1422-10-21:0":{"b": ["Karli VI vdiq; Karli VII u shpall mbret i Francës", "7aeefd1a"], "d": ["Karli VI vdiq më 21 tetor 1422; pavarësisht Traktatit të Troyes-it, Karli VII e shpalli veten mbret (rajoni i Bourges-it); Parisi mbeti nën kontrollin anglo-burgonj.", "da118a77"]},
"OLAYLAR_FRANSA_KONTROL_1027:1435-09-21:0":{"b": ["Traktati i Arrasit: qytezat e Somme-s dhe Mâconnais iu lanë Burgonjës: Amiensi", "8e68bd94"], "d": ["Traktati i Arrasit, i nënshkruar më 21 shtator 1435 midis Karlit VII dhe dukës së Burgonjës Filipit të Mirë, e shkëputi Burgonjën nga aleanca angleze. Në këmbim, qytezat e Somme-s (përfshirë Amiensin), Mâcon dhe Mâconnais si dhe Auxerre dhe Auxerrois iu lanë dukatit të Burgonjës (me kushtin që qytezat e Somme-s të mund të bliheshin përsëri).", "4ab2b326"]},
"OLAYLAR_FRANSA_KONTROL_1027:1435-09-21:1":{"b": ["Traktati i Arrasit: qytezat e Somme-s dhe Mâconnais iu lanë Burgonjës: Mâcon", "3d7aa44d"], "d": ["Traktati i Arrasit, i nënshkruar më 21 shtator 1435 midis Karlit VII dhe dukës së Burgonjës Filipit të Mirë, e shkëputi Burgonjën nga aleanca angleze. Në këmbim, qytezat e Somme-s (përfshirë Amiensin), Mâcon dhe Mâconnais si dhe Auxerre dhe Auxerrois iu lanë dukatit të Burgonjës (me kushtin që qytezat e Somme-s të mund të bliheshin përsëri).", "4ab2b326"]},
"OLAYLAR_FRANSA_KONTROL_1027:1436-04-13:0":{"b": ["Parisi iu dorëzua mbretit francez Karlit VII", "f3d92546"], "d": ["Pas Traktatit të Arrasit (1435), populli i Parisit më 13 prill 1436 ua hapi portat komandantëve të Karlit VII; mori fund administrata angleze.", "79a422fe"]},
"OLAYLAR_FRANSA_KONTROL_1027:1450-04-15:0":{"b": ["Beteja e Formigny-së: ushtria franceze mundi ushtrinë angleze, u përshpejtua rimarrja e Normandisë", "77d20042"], "d": ["Më 15 prill 1450 në Formigny ushtria franceze mundi forcën ndihmëse angleze; Caen dhe Cherbourg ranë, Normandia u kthye nën kontrollin francez.", "0287dae5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1477-01-01:0":{"b": ["Luigji XI mori Artuanë (Arrasin) nga trashëgimia burgonje", "da697a1e"], "d": ["Me vdekjen e Karlit të Guximshëm në Nancy (5 janar 1477), mbreti francez Luigji XI pushtoi Artuanë; meqë Arrasi qëndroi, u mor me sulm dhe muret iu rrënuan. Traktati i Arrasit (23 dhjetor 1482) ia la Artuanë Francës me pajën e Margaritës; me Traktatin e Senlis-it të vitit 1493 u kthye te Habsburgët.", "7867c9fc"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:0":{"b": ["Me vdekjen e Karlit III, Provanca sipas testamentit të tij kaloi te mbreti francez Luigji XI: Aix-en-Provence", "dc558e2c"], "d": ["Konti i fundit i Provancës nga dinastia Anzhu, Karli III, bëri testamentin në Marsejë më 10 dhjetor 1481 dhe vdiq më 11 dhjetor 1481; Kontea e Provancës kaloi në duart e mbretit francez. Bashkimi u përforcua juridikisht në vitin 1486 (me miratimin e Shteteve të Provancës).", "42fad3ff"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:1":{"b": ["Me vdekjen e Karlit III, Provanca sipas testamentit të tij kaloi te mbreti francez Luigji XI: Marseja", "bd072b2d"], "d": ["Testamenti u hartua në Marsejë (10 dhjetor 1481); me vdekjen e Karlit (11 dhjetor) Provanca dhe me të Marseja kaluan te kurora franceze.", "3baf7804"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:2":{"b": ["Me vdekjen e Karlit III, Provanca sipas testamentit të tij kaloi te mbreti francez Luigji XI: Arli", "de44f23c"], "d": ["Arli ishte që nga viti 1251 në duart e kontëve të Provancës (Anzhu); me kalimin e kontesë te kurora franceze (11 dhjetor 1481) u bë francez.", "b58a0e54"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:3":{"b": ["Me vdekjen e Karlit III, Provanca sipas testamentit të tij kaloi te mbreti francez Luigji XI: Tuloni", "7a8c1f9a"], "d": ["Porti i Provancës, Tuloni, u bë francez me kalimin e kontesë te kurora franceze (11 dhjetor 1481); nuk ka burim të veçantë për Tulonin, qendra e madhe referuese (\"abi merkez\") është Aix-en-Provence (PËRAFRIM I DEKLARUAR).", "11d22f4b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1493-01-01:0":{"b": ["Traktati i Senlis-it: Arrasi (Artuaja) iu kthye habsburgut Maksimilian", "040b03f8"], "d": ["Traktati i Senlis-it midis Karlit VIII dhe Maksimilianit I (1493) ua dha Artuanë dhe Arrasin Habsburgëve.", "2e7e96b7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1498-04-07:0":{"b": ["Karli VIII vdiq; Luigji XII u bë mbret i Francës", "560db6d5"], "d": ["Karli VIII vdiq më 7 prill 1498 në Amboise; kushëriri i tij, duka i Orleanit Luigji XII, hipi në fron.", "24214314"]},
"OLAYLAR_FRANSA_KONTROL_1027:1552-01-01:0":{"b": ["Fushata e Henrit II për Tri Peshkopatat: Tuli iu bashkua Francës", "5d7053ac"], "d": ["Tuli, i udhëhequr nga peshkopë-kontë dhe i lidhur me Perandorinë Gjermane, iu bashkua Francës në vitin 1552 (bashkë me Mecin dhe Verdenin, Tri Peshkopatat); juridikisht u miratua në Vestfali në vitin 1648. Dita e Mecit (18 prill 1552) në atlas është e veçantë; për Tulin dita mungon te burimi.", "5cdb37db"]},
"OLAYLAR_FRANSA_KONTROL_1027:1559-07-10:0":{"b": ["Henri II vdiq; Francesku II u bë mbret i Francës", "88a1a26e"], "d": ["Henri II vdiq më 10 korrik 1559; djali i tij 15-vjeçar Francesku II hipi në fron (ndikimi i dinastisë Guise).", "746455f8"]},
"OLAYLAR_FRANSA_KONTROL_1027:1560-12-05:0":{"b": ["Francesku II vdiq; Karli IX u bë mbret i Francës", "16566c2b"], "d": ["Francesku II vdiq më 5 dhjetor 1560; vëllai i tij Karli IX (10 vjeç) hipi në fron, nëna e tij Katerina de' Mediçi u bë regjente.", "0139a790"]},
"OLAYLAR_FRANSA_KONTROL_1027:1574-05-30:0":{"b": ["Karli IX vdiq; Henri III u bë mbret i Francës (ndërsa ishte mbret i Polonisë)", "f86885f1"], "d": ["Karli IX vdiq më 30 maj 1574; vëllai i tij Henri de Valua, mbret i Polonisë, u bë trashëgimtar i fronit francez dhe në shtator 1574 u kthye në Francë.", "f3fea374"]},
"OLAYLAR_FRANSA_KONTROL_1027:1589-08-01:0":{"b": ["Henri III në shtratin e vdekjes njohu Henrin e Navarrës (Henri IV) si pasardhës: nis dinastia Burbon", "328bca08"], "d": ["Henri III, pre e atentatit, si mbreti i fundit i linjës Valua, më 1 gusht 1589 e njohu solemnisht Henrin e Navarrës si pasardhës; me vdekjen e tij (2 gusht) dinastia Burbon kaloi në fronin e Francës.", "df18d0c2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1610-05-14:0":{"b": ["Sundimi i Henrit IV mori fund; Luigji XIII u bë mbret", "dfe5892c"], "d": ["Henri IV vdiq nga atentati në Paris më 14 maj 1610; djali i tij Luigji XIII u bë mbret. (Fundi i sundimit te Treccani: «Regnò fino al 14 maggio 1610».)", "86a0f811"]},
"OLAYLAR_FRANSA_KONTROL_1027:1643-05-14:0":{"b": ["Luigji XIII vdiq; Luigji XIV pesëvjeçar u bë mbret (regjenca: Ana e Austrisë, Mazarin)", "2ac0d106"], "d": ["Luigji XIII vdiq më 14 maj 1643 në Saint-Germain-en-Laye; djali i tij Luigji XIV hipi në fron po atë ditë.", "6a173c34"]},
"OLAYLAR_FRANSA_KONTROL_1027:1659-11-07:0":{"b": ["Traktati i Pirenejve: Rusijoni dhe Artuaja kaluan te Franca: Perpinjani", "7c9041e1"], "d": ["Traktati i Pirenejve, i nënshkruar më 7 nëntor 1659 midis Francës dhe Spanjës në Ishullin e Fazanëve (île des Faisans) në Bidasoa, ia la Francës Rusijonin, Cerdanjën Veriore dhe Artuanë. Perpinjani që nga viti 1642, Arrasi që nga 1640 ishin faktikisht nën pushtimin francez; atlasi këputjen e sovranitetit e shkruan në ditën e traktatit.", "82ee6b22"]},
"OLAYLAR_FRANSA_KONTROL_1027:1659-11-07:1":{"b": ["Traktati i Pirenejve: Rusijoni dhe Artuaja kaluan te Franca: Arrasi", "ef09e034"], "d": ["Traktati i Pirenejve, i nënshkruar më 7 nëntor 1659 midis Francës dhe Spanjës në Ishullin e Fazanëve (île des Faisans) në Bidasoa, ia la Francës Rusijonin, Cerdanjën Veriore dhe Artuanë. Perpinjani që nga viti 1642, Arrasi që nga 1640 ishin faktikisht nën pushtimin francez; atlasi këputjen e sovranitetit e shkruan në ditën e traktatit.", "82ee6b22"]},
"OLAYLAR_FRANSA_KONTROL_1027:1681-09-30:0":{"b": ["Strasburgu kapitulloi para ushtrisë së Luigjit XIV: iu bashkua Francës", "3c3c1cc6"], "d": ["Gjatë politikës së Réunion-eve, ushtria e Louvois-së rrethoi Strasburgun; qyteti nënshkroi kushtet e dorëzimit më 30 shtator 1681 (akti i kapitullimit në Illkirch); ratifikimi më 3 tetor, hyrja solemne e Luigjit XIV më 23 tetor 1681. Qyteti iu bashkua Francës, autonomia komunale u zhduk.", "4f2a5014"]},
"OLAYLAR_FRANSA_KONTROL_1027:1791-09-14:0":{"b": ["Asambleja Kushtetuese miratoi bashkimin e Avinjonit dhe të Comtat Venaissin-it me Francën", "d15fe246"], "d": ["Pas dëbimit të vicelegatit papnor nga Avinjoni (12 qershor 1790), Asambleja Kushtetuese shqyrtoi kërkesën për bashkim; bashkimi u miratua më 14 shtator 1791. Piu VI kundërshtoi më 5 nëntor 1791; me nenin 6 të Traktatit të Tolentinos (19 shkurt 1797) papati hoqi dorë nga Avinjoni dhe Comtat-i.", "a422cae7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1793-01-03:0":{"b": ["Monako iu bashkua Republikës Franceze me emrin Fort-Hercule", "1b846e31"], "d": ["Me aneksimin e Monakos nga Franca revolucionare, sovraniteti i Grimaldëve u ndërpre; principata deri në vitin 1814 u bë pjesë e Francës (Fort-Hercule).", "c3f4c386"]},
"OLAYLAR_FRANSA_KONTROL_1027:1795-07-22:0":{"b": ["Traktati i Bazelit: Spanja ia la Francës lindjen e Hispaniolës (Santo Domingon): Santo Domingo", "25497735"], "d": ["Paqja e nënshkruar në Bazel më 22 korrik 1795 midis Spanjës dhe Republikës Franceze, kundrejt heqjes së pushtimit francez në Pirenej, ia la Francës pjesën spanjolle të ishullit Hispaniola (Santo Domingo, Santiago de los Caballeros, Higüey).", "d1c0a4ab"]},
"OLAYLAR_FRANSA_KONTROL_1027:1798-03-15:0":{"b": ["Republika e Mulhouse-it iu bashkua Republikës Franceze (Réunion)", "0c2b4f8a"], "d": ["Republika e Mulhouse-it, aleate e Konfederatës Zvicerane që nga viti 1515, pas Paqes së Bazelit (1795) iu bashkua vullnetarisht Francës; bashkimi u krye në vitin 1798 (Réunion).", "e775b26b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1814-05-30:0":{"b": ["Traktati i Parisit: Monako iu kthye sovranitetit të Grimaldëve", "f3011157"], "d": ["Me Traktatin e Parisit të 30 majit 1814 u kthyen të drejtat e Grimaldëve; Monako doli nga aneksimi francez (protektorati i Sardinjës 1815–1861 është çështje e veçantë dhe nuk trajtohet në këtë regjistrim). Me këtë traktat Mentoni (Principata e Monakos) iu kthye sovranitetit të Grimaldëve.", "91de9178"]},
"OLAYLAR_FRANSA_KONTROL_1027:1861-02-02:0":{"b": ["Traktati Francë-Monako: Monako hoqi dorë nga të drejtat mbi Mentonin (dhe Roquebrune-n) kundrejt 4 milionë frangave; Mentoni kaloi te Franca", "ffa21e54"], "d": ["Pas dorëzimit të Nicës te Franca nga Piemont-Sardinja në vitin 1860, Princi i Monakos ia dorëzoi Francës të drejtat sovrane mbi Mentonin dhe Roquebrune-n. Mentoni që nga viti 1848 ishte qytet i lirë, nën protektoratin e Sardinjës.", "0aff978e"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-17:0":{"b": ["Njësitë franceze hynë në Mulhouse: nisi kthimi i Alzasës", "a56edca7"], "d": ["Gjashtë ditë pas armëpushimit (11 nëntor 1918), njësitë franceze hynë në Mulhouse. Neni 51 i Versajës e konsideron kthimin e Alzas-Lorenës nën sovranitetin francez me fuqi prapavepruese nga 11 nëntori 1918; nënshkrimi 28 qershor 1919, hyrja në fuqi 10 janar 1920.", "204a7d28"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-18:0":{"b": ["Njësitë franceze hynë në Colmar", "dabdf81a"], "d": ["Colmari më 18 nëntor 1918 i priti njësitë franceze; Alzasa po kthehej nën administratën franceze (fuqia prapavepruese juridike 11 nëntor 1918, neni 51 i Versajës).", "04dcdb67"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-19:0":{"b": ["Divizioni 28 francez i këmbësorisë hyri në Mec", "c37a5b99"], "d": ["Divizioni 28 francez i këmbësorisë hyri në Mec më 19 nëntor 1918; Moselle u kthye nën administratën franceze.", "aa57e100"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-21:0":{"b": ["Njësitë franceze hynë në Strasburg (ceremonia zyrtare 22 nëntor)", "92b3cc2e"], "d": ["Pas 47 vitesh administratë gjermane, njësitë e para franceze hynë në Strasburg më 21 nëntor 1918; ceremonia zyrtare e hyrjes u bë të nesërmen.", "22f53345"]},
"OLAYLAR_FRANSA_KONTROL_1027:1940-08-02:0":{"b": ["Wagner dhe Bürckel u bënë shefa të administratës civile të Alzasës dhe Lorenës: rajoni faktikisht iu bashkua Reich-ut", "0e36dc11"], "d": ["Pas disfatës së Francës, Alzasa dhe Moselle iu bashkuan Gjermanisë faktikisht, pa traktat: Alzasa iu dha administratës civile të gauleiterit të Badenit, Wagner, Moselle asaj të gauleiterit të Saar-Pfalz-it, Bürckel (Moselle më 30 nëntor 1940 iu lidh Gau Westmark-ut). Në tekstin e armëpushimit nuk ka nen aneksimi; juridikisht sovraniteti francez vazhdon (ordonanca e 9 gushtit 1944). Me këto emërime Meci (Moselle), Colmari dhe Mulhouse (Alzasë) kaluan faktikisht nën administratën civile gjermane.", "01aeb601"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-20:0":{"b": ["Mulhouse u çlirua", "151f48e4"], "d": ["Armata I franceze (de Lattre) çliroi Mulhouse-in në nëntor 1944.", "78fba884"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-22:0":{"b": ["Meci u çlirua (kështjellat qëndruan deri në dhjetor)", "17049694"], "d": ["Armata III e SHBA-së çliroi Mecin më 22 nëntor 1944; kështjellat përreth qëndruan deri në muajin dhjetor.", "4566f454"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-23:0":{"b": ["Divizioni 2 i blinduar i Leclerc-ut çliroi Strasburgun", "7b399aa3"], "d": ["Divizioni 2 i blinduar nën komandën e Leclerc-ut hyri në Strasburg më 23 nëntor 1944; mori fund administrata gjermane në kryeqytetin e Alzasës (aneksim faktik që nga viti 1940).", "4f1f13e2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1945-02-02:0":{"b": ["Colmari u çlirua (Xhepi i Colmarit u pastrua më 9 shkurt)", "41a297f7"], "d": ["Colmari u çlirua më 2 shkurt 1945; Xhepi i Colmarit u pastrua plotësisht më 9 shkurt 1945.", "3cc05417"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Nisja e Kanuniut në fushatën e Vjenës — lufta me Habsburgët filloi sërish", "f7afd2a9"], "d": ["Pas Mohaçit froni hungarez ishte ndarë më dysh, Ferdinandi në 1527 kishte marrë Budinin dhe e kishte nxjerrë Zápolya-n nga kryeqyteti. Padishahu doli për herë të katërt në fushatë për të mbështetur Zápolya-n dhe për të ndalur përparimin habsburg; para fushatës, veziri i madh Ibrahim Pasha u pajis me titullin serasker dhe me bejlerbejllëkun e Rumelisë dhe i gjithë planifikimi u bë me të. Shirat e dendura gjatë rrugës e vonuan përparimin e ushtrisë; fushata vazhdoi me marrjen e Budinit dhe dhënien e tij Zápolya-s, dhe me rrethimin e Vjenës.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Ripërtëritja e paqes me Habsburgët — fundi i luftës së Transilvanisë dhe Temeshvarit", "97071975"], "d": ["Lufta që filloi me kalimin e Transilvanisë te Ferdinandi në 1551 dhe vazhdoi me fushata si pushtimi i Temeshvarit dhe rrethimi i Egerit u mbyll me vendimin për vazhdimin e paqes me Habsburgët. Marrëveshja i ripërtërinte reciprokisht angazhimet e vjetra të të dyja palëve; por nuk solli zgjidhje për trazirat në zonat kufitare dhe pas vdekjes së Ferdinandit në 1564 ngjarjet në Transilvani u shtuan sërish.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["Fushata e fundit e Kanuniut — nisja nga Stambolli me synim Sigetvarin dhe Egerin", "31277d21"], "d": ["Pas vdekjes së Ferdinandit në 1564 dhe hipjes në fron të Maksimilianit II, përplasjet në kufirin e Transilvanisë ishin shtuar. Në fushatën që padishahu plak e planifikoi me Mehmet Pashë Sokolin, objektivi do të ishin kështjellat e Sigetvarit dhe Egerit dhe perandorit do t'i jepej një kërcënim. Pasi u lut në tyrben e Ejup Sulltanit, u nis nga Stambolli me një ceremoni madhështore; më 15 maj arriti në Edrene dhe në ditën e pesëdhjetë të nisjes arriti në Beograd. Kjo ishte dalja e fundit nga kryeqyteti që nuk do ta shihte më kurrë.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Traktati i Edrenes — fundi i gjendjes së luftës me Habsburgët", "d08883e3"], "d": ["Pas fushatës së Sigetvarit, në prani të Selimit II, që po dimëronte në Edrene, ndodheshin ambasadorët habsburg, safavid, polak, francez dhe venedikas. U vendos që paqja me safavidët të vazhdonte; u nënshkrua traktati që i dha fund gjendjes së luftës me Habsburgët. Në këto punë ndikimi i veziriut të madh Mehmet Pashë Sokoli ishte i madh.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Vendimi për fushatën e Iranit — dy serdarë u emëruan kundër safavidëve të tronditur nga vdekja e Tahmaspit", "1f09b186"], "d": ["Me helmimin e Shah Tahmaspit I në 1576, si pasojë e grindjeve brenda dinastisë dhe midis burrave të shtetit, safavidët ishin zhytur në një kaos të madh; kjo gjendje përcaktoi drejtimin e fushatës që do të hapej. Lala Mustafa Pasha u ngarkua të hynte në Iran nga ana e Erzurumit, Koxha Sinan Pasha nga ana e Bagdadit. Kur grindja midis dy vezirëve u shtua, ndërhyri Sokoli: Sinan Pasha u hoq nga detyra, Lala Mustafa Pasha u ngarkua me pushtimin e Shirvanit nëpërmjet Gjeorgjisë. Ky vendim është hapja e luftës osmano-safavide të viteve 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Cigalazade Sinan Pasha doli në fushatën e Iranit", "1e90763e"], "d": ["Ndërsa vazhdonte lufta në dy fronte me Iranin dhe Austrinë, Shah Abbasi kishte rrethuar dhe marrë Jerevanin, kishte hyrë në Kars, por ishte ndalur vetëm përpara Akhaltsikhes. Cigalazade Sinan Pasha, i emëruar serdar i Lindjes, u nis me vonesë nga Stambolli dhe më 8 nëntor arriti para Karsit. Ndonëse gjendja ishte e përshtatshme, nuk marshoi kundër shahut, por dimëroi në Van dhe, me sulmin e shahut, kaloi në Erzurum; një stinë fushate shkoi kot.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Disfata e Cigalazade Sinan Pashës pranë liqenit të Urmisë (Sufijan)", "7438fec4"], "d": ["Gjendja e Sinan Pashës, që marshonte për të rimarrë Tabrizin në stinën e fushatës së vitit 1605, u tronditë kur bejlerbeu i Erzurumit, Köse Sefer Pasha, veproi veç ushtrisë kryesore dhe ra rob. Sulmi i befasishëm i Shah Abbasit i shkaktoi ushtrisë një disfatë të rëndë rreth liqenit të Urmisë; Sinan Pasha u tërhoq fillimisht në Van, pastaj në Dijarbekir. Ekzekutimi i bejlerbeut të Halepit, Xhanbollatoglu Hysein Pasha, për arsyen se u vonua në ndihmë, ndezi një kryengritje të madhe në Anadoll; pas vdekjes së Sinan Pashës, Shah Abbasi mori Gjanxhën, Shirvanin dhe Shamahin.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Fushata e Kujuxhu Murat Pashës drejt Tabrizit — në Açıçaj nuk u bë përballje", "3c0a0a5d"], "d": ["Veziri i madh Kujuxhu Murat Pasha, që shtypi kryengritjet xhelali dhe vendosi qetësinë në Anadoll, marshoi nëpër Erzurum, Hasankale, Çalldiran dhe Hoj kundër Shah Abbasit, për të cilin ishte marrë lajmi se po priste në Tabriz. Dy ushtritë u ndodhën përballë në vendin e quajtur Açıçaj, në veri të Tabrizit, por nuk pati përleshje; letërkëmbimi vazhdoi. Për shkak të afrimit të dimrit dhe mungesës së municioneve e furnizimeve, pasha u tërhoq nëpër Ahlat, Van dhe Bitlis në Dijarbekir dhe vdiq atje verën pasardhëse, ndërsa po përgatiste një fushatë të re (5 gusht 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["Lufta osmano-safavide filloi sërish — veziri i madh Öküz Mehmed Pasha doli në fushatën e Lindjes", "ef32fa31"], "d": ["Kur nuk erdhi lajm nga Inxhili Mustafa Çavushi, i dërguar si ambasador në Iran pas Traktatit të Nasuh Pashës të vitit 1612, veziri i madh Mehmed Pasha u ngarkua me fushatën e Lindjes dhe, pasi përfundoi përgatitjet, kaloi në Yskydar. Pikërisht kur po nisej, erdhi lajmi se Inxhili Çavushi dhe ambasadori iranian Burun Kasëm Han kishin arritur në Van me marrëveshjen dhe dhuratat, por fushata nuk u shty. Veziri i madh e kaloi dimrin në Halep.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Rrethimi i Jerevanit — u hoq pa rezultat pas pesëdhjetë e pesë ditësh", "64a4ecb6"], "d": ["Veziri i madh, që doli në prill 1616 nga Halepi me një ushtri të madhe, arriti nëpër rrugën Erzurum-Kars para Jerevanit. Me mendimin se kështjella do të dorëzohej lehtë, nuk ishin sjellë topa të rëndë; rrethimi zgjati pesëdhjetë e pesë ditë në mungesë materialesh. Për shkak të rënies dëshmor të agait të jeniçerëve Muslu Aga dhe Tekeli Mehmed Pashës, ngurrimit të ushtarëve dhe përparimit të stinës, rrethimi u hoq dhe ushtria u tërhoq në Erzurum. Mehmed Pasha u shkarkua në nëntor 1616 dhe vendin e tij e zuri Halil Pasha.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Disfata e Seravit (Pul-i Shikeste) — fushata e Halil Pashës në Iran", "d323ed03"], "d": ["Halil Pasha, që u bë serdar në vend të Öküz Mehmed Pashës, marshoi sërish kundër Iranit në 1618. Beteja në vendin Pul-i Shikeste, midis Tabrizit dhe Ardabilit, përfundoi me disfatën e ushtrisë osmane. Pas kësaj disfate, që në burime quhet edhe Beteja e Seravit, po atë muaj u nënshkrua Traktati i Seravit.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["Rrethimi i Bagdadit nga Hafëz Ahmed Pasha — zgjati shtatë muaj e njëzet ditë, pa rezultat", "764acb0a"], "d": ["Osmanët, që humbën Bagdadin në 1623, marshuan për ta rimarrë qytetin nën komandën e veziriut të madh dhe serdarit Hafëz Ahmed Pasha. Kur në mbledhjen e Kirkukut propozimi për të mbajtur më parë grykat nuk u pranua, ushtria rrethoi drejtpërdrejt Bagdadin. Pasha hynte vetë në llogore; ndonëse ditën e shtatëdhjetë e dytë hynë në qytet nga një tunel i shpërthyer, ushtarët u zmbrapsën. Kur në mars 1626 Shah Abbasi erdhi në ndihmë me 30.000 veta, ushtria mbeti midis dy zjarreve; në sulmin e shahut më 7 qershor pati humbje të rënda. Kur u mbaruan furnizimet dhe i nxehti e ethet e dobësuan ushtrinë, rrethimi u hoq dhe ushtria u tërhoq në Dijarbekir.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["Rrethimi i Bagdadit nga Husrev Pasha — u hoq pas tridhjetë e nëntë ditësh", "18de5581"], "d": ["Veziri i madh Husrev Pasha, që pas fitores së Mihribanit (5 maj 1630) hyri në Hamadan dhe e dogji e shkatërroi qytetin, në vend që të marshonte mbi Kazvin, me vendim të këshillit të luftës të mbledhur në Dergezin u kthye drejt objektivit kryesor, Bagdadit. Ushtria, që arriti rrethinat e Bagdadit në fillim të gushtit, e rrethoi qytetin më 6 tetor. Në daljen e garnizonit iranian më 26 tetor dhe në sulmin e përgjithshëm të 9 nëntorit pati humbje të mëdha; edhe ky rrethim i dytë pas humbjes së Bagdadit u hoq pa rezultat. Ushtria u tërhoq në Mosul.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Lepanto iu kthye Osmanëve sipas Karllovcit", "9ca4f9dd"], "d": ["Lepanto, që pas një rezistence të gjatë gjatë luftërave të viteve 1683-1699 ra në korrik 1687 bashkë me kështjellat pranë tij në duart e Venedikut, mbeti në duart e venedikasve deri një vit pas Traktatit të Karllovcit dhe pastaj iu kthye Osmanëve. Kështu kështjella në hyrje të gjirit të Korintit u kthye nën administratë osmane pesëmbëdhjetë vjet para Moresë.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Topal Osman Pasha mundi Nadirin në Duxhum — rrethimi i Bagdadit u hoq", "7ae1fc9e"], "d": ["Kundër Nadirit, që rrethoi Bagdadin në janar 1733, ushtria nën komandën e Topal Osman Pashës, e dërguar në ndihmë të Bagdadit, theu forcat e Nadirit në Duxhum, pranë Samarrasë; Nadiri i plagosur u tërhoq në Hamadan dhe rrethimi shumëmujor u hoq. Por fitorja zgjati pak: Nadiri në fund të po atij viti hyri sërish në Irak dhe mundi forcat osmane në Akderbend, në veri të Kirkukut; Topal Osman Pasha humbi jetën gjatë këtyre luftimeve dhe u varros në Kirkuk.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Fushata e Nadir Shahut në Irak — filloi lufta e fundit osmano-iraniane, ra Kirkuku", "ba014bf5"], "d": ["Nadir Shahu, që qëndroi tetëmbëdhjetë muaj në Dagestan dhe Gjeorgji, meqë osmanët e hodhën poshtë kërkesën për njohjen e xhaferizmit si medh'hebi i pestë, nisi në 1743 një fushatë të re kundër osmanëve dhe hyri me ushtri të madhe në Kirkuk. Të njëjtin sukses nuk e pati në Mosul; u detyrua të heqë rrethimin. Kjo luftë është lufta e fundit osmano-iraniane, që përfundoi me Traktatin e Kerdenit të vitit 1746.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Rrethimi i Karsit nga Nadir Shahu — zgjati dy muaj, pa rezultat", "a3ea61d9"], "d": ["Shehzadeja safavid Safi Mirza, që ishte strehuar te osmanët, pretendonte fronin iranian; sipas planit, seraskeri i Karsit do ta çonte nëpër Tabriz në Isfahan dhe do ta hipte në fron, dhe osmanët kishin hapur tre fronte kundër Iranit. Për këtë arsye Nadir Shahu marshoi mbi Kars dhe e rrethoi kështjellën. Nga rrethimi dymujor nuk arriti asnjë rezultat.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Disfata e Kaghaverdit — ushtria e Jegen Mehmed Pashës u shpërbë", "7caf6f22"], "d": ["Vitin pas rrethimit të Karsit, Nadir Shahu i theu në vendin e quajtur Kaghaverd forcat osmane nën komandën e Jegen Mehmed Pashës. Pastaj u kthye në Isfahan. Heqja dorë vitin pasardhës nga këmbëngulja për njohjen e xhaferizmit i hapi rrugën Traktatit të Kerdenit.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Forcat saudito-vehabite shtien në dorë emiratin e Hailit — administrimi ishte në familjen Ibn Ali nga fisi Abde", "2d29ceb9"], "d": ["Kur forcat e Shtetit të Parë Saudit shtinë në dorë emiratin e Hailit, administrimi i qytetit ishte në familjen Ibn Ali nga fisi Abde i fisit Shamar. Kjo familje e drejtoi Hailin deri kur Abdullah b. Reshidi e mori emiratin më 1835; dinastia e Reshidëve u themelua vetëm në atë datë. Në atlas, Haili deri tani dukej pa zot deri më 1836, ndërsa burimi më 1820 e jep me emër emirin e qytetit.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Kalimi i ishujve të Kvarnerit te Mbretëria e Italisë e Napoleonit dhe i Gjirit të Kotorrit nën administrimin rus", "c5e411c8"], "d": ["Pas Traktatit të Pressburgut, ishujt e Kvarnerit — ndryshe nga Dalmacia — iu lidhën jo drejtpërdrejt Francës, por Mbretërisë së Italisë të Napoleonit; në Provincat Ilirike hynë vetëm më 1809. Ndërsa në Gjirin e Kotorrit (Boka Kotorska) administrimi austriak mori fund dhe mes viteve 1806-1807 u vendos administrimi rus; Boka kaloi te Franca vetëm më 1807. Këto dy dallime nuk mund të pasqyrohen me një dritare të vetme 'Francë' të atlasit.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Kalimi i Dalmacisë nën administrimin francez — zbatimi i Traktatit të Pressburgut (Bratislavës)", "00bfe4f6"], "d": ["Traktati i Pressburgut (Bratislavës) i 26 dhjetorit 1805 e detyroi Austrinë të hiqte dorë nga Istria, Dalmacia dhe të gjithë ishujt e Adriatikut. Franca e mori faktikisht administrimin në shkurt 1806; Zara mbeti seli e proveditorit të përgjithshëm dhe nga viti 1806 deri më 1810 këtë detyrë e ushtroi venedikasi Vicenzo Dandolo. Dalmacia pas Traktatit të Schönbrunnit të vitit 1809 iu bashkua Provincave Ilirike. Kështu mori fund administrimi i parë austriak që vazhdonte nga viti 1797 — në atlas kjo periudhë deri tani dukej austriake pa ndërprerje.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Rimarrja nga Austria e Provincave Ilirike dhe Dalmacisë — fundi i administrimit napoleonik", "1b2ac942"], "d": ["Në fund të vitit 1813, njësitë habsburge rimorën zonën në jug të Savës dhe u rivendos organizimi i vjetër kufitar; ushtria austriake hyri në Istri në tetor 1813. Karlovaci pas asaj date u bë pjesë e Mbretërisë Austriake të Ilirisë. Edhe periudha e administrimit francez në Dalmaci u mbyll më 1813. Përkatësia austriake e rajonit u miratua zyrtarisht me vendimet e Paqes së Parisit të vitit 1814 dhe të Kongresit të Vjenës të vitit 1815. Me këtë operacion, Villachu, Tarvisi, Gorizia, Gradisca dhe Pula (Provincat Ilirike) në fund të vitit 1813 u kthyen te Austria.", "bf1e49a8"]},
"OLAYLAR_KI117:1684-08-24:0":{"b": ["Kalimi i Jazlofçës në duart polake", "c86581e5"], "d": ["Në fushatën e Sobieskit në Moldavi, ushtria polake, pas një rrethimi dyditor, e rimori Jazlofçën, e cila që nga viti 1672 ishte në duart osmane. Kështu nisi shpërbërja e sanxhakut të Kamenecit.", "98482094"]},
"OLAYLAR_KI117:1684-11-03:0":{"b": ["Kthimi i Peshtit te osmanët", "13914c49"], "d": ["Peshti, ku njësitë habsburge hynë në qershor 1684, pas dështimit të rrethimit të Budinit u kthye në fillim të nëntorit 1684 përsëri nën kontrollin osman; Habsburgët do të hyjnë përfundimisht në Pesht në vitin 1686.", "41164adc"]},
"OLAYLAR_KI117:1686-01-01:0":{"b": ["Zbrazja e kështjellës së Meçibozhit nga osmanët", "2c4b5a7f"], "d": ["Kështjella e Meçibozhit në Podoli u zbraz nga osmanët në vitin 1686; gjatë tërheqjes u përpoqën ta hidhnin kështjellën në erë. Mori fund sundimi osman prej rreth tetë vjetësh.", "27fe058d"]},
"OLAYLAR_KI117:1686-06-17:0":{"b": ["Kalorësia habsburge hyri në Pesht — përgatitja për rrethimin e Budinit", "c9d23487"], "d": ["Pararoja e ushtrisë habsburge që përgatitej për rrethimin e Budinit, kalorësia bavareze, hyri në Peshtin e braktisur nga garnizoni osman; bregu lindor i Danubit kaloi përfundimisht nën kontrollin habsburg. Vetë Budini do të bjerë më 2 shtator.", "9329e3b2"]},
"OLAYLAR_KI117:1686-10-01:0":{"b": ["Kalimi i Mohaçit nën kontrollin habsburg", "f022d9c0"], "d": ["Pas rënies së Budinit, gjatë përparimit habsburg në jug të Danubit, Mohaçi në vjeshtën e vitit 1686 kaloi nën kontrollin e aleatëve; verën pasuese ushtria do të përpiqet t'u bëjë ballë atyre në këtë vijë në Harsan (1687).", "06cb2407"]},
"OLAYLAR_KI117:1687-07-01:0":{"b": ["Kalimi i Lepantos në duart e Venedikut", "8daedb90"], "d": ["Pas rënies së Patrës, edhe Lepantoja në hyrje të Gjirit të Korintit u braktis nga osmanët dhe kaloi nën kontrollin venedikas; do të kthehet me Traktatin e Karlovcit të vitit 1699.", "2b368884"]},
"OLAYLAR_KI117:1689-09-11:0":{"b": ["Badeni mbërriti në Jagodinë — korridori i Moravës hyri në vijën austriake", "a6459b85"], "d": ["Pas disfatës së Batoçinës (30 gusht), ushtria osmane u tërhoq në jug; Badeni mbërriti në Jagodinë më 11 shtator 1689 dhe ndërtoi urë mbi Moravë. Vija austriake nëpërmjet Jagodinë–Ćuprija–Paraćin u shtri deri në Nish; ndërsa Alacahisari (Krushevci) mbeti jashtë vijës.", "9badb3bd"]},
"OLAYLAR_KI117:1690-08-29:0":{"b": ["Dursun Mehmed Pasha hyri në Vidin — bregu i Danubit përsëri në duart osmane", "2b4d5344"], "d": ["Në kundërsulmin e Fazil Mustafa Pashës, ushtria tokësore e mytesarrifit të Karamanit, Dursun Mehmed Pashës, dhe flota danubiane e Mezzomorto Hysein Pashës ia rimorën Vidinin Austrisë.", "d76ac495"]},
"OLAYLAR_KI117:1690-09-01:0":{"b": ["Pashai i Rumelisë hyri në kështjellën e Orshovës", "3884232b"], "d": ["Me tërheqjen e ushtrisë austriake nga Serbia në fund të gushtit 1690, pashai i Rumelisë e rimori Orshovën; bregu danubian i Banatit u kthye nën kontrollin osman.", "541ca167"]},
"OLAYLAR_KI117:1690-09-17:0":{"b": ["Kështjellat e Vlorës dhe të Kaninës ranë në duart e Venedikut", "51bf7b50"], "d": ["Ndërsa vazhdonte kundërsulmi osman në Serbi, flota dhe forcat venedikase morën Vlorën dhe Kaninën në bregdetin shqiptar; në mars 1691 të dyja kështjellat do të prishen e do të braktisen.", "238bd38c"]},
"OLAYLAR_KI117:1691-03-15:0":{"b": ["Venediku prishi kështjellat që kishte marrë në Shqipëri dhe u tërhoq", "378490dd"], "d": ["Venedikasit, që morën Vlorën dhe Kaninën më 17 shtator 1690, në mes të marsit 1691 i prishën kështjellat dhe u tërhoqën; Shqipëria e Jugut u kthye nën kontrollin osman.", "aa90ce2d"]},
"OLAYLAR_KI117:1695-01-01:0":{"b": ["Kalimi i Kızıkermenit në duart ruse", "2b90f9af"], "d": ["Në operacionin e vijës së Dnjeprit, paralel me fushatën ruse të Azovit, Sheremetevi dhe Mazepa morën Kızıkermenin; kështjella mbeti në duart ruse deri në Traktatin e Stambollit të vitit 1700.", "c310dfdd"]},
"OLAYLAR_KI117:1695-01-12:0":{"b": ["Dorëzimi i Gjulës te Habsburgët", "e378c570"], "d": ["Gjula e rrethuar nënshkroi kapitullimin më 21 dhjetor 1694; më 12 janar 1695 garnizoni doli dhe hynë njësitë habsburge. Deri në Karlovc (1699) kështjella ishte në duart habsburge, jo osmane.", "5e4c275b"]},
"OLAYLAR_KI117:1699-09-22:0":{"b": ["Dorëzimi i Kamenecit te Polonia", "05950f7a"], "d": ["Si kërkesë e Traktatit të Karlovcit të 26 janarit 1699, zbrazja e Podolisë përfundoi në shtator; çelësat e Kamenecit iu dorëzuan komisionit polak më 22 shtator 1699. Kalimi te Polonia, bashkë me kështjellat e varura të sanxhakut (Bari, Meçibozhi, Jazlofça), faktikisht u krye në këtë ditë.", "15c85c1d"]},
"OLAYLAR_KURULUS_GERI_1021:0630-01-11:0":{"b": ["U pushtua Meka: qyteti i kaloi Shtetit të Medinës", "8435e73c"], "d": ["Profeti pushtoi Mekën (20 ramazan 8 / 11 janar 630).", "865a73bd"]},
"OLAYLAR_KURULUS_GERI_1021:0632-06-08:0":{"b": ["Vdekja e Profetit: Meka u lidh me kalifët rashidinë", "b65e8cd1"], "d": ["Hz. Muhamedi vdiq më 13 rebiulevel 11 / 8 qershor 632; Meka hyri nën administratën e kalifëve rashidinë.", "99716bea"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["U themelua Kufa", "617d0f35"], "d": ["Kufa u ngrit si qytet garnizon zakonisht në vitin 17 (638); u bë qendra e Kalifatit Rashidin në Irak (dita nuk dihet).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["Hasan b. Aliu ia la kalifatin Muavijes; Muavija mori bejatin në Kufë, Kufa kaloi nën sundimin umajad", "cc9c9de4"], "d": ["Hasan b. Aliu, që u bë kalif pas rënies dëshmor të Hz. Aliut në Xhaminë e Kufës nga Ibn Mulxhemi (janar 661), ia la kalifatin Muavijes; Muavija erdhi në Kufë dhe mori bejatin nga populli (25 rebiulevel 41 / 29 korrik 661). Mbaroi periudha rashidine, qyteti hyri nën administratën umajade (periudha ndërmjetëse zubejride 680-691 nuk u shkrua veçmas në regjistrim).", "6cadb24f"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:1":{"b": ["Muavija mori bejatin: Meka hyri nën sundimin umajad", "d6dcc232"], "d": ["Muavija mori bejatin më 25 rebiulevel 41 / 29 korrik 661; Meka u lidh me guvernatorët umajadë (nuk ka ditë specifike për Mekën, dita e shtetit).", "16cecb18"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["U themelua Kajruani (Ukbe b. Nafi', umajad)", "7409e9ae"], "d": ["Guvernatori umajad Ukbe b. Nafi' themeloi Kajruanin në 670 si bazë të Ifrikijes.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0683-11-27:0":{"b": ["Ibnuz-Zubejri shpalli kalifatin e vet në Mekë: Meka doli nga Umajadët", "9e31ca5c"], "d": ["Lajmi për vdekjen e Jezidit arriti në Mekë (27 nëntor 683); Abdullah b. Zubejri shpalli kalifatin me qendër në Mekë (64/683).", "212a96b5"]},
"OLAYLAR_KURULUS_GERI_1021:0692-10-01:0":{"b": ["Haxhxhaxhi mori Mekën: qyteti hyri sërish nën sundimin umajad", "48dd6e68"], "d": ["Në fund të rrethimit të Haxhxhaxh b. Jusufit, Meka hyri sërish nën sundimin umajad më 14 xhumadelula 73 / 1 tetor 692.", "25eedec5"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["Abdurrahman b. Habibi u ngrit: Kajruani doli nga administrata umajade", "4c7a0da0"], "d": ["Në 745, me kryengritjen e Abdurrahman b. Habibit, Kajruani doli nga guvernatorati umajad; deri në 761 periudhë ndërmjetëse habibide/haridxhite (zotërues: boshllëk i deklaruar).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["Ushtria abaside pushtoi Kufën", "0191709e"], "d": ["Ushtria abaside mori Kufën më 14 muharrem 132 (2 shtator 749); qyteti kaloi nga Umajadët te Abasidët.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0750-08-05:0":{"b": ["Mori fund shteti umajad: Meka kaloi nën sundimin abasid", "382e4d6e"], "d": ["Kalifi i fundit umajad Mervani II u vra më 26 dhulhixhe 132 / 5 gusht 750; Meka hyri nën guvernatoratin abasid të Haramejnit (nuk ka ditë specifike për Mekën — dita e fundit të shtetit, përafrim i deklaruar).", "710c6ec7"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["Muhamed b. Esh'asi, i emëruar nga Abasidët, mori Kajruanin", "71af9f79"], "d": ["Muhamed b. Esh'asi pushtoi Kajruanin në emër të Abasidëve në vitin 144 (761).", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["Kalifi Mansur nisi ndërtimin e Bagdadit (Medinetus-Selam)", "844a94d5"], "d": ["Punimet e ndërtimit të qytetit të themeluar në bregun e Tigrit filluan në 762; u bë kryeqyteti i përhershëm i Abasidëve (dita nuk dihet, i konfirmuar vetëm viti).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0800-01-01:0":{"b": ["Ibrahim b. Aglebi u bë guvernator: Aglebidët në Kajruan", "f7279ba9"], "d": ["Harun Rashidi e emëroi Ibrahim b. Aglebin guvernator të Ifrikijes; Aglebidët (800-909) e bënë Kajruanin kryeqytet.", "3b6e9426"]},
"OLAYLAR_KURULUS_GERI_1021:0909-01-01:0":{"b": ["Fatimidët morën Kajruanin; Aglebidët morën fund", "021693e0"], "d": ["Në 909 Zijadetullahu III iku në Egjipt; Kajruani u kaloi Fatimidëve.", "a6422efd"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["Buvejhidi Ahmed (Muizzuddevle) hyri në Bagdad; qyteti kaloi nën sundimin buvejhid", "31accd4a"], "d": ["Ahmedi hyri në Bagdad më 11 xhumadelula 334 (19 dhjetor 945); kalifi Mustekfi e bëri emirul-umera, qyteti kaloi nën sundimin e Buvejhidëve (edhe Kufa hyri nën sundimin buvejhid 945-1055; dita për Kufën u mor nga fqinji, Bagdadi).", "11f31be7"]},
"OLAYLAR_KURULUS_GERI_1021:0969-01-01:0":{"b": ["Në Mekë u lexua hutbja në emër të Fatimidëve (358/969)", "3f069fea"], "d": ["Emiri i Mekës Xha'fer b. Muhamed e lexoi hutbën në emër të Fatimidëve (358/969, saktësi viti); si shtet sovran Fatimidët.", "2256892c"]},
"OLAYLAR_KURULUS_GERI_1021:0972-10-02:0":{"b": ["Ziridët në Kajruan (Bulukkin b. Ziri guvernator i Ifrikijes)", "5494e662"], "d": ["Në emër të kalifit fatimid, Bulukkin b. Ziri qeverisi Ifrikijen; Ziridët (972-1057) zotër të Kajruanit (TDV jep vitin, dita nga f e regjistrit).", "ffcba4c5"]},
"OLAYLAR_KURULUS_GERI_1021:1057-01-01:0":{"b": ["Plaçkitja hilalide: Muizz b. Badisi u tërhoq në Mahdije, sundimi zirid mori fund në Kajruan", "4dbbdff5"], "d": ["Rreth vitit 449 (1057) Hilalidët plaçkitën Kajruanin; Ziridët u tërhoqën në Mahdije; deri në 1229 zotëruesi i qytetit nuk mund të ndiqet vit për vit në burime (boshllëk i deklaruar).", "8bebfdc7"]},
"OLAYLAR_KURULUS_GERI_1021:1085-05-25:0":{"b": ["Alfonsi VI hyri në Toledo: qyteti kaloi nën sundimin kastilian", "3b72bb5f"], "d": ["Treccani: më 25 maj 1085 Alfonsi VI hyri në Toledo; dy vjet më vonë qyteti u bë kryeqyteti i Kastiljes (TDV tuleytula jep vetëm vitin: 478/1085; në kronologjinë bisht regjistrohet veçmas dita e dorëzimit, 8 maj 1085).", "fa2c9677"]},
"OLAYLAR_LAB19_2S_P5:1918-02-16:0":{"b": ["Këshilli i Lituanisë (Taryba) nënshkroi në Vilnius aktin e pavarësisë", "230ccf8d"], "d": ["Në Lituaninë nën pushtimin gjerman që nga viti 1915, Këshilli i Lituanisë, që vepronte nën kontrollin ushtarak gjerman, nënshkroi në Vilnius aktin e pavarësisë. Gjermania e kishte nxitur këtë hap gjatë bisedimeve të Brest-Litovskut; sovraniteti i vërtetë nuk erdhi para tërheqjes gjermane në nëntor 1918. Vendbanimet që iu bashkuan shtetit të ri në të njëjtën datë: Kaunas, Šiauliai.", "529d9290"]},
"OLAYLAR_LAB19_2S_P5:1918-10-07:0":{"b": ["Zbarkimi i forcave franceze në Bejrut — fillimi i administratës franceze në bregdetin libanez", "7fb62c6f"], "d": ["Me tërheqjen e forcave osmane nga Siria, mbështetur në modus vivendi anglo-francez të 30 shtatorit 1918, njësitë franceze detare e tokësore pushtuan Bejrutin më 7 tetor 1918. Rripi bregdetar — Bejruti, Sidoni, Tiri dhe, brenda muajit tetor, Tripoli i Shamit — së bashku me Malin e Libanit (Deir el-Kamar) iu lanë administratës ushtarake franceze me emrin Zona Perëndimore e Territorit Armik të Pushtuar (OETA West), e krijuar më 23 tetor. Vendbanime të tjera që u humbën në të njëjtën datë: Tiri, Deir el-Kamar.", "706a7f2c"]},
"OLAYLAR_LAB19_2S_P6:1037-01-01:0":{"b": ["Hamama e dëboi Temimin nga Fesi: Emirati Magravid u kthye në Fes", "1d208deb"], "d": ["Pasi Benu Ifren në vitin 1033 ia morën Fesin emirit magravid Hamama, ky u tërhoq në Vexhde dhe Tenes; katër vjet më vonë Hamama e dëboi nga Fesi emirin e Benu Ifrenit, Temimin; Fesi mbeti nën Emiratin Magravid deri në pushtimin nga murabitët në vitin 1070.", "0c4f2f3a"]},
"OLAYLAR_LAB19_2S_P6:1169-01-01:0":{"b": ["Kajseri dhe Zamantëja iu morën danishmendëve dhe iu bashkuan tokave selxhuke", "ef7556eb"], "d": ["Këllëç Arslani II ia mori Kajserin dhe Zamantën danishmendit Zunnun dhe i bashkoi me tokat selxhuke të Anadollit.", "29bdf0d1"]},
"OLAYLAR_LAB19_2S_P6:1175-01-01:0":{"b": ["Sivasi, Tokati dhe Niksari iu morën danishmendëve dhe iu bashkuan tokave selxhuke", "e4e4c038"], "d": ["Këllëç Arslani II në verën e vitit 1175 pushtoi vendin danishmend, përfshirë Sivasin, Niksarin, Komanën dhe Tokatin; dega e Sivasit e danishmendëve u zhduk.", "feecde45"]},
"OLAYLAR_LAB19_2S_P6:1178-10-25:0":{"b": ["Këllëç Arslani II mori Malatjen: dega e Malatjes e danishmendëve mori fund", "b1662c9e"], "d": ["Pas një rrethimi katërmujor, Këllëç Arslani II më 11 xhumadelula 574 (25 tetor 1178) pushtoi Malatjen dhe i dha fund kësaj dege të dinastisë danishmende.", "9b20f183"]},
"OLAYLAR_LAB19_2S_P6:1244-07-11:0":{"b": ["Horezmët hynë në Jerusalem: Jerusalemi doli nga duart e kryqtarëve", "97cdc2e1"], "d": ["Njësitë horezme, që plaçkitnin dhe digjnin rrethinat e Damaskut, hynë në Jerusalem më 11 korrik 1244; qyteti doli nga duart e kryqtarëve. Në tetor të po atij viti, në betejën pranë Gazës, ajubidët e Egjiptit të mbështetur nga horezmët i shpartalluan ajubidët e Sirisë dhe aleatët e tyre kryqtarë, dhe Jerusalemi kaloi përfundimisht nën sundimin e ajubidëve të Egjiptit.", "d90527b2"]},
"OLAYLAR_LAB19_2S_P6:1643-01-01:0":{"b": ["Jarubidët ua rimorën Suharin portugezëve", "8e9b38d1"], "d": ["Prijësi i dinastisë jarubide të Omanit, Nasir b. Murshid, në vitin 1643 ua rimori Suharin portugezëve.", "17402e41"]},
"OLAYLAR_LAB19_2S_P6:1650-01-01:0":{"b": ["Jarubidët ua rimorën Maskatin portugezëve", "afeaa6dd"], "d": ["Prijësi i dinastisë jarubide të Omanit, Nasir b. Murshid, në vitin 1650 ua rimori Maskatin portugezëve; ky port i Omanit, që Portugalia e mbante që nga viti 1507, kaloi te jarubidët.", "a68e0b2b"]},
"OLAYLAR_LAB19_2S_P6:1829-05-14:0":{"b": ["Mesollongji dhe Anatolikoja u zbrazën nga garnizonet osmane", "60ac1fdf"], "d": ["Pas dorëzimit të Lepantos më 30 prill 1829, garnizonet e Mesollongjit dhe të Anatolikos i zbrazën qytetet më 14 maj 1829 dhe ua lanë forcave greke.", "49fa6f9b"]},
"OLAYLAR_LAB19_2S_P6:1841-05-30:0":{"b": ["Ushtria franceze hyri në Maskarë: ra qendra e Abd el-Kadirit në brendësi të Algjerisë", "f7bbe843"], "d": ["Në fushatën e vitit 1841, ushtria franceze nën komandën e Mareshalit Bugeaud, pas Takdemtit, më 30 maj hyri në Maskarë; Abd el-Kadiri nuk u përpoq seriozisht ta mbronte qytetin.", "68dd3e47"]},
"OLAYLAR_LAB19_2S_P6:1844-05-08:0":{"b": ["Njësitë franceze hynë në Dellys dhe lanë garnizon", "2a98a144"], "d": ["Njësitë franceze nën komandën e Mareshalit Bugeaud hynë në Dellys më 8 maj 1844; lanë në qytet një garnizon prej dyqind e pesëdhjetë vetash dhe më 11 maj vazhduan rrugën për në Bordj-Mnaïel.", "b469cbc0"]},
"OLAYLAR_LAB19_2S_P6:1916-06-16:0":{"b": ["Xheda ra në duart e forcave kryengritëse të Sherif Hyseinit", "36c7eb82"], "d": ["Në kryengritjen që Sherif Hyseini nisi në qershor 1916 në Mekë, Xheda ra në duart e kryengritësve më 16 qershor.", "3f61e26f"]},
"OLAYLAR_LAB19_2S_P6:1916-09-17:0":{"b": ["Taifi ra në duart e Sherif Hyseinit", "4b420ead"], "d": ["Forcat e Sherif Hyseinit, që u ngrit kundër administratës osmane gjatë Luftës I Botërore, më 17 shtator 1916 pushtuan Taifin; qyteti mbeti nën administratën hashemite deri në tërheqjen e osmanëve nga Hixhazi më 30 tetor 1918.", "a0ba88b4"]},
"OLAYLAR_LAB19_2S_P6:1918-10-25:0":{"b": ["Forcat osmane e lanë Kirkukun në mbrëmje, hyri kolona britanike e Lewinit", "4e8e0d56"], "d": ["Më 25 tetor 1918 forca osmane në Kirkuk e mbajti pozicionin deri në mbrëmje, pastaj filloi të tërhiqej në drejtim të Altun Köprüsë; kolona britanike e gjeneralit Lewin pas errësirës pushtoi Kirkukun dhe një vijë në veri të tij.", "28bed7ca"]},
"OLAYLAR_LAB19_2S_P6:1918-10-31:0":{"b": ["Kolona britanike e Lewinit pushtoi Altun Köprünë pa qëndresë", "4e54f6b8"], "d": ["Në mëngjesin e 31 tetorit 1918 kolona britanike e gjeneralit Lewin pushtoi Altun Köprünë pa hasur qëndresë; forca osmane po tërhiqej në drejtim të Mosulit.", "1e23aefa"]},
"OLAYLAR_LAB19_2S_P6:1919-02-01:0":{"b": ["Pas tërheqjes osmane nga Asiri, sundimin e Aizit e zëvendësoi Muhamed b. Ali el-Idrisi", "f3f129c8"], "d": ["Kur forcat osmane u tërhoqën nga Asiri midis tetorit 1918 dhe shkurtit 1919, në rajon lindi një boshllëk pushteti; fillimisht familja e vjetër Aiz mori sundimin, por menjëherë pas saj rajonin e vuri nën sundim Muhamed b. Ali el-Idrisi.", "e4292793"]},
"OLAYLAR_LAB19_2S_P6:1920-02-02:0":{"b": ["Traktati i Tartusë: Rusia Sovjetike njohu pavarësinë e Estonisë, Petseri mbeti në Estoni", "65ad6147"], "d": ["Me traktatin që i dha fund Luftës së Çlirimit të Estonisë, Rusia Sovjetike njohu pavarësinë e Estonisë. Kufiri i caktuar kaloi pak në lindje të kufirit të sotëm dhe e la Petserin (Pechory), në juglindje, brenda Estonisë.", "96a8a8b0"]},
"OLAYLAR_LAB19_2S_P6:1922-01-01:0":{"b": ["Saudët shpallën sundimin në Ebha të Asirit: sundimi i Idrisit mori fund", "16f33b66"], "d": ["Emiri saudit Abdulaziz dërgoi djalin e tij Fejsalin në rajonin e Asirit dhe shpalli sundimin mbi Ebhan; kështu mori fund sundimi i Muhamed b. Ali el-Idrisit në Asir.", "a28adf26"]},
"OLAYLAR_LAB19_2S_P6:1936-07-18:0":{"b": ["Kryengritje në Sevilje, Valladolid dhe Burgos: qytetet kaluan në duart e Nacionalistëve", "04ee444e"], "d": ["Kryengritja ushtarake që nisi Luftën Civile Spanjolle shpërtheu më 18 korrik 1936 në Ishujt Kanarie, në Sevilje, në Valladolid dhe në Burgos. Gran Enciclopèdia Catalana e përmend Seviljen si 'bazën e kryengritjes në Andaluzi'. Me kryengritjen këto qytete kaluan nën administratën Nacionaliste (kundër Republikës Spanjolle).", "0edcbde9"]},
"OLAYLAR_LAB19_2S_P6:1936-07-19:0":{"b": ["Kryengritje në Saragosë, Pamplonë, Oviedo, Salamankë dhe Palmë: qytetet kaluan në duart e Nacionalistëve", "1610d143"], "d": ["Kryengritja ushtarake shpërtheu më 19 korrik 1936 në Saragosë, në Pamplonë, në Vitoria, në Oviedo, në Salamankë dhe në Palmë (Majorkë). Gran Enciclopèdia Catalana i rendit këto qytete ndër kryengritjet e 19 korrikut. Majorka (Palma) që nga kjo datë kalon nën administratën Nacionaliste.", "287e0df5"]},
"OLAYLAR_LAB19_2S_P6:1938-10-10:0":{"b": ["Vendimi i arbitrazhit për Chaco-n: pjesa më e madhe e Chaco Boreal iu dha Paraguait", "ecf3de14"], "d": ["Bordi i Arbitrazhit, i përbërë nga përfaqësuesit e Argjentinës, Brazilit, Kilit, SHBA-së, Perusë dhe Uruguait, më 10 tetor 1938 shpalli vendimin që caktonte kufirin Bolivi-Paraguai sipas Traktatit të Paqes të 21 korrikut 1938. Pjesa më e madhe e Chaco Boreal-it të diskutuar i mbeti Paraguait; Bolivia fitoi një dalje të ngushtë në lumin Paraguai.", "5b2f0579"]},
"OLAYLAR_LAB19_2S_P6:1939-03-30:0":{"b": ["Njësitë Nacionaliste hynë në Valencia", "6faa6441"], "d": ["Njësitë Nacionaliste hynë në Madrid më 28 mars 1939 dhe në Valencia më 30 mars. Kështu ra edhe qyteti i fundit i madh i frontit Republikan; lufta mori fund zyrtarisht dy ditë më vonë, më 1 prill 1939.", "ae0c6ab4"]},
"OLAYLAR_LAB19_2S_P6:1941-08-29:0":{"b": ["Komanda gjermane ngriti Qeverinë e Shpëtimit Kombëtar të kryesuar nga Nedić", "b0c34dad"], "d": ["Në Serbinë nën pushtimin gjerman, më 29 gusht 1941 u ngrit një Qeveri e Shpëtimit (Çlirimit) Kombëtar të kryesuar nga Milan Nedić. Qeveria ishte një administratë kolaboracioniste e varur nga komanda ushtarake gjermane; Beogradi që nga kjo datë konsiderohet kryeqyteti i Serbisë së Nedićit.", "f25ea523"]},
"OLAYLAR_LAB19_2S_P6:1944-10-06:0":{"b": ["Nedić u largua nga Beogradi; qeveria kolaboracioniste faktikisht mori fund", "a56652e3"], "d": ["Milan Nedić më 6 tetor 1944 u largua nga Beogradi dhe nga territori i Serbisë; Ivan Petković, i emëruar kryeministër, faktikisht nuk e mori kurrë detyrën. Qyteti mbeti nën kontrollin ushtarak gjerman derisa u çlirua nga Partizanët më 20 tetor 1944.", "bcd6274d"]},
"OLAYLAR_LAB19_2S_P6:1944-10-20:0":{"b": ["Beogradi u çlirua nga Ushtria Popullore Çlirimtare Jugosllave dhe Ushtria e Kuqe", "bf067abe"], "d": ["Njësitë e Ushtrisë Popullore Çlirimtare Jugosllave, me mbështetjen e Ushtrisë së Kuqe, më 20 tetor 1944 e çliruan Beogradin nga pushtimi gjerman. Qyteti kaloi nën administratën Partizane; Serbia e Nedićit ishte shpërbërë faktikisht dy javë më parë.", "5114a3cc"]},
"OLAYLAR_LAB19_2S_P6:1945-02-14:0":{"b": ["Mostari u mor nga Partizanët Jugosllavë: kontrolli i Shtetit të Pavarur të Kroacisë në Hercegovinë u shemb", "1e551550"], "d": ["Njësitë e Ushtrisë Popullore Çlirimtare Jugosllave morën Mostarin në shkurt 1945; me marrjen e Drežnicës më 16 shkurt u përfundua operacioni i Mostarit dhe pjesa më e madhe e Hercegovinës kaloi në duart e Partizanëve.", "8bd01f9f"]},
"OLAYLAR_LAB19_2S_P6:1945-05-09:0":{"b": ["Partizanët sllovenë çliruan Lubjanën", "fe8463ad"], "d": ["Njësitë e Divizionit 29 dhe të Korpusit VII të Ushtrisë Partizane Sllovene hynë në Lubjanë më 9 maj 1945 dhe e çliruan qytetin. Kështu mori fund administrata e Zonës Operative të Bregdetit Adriatik (OZAK) gjermane.", "b41462f0"]},
"OLAYLAR_LAB19_BOS_1119:1446-01-01:0":{"b": ["Dir'ija iu dha për herë të parë Mani' b. Rebiasë: fillimi i vendbanimit të Dir'ijes", "17298eb7"], "d": ["Sipas burimeve, themelimi i parë i Dir'ijes është në vitin 850 (1446-47): Haxher el-Jemame b. Dir' ia dha Asibën dhe Mulejibidin përreth të afërmit të tij Mani' b. Rebia.", "16e25bc0"]},
"OLAYLAR_LAB19_BOS_1119:1470-01-01:0":{"b": ["Bengazi u shfaq përsëri si qendër vendbanimi (vlerësim)", "a54842f9"], "d": ["Vlerësohet se rishfaqja si qendër vendbanimi e Bengazit, i braktisur në periudhën e vonë bizantine, përkon me vitet rreth 1470.", "e6454ed3"]},
"OLAYLAR_LAB19_BOS_1119:1551-01-01:0":{"b": ["Në fushatën e Tripolit të vitit 1551, rajoni i Barkës hyri nën sundimin osman", "e2d7e52c"], "d": ["Gjatë fushatës së Tripolit të vitit 1551, rajoni i Barkës hyri nën sundimin osman.", "a4de9dc5"]},
"OLAYLAR_LAB19_BOS_1119:1578-01-01:0":{"b": ["Bengazi iu bashkua përfundimisht administratës osmane", "d50b0ffb"], "d": ["Pasi Barka hyri nën sundimin osman në vitin 1551, Bengazi në vitin 1578 iu bashkua përfundimisht administratës osmane; më pas, si sanxhak i ejaletit të Tripolit, në shekullin XVII mbeti nën administratën e dejve dhe në shekullin XVIII të familjes Karamanli.", "e56ee4c8"]},
"OLAYLAR_LAB19_BOS_1119:1688-01-01:0":{"b": ["Rijadi nën sundimin e familjes Ebu Zer'a nga Benu Hanife", "021a6f1c"], "d": ["Rijadi që nga viti 1099 (1688) ishte nën sundimin e familjes Ebu Zer'a nga Benu Hanife; ndërsa emirati fqinj i Dir'ijes kaloi te saudët.", "ba2e75f1"]},
"OLAYLAR_LAB19_BOS_1119:1726-01-01:0":{"b": ["Muhamed b. Saud nisi të sundojë si emir i pavarur në Dir'ije", "e76002ec"], "d": ["Muhamed b. Saud, emiri nga pasardhësit e Mani' b. Rebiasë që i dha emrin dinastisë së sotme saude, në vitin 1726 filloi të sundojë i pavarur në Dir'ije dhe rrethina.", "2dadd98a"]},
"OLAYLAR_LAB19_BOS_1119:1744-01-01:0":{"b": ["Muhamed b. Abdulvehabi u dëbua nga Ujejne dhe erdhi në Dir'ije te Muhamed b. Saud: bazat e aleancës vehabite-saude", "8fba33c0"], "d": ["Në vitin 1744 Muhamed b. Abdulvehabi, nën mbrojtjen e kreut të temimëve në Ujejne, Osman b. Ahmed Al Muammer, u dëbua nga qyteti dhe erdhi në Dir'ije te Muhamed b. Saud; të dy formuan një forcë fetaro-politike.", "0af60871"]},
"OLAYLAR_LAB19_BOS_1119:1746-01-01:0":{"b": ["Nisi përplasja me tridhjetë e pesë ndeshje midis emirit të Rijadit, Deham b. Devvas, dhe forcave saude", "46db3863"], "d": ["Emiri i Rijadit, Deham b. Devvas, dhe forcat e lidhura me familjen Saud u ndeshën tridhjetë e pesë herë midis viteve 1746-1773; në fund të përplasjes Rijadi ra në duart e saudëve.", "12494f64"]},
"OLAYLAR_LAB19_BOS_1119:1765-09-16:0":{"b": ["Muhamed b. Saud vdiq në Dir'ije dhe u varros atje", "8ebaece4"], "d": ["Themeluesi i dinastisë saude, Muhamed b. Saud, vdiq në Dir'ije më 30 rebiulevel 1179 (16 shtator 1765) dhe u varros atje.", "1d6dea75"]},
"OLAYLAR_LAB19_BOS_1119_D:1665-01-01:0":{"b": ["Atamani kozak Çernigovski ndërtoi kështjellën Albazin", "a7dab4cf"], "d": ["Kështjella Albazin u ndërtua në vitin 1665 nga atamani kozak N. R. Çernigovski, në vendin e lagjeve dimërore të fortifikuara që çeta e Habarovit i kishte shkatërruar në vitin 1651; lagjet dimërore ishin ngritur në tokat e kasabasë Jaksa në trojet e beut daur Albazi.", "4699838b"]},
"OLAYLAR_LAB19_BOS_1119_D:1685-06-01:0":{"b": ["Kështjella Albazin u dogj e u shkatërrua në qershor 1685, pas rrethimit të parë mançu", "a6af183c"], "d": ["Kështjella Albazin, pas rrethimit të parë nga forcat mançu, u zhduk nga zjarri në qershor 1685; kështjella u rindërtua në të njëjtin vend në 1685-1686.", "109536af"]},
"OLAYLAR_LAB19_BOS_1119_D:1739-01-01:0":{"b": ["Njerëzit e Demidovit nisën ndërtimin e uzinës për shkrirjen e bakrit në grykën e Barnaulit", "4ed15cec"], "d": ["Njerëzit e Demidovit u shfaqën në vjeshtën e vitit 1739 në grykën e lumit Barnaul dhe nisën ndërtimin e uzinës për shkrirjen e bakrit; pranë uzinës lindi vendbanimi i saj.", "53596692"]},
"OLAYLAR_LAB19_BOS_1119_E:1718-01-01:0":{"b": ["U ngrit kështjella e Semipalatinskut (vija e Irtyshit)", "3ba4dbbc"], "d": ["Në vijën e fortifikimeve ruse të Irtyshit, në vitin 1718 u ngrit kështjella e Semipalatinskut; po atë vit pranë saj u ngrit edhe kështjella Dolonskaja.", "05ac7e1e"]},
"OLAYLAR_LAB19_BOS_1119_E:1720-01-01:0":{"b": ["Majori Liharev ngriti kështjellën Ust-Kamenogorsk në derdhjen e Ulbës në Irtysh", "3cbb514d"], "d": ["Majori Liharev në vitin 1720 ngriti kështjellën Ust-Kamenogorsk në vendin ku lumi Ulba derdhet në Irtysh; kështjella u bë pjesë e vijës së fortifikimeve të Irtyshit.", "739f9c8e"]},
"OLAYLAR_LAB19_BOS_1119_F:1680-08-10:0":{"b": ["Nisi Kryengritja e Pueblos: Taos, Picuris dhe fshatrat e tjera Pueblo shënjestruan spanjollët dhe priftërinjtë", "b22c32c9"], "d": ["Fshatrat Pueblo të Nju-Meksikos u ngritën së bashku më 10 gusht 1680: në Santa Clara u vranë ushtarë spanjollë, në Jemez, duke ndjekur shembullin e Taos-it dhe Picuris-it, u bë thirrje për vrasjen e priftërinjve dhe spanjollëve; kryengritja çoi në evakuimin e Santa Fe-së nga guvernatori Otermín.", "eb1a3ce7"]},
"OLAYLAR_LAB19_BOS_1119_F:1680-08-21:0":{"b": ["Guvernatori Otermín braktisi Santa Fe-në dhe u nis drejt Isleta-s", "61a1cd02"], "d": ["Pas rrethimit nëntëditor, guvernatori Antonio de Otermín më 21 gusht 1680 dha urdhrin për braktisjen e Santa Fe-së dhe po atë mëngjes nisi banorët spanjollë drejt Isleta-s; Santa Fe ra në duart e forcave kryengritëse Pueblo.", "a5c086d3"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1630-01-01:0":{"b": ["U themelua Kirenski ostrog: ostrog i kozakëve rusë për t'i nënshtruar tunguzët ndaj jasakut", "03d599c0"], "d": ["Kozakët rusë në vitin 1630 ngritën Kirenski ostrog në bregun e Lenës (po atë vit me Ilimskin, ndërsa Bratski në 1631); ostrogu u ngrit për nënshtrimin e tunguzëve.", "94e94865"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1709-06-29:0":{"b": ["Në bashkimin e Bisë me Katunin u ndërtua ostrogu i parë Bikatun (Biysku i mëvonshëm)", "2fbcd72e"], "d": ["Kozakët rusë në vitin 1709 ngritën në bashkimin e lumenjve Bi dhe Katun ostrogun e parë Bikatun (paraardhësin e kështjellës së mëvonshme të Biyskut); ostrogu nisi në kufirin jugperëndimor të ujezdit Kuznetsk një fazë të re të kolonizimit rus drejt Altait.", "fed7b8d1"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1710-01-01:0":{"b": ["Një çetë xhungare nën komandën e zaisanit Duhar dogji ostrogun e parë Bikatun", "8c2510ca"], "d": ["Ostrogu i parë Bikatun, një vit pas themelimit (1710), u dogj nga një çetë xhungare nën komandën e zaisanit Duhar.", "7a8fc48f"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1803-01-01:0":{"b": ["Gubernia e Irkutskut u nda: u formua ujezdi Kirenski", "40f81910"], "d": ["Në vitin 1803 gubernia e Irkutskut u nda në ujezdet e Irkutskut, Nizhneudinskut, Verhneudinskut, Kirenskit, Nerçinskut dhe Jakutskut; ndarja e Kirenskit vazhdoi më vonë si okrug deri në fund të shekullit XIX.", "e10043ad"]},
"OLAYLAR_LAB19_DUZELTME_1120:1814-05-01:0":{"b": ["Garnizoni francez i Nieuwpoort-it u tërhoq në fillim të majit 1814: mori fund administrata franceze në Flandrën Perëndimore", "3b3be3fa"], "d": ["Pas armëpushimit të 12 prillit 1814, Ostende, Diksmuide, Nieuwpoort dhe Yper kishin mbetur në duart franceze; pjesa tjetër e departamentit Lys (Flandra Perëndimore) u zbraz nga francezët në fillim të majit, para Paqes së Parë të Parisit (30 maj 1814). Rajoni mbeti i varur nga Guvernatorati i Përgjithshëm i Belgjikës deri më 1 gusht 1814.", "3484e0d8"]},
"OLAYLAR_LAB19_DUZELTME_1120:1821-03-05:0":{"b": ["Meliku i provincës së Berberit iu dorëzua Ismail Pashës", "d1e6e36b"], "d": ["Ushtria e Ismail Pashës, djalit të Mehmet Ali Pashës, hyri në provincën e Berberit më 3 mars 1821; më 5 mars meliku Nasiruddin, që qëndronte në qendrën e provincës, shehlerët dhe paria dolën ta presin Ismail Pashën dhe iu nënshtruan.", "380181bd"]},
"OLAYLAR_LAB19_DUZELTME_1120:1918-09-23:0":{"b": ["Maani u zbraz nga garnizoni osman, Ushtria Arabe e pushtoi qytetin", "40f0e4b1"], "d": ["Sipas raportit të Allenby-t, njësitë e Korpusit II të Ushtrisë osmane që tërhiqeshin nga Hixhazi e zbrazën Maanin më 23 shtator 1918 dhe qytetin e pushtoi Ushtria Arabe; Ushtria Arabe e ndoqi praparojën e garnizonit që tërhiqej deri në Jerdun.", "752cf8c4"]},
"OLAYLAR_LAB19_MOCHE_1120:0850-01-01:0":{"b": ["Fundi i kulturës Moche (rreth viti 850 e.s.): u shpërbë shteti Moche me qendër në Huacas de Moche", "e8cad6b1"], "d": ["Arkeologët e bregdetit verior përgjithësisht e vendosin fundin e kulturës Moche rreth vitit 850 e.s.; datimet e reja me radiokarbon tregojnë se banimi në Huacas de Moche zgjati deri në shekullin IX e më pas, me gjetjet tekstile në Huaca del Sol deri në shekullin X, por se kultura gjatë këtij procesi ndryshoi në masë të konsiderueshme.", "a4aab3f8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Marrja e Damietës nga francezët — boshatisja e kështjellës Lesbe", "06b1e7b0"], "d": ["Nga ushtria e vezirit të madh, një forcë nën komandën e Ibrahim Pashës u dërgua në Damietë. Në mëngjesin e 14 majit, ndërsa po përgatitej sulmi mbi kështjellën Lesbe që mbronte Damietën, u pa se francezët e kishin boshatisur kështjellën dhe garnizoni ishte tërhequr; u morën edhe dy kështjellat e vogla të varura prej saj. Damieta u bë qyteti i dytë në grykën e Nilit që doli nga kontrolli francez pas Rashidit që ra në prill.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Marrja në dorëzim e Kajros nga francezët — kapitullimi i Belliard-it", "7a11bb5e"], "d": ["Gjatë operacionit të përbashkët të forcave osmane dhe angleze drejt Egjiptit, komandanti i forcave franceze në Kajro, gjenerali Belliard, nënshkroi kapitullimin. Bashkë me Kajron, edhe Suezi, që francezët e kishin pushtuar në nëntor 1798, doli nga kontrolli francez. Mbyllja e pushtimit do të përfundonte dy muaj më vonë në Aleksandri, kurse evakuimi nga vendi do të zgjaste deri në tetor.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Marrja në dorëzim e Aleksandrisë nga francezët — kapitullimi i Menou-së", "cd50663c"], "d": ["Komandanti i përgjithshëm i Ushtrisë së Lindjes, gjenerali Menou, u rrethua në Aleksandri më 17 gusht; më 21 gusht anglezët morën kështjellën Marabout pranë qytetit dhe më 31 gusht Menou nënshkroi kapitullimin e ushtrisë. Kthimi i trupave franceze në Francë filloi më 2 shtator. Kështu pushtimi, që nisi me zbarkimin në Aleksandri në qershor 1798, mori fund në qytetin ku kishte filluar.", "22e807c1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:0763-01-01:0":{"b": ["Duka i Napolit Stefani II u kthye nga Konstandinopoja drejt Romës: dukati faktikisht u pavarësua", "5a181f23"], "d": ["Dukati i Napolit i lidhur me Bizantin, në kohën e Stefanit II, në vitin 763 duke u kthyer nga Papa faktikisht u bë autonom (duka i parë Basil ishte emëruar në 661).", "4202f3af"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:0":{"b": ["Kozenca kaloi nga Bizanti te normanët: Dukati i Pulias dhe Kalabrisë", "80b85c65"], "d": ["Dukati i Robert Guiscard-it (1059) përfshiu Kalabrinë; Kozenca kaloi nga Bizanti te dukati norman (dita e pushtimit e veçantë për qytetin nuk u lexua, në nivel viti).", "97fda44a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:1":{"b": ["Reggio Calabria kaloi nga Bizanti te normanët: Dukati i Pulias dhe Kalabrisë", "221f6474"], "d": ["Dukati i Robert Guiscard-it (1059) përfshiu Kalabrinë; Reggio kaloi nga Bizanti te dukati norman (dita e pushtimit e veçantë për qytetin nuk u lexua, në nivel viti).", "31927a9e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:0":{"b": ["Brindizi kaloi nga Bizanti te normanët: Dukati i Pulias", "52c14154"], "d": ["Me pushtimin norman të Barit në 1071, ra kështjella e fundit e Bizantit në Itali; Brindizi, i lidhur me zinxhirin e Barit, iu bashkua dukatit të Pulias (nuk u gjet fjali e datuar e veçantë për qytetin).", "db68d985"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:1":{"b": ["Lecce kaloi nga Bizanti te normanët: Dukati i Pulias", "73da4722"], "d": ["Me pushtimin norman të Barit në 1071, ra kështjella e fundit e Bizantit në Itali; Lecce, e lidhur me zinxhirin e Barit, iu bashkua dukatit të Pulias (nuk u gjet fjali e datuar e veçantë për qytetin).", "e11ac323"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1099-01-01:0":{"b": ["Në Gjenovë u themelua Compagna Communis: qyteti kaloi nën administratën komunale", "1cc30776"], "d": ["Paria e Gjenovës, duke themeluar Compagna Communis, e organizoi administrimin e qytetit si komunë; fillimi i Republikës së Gjenovës.", "952b5184"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:0":{"b": ["Taranti kaloi nga Dukati i Pulias te Mbretëria e Sicilisë (Ruggero II)", "3ecf982e"], "d": ["Ruggero II në vitin 1128 mori dukatin e Pulias dhe principatën e Tarantit/Otrantos/Brindizit të Bohemondit II (maj-qershor 1128, burim dytësor); e njëjta ditë me zinxhirët e Barit dhe Salernos.", "b52e2957"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:1":{"b": ["Brindizi kaloi nga Dukati i Pulias te Mbretëria e Sicilisë (Ruggero II)", "6519178f"], "d": ["Ruggero II në vitin 1128 mori Brindizin nga principata e Tarantit të Bohemondit II (burim dytësor); e njëjta ditë me zinxhirët e Barit dhe Salernos.", "7adade28"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:2":{"b": ["Lecce kaloi nga Dukati i Pulias te Mbretëria e Sicilisë (Ruggero II; qendra e madhe referuese: Bari)", "22cdacd2"], "d": ["Lecce ndërroi zot, e lidhur me zinxhirin e Barit, me bashkimin e dukatit të Pulias me Mbretërinë e Sicilisë (1128); nuk u gjet fjali e datuar e veçantë për qytetin.", "9c938986"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:3":{"b": ["Kozenca kaloi nga Dukati i Pulias dhe Kalabrisë te Mbretëria e Sicilisë (Ruggero II)", "75da9e9c"], "d": ["Kalabria, me kalimin e dukatit të Pulias dhe Kalabrisë te Roger II (1128), u bë pjesë e Mbretërisë së Sicilisë; nuk u gjet fjali e datuar e veçantë për qytetin (qendra e madhe referuese: zinxhiri Bari/Melfi).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:4":{"b": ["Reggio Calabria kaloi nga Dukati i Pulias dhe Kalabrisë te Mbretëria e Sicilisë (Ruggero II)", "37e6922f"], "d": ["Kalabria, me kalimin e dukatit të Pulias dhe Kalabrisë te Roger II (1128), u bë pjesë e Mbretërisë së Sicilisë; nuk u gjet fjali e datuar e veçantë për qytetin (qendra e madhe referuese: zinxhiri Bari/Melfi).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1143-01-01:0":{"b": ["U themelua Komuna e Romës: senati u përtëri (renovatio senatus), pushteti tokësor i Papës u pezullua", "b54d2c34"], "d": ["Populli i Romës në Kapitol rithemeloi komunën dhe senatin; me ndikimin e Arnaldos nga Breshia, deri në vitin 1155 pushteti papnor faktikisht nuk u njoh (titullatura f 1143, Treccani 1144).", "baeccd38"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1283-01-01:0":{"b": ["Reggio Calabria kaloi nga Anzhuja te Aragon-Siçilia (Pedro III zbarkoi në Kalabri)", "800b47b1"], "d": ["Pas Vesprave Siçiliane (1282), Reggio mbeti në duart e Anzhusë; në fillim të vitit 1283 mbreti i Aragonit Pedro III zbarkoi në Kalabri dhe Reggio u bë baza aragoneze e luftës kundër anzhuinëve (në korrik 1284 Carlo d'Angiò e rrethoi qytetin, por s'e mori dot). Dita mungon te burimi, në nivel viti.", "6b2afca7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1302-08-31:0":{"b": ["Paqja e Caltabellottës: Reggio Calabria u kthye nga Aragon-Siçilia te Anzhuja (Napoli)", "241c90a7"], "d": ["Paqja e Caltabellottës (31 gusht 1302) bëri që Federico III të hiqte dorë nga pronat kontinentale në Kalabri dhe ishulli të mbetej te dega aragoneze si Mbretëria e Trinakrisë; Reggio kaloi te Mbretëria anzhuine e Napolit.", "c2a155cb"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1318-07-25:0":{"b": ["Jacopo I da Carrara u zgjodh mbrojtës dhe guvernator i Padovës: Komuna e Padovës kaloi te një zot i vetëm", "b3fc0eae"], "d": ["Aristokracia e Padovës e zgjodhi Jacopo I da Carrarën mbrojtës/guvernator për jetë (pak pas 25 korrikut 1318); komuna kaloi te një zot i vetëm. Dita nuk është e saktë, u mor dita e parë e intervalit.", "aa9a4a3f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1351-05-01:0":{"b": ["Cyrihu iu bashkua Konfederatës me aleancë të përjetshme: u bë anëtari i pestë pas Lucernit, Urit, Schwyz-it dhe Unterwalden-it", "78e9419b"], "d": ["Cyrihu më 1 maj 1351, duke lidhur aleancë të përjetshme me Lucernin, Urin, Schwyz-in dhe Unterwalden-in, u bë anëtar i Konfederatës së Vjetër Zvicerane.", "4646e7ae"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1399-01-01:0":{"b": ["Piza iu shit Gian Galeazzo Viskontit (Gherardo d'Appiano)", "eba05ce2"], "d": ["Sinjoria e Pizës e familjes Appiano u shit nëpërmjet Gherardos te duka i Milanos Gian Galeazzo Viskonti; Piza në vitet 1399-1402 mbeti e lidhur me Dukatin e Milanos. Dita mungon te burimi (në nivel viti 1399).", "705f44b2"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1402-09-03:0":{"b": ["Gian Galeazzo Viskonti vdiq: Piza u shkëput nga Milano dhe mbeti e pavarur nën Gabriele Maria Viskontin", "9e80b0ad"], "d": ["Me vdekjen e Gian Galeazzos (shtator 1402), Piza me testament kaloi te djali i tij jashtëmartesor Gabriele Maria Viskonti; Treccani EI dhe SNS e tregojnë këtë si pavarësinë jetëshkurtër të Pizës. Gabriele Maria më 27 gusht 1405 ia shiti të drejtat Firences, qyteti u pushtua në tetor 1406.", "e34aec85"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1506-11-11:0":{"b": ["Papa Juli II hyri në Bolonjë: u hoq zotërimi i Bentivoglio-s, Papati nisi administratën e drejtpërdrejtë", "dc4823a7"], "d": ["Papa Juli II hyri me ushtrinë e tij në Bolonjë dhe e dëboi Giovanni II Bentivoglio-n; qyteti iu lidh Shtetit Papnor.", "9afc6459"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1532-01-01:0":{"b": ["Mori fund liria komunale e Ankonës: me Klementin VII hyri nën sovranitetin e drejtpërdrejtë të Papatit", "d2fbbb8f"], "d": ["Liria komunale e Republikës së Ankonës mori fund në vitin 1532, kur në kohën e Klementit VII hyri nën sovranitetin e drejtpërdrejtë të Papatit (saktësi vetëm për vitin; dita/muaji nuk u lexuan).", "518c4913"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1536-05-21:0":{"b": ["Gjeneva votoi për Reformën: mori fund sundimi i peshkopit dhe i Savojës, lindi Republika e Gjenevës", "dcb02e44"], "d": ["Me votimin e asamblesë së përgjithshme të 21 majit 1536, Gjeneva pranoi Reformën; qyteti mbeti republikë e pavarur pranë Bernës, por nuk u bë anëtar i Konfederatës.", "fd9e9db5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1540-01-01:0":{"b": ["Mori fund zotërimi i Baglionëve: Peruxhia hyri nën administratën e drejtpërdrejtë papnore të Palit III", "3c57f2fe"], "d": ["Në fund të Luftës së Kripës u hoq zotërimi i Baglionëve, Pali III nisi ndërtimin e Rocca Paolina-s; mori fund pavarësia faktike e Komunës së Peruxhias (saktësi vetëm për vitin; dita nuk u lexua).", "0a01ed80"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1739-10-17:0":{"b": ["Kardinali Alberoni pushtoi San Marinon: u imponua administrata papnore", "4d3a4296"], "d": ["Legati i Ravenës, kardinali Giulio Alberoni, pushtoi ushtarakisht San Marinon dhe u përpoq ta lidhte me Papatin; populli qëndroi me mosbindje civile.", "79343d06"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1740-02-05:0":{"b": ["Papa Klementi XII njohu të drejtat e San Marinos: pavarësia u kthye", "0783c00e"], "d": ["Pas lutjeve të fshehta, Papa njohu të drejtat e San Marinos; pushtimi i Alberonit mori fund.", "d3268069"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-05-15:0":{"b": ["Napoleoni hyri në Milano: mori fund administrata austriake", "adce9a6c"], "d": ["Bonaparti, pas fitoreve të para të fushatës së Italisë, hyri në Milano më 15 maj 1796; Lombardia doli nga duart e Austrisë.", "2a2ae65e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-06-23:0":{"b": ["Armëpushimi i Bolonjës: Bolonja dhe Ferrara kaluan në duart franceze", "5eed42c8"], "d": ["Papa Piu VI nënshkroi armëpushim në Bolonjë; legacionet e Bolonjës dhe Ferrarës hynë nën kontrollin francez, u pagua dëmshpërblim i rëndë.", "4447b7b3"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-12-27:0":{"b": ["U shpall Republika Cispadane (Modena, Reggio, Bolonja, Ferrara)", "f9ee3f5a"], "d": ["Në kongresin e Reggios, Modena, Reggio, Bolonja dhe Ferrara u bashkuan dhe shpallën Republikën Cispadane; dukati Este faktikisht mori fund.", "0529810e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-02:0":{"b": ["Wurmser dorëzoi Mantovën", "476b954d"], "d": ["Në fund të rrethimit që zgjati me muaj, komandanti austriak Wurmser më 2 shkurt 1797 ua dorëzoi Mantovën francezëve.", "68c18933"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-19:0":{"b": ["Traktati i Tolentinos: Papa ia la Francës Bolonjën, Ferrarën dhe Romanjën", "9868973b"], "d": ["Piu VI bëri paqe me Francën në Tolentino; Bolonja, Ferrara dhe Romanja (Ravena, Rimini) kaluan te Republika Cispadane nën drejtimin francez.", "2d453d48"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-05-12:0":{"b": ["Republika e Venedikut mori fund: Këshilli i Madh u vetëshpërbë", "a03a1a31"], "d": ["Nën trysninë e Napoleonit, Këshilli i Madh më 12 maj 1797 u vetëshpërbë, Doxhi Manin dha dorëheqjen; nisi pushtimi francez, fati i mëvonshëm i Venetos u përcaktua në Campo Formio.", "cd4ad1df"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-07-09:0":{"b": ["Republika Cisalpine u themelua me ceremoni në Milano: u bashkuan Lombardia, Mantova, Bergamo, Breshia dhe tokat cispadane", "b8338ba1"], "d": ["Lombardia, Mantova, Bergamo, Breshia që pushtoi Napoleoni, Republika Cispadane (Modena, Reggio, Bolonja, Ferrara) dhe Romanja u bashkuan në një shtet të vetëm.", "ed1bf80a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-02-15:0":{"b": ["U shpall Republika Romake: administrata papnore u ndërpre", "30145500"], "d": ["Nën pushtimin e Romës nga Berthier, në Kapitol u shpall Republika Romake; Papa Piu VI u dërgua në mërgim.", "99f72dba"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-04-26:0":{"b": ["Gjeneva iu aneksua Francës: Republika e Gjenevës mori fund, u krijua departamenti Léman", "cbee4241"], "d": ["U nënshkrua traktati i aneksimit me Francën; Gjeneva dhe rrethinat iu bashkuan Republikës Franceze si departamenti Léman.", "3c1c8254"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-12-09:0":{"b": ["Piemonti u mor nën administratën franceze; Carlo Emanuele IV u tërhoq në Sardinjë", "d4e022ae"], "d": ["Dinastia Savojë në dhjetor 1798 braktisi Piemontin kontinental dhe u tërhoq në ishullin e Sardinjës, Torino hyri nën kontrollin francez (aneksimi zyrtar 11 shtator 1802).", "dcb442ed"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-01-23:0":{"b": ["U shpall Republika Partenopease: ushtria franceze hyri në Napoli, mbretërinë burbone e zëvendësoi një republikë motër", "f657b307"], "d": ["Ushtria e Championnet-it mori Napolin; burboni Ferdinando IV kishte ikur në Palermo. Kontrolli faktik i republikës kufizohet kryesisht te qyteti i Napolit dhe rrethinat (provincat mbetën pro Burbonëve).", "9e17f40e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-04-27:0":{"b": ["Pas Cassanos, ushtria austro-ruse shembi Republikën Cisalpine", "5b6ad0d8"], "d": ["Pas Betejës së Cassanos, forcat austro-ruse hynë në Lombardi; Republika Cisalpine u shemb.", "09c16276"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-06-13:0":{"b": ["Kardinali Ruffo e rimori Napolin: Republika Partenopease mori fund, administrata burbone u kthye", "04d437c6"], "d": ["Ushtria sanfediste nën komandën e kardinalit Ruffo hyri në Napoli; kështjellat republikane u dorëzuan pak më vonë, mbretëria u kthye nën administratën burbone.", "775b1d4c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-09-30:0":{"b": ["Njësitë napolitane hynë në Romë: Republika Romake mori fund, administrata papnore u kthye", "a367ed6a"], "d": ["Forcat napolitane pushtuan Romën, Republika Romake mori fund; kthimi faktik i administratës papnore u përfundua me hyrjen e Piut VII në korrik 1800.", "6ee7e336"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1800-06-04:0":{"b": ["Pas Marengos, Napoleoni e rithemeloi Republikën Cisalpine", "c03710d1"], "d": ["Pas fitores së Marengos, Napoleoni u kthye në Milano dhe e rithemeloi Republikën Cisalpine (kutia e informacionit: 2 qershor).", "df5345f5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1802-10-09:0":{"b": ["Duka i Parmës Ferdinando I vdiq: dukati kaloi nën administratën franceze", "0e6bc319"], "d": ["Ferdinandi, që me Traktatin e Aranjuezit (1801) ia kishte dorëzuar dukatin Francës, vdiq më 9 tetor 1802; Parma dhe Piaçenca hynë nën administratën franceze (aneksimi zyrtar 1808).", "5d07614d"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-06-04:0":{"b": ["Napoleoni pranoi aneksimin e Ligurisë: Gjenova iu bashkua Perandorisë Franceze", "ecc8047e"], "d": ["Senati i Ligurisë miratoi aneksimin më 25 maj 1805; Napoleoni e pranoi më 4 qershor 1805, Republika e Ligurisë mori fund.", "054ecfb4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-12-26:0":{"b": ["Traktati i Pressburgut: Veneto, Istria dhe Dalmacia kaluan te Mbretëria e Italisë", "94ff5a04"], "d": ["Austria ia la Mbretërisë së Italisë së Napoleonit ish-tokat venedikase (Veneton, Friulin, Istrien, Dalmacinë).", "5e25f259"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1807-12-10:0":{"b": ["Mbretëria e Etrurisë mori fund: Toskana ra nën pushtimin francez", "f4c9b9ef"], "d": ["Napoleoni shpërndau Mbretërinë e Etrurisë; mbretëresha regjente u largua nga Firencja, Toskana në vitin 1808 iu bashkua Francës si departamentet Arno, Ombrone dhe Méditerranée.", "d2e2917f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1808-04-02:0":{"b": ["Napoleoni ia bashkoi Markën Mbretërisë së Italisë: Ankona u bë qendra e departamentit Metauro", "2314868d"], "d": ["Me dekretin nr. 158 të dhënë në Saint-Cloud, Marka e Papatit iu shtua Mbretërisë së Italisë; dekreti i 20 prillit 1808 krijoi departamentet Metauro (Ankonë), Musone (Macerata) dhe Tronto (Fermo).", "10d2d834"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1809-05-17:0":{"b": ["Napoleoni ia bashkoi tokat papnore Perandorisë Franceze", "f4ba4cb8"], "d": ["Roma dhe tokat e mbetura të Shtetit Papnor (përfshirë Umbrian) iu aneksuan Francës; Piu VII u arrestua. Me këtë dekret Peruxhia (Umbria) iu bashkua Perandorisë Franceze.", "824297f5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1810-02-28:0":{"b": ["Traktati i Parisit: Bavaria ia la Napoleonit Tirolin Jugor (Trenton), rajoni iu bashkua Mbretërisë së Italisë", "01762dda"], "d": ["Mbreti i Bavarisë ia dorëzoi Tirolin Jugor Napoleonit; u krijua departamenti Alto Adige me qendër në Trento dhe iu lidh Mbretërisë së Italisë (ndarja e 9 qershorit 1810).", "1ceb45f7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-10-13:0":{"b": ["Austria u kthye në Trieste: mori fund administrata franceze në Provincat Ilirike", "8d0c9c7d"], "d": ["Njësitë austriake dhe flota angleze hynë në Trieste në tetor 1813; sipas Treccanit, qyteti iu kthye Austrisë më 13 tetor 1813. Garnizoni francez u tërhoq në kështjellën San Giusto, më 29 tetor u nënshkruan kushtet e kapitullimit, më 8 nëntor doli nga kështjella. Harta tregon kthimin e qytetit (13 tetor).", "a8adb522"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-10-15:0":{"b": ["Njësitë austriake hynë në Trento: departamenti Alto Adige i Mbretërisë së Italisë u shemb", "1870c11e"], "d": ["Njësitë austriake nën komandën e gjeneralit Fenner hynë në Bolcano më 11, në Trento më 15 tetor 1813; më 10 dhjetor 1813 u vendos administrata e përkohshme austriake.", "66916a3e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-12-31:0":{"b": ["Garnizoni francez u tërhoq nga Gjeneva: Republika e Gjenevës u rithemelua", "b06ab617"], "d": ["Me afrimin e njësive austriake, administrata franceze u shemb; më 31 dhjetor 1813 Republika e Gjenevës u rivendos, në 1814-1815 iu bashkua Konfederatës.", "0fe9a364"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-11:0":{"b": ["Fontainebleau: Parma dhe Piaçenca iu dhanë Marie-Louise-s", "909f6ba0"], "d": ["Me abdikimin e Napoleonit, Parma, Piaçenca dhe Guastalla iu dhanë bashkëshortes së tij Marie-Louise (kalimi në administrimin faktik 1816).", "6d19058c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-16:0":{"b": ["Eugène nënshkroi armëpushim në Mantovë: Mbretëria e Italisë u shemb, Austria mori Milanon", "f658fa23"], "d": ["Me armëpushimin e Schiarino-Rizzino-s, Mbretëria e Italisë së Napoleonit faktikisht mori fund; Lombardia dhe Veneto hynë nën kontrollin austriak (dorëzimi zyrtar: Akti Përfundimtar i Vjenës, 9 qershor 1815).", "a0989fbc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-20:0":{"b": ["Vittorio Emanuele I u kthye në Torino: dinastia Savojë u rivendos", "32499bf1"], "d": ["Mori fund administrata franceze e Piemontit; Vittorio Emanuele I u kthye nga Sardinja në Torino dhe rivuri në fuqi kushtetutën e vitit 1770.", "8db5bb96"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-24:0":{"b": ["Piu VII u kthye në Romë: administrata papnore u rivendos", "d0b4171c"], "d": ["Pas pesë vjet robërie, Papa Piu VII më 24 maj 1814 hyri triumfalisht në Romë; Shteti Papnor u rivendos (legacionet u kthyen në vitin 1815).", "d93a4a6c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-07-14:0":{"b": ["Francesco IV mori pushtetin si duka i Modenës: dukati Este-Habsburg u rivendos", "e06a5823"], "d": ["Kur Mbretëria e Italisë së Napoleonit u shpërbë, Dukati i Modenës dhe Reggios iu kthye dinastisë Habsburg-Este (Francesco IV).", "daa659f4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-09-01:0":{"b": ["Duka i Madh i Toskanës Ferdinando III u rivendos", "f6f21c83"], "d": ["Me përfundimin e epokës napoleonike, Ferdinando III nga dinastia Habsburg-Lorenë rimori pushtetin në Toskanë (shtator 1814).", "a310e5c7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1848-03-22:0":{"b": ["Manini mori Arsenalin e Venedikut: u shpall Republika e San Markos", "154bae0a"], "d": ["Nën udhëheqjen e Daniele Manin-it, Venediku u ngrit kundër administratës austriake dhe shpalli Republikën e San Markos; njësitë austriake u tërhoqën nga qyteti më 26 mars.", "476c31cc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-02-09:0":{"b": ["U shpall Republika Romake: ndërsa Papa kishte ikur në Gaeta, Asambleja Kushtetuese themeloi republikën", "282025d1"], "d": ["Triumvirati i kryesuar nga Mazzini shpalli republikën në Romë; administrata papnore u pezullua.", "03575b62"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-07-03:0":{"b": ["Ushtria franceze hyri në Romë: Republika Romake mori fund, administrata papnore u kthye", "2e5ed341"], "d": ["Forca ekspeditive franceze e Oudinot-së mori Romën; Garibaldi u tërhoq, republika ra (Wikipedia 2 korrik, shumica e burimeve 3 korrik).", "bbaabf25"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-08-22:0":{"b": ["Venediku iu dorëzua Austrisë: Republika e San Markos mori fund", "f5e5de33"], "d": ["Në fund të rrethimit, kolerës dhe urisë, Manini e dorëzoi qytetin; administrata austriake u kthye (kutia e informacionit thotë 27 gusht).", "70a16b74"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1943-09-23:0":{"b": ["Musolini themeloi Republikën e Salòs: Italia veriore u bë Republika Sociale Italiane nën protektoratin gjerman", "9248adee"], "d": ["Musolini, i liruar nga gjermanët, themeloi nën kontrollin ushtarak gjerman Republikën Sociale Italiane (të Salòs) që përfshinte Italinë veriore e qendrore; Mbretëria dhe qeveria Badoglio mbetën në jug. Me themelimin e Republikës së Salòs, Venediku, Torino, Gjenova, Verona, Bolonja dhe qytetet e tjera të Italisë veriore kaluan te Republika Sociale Italiane.", "d8f8bd9c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:536-12-09:0":{"b": ["Belisari hyri në Romë: Roma kaloi nga administrata ostrogote te Bizanti", "f74ca8a4"], "d": ["Në Luftën Gotike, ushtria e Belisarit hyri në Romë më 9 dhjetor 536; qyteti iu mor ostrogotëve dhe iu lidh Bizantit (Totila do ta rimarrë në vitin 546).", "75602e01"]},
"OLAYLAR_OK104:1284-01-01:0":{"b": ["Bizanti ia rimori Anzhusë Krujën (Akçahisarin), Durrësin dhe Vlorën", "4e1a9810"], "d": ["Durrësi dhe Kruja, që Karli i Anzhusë i kishte marrë në vitet 1271-1272, pas vdekjes së Karlit u rimorën nga perandori bizantin Androniku II (TDV Kruja: 'rimori Vlorën, Durrësin dhe Krujën'). Dihet vetëm viti; dita është e pakonfirmuar.", "eef9a5c3"]},
"OLAYLAR_OK104:1304-01-01:0":{"b": ["Filipi i Tarantit e riktheu Durrësin nën administratën anzhuine", "be355b48"], "d": ["Në Durrësin që në vitin 1284 kishte kaluar te Bizanti, princi i Tarantit Filip, djali i mbretit të Napolit Karlit II, në vitin 1304 e rivendosi administratën anzhuine; Mbretëria e Shqipërisë (Regnum Albaniae) u shpall përsëri, por sa ishte gjallë Filipi mbeti e kufizuar te ky qytet (Europange: 'The kingdom of Albania was re-established in 1304, when Philip of Taranto was able to restore the Angevin regime in Durazzo'). Në vitin 1332 djali i tij Robert ia dha Durrësin Gjonit të Gravinës në këmbim të Principatës së Akesë; dukati i Durrësit mbeti në duart anzhuine derisa Karl Topia mori qytetin në vitin 1368. Dihet vetëm viti; dita është e pakonfirmuar.", "f918f799"]},
"OLAYLAR_OK104:1344-01-01:0":{"b": ["Serbët pushtuan Krujën (Akçahisarin), Beratin dhe Vlorën", "cef4ca73"], "d": ["TDV Kruja: 'Në vitin 1344 serbët pushtuan Krujën, Beratin dhe Vlorën'. TDV Shqipëria thotë se Dushani e pushtoi Shqipërinë midis viteve 1343-1346 dhe se me shembjen e perandorisë së tij në 1355 u forcuan bejlerët vendas. Dihet vetëm viti; dita është e pakonfirmuar.", "0ab9765f"]},
"OLAYLAR_OK104:1393-05-01:0":{"b": ["Lënia e Lezhës (Alessio) Venedikut nga Dukagjinët", "2cab90db"], "d": ["Pal dhe Lekë Dukagjini, që e mbanin Lezhën (Alessio) që nga viti 1387 si qendër të Principatës shqiptare të Dukagjinëve, duke parë se përballë trysnisë osmane nuk mund ta mbronin këtë port në grykë të Drinit, ia lanë kështjellën Venedikut dhe u tërhoqën në rajonin malor në lindje të qytetit. Pas kësaj qyteti mbeti në duart e Venedikut deri sa në vitin 1478, gjatë fushatës së Fatihut kundër Shkodrës, e mori bejlerbeu i Rumelisë Davud Pasha — edhe mbledhja nga Skënderbeu më 1 mars 1444 e aleancës antiosmane (Lidhja e Lezhës) këtu, edhe vdekja e tij këtu më 17 janar 1468 ndodhën në një kështjellë venedikase.", "a7df86bc"]},
"OLAYLAR_OK104:1443-01-01:0":{"b": ["Skënderbeu mori Krujën (Akçahisarin) — nis qëndresa shqiptare", "8f007d17"], "d": ["Pas disfatës së Izlladit (TDV Kruja: 847/1443), Skënderbeu pushtoi Krujën. Pas vdekjes së babait të tij Gjon Kastriotit në vitin 1437, osmanët nuk ia dhanë qytetin atij, por Hasan Beut, që e emëruan vetë. Dihet vetëm viti; dita është e pakonfirmuar.", "d5be30c0"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Zgjatja e vijës së Dnieprit nga Polonia — themelimi i Kremençukut", "1bc86966"], "d": ["Polonia-Lituania themeloi një qytezë të re kufitare në nyjën e Dnieprit të mesëm, që ishte vendkalim i bastisjeve të Krimesë; njëzet e pesë vjet më vonë këtu u shtua edhe një kështjellë. Kështu vija e kontrollit polak zbriti deri në bregun verior të stepës së Zaporozhjes dhe ky vendkalim i lumit u lidh për herë të parë me një garnizon të përhershëm shteti. Në shekullin pasardhës qyteza do të kalonte në rendin e Hetmanatit si qendër regjimenti kozak.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Shfaqja e Umanit në vijën kufitare të Polonisë drejt Jedisanit", "2e6551ab"], "d": ["Umani u shënua për herë të parë në dokumente si vendbanim në skajin juglindor të rajonit të Bracllavit nën administratën polake. Vendi ku ndodhej ishte mbi udhët e bastisjeve të Hanatit të Krimesë drejt veriut; vendosja këtu e një qyteze të përhershme tregon se brezi i stepës së zbrazët midis dy shteteve kishte filluar të ngushtohej nga veriu. Gjatë dy shekujve pasardhës qyteti do të mbetej vendbanimi më jugor i madh polak i kësaj vije.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Avancimi i vijës mbrojtëse stepore të Moskës — Çugujevi", "c68d36d3"], "d": ["Udhëheqësi kozak Jakiv Ostrjanin, që pas kryengritjes në Poloni u strehua në Moskë, dhe njerëzit e tij themeluan një vendbanim kufitar përgjatë Donecit. Ky ishte një nga kërcimet e para të mëdha drejt stepës të vijës mbrojtëse që Moska ngriti kundër bastisjeve të Krimesë; gjatë gjysmës së shekullit pasardhës në të njëjtën vijë do të lindnin njëra pas tjetrës qyteza si Sumi, Izjumi dhe Bahmuti. Vendbanimi vazhdoi deri më 1765 si qendër kompanie e lidhur me regjimentin e Harkovit.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Themelimi i Ukrainës Slloboda — Sumi dhe brezi i vendosjes në stepë", "ab7abf59"], "d": ["Fshatarë dhe kozakë të ardhur nga regjimenti i Bila Cerkvës në Ukrainën e bregut të djathtë themeluan një qytezë të re përgjatë Pselit nën udhëheqjen e kolonelit Herasim Kondratiev; katër vjet më vonë vojvoda i Moskës e fortifikoi kështjellën. Ky valë migrimi është fillimi i rendit të Ukrainës Slloboda, që e hapi për vendosje stepën e zbrazët në kufirin jugor të Moskës: të ardhurve u jepej përjashtim nga taksat dhe në këmbim pritej prej tyre roja kufitare. Sumi ishte nga 1658 deri më 1765 qendra e regjimentit që mbante emrin e tij.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Ndërtimi i Jenikale-s — mbyllja e ngushticës së Kerçit", "d9067015"], "d": ["Pasi Azovi iu la Rusisë në 1700, porta e vetme e Detit të Zi drejt Detit të Azovit u kthye në një vijë kufitare strategjike. Shteti Osman ndërtoi një fortifikim të ri në vendin e quajtur Akıntı Burnu, dhjetë kilometra në verilindje të qytetit të Kerçit, dhe e vuri kalimin e ngushticës nën rrezen e topave; kështjellës iu dha emri Jenikale, që do të thotë vetë këtë. Kështjella mbeti për shtatëdhjetë vjet bravë lindore e Krimesë dhe me nenin e nëntëmbëdhjetë të Traktatit të Küçük Kajnarxhës të vitit 1774 iu braktis Rusisë bashkë me Kerçin.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Kështjella e Shën Jelisavetës — kufiri jugor i Rusisë arrin te vija e bastisjeve osmano-krimeane", "b9097272"], "d": ["Rusia ndërtoi në tokën e kozakëve të Zaporozhjes një kështjellë të re me emrin e Shën Jelisavetës. Arsyeja e shpallur e kështjellës ishte të mbronte emigrantët ballkanas të vendosur në Serbinë e Re nga bastisjet osmane dhe të Krimesë; pra vija kufitare ruse zbriti për herë të parë deri në mes të stepës, mbi udhët e bastisjeve. Ky post i përparuar u bë pikënisja e zgjerimit në Detin e Zi verior, që do të fillonte njëzet vjet më vonë me Küçük Kajnarxhën.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["Traktati i Dytë i Erzurumit — kufiri i Shat al-Arabit dhe lënia e bregdetit të Huzistanit", "5d1f9103"], "d": ["Mosmarrëveshja kufitare osmano-iraniane, e pazgjidhur për më shumë se një shekull, u rregullua me traktatin e dytë të nënshkruar në Erzurum, pas bisedimeve të gjata me ndërmjetësim anglez dhe rus. E gjithë udha ujore e Shat al-Arabit mbeti te Osmanët; në këmbim, vendbanimet në bregun lindor të lumit -përfshirë portin e Muhammeres dhe ishullin Abadan përballë tij- iu lanë Kaxharëve. Kështu rripi bregdetar i Huzistanit, që që nga aneksimi i Basrës në 1546 numërohej nën administratë osmane, u humb pas treqind vjetësh. Mehmed Hurshid Pasha, anëtar i komisionit kufitar të krijuar për të caktuar në vend vijën e traktatit, e përshkoi rajonin në vitet 1848-1852 dhe shkroi Seyâhatnâme-i Hudûd.", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Tërheqja nga Tabrizi — fundi i pushtimit njëjavor dhe kthimi nëpër Kars-Bajburt", "fd1542e3"], "d": ["Selimi I Javuz, që pas fitores së Çalldiranit hyri në Tabriz më 6 shtator, qëndroi në qytet rreth një javë; thesarin e Shah Ismailit dhe një pjesë të mjeshtrave dhe dijetarëve të qytetit, bashkë me familjet, i shpërnguli në Stamboll. Donte ta kalonte dimrin në Karabak dhe ta vazhdonte fushatën vitin tjetër, por për shkak të kundërshtimit të jeniçerëve hoqi dorë nga ky plan dhe ushtria u kthye nëpër Kars e Bajburt. Kështu Tabrizi nuk mbeti në duart osmane: Çalldirani ishte fitore në fushëbetejë, ndërsa fitimi i përhershëm territorial erdhi vitin tjetër me fushatën e Kemahut, Dijarbekirit dhe Anadollit Lindor.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Bashkimi i Nusajbinit, Derikut dhe Silopit me Shtetin Osman — krahu jugor i Dijarbekirit", "c3621d22"], "d": ["Pas dorëzimit të Amidit dhe krijimit të bejlerbejllëkut të Dijarbekirit, me fitimin e bejlerëve kurdë të rajonit nga Idris Bitlisiu, edhe Nusajbini, Deriku dhe Silopi, në jug të fushës së Mardinit, kaluan nën administratën osmane. Këto vende u organizuan si qendra nahijesh dhe kazash të bejlerbejllëkut të ri; disa, si Xhizra, iu lanë bejlerëve vendas me statusin jurtluk-oxhakllëk. Kështu fushata e Anadollit Lindor, e filluar pas Çalldiranit, arriti në Xhezirën e Epërme.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Shpallja e pavarësisë së Çekosllovakisë — shteti i parë pasardhës i trashëgimisë habsburge", "8f40155f"], "d": ["Për shkak të humbjes së fuqisë së Austro-Hungarisë në luftë dhe të grevave, demonstratave e kryengritjeve brenda vendit, Këshilli Kombëtar shpalli pavarësinë e Çekosllovakisë më 28 tetor 1918. Mbi bazën e gjendjes zgjedhore të vitit 1911 u krijua një kuvend kombëtar i përkohshëm; më 14 nëntor 1918 mori detyrën qeveria, në krye të së cilës u vu Masaryk. Shteti i ri e fitoi vendin e vet në të drejtën ndërkombëtare me Traktatin e Saint-Germain-en-Laye (10 shtator 1919). Në hartë Çekosllovakia shfaqet më 11 nëntor 1918; shpallja e pavarësisë është dy javë më parë. Me këtë shpallje Hradec Králové (Bohemi), Olomouc dhe Brno (Moravi) i kaluan Çekosllovakisë.", "74de11eb"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Shpallja e Shtetit të Sllovenëve, Kroatëve dhe Serbëve — Sabori kroat këputi lidhjet me Habsburgët", "2e5ae559"], "d": ["Sabori kroat shpalli më 29 tetor 1918 se Kroacia, Sllavonia dhe Dalmacia i këpusnin të gjitha lidhjet shtetërore-juridike me Austro-Hungarinë; po atë ditë në Lubjanë u festua krijimi i Shtetit të Sllovenëve, Kroatëve dhe Serbëve. Në Bosnjë-Hercegovinë, administrata austro-hungareze ia dorëzoi pushtetin qeverisë së Këshillit Kombëtar më 1 nëntor 1918. Ky shtet vazhdoi deri më 1 dhjetor 1918, kur në Beograd u shpall Mbretëria Serbo-Kroato-Sllovene.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Themelimi i Republikës së Austrisë — bërthama gjermane e trashëgimisë habsburge", "1ec8b06f"], "d": ["Pasi më 29 tetor u shpall themelimi i Çekosllovakisë në Pragë dhe i Shtetit Serbo-Kroato-Slloven në Zagreb, edhe gjermanët e Austrisë themeluan më 30 tetor Republikën e Austrisë. Po atë ditë Shteti Osman po nënshkruante Armëpushimin e Mudrosit; fundi i dy perandorive ra krah për krah në kalendar.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Revolucioni i Krizantemave — Károlyi u bë kryeministër, monarkia në Hungari filloi të shpërbëhej (republika popullore u shpall më 16 nëntor)", "d7780d2e"], "d": ["Kur u kuptua disfata e Fuqive Qendrore, në Hungari u forcuan ndjenjat kundër monarkisë dhe ndodhi një rrëshqitje drejt së majtës. Më 31 tetor 1918, në përfundim të \\\"revolucionit të krizantemave\\\", konti Mihály Károlyi me pikëpamje radikale u bë kryeministër, më pas u shpall republika popullore; Károlyi u zgjodh president i rregullt më 11 janar 1919.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Armëpushimi i Villa Giusti-t — Austro-Hungaria dorëzoi armët, Trento dhe Trieste i kaluan Italisë", "75da65fb"], "d": ["Nënshkrimi i armëpushimit me italianët në Villa Giusti nga perandori Karl më 3 nëntor 1918 e përshpejtoi copëtimin e perandorisë. TDV e shënon qartë këtë ditë si dorëzimin e armëve nga Austria: \"Austria, që pranoi disfatën, i dorëzoi armët më 3 nëntor, e Gjermania më 11 nëntor.\" Në hartë, Trento dhe Trieste kalojnë këtë ditë nga Austria te Italia — ky është transferimi i parë territorial i shpërbërjes që shihet në hartë. Me këtë armëpushim, Brixen, Cortina d'Ampezzo, Görz dhe Gradisca, në jug të vijës Brenner–Toblach–Alpet Juliane, kaluan nën pushtimin italian.", "11a74dbf"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Pavarësia e Polonisë — Këshilli i Regjencës ia dha Piłsudskit komandën e ushtrisë", "e8b546cf"], "d": ["Józef Piłsudski u kthye në Varshavë më 10 nëntor 1918. Më 11 nëntor Këshilli i Regjencës i dha komandën e ushtrisë; disa ditë më vonë i la edhe detyrën e formimit të qeverisë kombëtare.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["Ushtria serbe pushtoi Pécs-in (Peçuy) — filloi pushtimi serb i Baranyas", "68f0695f"], "d": ["Pécs-i, me rëndësi strategjike për shkak të minierave të qymyrit, hyri nën pushtimin serb më 14 nëntor 1918. Pushtimi serb i Pécs-it dhe i provincës së Baranyas vazhdoi deri në gusht 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["Ushtria serbe pushtoi Timișoarën (Temeshvar) — filloi administrata ushtarake serbe e Banatit", "3cc85350"], "d": ["Njësitë serbe e pushtuan Timișoarën më 14 nëntor 1918, e shpërndanë gardën kombëtare dhe morën administratën ushtarake, e pas pak edhe civile, të Banatit. Në fillim të dhjetorit në qytet hynë edhe njësi franceze; administrata rumune u vendos vetëm në korrik-gusht 1919.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Njësitë serbe hynë në Szigetvár — pushtimi i Somogy-t jugor", "a06b1907"], "d": ["Nga ushtria serbe që përparonte në veri të vijës së përcaktuar nga marrëveshja ushtarake e Beogradit, 220 ushtarë nën komandën e Obren Petrović-it hynë natën midis 18 dhe 19 në Szigetvár, qendrën e rrethit të Somogy-t; me këtë forcë u mbajtën edhe fshatrat e rrethit. Pushtimi vazhdoi deri në gusht 1921; Trianoni e la Szigetvárin në Hungari.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Themelimi i Mbretërisë Serbo-Kroato-Sllovene dhe i Rumanisë së Madhe — të njëjtën ditë, dy shtete", "6fd85345"], "d": ["Me bashkimin me Serbinë të sllavëve që u shkëputën nga perandoria pas shpërbërjes së Austro-Hungarisë, më 1 dhjetor 1918 u themelua Mbretëria Serbo-Kroato-Sllovene; rreth 250.000 km² territor dhe 12.000.000 banorë. Themeli ishte hedhur me Deklaratën e Korfuzit të 20 korrikut 1917; kuvendet e Podgoricës më 26 tetor, të Bosnjë-Hercegovinës më 28 tetor dhe të Novi Sadit më 25 nëntor kishin vendosur bashkimin. Po atë ditë, me bashkimin e Transilvanisë, Bukovinës dhe Besarabisë me vendim të popujve të tyre, u formua Rumania e Madhe. Në hartë, tokat e Mbretërisë së Serbisë i kalojnë Jugosllavisë. Me themelimin e mbretërisë, të gjitha tokat e Mbretërisë së Serbisë (Nish, Shkup, Manastir, Ohër, Prishtinë, Prizren, Pejë etj.) i kaluan Mbretërisë Serbo-Kroato-Sllovene.", "4fd0ff67"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["Ushtria rumune hyri në Brașov (Brassó) dhe u prit me ceremoni", "4a917d27"], "d": ["Ushtria rumune hyri në Brașov në dhjetor 1918; paria rumune e qytetit e priti me ceremoni ushtrinë dhe gjeneralin Berthelot.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["Ushtria italiane pushtoi Knin-in", "7949dd0f"], "d": ["Ushtria italiane e pushtoi Knin-in më 19 dhjetor 1918. Pushtimi vazhdoi deri më 4 prill 1921, kur ushtria italiane u tërhoq nga qyteti pas Traktatit të Rapallos.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Njësitë çekosllovake morën Košice-n (Kassa)", "0989490f"], "d": ["Kur Regjimenti 30 i Këmbësorisë me emrin Alois Jirásek e pushtoi qytetin më 29 dhjetor 1918, Košice-ja iu bashkua de facto Republikës Çekosllovake.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["Ushtria rumune hyri në Szatmár (19 prill) dhe në Oradea (Varad, 20 prill)", "3ee2bd72"], "d": ["Të shtunën e Pashkëve, më 19 prill 1919, në Satu Mare delegacioni vendor i kryesuar nga dr. Ilie Carol Barbul priti në urën e Someș-it patrullën e parë të Divizionit të 2-të të Kalorësisë nën komandën e kolonelit Ressel. Të nesërmen, më 20 prill 1919, njësitë rumune nën komandën e gjeneralit Traian Moșoiu hynë në Oradea.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Traktati i Versajës — kthimi i Alzas-Lorenës te Franca u bë juridik", "3babdfcb"], "d": ["Konferenca e Paqes e Parisit u mblodh më 18 janar 1919 dhe më 28 qershor u nënshkrua me Gjermaninë Traktati i Versajës. Neni 51 i traktatit e ktheu nën sovranitetin francez Alzas-Lorenën (Strasburg, Metz, Colmar, Mulhouse), gjermane që nga 1871 — por transferimin nuk e lidhi me ditën e nënshkrimit, por, me fuqi prapavepruese, me armëpushimin e 11 nëntorit 1918. E njëjta seri konferencash lindi Saint-Germain-in me Austrinë (10 shtator 1919), Neuilly-n me Bullgarinë (27 nëntor 1919), Trianonin me Hungarinë (4 qershor 1920) dhe Sevrën me Shtetin Osman (10 gusht 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Njësitë rumune arritën në Lugoj (Lugos) — administratë rumune në lindje të Banatit", "f65fc73c"], "d": ["Treni që mbante njësitë rumune arriti në Lugoj më 22 korrik 1919, në orën 14; banorët e qytetit e pritën ushtrinë në stacion, prefekti i Caraș-Severin-it George Dobrin mbajti fjalën e mirëseardhjes, gjenerali Jitianu u përgjigj. Në pjesën e Banatit që i ra Rumanisë, administrata rumune u vendos në korrik 1919; transferimi juridik u bë me Traktatin e Trianonit të vitit 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["Ushtria rumune hyri në Timișoara (Temeshvar) — në qytet u vendos administrata rumune", "8728e1d1"], "d": ["Në Timișoara, ku më 14 nëntor 1918 kishin hyrë njësi serbe dhe në fillim të dhjetorit njësi franceze, në mëngjesin e 3 gushtit 1919 hynë njësitë e para të ushtrisë rumune nën komandën e kolonelit Virgil Economu dhe në qytet u vendos administrata rumune.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["Ushtria SKS hyri në Prekmurje — Murska Sobota dhe Lendava dolën nga administrata hungareze", "21b2ba08"], "d": ["Njësitë e Mbretërisë Serbo-Kroato-Sllovene hynë më 12 gusht 1919 në Prekmurje, përtej lumit Mura; atë ditë mori fund administrata hungareze në rajon. Transferimi juridik u bë me Traktatin e Trianonit të vitit 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Traktati i Saint-Germain-it — zvogëlimi i Austrisë u bë juridik", "e7b722d5"], "d": ["Pas luftës Austria nënshkroi me aleatët Traktatin e Paqes të Saint-Germain-it. Sipas traktatit, Austria njihte pavarësinë e Hungarisë, Çekosllovakisë dhe Jugosllavisë; pranonte të mos bashkohej me Gjermaninë pa pëlqimin e Lidhjes së Kombeve, të hiqte shërbimin e detyrueshëm ushtarak dhe ta kufizonte ushtrinë në 30.000 veta. Ky është edhe dokumenti me të cilin Çekosllovakia fitoi vendin e vet në të drejtën ndërkombëtare. Transferimi në hartë kishte ndodhur një vit më parë; ky traktat e regjistroi atë. Me këtë traktat, Lvovi, Jazlofça, Karviná, si dhe bregdeti dhe ishujt e Dalmacisë (Krk, Cres, Lošinj, Rab, Pag, Hvar, Korçula, Vis, Zadar, Šibenik, Knin) kaluan nga Austria në dispozicion të Fuqive kryesore Aleate; Ungvár dhe Munkács (Rutenia Karpatike) i kaluan Çekosllovakisë.", "b4d5f306"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Traktati i Neuilly-së — Bullgaria humbi Trakinë Perëndimore dhe bregdetin e Egjeut", "01f2b8c8"], "d": ["Meqë lufta përfundoi me disfatë, cari Ferdinand u detyrua të kërkonte armëpushim dhe të abdikonte në favor të birit të tij, Borisit (29 shtator 1918). Me Traktatin e Neuilly-së, që i dha fund luftës, Bullgaria pësoi humbje territoriale strategjike në dobi të serbëve, humbi gjithë Trakinë Perëndimore, u detyrua t'ia linte Greqisë bregdetin e Detit Egje dhe ratifikoi dispozitat e Traktatit të Bukureshtit, që ia jepte Dobruxhën Jugore Rumanisë. Në hartë, ky transferim nuk shfaqet në ditën e traktatit, por në maj 1920, kur administrata ndërroi dorë de facto: Dedeagaçi, Sofuluja, Orestiada dhe Çirmeni i kalojnë Greqisë më 14 maj, Gjymylxhina, Iskeçeja, Dimotika dhe Ferexhiku më 27 maj.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Traktati i Trianonit — Hungaria humbi dy të tretat e territorit", "84aff507"], "d": ["Sipas Traktatit të Trianonit, të nënshkruar tre muaj pas emërimit të Horthy-t regjent të mbretërisë më 1 mars 1920, Hungaria pësoi humbje të rënda territoriale dhe njerëzore: dy të tretat e territorit të saj prej 283.000 km², pa Kroacinë, dhe gjashtëdhjetë për qind e popullsisë, përfshirë më shumë se tre milionë hungarezë, mbetën jashtë kufirit; ushtria u ul në 35.000 veta. Në hartë, Regjenca e Hungarisë shfaqet me këta kufij të zvogëluar; edhe Transilvania dhe Hungaria e Epërme marrin pikërisht këtë ditë ngjyrën e Rumanisë dhe Çekosllovakisë. Me këtë traktat, Bratislava, Kassa, Nitra dhe Komárom (Hungaria e Epërme) i kaluan de jure Çekosllovakisë; Varadi, Szatmár, Lugos, Gyulafehérvár dhe Brașov (Transilvania dhe lindja e Banatit) Rumanisë; Subotica, Becskerek, Baçi, Murska Sobota dhe Čakovec (Bačka, perëndimi i Banatit, Prekmurje, Međimurje) Mbretërisë Serbo-Kroato-Sllovene.", "f7c54f07"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["Banati u nda, Temeshvari iu la Rumanisë (Trianon neni 27/3 dhe 45)", "256b4aca"], "d": ["Traktati i Trianonit e vijëzoi kufirin hungarez-rumun me nenin 27/3 dhe me nenin 45 Hungaria hoqi dorë, në dobi të Rumanisë, nga të gjitha të drejtat dhe titujt mbi tokat e ish-monarkisë përtej këtij kufiri; kështu bashkimi i Transilvanisë, Banatit, Crișanës dhe Maramureș-it me Rumaninë u njoh në të drejtën ndërkombëtare. Rajoni i Banatit u nda midis Rumanisë dhe Serbisë; qyteti i Timishoarës iu bashkua Mbretërisë së Rumanisë. Në Temeshvar administrata rumune funksiononte de facto që nga 3 gushti 1919; traktati e bëri këtë gjendje juridike.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["Ushtria italiane u tërhoq nga Knin-i", "a1d2e846"], "d": ["Pas Traktatit të Rapallos, ushtria italiane u tërhoq nga Knin-i më 4 prill 1921; pushtimi i filluar më 19 dhjetor 1918 mori fund.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Italia ia dorëzoi Šibenik-un Mbretërisë SKS", "9d07b12a"], "d": ["Pushtimi italian, i filluar më 6 nëntor 1918, mori fund më 12 qershor 1921 me një ceremoni ku morën pjesë përfaqësuesit ushtarakë të Italisë dhe Mbretërisë SKS.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Njësitë serbe u tërhoqën nga Szigetvár — xhandarmëria hungareze mori në dorëzim qytetin", "97781b77"], "d": ["Pas hyrjes në fuqi të Trianonit, forcat serbe filluan të tërhiqeshin nga Barcs dhe Szigetvár më 17 gusht dhe morën me vete gjithçka që mund të bartej. Më 20 gusht, rreth mesditës, hynë njësitë e xhandarmërisë hungareze; pasdite këshilli bashkiak dhe nëpunësit bënë betimin, dhe në orën pesë në ndërtesën e bashkisë u bë dorëzim-marrja ushtarake.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["Mori fund pushtimi serb i Pécs-it (Peçuy) — Ushtria Kombëtare Hungareze hyri në qytet", "f437115a"], "d": ["Njësitë serbe filluan të evakuonin rajonin më 18 gusht 1921; më 20-21 gusht administrata e qytetit dhe e provincës iu dorëzua përfaqësuesve të qeverisë hungareze, më 22 gusht njësitë e Ushtrisë Kombëtare Hungareze hynë në qytet.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["Bundesheer-i austriak hyri në Burgenland — territori që Trianoni ia la Austrisë u mor de facto në dorëzim", "7bfd6915"], "d": ["Trianoni (1920) dhe Saint-Germain-i (1919) ia kishin lënë Austrisë rripin gjermanishtfolës të Hungarisë Perëndimore; përpjekja e parë për ta marrë më 28 gusht 1921 dështoi për shkak të rezistencës së njësive të parregullta hungareze. Pas Protokollit të Venedikut (13 tetor 1921), Komisioni i Përgjithshëm Aleat miratoi më 11 nëntor hyrjen e Bundesheer-it dhe marrja në dorëzim e Burgenlandit verior filloi dy ditë më pas; jugu u mor më 6 dhjetor 1921, ndërsa rajoni i Sopronit mbeti në Hungari me referendum.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["Konstandinopoja u inaugurua me ceremoni; qendra e perandorisë u zhvendos de facto në lindje", "e4d78842"], "d": ["Kryeqyteti i ri i themeluar nga Konstandini I u inaugurua me ceremoni më 11 maj 330; Konstandinopoja u bë kryeqyteti i Perandorisë Bizantine (Romake të Lindjes).", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["Komandanti Xhevher es-Sikilli hyri në Fustat dhe pushtoi Egjiptin; Ihshididët morën fund", "fd0410b1"], "d": ["Në emër të kalifit fatimid Mu'izz-Lidinillah, Xhevher es-Sikilli hyri në Fustat (17 shaban 358 / 6 korrik 969); Egjipti kaloi nga Ihshididët te Fatimidët, rajoni ku do të themelohej Kajroja hyri nën sundimin fatimid.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["Ebuz-Zevvadi mori Mosulin; u themelua dinastia ukajlide", "c3032f55"], "d": ["Ukajlidi Ebuz-Zevvad Muhamed b. Musejjeb pushtoi Mosulin (380 / 990); u zgjodh 31 mars 990, dita e parë e prerjes së vitit hixhri 380 ∩ 990 (tabela hixhri-gregoriane, ±1-2 ditë), dita mungon te burimi.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["Afonso Henriques mori Lisbonën (Ushbunen); qyteti u bë qendra e Mbretërisë së re të Portugalisë", "24fddde8"], "d": ["Ushbune iu mor Almoravidëve dhe kaloi në duart e Portugalisë (27 xhumadelula 542 / 24 tetor 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["Jaume I mori qytetin e Majorkës (Medina Mayurqa)", "47fd675c"], "d": ["Mbreti i Aragonit Jaume I ua mori qytetin e Majorkës myslimanëve; Palma i kaloi Kurorës së Aragonit.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["Muhamed b. Jusuf Ibnul-Ahmer themeloi në Granadë Shtetin Nasrid", "23f66f33"], "d": ["Shteti Nasrid u themelua me qendër Granadën (26 ramazan 635 / 12 maj 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["Marrëveshja e Stensbyt: Urdhri Teutonik ia ktheu Estoninë Veriore (Revalin) mbretit të Danimarkës Valdemar II", "b64c584d"], "d": ["Me marrëveshjen e arritur në Stensby të Sjælland-it në qershor 1238, Revali dhe Estonia Veriore u kthyen nën sundimin danez (dita mungon te burimi).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["Marrëveshja e dorëzimit të Valencias: Jaume I mori qytetin", "977120b3"], "d": ["Belensiye (Valencia) më 28 shtator 1238, me marrëveshjen e dorëzimit, i kaloi mbretit të Aragonit Jaume I (hyrja ceremoniale më 9 tetor).", "c3465b4f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1054-11-05:0":{"b": ["Ukailidi Kurejshi urdhëroi të lexohej hytbja në emër të Tugrul Beut", "9fb65fc0"], "d": ["Me ardhjen e Tugrul Beut në krahinë për shkak të fushatës së Bagdadit, emiri ukailid Kurejsh në shaban 446 / nëntor 1054 urdhëroi të lexohej hytbja në emër të Tugrul Beut; pas vrasjes së mervanidit Sulejman, në 447/1055 u plagos rëndë.", "43df7313"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1064-01-01:0":{"b": ["Sulltan Alp Arslani pushtoi Anin dhe ia dha administrimin e qytetit shedadidit Ebu Shuxha Menuçihr", "f2c51a49"], "d": ["Alp Arslani, që pushtoi Anin në 456/1064, ia dha administrimin e qytetit Ebu Shuxha Menuçihrit, të birit të shedadidit Ebu'l-Esvar Shavur. Menuçihri ia bashkoi tokave të veta edhe Karsin dhe, duke u druajtur nga ushtria bizantine që po afrohej, urdhëroi të riparoheshin muret e dëmtuara gjatë pushtimit; si vasal selxhuk sundoi në Ani për pesëdhjetë e katër vjet.", "6ddc5837"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:0":{"b": ["Alp Arslani pushtoi Akhalcikhen", "31b9964f"], "d": ["Akhalcikhe, e pushtuar nga Alp Arslani në kohën e selxhukëve (1068), në 1267-1268 hyri nën sundimin mongol.", "f2d87d84"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:1":{"b": ["Alp Arslani dhe aleatët e tij rrafshuan Tbilisin dhe Kartlin", "ff50ab5d"], "d": ["Mbreti Bagrat kishte rimarrë pjesën më të madhe të kështjellave të veta; por në 1068 Alp Arslani dhe aleatët e tij rrafshuan Tbilisin dhe Kartlin.", "753e1b62"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1073-01-01:0":{"b": ["Filareti mblodhi murgjit armenë në qytetin Hunu (krahina e Elbistanit), urdhëroi zgjedhjen e një katolikosi dhe e bëri qytetin qendër të katolikosatit", "66005693"], "d": ["Filareti, duke e shfrytëzuar si rast zënien rob të Roman Diogjenit në Betejën e Manzikertit të 1071, mblodhi murgjit armenë në qytetin Hunu dhe urdhëroi zgjedhjen e një katolikosi. Kështu u krijua qendra fetare e një administrate armene të shkëputur nga Bizanti në krahinën Marash-Elbistan-Malatja.", "146d6889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1076-01-01:0":{"b": ["Sulltan Melikshahu, me fushatën në Gjeorgji, erdhi deri në Kartli; përgjegjësinë e krahinës ia dha Serheng Savteginit", "830b979a"], "d": ["Melikshahu, me komandantin gjeorgjian Juane, të birin e Liparitit, që i mbeti besnik, organizoi fushatë mbi Gjeorgji, erdhi deri në Kartli, u kthye me shumë robër dhe plaçkë dhe përgjegjësinë e krahinës ia dha Serheng Savteginit (1076). Mbreti Giorgi II fitoi betejat me Savteginin dhe rimori disa vende.", "8a5912c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1078-07-14:0":{"b": ["Melikshahu hyri në Gjeorgji përmes Araksit, plaçkiti krahinën Somkheth dhe zuri rob Juanen", "e62fd603"], "d": ["Kur mbreti Giorgi II mundi Savteginin dhe rimori disa vende, Sulltan Melikshahu doli sërish në fushatë dhe hyri në Gjeorgji përmes Araksit (471/1078-79); plaçkiti krahinën Somkheth, zuri rob Juanen, la atje Savteginin me njësi përforcuese dhe u kthye. Emiri Ahmed i shkaktoi mbretit një disfatë të rëndë në Kouel dhe rimori Karsin.", "57f4ff76"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1083-01-01:0":{"b": ["Sulejman Shahu I organizoi fushatë në Çukurova dhe pushtoi Tarsin, Adanën, Anazarbusin dhe Misisin", "c443ee8b"], "d": ["Sulejman Shahu, që në 1082 mori titullin sulltan, po atë vit organizoi fushatë në Çukurova dhe pushtoi qytetet dhe kështjellat e Tarsit, Adanës, Anazarbusit dhe Misisit (1082-1083); më pas, me ftesën e popullit të Antiokisë, marshoi mbi Antioki me djemtë e tij Këllëç Arslan dhe Daud.", "e617bea2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-01-01:0":{"b": ["Çubuk Beu pushtoi Harputin dhe themeloi Bejlikun Çubukogullare që përfshinte rrethinat e Palusë dhe Çemishgezekut", "1f333d7d"], "d": ["Gjatë inkursioneve turke drejt Anadollit pas vitit 1071, Çubuk Beu pushtoi Harputin dhe themeloi bejlikun që përfshinte krahinat e Palusë dhe Çemishgezekut. Jeta e bejlikut ishte e shkurtër; në vitet 1110 artukidi Belek mori qytetin.", "5c951bf7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-04-29:0":{"b": ["Sulltan Melikshahu ia dha Bitlisin dhe krahinën e tij si ikta Dilmaçogllu Mehmed Beut; filloi Bejliku i Dilmaçogullarëve", "7cdcb46f"], "d": ["Pasi kryekomandanti i ushtrisë selxhuke, Fahruddevle Ibn Xhehiri, pushtoi Bitlisin dhe krahinën e tij, Sulltan Melikshahu ia dha këtë vend si ikta Dilmaçogllu Mehmed Beut, që kishte marrë pjesë në Manzikert (478/1085). Bejliku sundoi në Bitlis dhe Erzen midis viteve 1085-1394.", "da296fec"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-06-20:0":{"b": ["Muslim b. Kurejshi u mund dhe u vra në Kurzahil nga Sulejman Shahu", "fc482adb"], "d": ["Ukailidi Muslim b. Kurejsh, që donte të themelonte një shtet arab të bashkuar të pavarur nga sulltani i madh selxhuk, pasi urdhëroi plaçkitjen e krahinës së Antiokisë, luftoi me Sulejman Shahun; u mund dhe u vra në vendin Kurzahil (24 safer 478 / 20 qershor 1085) dhe u varros te Porta e Alepit.", "9f4da840"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1086-01-01:0":{"b": ["Sulltan Melikshahu erdhi në Kaukaz me ushtri të madhe dhe e nënshtroi plotësisht krahinën", "79dd07e4"], "d": ["Pasi mbreti Giorgi II shkoi në Isfahan dhe pranoi sovranitetin e Melikshahut, Melikshahu për herë të fundit në 1086 erdhi edhe një herë në Kaukaz me ushtri të madhe dhe e nënshtroi plotësisht krahinën; Gjeorgjisë Lindore i ishte dhënë emri 'Didi Turkoba' (Turqia e Madhe).", "a15ba581"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1095-01-01:0":{"b": ["Çaka Beu u vra nga dhëndri i tij Këllëç Arslani I gjatë një gostie", "20cdcec9"], "d": ["Anna Komnena, që shënon se Çaka Beu u vra gjatë një gostie nga dhëndri i tij Këllëç Arslan, jep si datë të vdekjes 1097; por duke marrë parasysh rrethimin e Malatjas të 1096 dhe rënien e Iznikut të 1097, kjo është e gabuar; data e vdekjes duhet të jetë 1095 (v. 488/1095 [?]).", "9a287bc8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1097-01-01:0":{"b": ["Këllëç Arslani I rrethoi Malatjan, që edhe danishmendët donin ta pushtonin; kur kryqtarët u drejtuan drejt Iznikut, e hoqi rrethimin", "4f036db3"], "d": ["Këllëç Arslani në dimrin 490/1097 marshoi mbi Malatja, mbi të cilën i kishin hedhur sytë edhe danishmendët, dhe e rrethoi qytetin për një kohë; kur mësoi se ushtritë kryqtare ishin nisur, u drejtua drejt Iznikut dhe Izniku u humb (qershor 1097).", "4282aef8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1100-07-01:0":{"b": ["Gumushtegin Gaziu i zuri pritë dhe zuri rob princin e Antiokisë Boemund, dhe e çoi në Niksar e e burgosi", "c43f8a71"], "d": ["Danishmendi Gumushtegin, që rrethonte Malatjan, u zuri pritë dhe mundi forcat e princit të Antiokisë Boemund që erdhën në ndihmë; Boemundi u çua së pari në Sivas, pastaj në Niksar dhe u burgos. Me afrimin e kontit të Urfës Baldwin, rrethimi u hoq.", "543833c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-06-23:0":{"b": ["Sipas marrëveshjes midis kryqtarëve dhe perandorit Aleks Komnen, Ankaraja iu la Bizantit", "d64f8668"], "d": ["Gjatë Kryqëzatës I, Raimondi i Tuluzës e pushtoi Ankaranë pa hasur rezistencë serioze, turqit në kështjellë u kaluan në shpatë; sipas marrëveshjes midis kryqtarëve dhe Aleks Komnenit, qyteti më 23 qershor 1101 iu la Perandorisë Bizantine. Administrimi bizantin zgjati rreth njëzet vjet.", "f8a37732"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-08-01:0":{"b": ["Gumushtegini, Këllëç Arslani I dhe Ridvani shpartalluan pranë Merzifonit ushtrinë kryqtare lombarde", "f2703ea8"], "d": ["Kryqtarët lombardë, që për të çliruar Boemundin nga robëria morën Ankaranë dhe përparuan në drejtim të Çankërit, përballë ushtrisë së përbashkët turke prej 20.000 vetësh të Gumushteginit, Këllëç Arslanit I, melikut të Alepit Ridvan dhe emirit të Harranit Karaxha, në gusht 1101 u shpartalluan pranë Merzifonit.", "ddaa77e1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1102-01-01:0":{"b": ["Sökmeni mori në dorëzim Hasankeyfin; u themelua dega e Hësnëkejfasë e artukidëve", "07e6f974"], "d": ["Sökmeni, që pas vdekjes së emirit të Mosulit Kurboga përkrahu Musanë në Mosul, në këmbim të premtimit të Musasë e ndihmoi të mundte Çökürmüşin; pas vrasjes së Musasë shkoi në Hasankeyf dhe mori në dorëzim qytetin. Kështu u themelua dega e Hësnëkejfasë e artukidëve (1102-1232).", "fccc615e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-01-01:0":{"b": ["Sökmeni shtiu në dorë Mardinin pas vdekjes së nipit të tij Jakuti", "a5099d54"], "d": ["Mardini ishte nën sundimin e nipit të Sökmenit, Jakutit; Sökmeni, duke përfituar nga mosmarrëveshja që shpërtheu me vdekjen e tij, në 1103 shtiu në dorë qytetin dhe ia lidhi vetes një pjesë të madhe të krahinës së Dijarbekirit.", "43484644"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-08-01:0":{"b": ["Këllëç Arslani I mundi pranë Marashit Gumushtegin Gazin", "15ec5217"], "d": ["Lirimi i Boemundit nga Gumushtegini kundrejt shpërblesës dhe pakënaqësia e Këllëç Arslanit që kërkonte pjesë nga shpërblesa i kundërvunë dy aleatët; Këllëç Arslani i shkaktoi Gumushteginit një disfatë pranë Marashit.", "64f2df55"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-01-01:0":{"b": ["Gumushtegin Gaziu vdiq në Sivas; i biri, emiri Gazi, erdhi në krye të dinastisë danishmende", "75915f65"], "d": ["Me vdekjen e Gumushteginit, danishmendët pësuan një tronditje të madhe; Malatja iu dorëzua selxhukëve, midis anëtarëve të dinastisë shpërthyen luftëra për fronin. Djali i madh, emiri Gazi, mori administrimin.", "f184fc73"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-05-07:0":{"b": ["Sökmen el-Kutbi dhe Çökürmüşi, pranë Harranit (Belihut), mundën dhe zunë rob kontin e Urfës Baldwin du Bourg dhe Josselinin", "5240d89c"], "d": ["Konti kryqtar i Urfës Baldwin du Bourg dhe konti i Tell Bashirit Josselin, më 9 shaban 497 / 7 maj 1104, në Betejën e Harranit u mundën nga myslimanët dhe ranë robër. Heroi i fitores, Sökmeni, po atë vit në tetor u sëmur dhe vdiq.", "3b141414"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-10-01:0":{"b": ["Sökmeni vdiq; e pasoi i biri, Ibrahimi", "c40e3436"], "d": ["Sökmeni, që u sëmur pak kohë pas fitores së Harranit, vdiq në tetor 1104; në degën e Hësnëkejfasë erdhi i biri Ibrahim, dhe pas vdekjes së Ibrahimit në 1108, vëllai i tij Daudi u bë sundimtar artukid.", "3fb73425"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:0":{"b": ["Muhamed Tapari shpartalloi forcat gjeorgjiane dhe shkatërroi disa qytete", "372cbcc6"], "d": ["Meqë mbreti David II, me një ushtri të madhe nga kipçakët, filloi një fushatë të re pushtuese dhe erdhi deri në Ganxhë, sulltani selxhuk Muhamed Tapar marshoi mbi Gjeorgji, shpartalloi forcat gjeorgjiane dhe shkatërroi disa qytete (503/1110).", "f381ea2e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:1":{"b": ["Melikshahu (Shahinshah), i dërguar nga sulltani i madh selxhuk Muhamed Tapar, u ul në fronin selxhuk të Anadollit në Konjë", "b8987991"], "d": ["Pas vdekjes së Këllëç Arslanit I, për shkak të sulmeve të Aleks Komnenit, Muhamed Tapari e dërgoi në Anadoll Melikshahun, djalin e madh të Këllëç Arslanit; Melikshahu erdhi në Konjë, u ul në fron dhe luftoi gjashtë vjet me Aleksin.", "a8488c23"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1111-09-01:0":{"b": ["Sökmen el-Kutbi vdiq në Balis në brigjet e Eufratit; e pasoi i biri, Zahiruddin Ibrahimi", "510ea223"], "d": ["Sökmeni, që mori pjesë në ushtrinë e Mevdudit, të birit të Altunteginit, të dërguar nga Muhamed Tapari kundër kryqtarëve, kur iu rëndua sëmundja, u nda nga ushtria dhe vdiq në Balis në shtator 1111. Në krye të ahlatshahëve erdhi i biri Ibrahim dhe qëndroi deri në 1126/1127.", "1ca34ea9"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1112-01-01:0":{"b": ["Artukidi Belek, duke e bërë Palunë qendër, vuri dorë mbi tokat e Çubukogullarëve", "624ab91f"], "d": ["Me sundimin e Belek b. Behramit mbi Harput në 1112, Paluja kaloi nga Çubukogullarët te dega e Harputit e artukidëve; Beleku e bëri këtë vend kryeqytet.", "2d7c33df"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["Davidi IV filloi të vendoste në Gjeorgji 45.000 familje kipçake", "559894b0"], "d": ["Davidi u mor vesh me 45.000 familje kipçake nga Kaukazi i Veriut dhe stepat e Rusisë Jugore, i solli në Gjeorgji që nga 1118 dhe me ndihmën e tyre në 1121 i dha fund sundimit selxhuk në Tbilisi.", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["Emiri Gazi shpartalloi princin e Antiokisë Roger dhe bëri inkursion në Antioki", "7bd138a2"], "d": ["Emiri Gazi në maj 1119 me një ushtri prej 7000 vetësh bëri inkursion në Antioki dhe shpartalloi princin e Antiokisë Roger që marshoi kundër tij.", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["Mbreti gjeorgjian David shpartalloi ushtrinë myslimane në Didgori; u hap rruga për në Tbilisi dhe Ani", "03b19a6d"], "d": ["Kundër ushtrisë së madhe me kipçakë të mbretit gjeorgjian David (në TDV David II; në burimet gjeorgjiane David IV Agmashenebeli), meliku i Ganxhës Tugrul, i dërguar nga sulltani selxhuk i Irakut Mahmud, atabegu Gündoğdu, Dubejs b. Sadaka dhe artukidi Ilgazi bashkë me Dilmaçogllu Togan Arslan u mundën pranë Didgorit më 12 gusht 1121. Gjeorgjianët më pas pushtuan Tbilisin, që prej shekujsh ishte nën sundimin islam, dhe e bënë kryeqytet.", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["Nexhmedin Ilgaziu vdiq; djemtë e tij sunduan Sulejmani në Mejjafarikin dhe Timurtashi në Mardin", "5e1a6c08"], "d": ["Ilgaziu, sundimtari artukid i Mardinit që nga Alepi bëri luftë të madhe kundër kryqtarëve, gjatë fushatës së kështjellës Zerdena me nipin e tij Belek dhe atabegun e Damaskut Tugtegin u sëmur dhe vdiq më 19 nëntor 1122. Nga djemtë e tij, Sulejmani sundoi në Mejjafarikin, Timurtashi në Mardin, nga nipat Sulejmani në Alep.", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["Me pushtimin e krahinës së Malatjas nga emiri Gazi, Elbistani hyri nën administrimin danishmend", "5be35d74"], "d": ["Elbistani, i rrënuar nga një tërmet i madh në 1114, në 1124, me pushtimin e krahinës së Malatjas nga danishmendi emir Gazi, hyri nën administrimin e tyre.", "a81725b1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:0":{"b": ["Danishmendët vunë nën kontroll krahinën e Kastamonusë", "e1be4a42"], "d": ["Në 1129 Ankaraja, Çankëri, Kastamonuja dhe brigjet e Detit të Zi hynë nën kontrollin e emir Gaziut; krahina e Kastamonusë iu bashkua kufijve danishmendë.", "df047345"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:1":{"b": ["Danishmendët vunë nën kontroll Çankërin, Kastamonunë dhe brigjet e Detit të Zi", "db4c771a"], "d": ["Danishmendët, shteti më i fuqishëm i Anadollit në periudhën e emir Gaziut, në 1129 vunë nën kontroll Ankaranë, Çankërin, Kastamonunë dhe brigjet e Detit të Zi; pjesa më e madhe e tokave që shtriheshin nga Malatja deri në Sakarja hyri nën administrimin danishmend.", "1d1edb93"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1130-01-01:0":{"b": ["Shedadidi Fadl IV vdiq në betejën që emiri i Erzenit Kurti bëri për të rimarrë Dvinin", "d8a7ad18"], "d": ["Fadli IV, që pas rrethimit të Anisë e rimori Anin dhe ia bashkoi tokave të veta Ganxhën dhe Dvinin, vdiq në 524/1130 në betejën që emiri i Erzenit Kurti bëri për të rimarrë Dvinin; e pasoi vëllai, por i biri, Mahmudi, duke ardhur në Ani mori administrimin.", "7810bf30"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1131-01-01:0":{"b": ["Saltukidi Zijaedin Gazi shpartalloi mbretin gjeorgjian Ivane", "5ba067d6"], "d": ["Zijaedin Gaziu, që mori pjesë në fushatën e organizuar kundër gjeorgjianëve kur ata në 1126 kapërcyen Ispirin dhe Pasinlerin dhe erdhën deri në Oltu, në 1131 shpartalloi mbretin Ivane.", "d91b0282"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1132-01-01:0":{"b": ["Me vdekjen e Zijaedin Gaziut, nipi i tij Izedin Saltuku II erdhi në krye të bejlikut saltukid", "726791ef"], "d": ["Zijaedin Gaziu, i afërm me artukidin Timurtash, vdiq në 526/1132; nipi i tij Izedin Saltuku II erdhi në krye të bejlikut.", "a7412435"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1134-01-01:0":{"b": ["Emiri Gazi vdiq; djali i madh, Melik Muhamedi, u shpall sundimtar në Malatja", "1cf04ea6"], "d": ["Sundimtari më me ndikim i Anadollit, emiri Gazi (Melik Gazi), vdiq në 528/1134. Menshuri, skeptri i artë dhe dhuratat e dërguara nga kalifi abasid Mustershid-Bil-lah dhe Sulltan Sanxhari iu dhanë Melik Muhamedit dhe ai u shpall sundimtar në Malatja. Vëllezërit Ajnuddevle dhe Jagani u ngritën në kryengritje.", "e39192f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:0":{"b": ["Sulltan Mesudi mori Sivasin; ua mori danishmendëve Ankaranë, Çankërin dhe Kastamonunë dhe ia dha të birit Shahinshah", "cc439683"], "d": ["Kur me vdekjen e Melik Muhamedit danishmendët u ndanë në tri degë, sulltani selxhuk i Anadollit Mesud I marshoi mbi Sivas, e mori qytetin dhe djalin e vogël Shahinshah e vuri vali të Ankarasë, Çankërit dhe Kastamonusë.", "6b775908"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:1":{"b": ["Sulltan Mesudi ua mori danishmendëve Kastamonunë dhe ia la të birit Shahinshah", "ae895779"], "d": ["Sulltan Mesudi, që mori Sivasin, bashkë me Ankaranë dhe Çankërin ia dha edhe Kastamonunë valillëkut të djalit të vogël Shahinshah.", "f8cfb811"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:2":{"b": ["Sulltan Mesudi ua mori danishmendëve Çankërin dhe ia la të birit Shahinshah", "8047e8a8"], "d": ["Mesudi I, duke përfituar nga luftërat danishmende për fronin, pushtoi Ankaranë, Çankërin dhe Kastamonunë dhe administrimin e këtyre tri qyteteve ia la të birit Shahinshah.", "07d66793"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-06-17:0":{"b": ["Sulltan Mesudi filloi rrethimin tremujor të Malatjas; pa rezultat e hoqi më 14 shtator 1143", "4c2d2d2b"], "d": ["Sulltan Mesudi, që mori Sivasin e dinastisë së ndarë tresh me vdekjen e danishmendit Melik Muhamed (537/1142), më 1 dhulhixhe 537 / 17 qershor 1143 rrethoi Malatjan; meqë për tre muaj nuk arriti rezultat, më 2 rebiulevel 538 / 14 shtator 1143 e hoqi rrethimin dhe u kthye në Konjë.", "2dc53da5"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-12-06:0":{"b": ["Melik Muhamedi vdiq në Kajseri; danishmendët u ndanë në degët e Sivasit, Malatjas dhe Kajserisë", "1ee92ff3"], "d": ["Sipas Mihail Sirianit, pas Melik Muhamedit që vdiq në Kajseri më 6 dhjetor 1143, vëllai i tij Jagëbasani vendosi sundimin në Sivas, i biri Zunnun në Kajseri, Ajnuddevle në Malatja dhe Elbistan; danishmendët, duke u ndarë në tri degë, hynë në luftë shkatërruese mes veti.", "b07a9299"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1144-08-01:0":{"b": ["Sundimtari artukid i Hësnëkejfasë Daudi vdiq; e pasoi i biri Fahredin Kara Arslan", "4782f166"], "d": ["Daudi, që bëri aleancë me artukidin e Mardinit Timurtash kundër atabegut të Mosulit Zengi, vdiq më 1 gusht 1144; i biri Fahredin Kara Arslani u mor vesh me sulltanin selxhuk të Anadollit Mesud I kundër Zengiut.", "48a2c46f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1153-03-29:0":{"b": ["Si rezultat i komplotit të ngritur nga emiri i Anisë Fahredin Shedad, ushtria saltukide u mund nga mbreti gjeorgjian Demetri; Izedin Saltuku ra rob", "f936d922"], "d": ["Emiri i Anisë Shedadi, që kërkoi për nuse të bijën e Saltukut dhe u refuzua, njoftoi se donte t'ia shiste qytetin Saltukut dhe të hynte në shërbim të tij; kur Saltuku erdhi me ushtrinë, lajmëroi mbretin gjeorgjian. Ushtria saltukide pësoi disfatë të rëndë nga mbreti Demetri, Saltuku ra rob dhe u çlirua me shpërblesë prej 100.000 dinarësh.", "0d47e21f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-01-01:0":{"b": ["Pas vdekjes së Sulltan Mesudit, dhëndrit danishmend Jagëbasan iu dhanë Amasja, Ankaraja dhe Kapadokia", "295fac37"], "d": ["Kur me vdekjen e Mesudit Këllëç Arslani II hipi në fron (1155), nga dy dhëndrit e Mesudit që i përkisnin dinastisë danishmende, Jagëbasanit iu dhanë Amasja, Ankaraja dhe Kapadokia, ndërsa Zunnunit qytetet Kajseri dhe Sivas; vëllezërit e tij u ngritën duke pretenduar fronin.", "b6540bd8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-03-07:0":{"b": ["Fahredin Shedadi ra rob te gjeorgjianët; në Ani, me kryengritjen e murgeshave armene, në vend të tij u vu vëllai i tij Fadl V", "2e64eb02"], "d": ["Pas fitores së mbretit gjeorgjian Demetri ndaj ushtrisë saltukide, murgeshat armene, që reaguan ndaj sjelljes së Fahredin Shedadit, u ngritën në kryengritje dhe në Ani, në vend të Saltukut, vunë vëllain e tij Fadl V (550/1155); emirati i Fadlit V mori fund në 1161 me dorëzimin e Anisë mbretit gjeorgjian.", "56cd50fc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-01-01:0":{"b": ["Mbreti gjeorgjian Giorgi pushtoi Anin", "8081e228"], "d": ["Mbreti gjeorgjian Giorgi, pasi në 1154 i shkaktoi një disfatë të rëndë sundimtarit saltukid Izedin Saltuk, në 1161 pushtoi qytetin e Anisë; emirati shedadid mori fund me kryengritjen e klerikëve dhe dorëzimin e qytetit mbretit gjeorgjian.", "357c7a97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-08-01:0":{"b": ["Ahlatshahu Sökmen, Izedin Saltuku dhe Devletshahu rrethuan Anin; me largimin e Saltukut nga kampi, myslimanët u mundën", "d651d8fe"], "d": ["Pas pushtimit të Anisë nga mbreti gjeorgjian Giorgi, shahu i Ahlatit Sökmen II, Izedin Saltuku II, beu i Erzenit dhe Bitlisit Fahruddevle Devletshah dhe emirë të tjerë turq u bashkuan dhe rrethuan qytetin. Me ardhjen e mbretit Giorgi, Saltuku u largua nga kampi pa i njoftuar bejlerët e tjerë; myslimanët u mundën, shumë u vranë, 9000 vetë ranë robër.", "2345b0e8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:0":{"b": ["Gjeorgjianët pushtuan Dvinin", "e8f2a041"], "d": ["Gjeorgjianët, që në 1161 morën Anin, vitin pasues pushtuan Karsin dhe Dvinin; më pas fushata e përbashkët e bejlerëve myslimanë mundi Gjeorgjinë në 1163.", "b28be1b3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:1":{"b": ["Gjeorgjianët pushtuan Karsin dhe Dvinin", "a7388ca5"], "d": ["Gjeorgjianët, pasi morën Anin në 1161, vitin pasues pushtuan Karsin dhe Dvinin; pasi vranë shumë myslimanë dhe dogjën xhami e shtëpi, u kthyen në Tbilisi.", "2a892f7b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-01-01:0":{"b": ["Ushtria e bashkuar e bejlerëve myslimanë mundi mbretin gjeorgjian Giorgi; Giorgi u detyrua ta kthente Anin", "346b30b1"], "d": ["Ushtria e madhe e formuar me nismën e Sulltan Tugrulit dhe atabegut Shemsedin Ildeniz në 558/1163 i shkaktoi mbretit të Gjeorgjisë Giorgi një disfatë të rëndë dhe Giorgi u detyrua ta kthente Anin.", "a59e4ef4"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-07-01:0":{"b": ["Ushtria aleate e bejlerëve turq mundi ushtrinë gjeorgjiane pranë kështjellës së Lukrit", "58d3a0d5"], "d": ["Mbi 50.000 muxhahidë, ku morën pjesë Ildenizi, Sökmeni, Izedin Saltuku, Ibn Aksunguri dhe Arslanshahu, pushtuan Gjeorgjinë; në korrik 1163 në rrethinat e kështjellës së Lukrit gjeorgjianët u mundën, mbreti Giorgi la plaçkat e rënda dhe iku, dhe u detyrua ta kthente Anin.", "7ac70a0b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1164-08-04:0":{"b": ["Meliku i Sivasit Jagëbasan vdiq në Çankër; midis danishmendëve filloi luftë e re", "59448eb7"], "d": ["Jagëbasani, që shkoi në Çankër për të siguruar ndihmë nga meliku selxhuk Shahinshah kundër Këllëç Arslanit II, vdiq atje më 4 gusht 1164; u varros në varrezat e medresesë që kishte ndërtuar vetë në Niksar. Se kush e pasoi pas vdekjes është e diskutueshme.", "0efd18be"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1165-01-01:0":{"b": ["Këllëç Arslani II u mori danishmendëve krahinën e Darendes dhe Gedukut (Sharkëshlla)", "917ee1e6"], "d": ["Këllëç Arslani II, duke përfituar nga lufta brenda dinastisë pas vdekjes së Jagëbasanit, në 1165 aneksoi krahinën e Elbistanit, Darendes dhe Gedukut.", "7f39a47e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1168-01-01:0":{"b": ["Izedin Saltuku II vdiq; i biri, Nasiruddin Muhamedi, hipi në fron", "40c0ab87"], "d": ["Pas Izedin Saltukut që vdiq në 563/1168, në fronin saltukid kaloi i biri Nasiruddin Muhamed; Xhamia e Madhe e Erzurumit u ndërtua në emër të tij në 1179.", "18b4b682"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1170-09-14:0":{"b": ["Këllëç Arslani II urdhëroi rindërtimin e Aksarajit dhe e bëri bazë ushtarake me emrin Daruzzafer", "e0f2e591"], "d": ["Këllëç Arslani II e shndërroi në bazë ushtarake qytetin e Aksarajit që e rindërtoi në 566 (1170-71) dhe i dha emrin Daruzzafer; ndërtoi xhami, zavije, medrese dhe një karvansaraj dhe vendosi këtu gazinjtë dhe dijetarët që solli nga Azerbajxhani.", "0ddd80f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1172-01-01:0":{"b": ["Populli i Sivasit u ngrit në kryengritje dhe vrau Ismailin; me përkrahjen e Nuredin Zengiut, Zunnuni hipi në fronin danishmend në Sivas", "ab96caf2"], "d": ["Në Sivas populli u ngrit kundër Ismailit që, gjatë zisë së bukës, nuk shpërndante rezervat e hambarit; Ismaili dhe e shoqja u vranë. Paria e qytetit ftoi Zunnunin, që ishte strehuar te Nuredini; Zunnuni me ndihmën e Nuredinit në 567/1172 hipi në fronin danishmend në Sivas, por pak kohë më vonë nën presionin e Këllëç Arslanit II iku në Niksar.", "374133e0"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:0":{"b": ["Këllëç Arslani II u mori danishmendëve Niksarin dhe e vuri nën sundimin selxhuk", "e49e3971"], "d": ["Këllëç Arslani II në verën e 1175 pushtoi Sivasin, Niksarin, Komanën, Tokatin dhe tokat e tjera danishmende; një nga qendrat danishmende, Niksari, ku Jagëbasani ishte varrosur në varrezat e medresesë së tij, ra në duart e selxhukëve.", "aa58d509"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:1":{"b": ["Këllëç Arslani II mori Tokatin nga principata e shuar danishmende dhe e vuri nën sundimin selxhuk", "1894c403"], "d": ["Pas vdekjes së atabegut Nuredin Mahmud Zengi në 569/1174, Këllëç Arslani II, duke i shpërfillur kushtet e traktatit, në verën e 1175 pushtoi Sivasin, Niksarin, Komanën, Tokatin dhe tokat e tjera danishmende; Zunnuni dhe Shahinshahu u strehuan në Bizant dhe dega e Sivasit e danishmendëve u shua.", "dbfcc454"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1180-05-28:0":{"b": ["Këllëç Arslani II ua mori bizantinëve krahinën Uluborlu, Kytahja dhe Dorylaion (Eskishehir)", "807be33d"], "d": ["Meqë perandori Manuel nuk i respektoi kushtet e traktatit dhe nuk e urdhëroi shembjen e kështjellës së Dorylaionit, Këllëç Arslani II në 573/1177 urdhëroi shkatërrimin e luginës së Meandrit; Uluborlu, Kytahja dhe Dorylaioni në 576/1180 kaluan nën sundimin selxhuk.", "60e80418"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-01-01:0":{"b": ["Mbreti gjeorgjian David marshoi mbi Erzurum; përballë rezistencës së popullit u kthye", "07419985"], "d": ["Mbreti gjeorgjian David, duke marshuar mbi Erzurum, mundi Nasiruddin Muhamedin dhe e detyroi të tërhiqej në qytet; përballë guximit dhe vendosmërisë së popullit turk, plaçkiti rrethinat dhe u tërhoq (580/1184-85).", "85711193"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-04-14:0":{"b": ["Këllëç Arslani II e ndau vendin midis njëmbëdhjetë djemve", "b1ee119d"], "d": ["Në pleqëri Këllëç Arslani II e ndau vendin midis djemve; Tokati i ra në pjesë djalit të madh Ruknedin Sulejman Shah. Vendi selxhuk u nda në njëmbëdhjetë pjesë.", "09e83cd3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-01-01:0":{"b": ["Valiu Isak Duka Komnen u ngrit kundër perandorit Andronik dhe shpalli pavarësinë e Qipros", "445f5db0"], "d": ["Ndërsa Qiproja vazhdonte si provincë e Bizantit, valiu Isak Duka Komnen u ngrit kundër perandorit Andronik Komnen dhe shpalli pavarësinë, dhe Qiproja në 1185 doli nga sundimi bizantin.", "00f3ca97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-07-10:0":{"b": ["Ahlatshahu Sökmen II (Shah-i Ermen) vdiq gjatë rrethimit të Mosulit", "f492f6ba"], "d": ["Kur Saladini në 1185 e rrethoi sërish Mosulin, erdhi lajmi i vdekjes së aleatit të tij Sökmen (9 rebiulahir 581 / 10 korrik 1185). Saladini, që nuk u kthye me duar bosh nga fushata e Ahlatit, mori Mejjafarikinin e mbetur pa sundimtar.", "2692f19a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1190-05-17:0":{"b": ["Ushtria kryqtare nën komandën e Frederik Barbarosës mundi ushtrinë selxhuke dhe hyri në Konjë", "f1f901b6"], "d": ["Perandori gjerman Barbarosa, që në mars 1190 kaloi nga Galipoli në Anadoll, hyri në tokat selxhuke në rrethinat e Uluborlusë dhe më 17 maj 1190 mundi ushtrinë e Kutbedin Melikshahut dhe melikëve të tjerë selxhukë dhe hyri në kryeqytetin Konjë, që sulltani e kishte zbrazur.", "0d30744a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1192-08-26:0":{"b": ["Këllëç Arslani II vdiq gjatë rrethimit të Aksarajit; e pasoi Kejhusrevi I", "083f9fae"], "d": ["Gjatë luftës me djemtë e vet, Këllëç Arslani II, që bashkë me Gijaseddin Kejhusrevin rrethonte Aksarajin, u sëmur dhe vdiq më 15 shaban 588 / 26 gusht 1192; Kejhusrevi hipi në fron në Konjë.", "1f04ea47"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1193-05-18:0":{"b": ["Ahlatshahu Begtemür u vra nga dhëndri i tij Hezar Dinari", "12078a3c"], "d": ["Rreth dy muaj e gjysmë pas vdekjes së Saladinit, Sejfedin Begtemür u vra më 18 maj 1193 nga një prej komandantëve të tij, dhëndri Bedredin Aksungur Hezar Dinari. Hezar Dinari burgosi djalin shtatëvjeçar dhe gruan e Begtemürit në një kështjellë në krahinën e Erzasit.", "e0117ffd"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1196-11-24:0":{"b": ["Gijaseddin Kejhusrevi ia la fronin vëllait të tij Ruknedin Sulejman Shah dhe shkoi në mërgim", "557c281e"], "d": ["Kejhusrevi I, që luftonte me vëllezërit, u detyrua t'ia linte fronin Sulejman Shahut II (Ruknedinit) (593/1196) dhe u largua nga Konja; Sulejman Shahu, duke marrë tokat e vëllezërve, vendosi unitetin e vendit.", "129847ea"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1197-01-01:0":{"b": ["Amaury de Lusignan mori titullin mbret i Qipros; po atë vit u njoh edhe nga kryqtarët e Akrës si mbret i Jerusalemit", "c38ed247"], "d": ["Amaury në 1197 mori titullin mbret dhe po atë vit u njoh nga kryqtarët e Akrës si mbret i Jerusalemit; Mbretëria e Qipros u bë baza detare e Lindjes kryqtare.", "1d28312c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1199-01-06:0":{"b": ["Levoni veshi në Katedralen e Tarsit kurorën e dërguar nga perandori i Shenjtë Romak Henriku VI dhe u bë mbreti i parë i Mbretërisë Armene të Kilikisë", "99ceea3a"], "d": ["Princi rubenid Levon veshi në Katedralen e Tarsit kurorën e dërguar nga perandori i Shenjtë Romak Henriku VI dhe u shenjtërua nga përfaqësuesi i papatit; principata rubenide u shndërrua në Mbretërinë Armene të Kilikisë.", "05fe804d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1201-06-23:0":{"b": ["Sulejman Shahu II ia mori me forcë Malatjan vëllait të tij Muizuddin Kajser Shah", "fff1df20"], "d": ["Sulejman Shahu, që veproi kundër vëllait të tij, melikut të Malatjas Muizuddin Kajser Shah, i cili këmbëngulte të mos i nënshtrohej, më 19 ramazan 597 / 23 qershor 1201 pushtoi qytetin.", "65e22bbb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-01-01:0":{"b": ["Fushata e Sulejman Shahut II në Gjeorgji: selxhukët, të zënë nga sulmi gjeorgjian në kamp, pësuan humbje të rënda; beu mengujekid i Erzinxhanit Behram Shah ra rob", "3ee9e922"], "d": ["Sulejman Shahu II, që në 1202 doli në fushatë kundër gjeorgjianëve që sulmonin tokat turke, ndërsa pushonte në kamp, pësoi sulm gjeorgjian dhe humbje të rënda; midis robërve ishte edhe beu mengujekid i Erzinxhanit Behram Shah.", "4151b3d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-06-25:0":{"b": ["Sulejman Shahu II i dha fund dinastisë saltukide dhe ia dha Erzurumin si ikta vëllait të tij Tugrul Shah", "37a63791"], "d": ["Sulltani selxhuk i Anadollit Sulejman Shahu II, që gjatë fushatës në Gjeorgji erdhi në Erzurum, burgosi Melikshahun, e shuajti bejlikun saltukid (2 sheval 598 / 25 qershor 1202) dhe ia dha Erzurumin vëllait të tij, melikut të Elbistanit Mugisuddin Tugrul Shah. Tokat saltukide mbetën në duart e Tugrul Shahut deri në 1225.", "6d717627"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-01-01:0":{"b": ["Sulejman Shahu II vdiq; i biri i vogël, Këllëç Arslani III, hipi në fron", "838d74dd"], "d": ["Sulejman Shahu II nuk arriti rezultat nga fushata gjeorgjiane e 1202; në 1204, duke marshuar për fushatën e dytë gjeorgjiane, vdiq rrugës (600/1204). Vendin e zuri i biri i vogël Këllëç Arslani III; gjatë sundimit të tij shtatë-tetëmujor u pushtua krahina e Ispartës.", "6d8da37d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-08-29:0":{"b": ["Gjeorgjianët bënë inkursion në Azerbajxhan, hynë në vendin e ahlatshahëve dhe plaçkitën krahinat e Manzikertit dhe Erxhishit", "beb13519"], "d": ["Gjeorgjianët, pasi bënë një inkursion të suksesshëm në Azerbajxhan në 601/1204-05, hynë në vendin e ahlatshahëve, përparuan deri në Manzikert, pastaj në anët e Erxhishit, duke djegur e shkatërruar çdo vend; përballë tyre nuk doli ushtar.", "5c1e0212"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1205-03-01:0":{"b": ["Gijaseddin Kejhusrevi I shkoi në Konjë dhe u ul për herë të dytë në fronin selxhuk të Anadollit", "f6332e53"], "d": ["Kejhusrevi, që për shkak të pushtimit të Stambollit nga kryqtarët (prill 1204) u detyrua të shkonte në kështjellën e vjehrrit të tij në krahinën e Trapezundës, gjatë moshës së vogël të Këllëç Arslanit III erdhi në qytet dhe u ul për herë të dytë në fron (rexheb 601 / mars 1205).", "831b9889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1207-01-01:0":{"b": ["Kejhusrevi I pushtoi krahinën e Denizlisë", "47cabadd"], "d": ["Në periudhën e sulltanatit të dytë të Gijaseddin Kejhusrevit I (1205-1211) u pushtuan krahinat e Denizlisë dhe Antalias (603/1207); Antalia u mor më 5 mars 1207.", "190b906c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-01:0":{"b": ["Në betejën me ushtrinë bizantine pranë Alashehirit Kejhusrevi I vdiq; edhe ushtria bizantine pësoi humbje të rënda", "fdac0ce7"], "d": ["Kejhusrevi vdiq në betejën që bëri me ushtrinë bizantine pranë Alashehirit; edhe ushtria bizantine pësoi humbje shumë të rënda. Trupi i tij u varros së pari në Alashehir, pastaj u çua në Konjë dhe u varros në Tyrben e Sulltanëve pranë Xhamisë së Aladinit (fundi i qershorit 1211).", "fd58f9bc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-15:0":{"b": ["Burrat e shtetit u mblodhën në Konjë dhe vendosën të vinin në fronin selxhuk melikun e Malatjas Izedin Kejkavus; Kejkavusi I u shpall sulltan në Kajseri", "f80be390"], "d": ["Me vdekjen e Kejhusrevit I (608/1211), burrat e shtetit, meqë ishte djali më i madh, vendosën të vinin në fron melikun e Malatjas Izedin Kejkavus dhe i dërguan lajmëtar që të vinte në Kajseri; vëllai i tij Aladin Kejkubad nuk ia njohu sulltanatin.", "09e0f400"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1212-01-01:0":{"b": ["Kejkubadi nuk e njohu sulltanatin e vëllait të madh Kejkavus I dhe u ngrit në kryengritje; u mbyll në kështjellën e Ankarasë dhe u dorëzua", "13cc17e2"], "d": ["Aladin Kejkubadi, i ngritur në kryengritje kundër Izedin Kejkavusit të shpallur sulltan në Kajseri pas vdekjes së të atit, bashkë me mbretin armen Leon dhe xhaxhanë e tij, melikun e Erzurumit Tugrul Shah, rrethoi Kajserinë; pa rezultat u tërhoq në kështjellën e Ankarasë dhe, kur mbaruan ushqimet, u dorëzua me kushtin që as atij as popullit të mos i bëhej dëm (608/1212).", "7b48bb7a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:0":{"b": ["Izedin Kejkavusi I vdiq në Viranshehir pranë Malatjas gjatë përgatitjes së fushatës së Alepit", "61f16209"], "d": ["Pas vdekjes së ejubidit të Alepit el-Melikuz-Zahir (1216), kur në fron hipi djali i tij ende fëmijë, Izedin Kejkavusi, duke marshuar mbi Alep, bëri aleancë me artukidin e Amidit Nasiruddin Mahmud dhe sundimtarin e Erbilit Kökböri, dhe kur erdhi në Malatja u sëmur dhe vdiq në Viranshehir pranë Malatjas (sheval 616 / janar 1220).", "a8264a2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:1":{"b": ["Aladin Kejkubadi u nxor nga burgu dhe u shpall sundimtar në Sivas", "2e697d48"], "d": ["Kejkubadi, i nxjerrë nga burgu pas vdekjes së Izedin Kejkavusit I, u shpall sulltan në Sivas (616/1220). Kundër pushtimit mongol urdhëroi rrethimin me mure të Konjës, Sivasit dhe Kajserisë.", "c731bdd7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:2":{"b": ["Mongolët shpartalluan për herë të parë gjeorgjianët", "b869830b"], "d": ["Mongolët për herë të parë në 1220 shpartalluan gjeorgjianët, në 1231 hynë në Gjeorgji.", "7f39fa9d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1225-01-13:0":{"b": ["Mbreti armen Hetum i kërkoi paqe Kejkubadit; u bë paqe kundrejt haraçit vjetor prej 40.000 florinjsh ari dhe ndihmës ushtarake", "0d137195"], "d": ["Me ankesën e tregtarëve ndaj frankëve dhe armenëve, Kejkubadi në 622 (1225) u shpalli luftë armenëve dhe kryqtarëve; mbreti armen Hetum dërgoi të dërguar dhe kërkoi paqe. Mbreti do t'i paguante sulltanit çdo vit 40.000 monedha ari dhe, kur ta kërkonte sulltani, do të dërgonte 1000 kalorës dhe 500 harkëtarë me arkibalistë.", "9d0f1a8e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:0":{"b": ["Aladin Kejkubadi mori Erzinxhanin dhe zhduku degën e Erzinxhanit të mengujekidëve", "edfdc566"], "d": ["Kejkubadi, që veproi kundër mengujekidëve që kërkonin pavarësi, në 625/1228 ia bashkoi Erzinxhanin tokave selxhuke të Anadollit; sundimtarit të Sharkikarahisarit nga dinastia, Melik Muzaferuddinit, i dha Kërshehirin si ikta dhe Efsusin, me disa vende, si pronë.", "ba31e942"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:1":{"b": ["Mori fund administrimi i Melik Muzaferuddinit, sundimtarit të degës së Sharkikarahisarit të mengujekidëve; Kërshehiri iu dha si ikta", "1ec2fd55"], "d": ["Aladin Kejkubadi në 1228 zhduku degën e Erzinxhanit të mengujekidëve; sundimtarit të Sharkikarahisarit nga dinastia, Melik Muzaferuddinit, i dha Kërshehirin si ikta dhe qytezën Efsus, me disa vende, si pronë.", "e17ab2ba"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1232-01-01:0":{"b": ["Ushtritë selxhuke morën disa kështjella në Gjeorgji; mbretëresha Rusudan ofroi paqe dhe pranoi t'ia martonte të bijën Tamara Kejhusrevit II", "2a057d64"], "d": ["Në periudhën e Aladin Kejkubadit I, në 1232 Kemaledin Kamjari dhe Mubarizudin Çavli organizuan fushatë në Gjeorgji dhe pushtuan disa kështjella; mbretëresha Rusudan, e paaftë t'i rezistonte ushtrisë selxhuke, ofroi paqe dhe pranoi t'ia martonte të bijën Tamara djalit të Kejkubadit, Gijaseddin Kejhusrevit II.", "c8ce3253"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1234-01-01:0":{"b": ["Dega e Harputit ra në duart e selxhukëve të Anadollit", "f2572ad0"], "d": ["Aladin Kejkubadi, kundër marshimit të ejubidëve në Anadoll, në 631/1234 mori Harputin; mori fund sundimi i degës artukide të Harputit (pas Kosedagut qyteti ra në duart e ilhanëve).", "b0bea54d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1236-01-01:0":{"b": ["Mongolët e pushtuan sërish Gjeorgjinë dhe dërguan parinë gjeorgjiane në Mongoli", "245ae81a"], "d": ["Kur mongolët në 633/1235-36 e pushtuan sërish Gjeorgjinë, dërguan parinë gjeorgjiane në Mongoli; ata qëndruan atje me vite. Mongolët përdorën shumë ushtarë gjeorgjianë në fushata.", "159ea654"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1237-05-31:0":{"b": ["Aladin Kejkubadi I vdiq i helmuar nga mishi i gjahut; e pasoi i biri Gijaseddin Kejhusrevi II", "5d74714c"], "d": ["Kejkubadi, që mbylli periudhën e ngritjes selxhuke, në gostinë që u dha të dërguarve në festën e ramazanit u helmua nga mishi i gjahut dhe vdiq të nesërmen (4 sheval 634 / 31 maj 1237); me përpjekjet e burrave të shtetit, në vend të trashëgimtarit Izedin Këllëç Arslan, hipi në fron Kejhusrevi II.", "7b42c0c6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1239-01-01:0":{"b": ["Ushtria mongole nën komandën e Çormagan Nojanit, gjatë fushatës në Gjeorgji, mori dhe shkatërroi Karsin", "f510f715"], "d": ["Në 636/1239 ushtria mongole nën komandën e Çormagan Nojanit gjatë fushatës në Gjeorgji mori dhe shkatërroi Karsin; qyteti mbeti nën administrimin ilhanid deri në 1336.", "38d144da"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1242-01-01:0":{"b": ["Komandanti mongol Bajxhu Nojan pushtoi Erzurumin dhe kaloi banorët në shpatë", "118b9e3a"], "d": ["Komandanti mongol i Azerbajxhanit, Bajxhu Nojani, duke përfituar nga dobësimi i selxhukëve nga kryengritja babaite, nga fundi i 1242 pushtoi Erzurumin, kaloi banorët në shpatë dhe u kthye në Mugan për ta sulmuar sërish Anadollin në pranverë.", "dcfa189c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:0":{"b": ["Mongolët që pas Kosedagut pushtuan Anadollin morën Amasjan dhe e qeverisën me valinj mongolë", "3b39a0ad"], "d": ["Pas Betejës së Kosedagut të 1243, mongolët që pushtuan Anadollin morën Amasjan dhe qyteti filloi të qeverisej nga valinj mongolë.", "a9d1a1e2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:1":{"b": ["Pas disfatës së Kosedagut, Kajseria ra në duart e mongolëve pas dhjetë ditë rezistence", "5600cbe9"], "d": ["Pas Betejës së Kosedagut (1243), Kajseria ra në duart e mongolëve pas dhjetë ditë rezistence dhe pësoi shkatërrime të mëdha.", "924187ac"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:2":{"b": ["Mbretëresha Rusudan pranoi t'u paguante haraç mongolëve dhe e njohu zyrtarisht Hanin e Madh si sovran", "99d19c31"], "d": ["Mbretëresha Rusudan, që e kuptoi se nuk mund t'ia dilte me mongolët, pranoi t'u nënshtrohej duke paguar haraç dhe në 1243 e njohu zyrtarisht Hanin e Madh si sovran. Pas vdekjes së Rusudanit mongolët e ndanë Kaukazin në tetë provinca.", "c61c6116"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:3":{"b": ["Emirati i Tokatit pas Kosedagut iu dha nga ilhanët Muinedin Sulejman Pervanes", "f2938da6"], "d": ["Ilhanët, zotër të Shtetit Selxhuk të Anadollit pas Betejës së Kosedagut, ia dhanë Emiratin e Tokatit Muinedin Sulejman Pervanes; në 1276 Tokati ishte nën administrimin e Nuredin Xhibrilit.", "d931de12"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1244-01-01:0":{"b": ["Komandanti mongol Jasavur Nojan pushtoi për pak kohë Malatjan", "98759910"], "d": ["Mongolët, pas fitores së Kosedagut (1243), nuk arritën rezultat nga përpjekjet e para ndaj Malatjas; Jasavur Nojani në 1244 e pushtoi për pak kohë qytetin, ndërsa në 1258 ai pësoi shkatërrime nga Bajxhu Nojani.", "78c903ae"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1246-01-01:0":{"b": ["Burrat e shtetit e shpallën sulltan melikun e Uluborlusë Izedin Kejkavus në fshatin Altuntash të Aksheheirit", "20d6f3e7"], "d": ["Izedin Kejkavusin, që në kohën e vdekjes së Gijaseddin Kejhusrevit II ishte melik i Uluborlusë (Borgulusë), burrat e shtetit e shpallën sulltan në fshatin Altuntash të Aksheheirit (643/1246).", "e7c6a924"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1247-01-01:0":{"b": ["Mbreti Hetum I dërgoi vëllain Sempad në Karakorum dhe lidhi me vëllain e Möngke Hanit aleancë kundër memlukëve", "7413b5e5"], "d": ["Mbreti Hetum I, duke dërguar vëllain Sempad në Karakorum, filloi aleancën zyrtare me Perandorinë Mongole.", "769d4bcf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1251-01-01:0":{"b": ["Dy Davidët që u kthyen nga Mongolia pas hipjes në fron të Mengu Hanit sunduan së bashku në Gjeorgji", "f1640157"], "d": ["Pas hipjes në fron të hanit të madh mongol Mengu (1251), dy gjeorgjianë me emrin David, të caktuar nga ai, u kthyen nga Karakorumi në vendin e tyre dhe sunduan së bashku; pastaj Batu Hani dhe Hulaguja u përpoqën të vendosnin sundim në Gjeorgji.", "96249933"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1255-01-01:0":{"b": ["Këllëç Arslani IV u mund në betejën e Ahmedhisarit pranë Kajserisë nga Kejkavusi II", "edac92e9"], "d": ["Pas vdekjes së Xhelaledin Karatait, Këllëç Arslani u shpall sulltan i pavarur në Kajseri (652/1254); vitin pasues, në betejën e zhvilluar në vendin e quajtur Ahmedhisar pranë Kajserisë, u mund nga Kejkavusi.", "d64649d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-01-01:0":{"b": ["Mongolët nën komandën e Jashmutit morën Mejjafarikinin pas rrethimit të gjatë; Mardini rezistoi tetë muaj", "c2328a27"], "d": ["Hulaguja, kur shkonte në fushatën e Sirisë në 1257, ngarkoi një njësi nën komandën e Jashmutit të merrte Mardinin dhe Mejjafarikinin; Mejjafarikini ra pas rrethimit të gjatë, Mardini i fortifikuar qëndroi më shumë se tetë muaj.", "18f326a7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-03-05:0":{"b": ["Këllëç Arslani IV, i sjellë nga Burgulu në Konjë, u vendos i vetëm në fronin selxhuk", "cb3eced9"], "d": ["Pas disfatës së Sulltanhanit (654/1256), Këllëç Arslani IV, që ndodhej në Burgulu (Uluborlu), u soll në Konjë dhe më 16 safer 655 / 5 mars 1257 u vendos i vetëm në fronin selxhuk; Kejkavusi II, kur erdhi në Konjë më 14 rebiulahir 655 / 1 maj 1257, dërgoi kundër Këllëç Arslanit komandantin e tij Ali Bahadër.", "32f17269"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1258-01-08:0":{"b": ["Kejkavusi II vuri nën sundim Malatjan, Sivasin, Tokatin dhe Amasjan; Këllëç Arslani u tërhoq në Erzinxhan", "d4834ad1"], "d": ["Kur Izedin Kejkavusi, me ndihmën e komandantëve të tij të njohur, vuri nën sundim Malatjan, Sivasin, Tokatin dhe Amasjan, Këllëç Arslani IV u detyrua të tërhiqej në Erzinxhan (656/1258); më pas me jarllëkun e Mengu Hanit vendi u nda dysh (657/1259).", "5954d32b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1259-01-01:0":{"b": ["Me jarllëkun e Mengu Hanit vendi selxhuk u nda dysh midis Kejkavusit II dhe Këllëç Arslanit IV", "4dacbe83"], "d": ["Pas largimit të Bajxhut nga Anadolli, Kejkavusi II u vendos sërish në fron në Konjë (1 maj 1257); me jarllëkun e Mengu Hanit vendi u nda midis Kejkavusit dhe Këllëç Arslanit. Kejkavusi, që nuk e pranoi sundimin mongol, në 660/1262 u strehua në Bizant.", "c7df29bf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:0":{"b": ["Sundimtari artukid i Mardinit Kara Arslan pranoi sundimin ilhanid", "c6b7b1a6"], "d": ["Mardini në rrethimin mongol që zgjati mbi 8 muaj përjetoi uri dhe murtajë; Kara Arslani, që pas vdekjes së Nexhmedin Gaziut erdhi në krye, njohu sundimin mongol në këmbim të kthimit te artukidët të Dara, Haburit, Nusajbinit dhe Re'sulajnit, dhe në 659/1261 u konfirmua nga Hulaguja si sundimtar i Mardinit.", "ff8d14de"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:1":{"b": ["Kur mongolët, të mundur nga memlukët, u tërhoqën në Iran, memlukët sulmuan Kilikinë dhe shkatërruan vendin", "505db4aa"], "d": ["Kur mongolët ilhanidë, të mundur nga memlukët, u tërhoqën në Persi, memlukët sulmuan Kilikinë dhe shkatërruan vendin; ky është fillimi faktik i sulmeve memluke.", "89ccf21b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:0":{"b": ["Muinedin Pervaneja bëri që mongolët ta vrisnin Këllëç Arslanin IV dhe vuri në fron të birin e tij të vogël Kejhusrevin III", "27f0dc7a"], "d": ["Kur Këllëç Arslani u detyrua të pranonte dhënien e Sinopit atij si pronë, veziri Muinedin Pervaneja bëri që mongolët ta vrisnin (664/1266) dhe në vend të tij vuri të birin e tij ende fëmijë, Kejhusrevin III; Pervaneja u bë zot i pakundërshtueshëm i shtetit.", "4aa91de1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:1":{"b": ["Bajbarsi zbriti në Kilikia dhe zuri rob Leonin, të birin e mbretit të Sisit Hethum", "2cefee6a"], "d": ["Sulltani memluk Bajbars, që zbriti në Kilikia në 1266, zuri rob Leonin, të birin e mbretit të Sisit Hethum; me marrëveshjen e mëvonshme, mbreti armen do t'i kthente qytetet dhe kështjellat që kishte pushtuar dhe Leoni do të lirohej (në 1268 vetëm Besni mbeti te armenët).", "e5f53d00"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:2":{"b": ["Hani i Hordës së Artë Berke arriti deri në Tbilisi", "23866ba3"], "d": ["Berke Hani në 1266 arriti deri në Tbilisi; megjithatë niveli i mirëqenies së Gjeorgjisë nën sundimin ilhanid ishte mjaft i lartë.", "013e2621"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1268-01-01:0":{"b": ["Atabegët që qeverisnin Akhalcikhen, Ardahanin dhe Artvinin (Atabegati Samcke/Meskhet) morën administrimin e krahinës", "71bb5a86"], "d": ["Midis viteve 1268-1578, atabegët, sundimtarë të krahinave të Akhalcikhes, Ardahanit dhe Artvinit, e mbajtën në dorë administrimin e krahinës dhe në këtë periudhë mbetën të lidhur me shtetet ilhanide, karakojunlu dhe akkojunlu.", "44bea8bb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1269-01-01:0":{"b": ["Hetumi I u tërhoq nga froni dhe ia la të birit Leonit II; mbretëria u bë faktikisht vasale memluke", "3d94aadc"], "d": ["Hetumi I u tërhoq nga froni dhe ia la vendin të birit Leonit II; Leoni II u detyrua të paguante haraç të madh vjetor dhe mbretëria u bë faktikisht vasale memluke.", "cd7ade63"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1271-01-01:0":{"b": ["Sulltani memluk Bajbars dërgoi mbi Qipro një flotë prej shtatëmbëdhjetë anijesh; për shkak të stuhisë sulmi dështoi", "cfeb4521"], "d": ["Bajbarsi në 1271, ndërsa pushtonte kështjellat dhe qytetet e fundit të kryqtarëve në Palestinë dhe Siri, dërgoi mbi Qipro një flotë prej shtatëmbëdhjetë anijesh, por për shkak të stuhisë që shpërtheu sulmi dështoi.", "c0ba5344"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1275-01-01:0":{"b": ["Bejliku i Sahib Ataogullarëve u themelua në Afjonkarahisar dhe rrethinat", "c909e2f5"], "d": ["Djemtë dhe nipat e vezirit selxhuk të Anadollit Sahib Ata themeluan një bejlik në Afjonkarahisar dhe rrethinat (1275-1341).", "26972b2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1277-06-04:0":{"b": ["Ilhanët e kuptuan tradhtinë e Muinedin Sulejman Pervanes dhe i morën jetën", "9a7cc34e"], "d": ["Pas largimit të Bajbarsit nga Anadolli, Abaka Hani, që erdhi me ushtri të madhe, me arsyetimin se ishte bashkëpunuar me memlukët urdhëroi masakrimin e 200.000 vetëve; duke kuptuar edhe tradhtinë e Pervanes, i morën jetën dhe filluan ta qeverisnin Shtetin Selxhuk të Anadollit me nëpunës të dërguar nga Tebrizi (vdekja e Pervanes 676/1277).", "c7bb6ee3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1280-05-03:0":{"b": ["I biri i Kejkavusit II, Mesudi II, erdhi në Sinop dhe shkoi në kryeqytetin ilhanid për të dalë përpara Abaka Hanit", "9b43e13f"], "d": ["I biri dhe trashëgimtari i Kejkavusit II, Mesudi II, erdhi në 679/1280 në Sinop, pastaj shkoi në kryeqytetin ilhanid dhe doli përpara Abaka Hanit; Abaka Hani ia dha atij administrimin e Erzurumit, Erzinxhanit, Sivasit, Dijarbekirit dhe Harputit.", "0ddb3753"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1282-04-11:0":{"b": ["Argun Hani shpalli sulltan Mesudin II dhe urdhëroi vrasjen e Kejhusrevit III", "0afda15b"], "d": ["Pasi Ahmed Tekuderi i ndau tokat selxhuke midis Mesudit II dhe Kejhusrevit III, Argun Hani, fitues i luftës për fronin ilhanid, shpalli sulltan Mesudin II që ndodhej në Tebriz (681/1282) dhe urdhëroi vrasjen e Kejhusrevit III që priste në Erzurum.", "ffa63120"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1284-03-20:0":{"b": ["Mesudi II u kthye në Anadoll dhe hipi në fron si sulltan selxhuk, së pari në Kajseri, pastaj në Konjë", "ca5c28f4"], "d": ["Mesudi II, me miratimin e Argunit, u kthye në Anadoll dhe në 683/1284 hipi në fron në Kajseri dhe Konjë; nën tiraninë e komandantëve dhe valinjve mongolë mbeti 'sundimtar hije' dhe luftoi me karamanogullarët, eshrefogullarët dhe germijanogullarët.", "c089c457"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1288-11-22:0":{"b": ["Veziri selxhuk Sahib Ata Fahredin Ali vdiq pranë Aksheheirit", "9c7034f1"], "d": ["Sahib Ata, që i shërbeu Kejkavusit si naib-i saltanat (657/1259), që në 670/1271-72 u burgos në kështjellën e Osmanxhëkut dhe në 674/1275-76 u emërua sërish vezir, në fund të 686 / fillim të 1288, pas fushatës me ushtrinë aleate selxhuko-mongole kundër karamanogullarëve, vdiq në fshatin Nadir të lidhur me Aksheheirin më 25 sheval 687 / 22 nëntor 1288 dhe u varros në tyrben e tij në Konjë.", "f8bf5f4a"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0481-01-01:0":{"b": ["Klodviku u bë mbret i frankëve salianë në vend të të atit, Childerikut; qendra e pushtetit ishte Turnai", "e4d35fd1"], "d": ["Klodviku në 481, pesëmbëdhjetë vjeç, u bë mbret i frankëve salianë në vend të të atit, Childerikut I. Në atë kohë frankët salianë kishin përparuar deri te lumi Somme dhe qendra e fuqisë së tyre ishte Turnai.", "d4c684f8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0486-01-01:0":{"b": ["Klodviku mund Siagriun në Betejën e Suasonit; principata e mbetur romake në jug të Sommes u kalon frankëve", "afa05aa7"], "d": ["Klodviku në 486 sulmoi gjeneralin romak Siagrius; Siagriu, i mundur në Betejën e Suasonit, u strehua te mbreti vizigot Alariku II dhe iu dorëzua Klodvikut. Pas kësaj Klodviku e zhvendosi rezidencën në Suason dhe pushtoi pjesë-pjesë Belgica Secunda (me kryeqytet Reims).", "f20e6e70"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0496-12-25:0":{"b": ["Klodviku pagëzohet në Reims nga peshkopi Remigius (Krishtlindje)", "16299c9a"], "d": ["Klodviku, pas fitores që korri ndaj alemanëve, shkoi në Reims dhe ditën e Krishtlindjeve të vitit 496, bashkë me tre mijë frankë, u pagëzua nga Shën Remigiu. Pagëzimi i ktheu sytë e popullsisë katolike në mbretëritë burgonde dhe vizigote nga Klodviku.", "2d58bf65"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0507-01-01:0":{"b": ["Klodviku vret në Vouillé (pranë Poitiersit) mbretin vizigot Alarik II; tokat vizigote deri në Pirenej u kalojnë frankëve", "e8ea0c78"], "d": ["Klodviku, pasi përfundoi nënshtrimin e alemanëve në 506, vitin pasues marshoi kundër mbretit vizigot Alarik II. Në Vouillé pranë Poitiersit e vrau Alarikun me dorën e vet; pjesa e mbretërisë vizigote që shtrihej deri në Pirenej, me përjashtim të Septimanisë, iu bashkua shtetit frank.", "e632a672"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0511-11-27:0":{"b": ["Klodviku vdes; varroset në Paris, të cilin në vitet e fundit e bëri kryeqytet, dhe uniteti i mbretërisë u mbetet trashëgimtarëve merovingë", "c6c9caa4"], "d": ["Klodviku i kaloi vitet e fundit në Paris dhe e bëri atë kryeqytet të mbretërisë; duke zhdukur mbretërit e vegjël frankë në qendra si Cambrai e Këlni, u bë mbreti i vetëm i të gjitha fiseve franke. Vdiq në 511.", "eeb42f8c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0756-01-01:0":{"b": ["Pipini III, me fushatat në Itali, ua merr langobardëve Ekzarkatin e Ravenës dhe ia dhuron papës; lind Shteti Papal", "f6bbc975"], "d": ["Pipini III, me thirrjen e Papës Stefan II, bëri dy fushata në Itali në 754 dhe 756; duke ia dhuruar papës Ekzarkatin e Ravenës që ia mori mbretit langobard Aistulf, u bë krijuesi i shtetit tokësor të papatit. Pipini i dha papës titullin ‘Patricius i romakëve’.", "0e4f19d8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0800-12-25:0":{"b": ["Karli i Madh shpallet dhe kurorëzohet perandor në Shën Pjetër të Romës nga Papa Leoni III", "3d72f37d"], "d": ["Karli i Madh në 800 shkoi në Romë për restaurim; ditën pasuese të Krishtlindjeve, teksa ngrihej nga lutja në kishën e Shën Pjetrit, u kurorëzua nga Papa Leoni III dhe u shpall perandor dhe augustus.", "d6956767"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0814-01-28:0":{"b": ["Karli i Madh vdes në Aachen dhe po atë ditë varroset në kishën e Shën Marisë", "915d6f61"], "d": ["Karli i Madh i kaloi shumicën e viteve të fundit në Aachen (Aix). Në fillim të 814 pati ethe, vdiq nga pleuriti më 28 janar 814 pasi mori kungimin dhe po atë ditë u varros në kishën e Shën Marisë në Aachen; e pasoi i biri, Luigji i Devotshëm.", "8ce37094"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0842-02-14:0":{"b": ["Betimet e Strasburgut: Karli Tullac dhe Luigji Gjerman betohen për aleancë në Strasburg", "b462f12a"], "d": ["Vitin pas fitores së Fontenoyt, Karli Tullac dhe Luigji Gjerman e përforcuan aleancën me Betimet e Strasburgut; Karli u betua në gjuhën germanike të popullit të Luigjit, ndërsa Luigji në gjuhën romane të nënshtetasve të Karlit.", "02ceae89"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0843-08-10:0":{"b": ["Traktati i Verdunit: Perandoria Karolinge ndahet tresh (Francia Perëndimore, Francia e Mesme, Francia Lindore)", "1b628d03"], "d": ["Djemtë e Luigjit të Devotshëm e ndanë perandorinë me traktatin e arritur në Verdun në gusht 843: Karli Tullac mori perëndimin e vijës Meuse-Saône-Rhône (Francia Perëndimore, përfshirë Markën Spanjolle), Luigji Gjerman lindjen e Rinit (Bavaria, Turingia, Franken, Saksonia; gjithashtu rrethinat e Speyer-Worms-Mainzit), Lotari Italinë, titullin perandorak dhe rripin në luginat e Rinit-Rhônes.", "5bda08ed"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0858-02-13:0":{"b": ["Cináed mac Ailpín vdiq në pallatin e Forteviotit (13 shkurt)", "d9eee9cb"], "d": ["Sipas listës historike të mbretërve të Albës (Skocisë), Chronicle of the Kings of Alba, Cináed mac Ailpín vdiq më 13 shkurt në pallatin e Forteviotit; Annals of Ulster e vendos vdekjen në 858. Në atlas, Fortevioti që nga kjo dëshmi e parë e datuar është i shkruar nën Mbretërinë e Skocisë.", "9ad98182"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0875-12-25:0":{"b": ["Karli Tullac merr në Romë kurorën perandorake", "49f42456"], "d": ["Pas vdekjes së Luigjit II, Karli Tullac, që zbriti në Itali me përkrahjen e Papës Gjon VIII, mori në Pavia kurorën mbretërore të Italisë dhe në Romë kurorën perandorake.", "d63d65ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0893-01-28:0":{"b": ["Karli i Thjeshtë kurorëzohet mbret në Reims; fillon mbretëria rivale kundër Odos", "ccc4acd5"], "d": ["Karli III ‘i Thjeshtë’ ishte përjashtuar për shkak të moshës së re kur Charles the Fat u rrëzua nga froni në 887; gjatë mbretërimit të Odos, me njohjen e një pjese të parisë, u kurorëzua në Reims më 28 janar 893 dhe me aleancën e perandorit e detyroi Odon t’i linte një pjesë të Neustrisë. Me vdekjen e Odos në 898 u bë zot i gjithë mbretërisë.", "cd52d1cb"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0911-01-01:0":{"b": ["Traktati i Saint-Clair-sur-Epte: Karli i Thjeshtë u lë normanëve Normandinë e sotme", "fd0306b0"], "d": ["Karli III në 911 lidhi traktat me normanët në Saint-Clair-sur-Epte; një pjesë e normanëve u pagëzuan dhe atyre iu la toka që më vonë do të njihej si Dukati i Normandisë. Historia e martesës së Rollos me motrën e mbretit është rrëfim i Dudos dhe është shumë e dyshimtë.", "5798ced7"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0923-06-15:0":{"b": ["Beteja e Suasonit: mbreti Robert I vdes, duka i Burgonjës Raoul zgjidhet mbret", "4430302d"], "d": ["Roberti, i zgjedhur në 922 mbret kundër Karlit të Thjeshtë, vdiq në Betejën e Suasonit; përkrahësit e Robertit, që fituan betejën, zgjodhën mbret dukën e Burgonjës Raoul (Rudolf). Karli, duke i besuar kontit të Vermandois Herbert, ra rob dhe vdiq në Péronne në 929.", "9c2c291f"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0955-08-10:0":{"b": ["Beteja e Lechfeldit: Otoni I u jep fund inkursioneve hungareze", "7bd31ba4"], "d": ["Otoni marshoi kundër hungarezëve që rrethonin Augsburgun dhe më 10 gusht 955, me fitoren e madhe në Lechfeld, e shpëtoi Gjermaninë nga inkursionet hungareze; po atë vit mundi edhe sllavët.", "fbb1b763"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0962-02-02:0":{"b": ["Otoni I merr kurorën perandorake në Romë; fillimi i Perandorisë së Shenjtë Romake-Gjermane", "24571f97"], "d": ["Otoni, me thirrjen e Papës Gjon XII për ndihmë kundër Berengarit, kaloi në Itali; pasi arriti në Pavia në Krishtlindjet e 961, mori kurorën perandorake në Romë më 2 shkurt 962 dhe konfirmoi të drejtat dhe privilegjet e papatit. Populli i Romës u betua se në zgjedhjen e papës do të merrte miratimin e perandorit. Në këtë datë mori fund Francia Lindore (Mbretëria Gjermane) dhe në vend të saj u themelua Gjermania (e Shenjta Romake): qytetet e Francias Lindore si Frankfurti, Hamburgu, Dorestadi (Wijk bij Duurstede) i kaluan Gjermanisë (Perandorisë së Shenjtë Romake).", "eae66234"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1016-04-23:0":{"b": ["Æthelredi II vdes; Cnuti (Canute) zgjidhet mbret nga paria e mbledhur në Southampton", "35653e3c"], "d": ["Pas vdekjes së Æthelredit II më 23 prill 1016, danezi Cnut u zgjodh mbret nga kuvendi i parisë në Southampton; ndërsa Londra i mbeti besnike Edmundit. Në betejën e madhe të Assandunit fitoi Cnuti dhe, pas vdekjes së Edmundit në nëntor 1016, në fillim të 1017 u zgjodh mbret i gjithë Anglisë.", "3a49dfc2"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:0":{"b": ["Mbreti Henri I ia jep Dukatin e Burgonjës vëllait të tij Robert; fillon Dukati kapetian i Burgonjës (shtëpia e parë dukale)", "18dcd0ab"], "d": ["Henri I, që u bë mbret i Francës, në 1032 ia dhuroi Dukatin e Burgonjës vëllait të tij Robert; nga Roberti rrodhi shtëpia e parë dukale kapetiane që do të zgjaste deri në 1361.", "cbb03a09"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:1":{"b": ["Vdes mbreti i fundit i Mbretërisë së Burgonjës (Arlit), Rudolfi III; vendi i tij i mbetet Konradit II (perandorit gjerman) — Bazeli hyn në tokat perandorake", "4dc8eb08"], "d": ["Mbreti i fundit i Mbretërisë së Burgonjës (Burgonjës së Jurës/Arlit), Rudolfi III (993-1032), kur vdiq pa trashëgimtar, ia la tokat perandorit Konrad II. Kjo trashëgimi është burimi i të drejtave perandorake që përfshijnë atë që pas shekullit XIII quhet Mbretëria e Arlit, me një pjesë të Zvicrës së sotme nga Jura deri te Aari, si dhe Franche-Comté, Lyonnais, Dauphiné, Savojën dhe Provencën. Që nga 888 autoriteti i mbretërisë ishte njohur në peshkopatat e Besançonit, Bazelit, Lozanës, Gjenevës dhe Sionit.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:2":{"b": ["Vdes mbreti i fundit i Mbretërisë së Burgonjës (Arlit), Rudolfi III; vendi i tij i mbetet Konradit II (perandorit gjerman) — Gjeneva hyn në tokat perandorake", "be189789"], "d": ["Mbreti i fundit i Mbretërisë së Burgonjës (Burgonjës së Jurës/Arlit), Rudolfi III (993-1032), kur vdiq pa trashëgimtar, ia la tokat perandorit Konrad II. Kjo trashëgimi është burimi i të drejtave perandorake që përfshijnë atë që pas shekullit XIII quhet Mbretëria e Arlit, me një pjesë të Zvicrës së sotme nga Jura deri te Aari, si dhe Franche-Comté, Lyonnais, Dauphiné, Savojën dhe Provencën. Që nga 888 autoriteti i mbretërisë ishte njohur në peshkopatat e Besançonit, Bazelit, Lozanës, Gjenevës dhe Sionit.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:3":{"b": ["Vdes mbreti i fundit i Mbretërisë së Burgonjës (Arlit), Rudolfi III; vendi i tij i mbetet Konradit II (perandorit gjerman) — Lioni hyn në tokat perandorake", "78601ea1"], "d": ["Mbreti i fundit i Mbretërisë së Burgonjës (Burgonjës së Jurës/Arlit), Rudolfi III (993-1032), kur vdiq pa trashëgimtar, ia la tokat perandorit Konrad II. Kjo trashëgimi është burimi i të drejtave perandorake që përfshijnë atë që pas shekullit XIII quhet Mbretëria e Arlit, me një pjesë të Zvicrës së sotme nga Jura deri te Aari, si dhe Franche-Comté, Lyonnais, Dauphiné, Savojën dhe Provencën. Që nga 888 autoriteti i mbretërisë ishte njohur në peshkopatat e Besançonit, Bazelit, Lozanës, Gjenevës dhe Sionit.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-01-05:0":{"b": ["Edward Rrëfimtari vdes; Harold Godwinson zgjidhet dhe kurorëzohet mbret në Londër", "3ff7af82"], "d": ["Edward Rrëfimtari, që nuk mundi të merrte pjesë në shenjtërimin e manastirit të Westminsterit, vdiq më 5 janar 1066; në çastin e vdekjes propozoi Haroldin si pasardhës. Haroldi u zgjodh dhe u kurorëzua menjëherë; edhe Northumbria, ndonëse në fillim e refuzoi, iu nënshtrua. Uiliami e kërkoi fronin duke u mbështetur në testamentin e Edwardit dhe premtimin e Haroldit rreth vitit 1064 dhe u përgatit për pushtim.", "c67100ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-12-25:0":{"b": ["Duka norman Uiliam kurorëzohet mbret i Anglisë në Westminster", "92ddd637"], "d": ["Uiliami, që zbriti në Pevensey më 28 shtator 1066, më 14 tetor në Betejën e Senlacit (Hastings) e shtypi Haroldin; ditën e Krishtlindjeve u kurorëzua në Westminster. Nënshtrimi i jugut, perëndimit dhe veriut të Anglisë zgjati edhe pesë vjet.", "78756409"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1068-01-01:0":{"b": ["Uiliam Pushtuesi organizon fushatë kundër Exeterit rebel", "cc25aa87"], "d": ["Viti 1068 i Uiliamit kaloi me fushata ushtarake kundër Exeterit dhe Yorkut, ku ishin strehuar përkrahësit e Haroldit.", "e1fb87c6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1069-01-01:0":{"b": ["Kryengritja e veriut: danezët dhe anglezët pushtojnë Yorkun; Uiliami e rrethon dhe e rimerr qytetin, shkatërron veriun", "c15ad892"], "d": ["Pas vrasjes së Robert of Comines në Durham, veriu shpalli Edgar Athelingun, mbreti i Danimarkës Sweyn dërgoi flotë; danezët dhe anglezët morën Yorkun, të mbrojtur nga dy kështjella normane. Uiliami marshoi mbi York, i shtyu danezët te anijet, e mori qytetin me bllokadë dhe e shkatërroi vendin deri në Durham; në fillim të 1070, duke marshuar mbi Chester, përfundoi nënshtrimin e veriut.", "a4420b47"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1075-01-01:0":{"b": ["Papa Gregori VII ndalon investiturën laike (dhënien e gradës kishtare nga persona laikë)", "bc8488be"], "d": ["Ndalimi i investiturës laike, i shpallur dy vjet pasi Hildebrandi u zgjodh papë në 1073 me emrin Gregori VII, kërcënoi fuqinë e perandorisë mbi emërimet fetare dhe u bë fillimi i përplasjes së hapur me Henrikun IV.", "c78da49d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1080-03-07:0":{"b": ["Papa Gregori VII shkishëron për herë të dytë Henrikun IV dhe e shpall të rrëzuar nga froni", "d73a0f3d"], "d": ["Me fitoren e Flarchheimit (27 janar 1080), nën presionin e saksonëve dhe nën ndikimin e informacionit të gabuar, Gregori VII e braktisi politikën e pritjes; më 7 mars 1080 e shkishëroi sërish Henrikun dhe e shpalli të rrëzuar nga froni, dhe i zgjidhi nënshtetasit e tij nga betimet e besnikërisë. Ndikimi ishte shumë më i dobët se në 1076; sinodi i Brixenit e shkarkoi Gregorin më 25 qershor 1080.", "518e832b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1111-04-13:0":{"b": ["Henriku V merr kurorën perandorake në Romë; çështja e investiturës zgjidhet përkohësisht me një kompromis", "f7e1aee5"], "d": ["Henriku V në shkurt 1111 në Sutri mori premtimin për kurorën perandorake në këmbim të heqjes dorë nga investitura; Papës Paskalit II iu shkulën nga duart e drejta e investiturës dhe premtimi për kurorën, dhe ceremonia e kurorëzimit u bë më 13 prill 1111. Pasi Henriku u largua nga Roma, një koncil e shpalli këtë privilegj të pavlefshëm.", "5d77b395"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1152-01-01:0":{"b": ["Henriku (II), duke u martuar me Aliénorën, fiton Poitou, Guyenne dhe Gascogne", "4db69859"], "d": ["Henri Plantagenet në 1150 u bë dukë i Normandisë, në 1151 me vdekjen e të atit kont i Anzhuit; në 1152, duke u martuar me Aleonorën (Eleanor), e divorcuar nga mbreti i Francës Luigji VII, fitoi Poitou, Guyenne dhe Gascogne — kjo është gjysma jugore e Perandorisë Anzhuine. Martesa i tërhoqi armiqësinë e sovranit të Henrikut, Luigjit VII.", "39880a5d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1154-10-25:0":{"b": ["Mbreti Stephen vdes; Henriku II kalon në fronin anglez pa hasur asnjë rezistencë", "e1882039"], "d": ["Henriku në 1153, me ndihmën e Kishës dhe të përkrahësve të nënës së tij Matilda, i kishte shkëputur Stephenit njohjen e të drejtës së tij të trashëgimisë angleze; kur Stepheni vdiq më 25 tetor 1154, ai e parashtroi pretendimin pa kundërshtim. Perandoria Anzhuine bashkoi tokat nga Anglia deri në Pirenej.", "82a14d22"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1155-06-18:0":{"b": ["Frederik I Barbarosa merr kurorën perandorake në Romë", "94350025"], "d": ["Frederiku, në fushatën e parë në Itali të 1154, mori kurorën perandorake në Romë më 18 qershor 1155; për shkak të forcave të pamjaftueshme dhe armiqësisë që shpërtheu, në vjeshtë u kthye në Gjermani.", "ae0ad79e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1157-01-01:0":{"b": ["Dieta e Besançonit: aristokratët e Burgonjës i shprehin besnikëri Frederikut; përshkallëzohet përplasja papë-perandor", "7252823d"], "d": ["Në dietën e mbledhur në Besançon në tetor 1157, aristokratët burgonjas iu betuan Frederikut për besnikëri; për shkak të kapjes së kryepeshkopit suedez gjatë kthimit nga Roma, u rrit mosmarrëveshja papë-perandor.", "7b20ab27"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1173-01-01:0":{"b": ["Konti i Tuluzës Raymond V i bën betimin e besnikërisë (homage) Henrikut II", "460d9e41"], "d": ["Henriku II, që mori përsipër pretendimet e Aleonorës mbi Tuluzën, pas një lufte të gjatë, në 1173 e detyroi kontin e Tuluzës Raymond V t'i betohej për besnikëri për Tuluzën.", "1727d885"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1176-05-29:0":{"b": ["Beteja e Legnanos: Lidhja Lombarde mund Frederikun I", "b7613445"], "d": ["Kundër Frederikut, që në 1174 doli në fushatën e pestë në Itali, ishte formuar Lidhja Lombarde dhe ishte ngritur kështjella e Alessandrias. Meqë duka i Saksonisë Henri Luani nuk ndihmoi, Frederiku u mund në Legnano më 29 maj 1176; u kujtua se ishte plagosur dhe kishte vdekur. U tërhoq në Pavia dhe filloi bisedimet e paqes me Papën Aleksandër III.", "4d37e6ac"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1177-01-01:0":{"b": ["Traktati i Venedikut: Frederik Barbarosa dhe Papa Aleksandër III pajtohen; armëpushim gjashtëvjeçar me Lidhjen Lombarde", "041665b3"], "d": ["Pas Legnanos, Frederiku, me traktatin e Venedikut të gushtit 1177, e njohu Aleksandrin III si papë të vërtetë dhe u çlirua nga shkishërimi (në korrik 1177 puthi këmbën e papës); me Lidhjen Lombarde u lidh armëpushim gjashtëvjeçar. Trashëgimia e Matildës iu la vendimit të arbitrit.", "1b138556"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1183-06-25:0":{"b": ["Traktati i Konstancës: Frederiku bën paqe të përhershme me Lidhjen Lombarde", "91ea5aaf"], "d": ["Në qershor 1183, në Konstancë, u lidh traktat me Lidhjen Lombarde (paqe e përhershme që zëvendësoi armëpushimin gjashtëvjeçar të 1177). Ndërkohë duka i Saksonisë Henri Luani ishte zhveshur nga dukati dhe ishte internuar, dhe dukati ishte copëtuar; në 1184 i biri Henriku u fejua me Konstancën, të bijën e mbretit të Sicilisë Roger.", "97ab19ec"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1201-01-01:0":{"b": ["Kapitulacioni i Neussit: Otoni IV njeh autoritetin papal mbi tokat papale", "b43b4c91"], "d": ["Perandori gjerman Otoni IV, me kapitulacionin e Neussit të 1201, pranoi autoritetin papal mbi krahinën që shtrihej nga Radicofani deri te gryka e Ceperanos (Ekzarkati i Ravenës, Pentapoli, Marka e Ankonës, peshkopata e Spoletos, pronat e Matildës, kontea e Brittenoros). Një pjesë e këtyre tokave për shekuj mbeti vetëm dëshirë e papatit; aneksimi faktik i vendeve si Ravena, Ankona, Bolonja, Ferrara daton në shekullin XVI.", "e76fd40c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:0":{"b": ["Filip Augusti pushton Normandinë: merr fund bashkimi me Anglinë që vazhdonte nga 1106; Maine, Touraine, Anzhu dhe Poitou i kalojnë Francës në 1204-1205", "ad5f7cb2"], "d": ["Pasi John Sans-Terre urdhëroi vrasjen e Arthurit, Filip Augusti në 1203-1204 pushtoi Normandinë (rrethimi i Château-Gaillardit shtator 1203-prill 1204, Rouen 24 qershor 1204). Pushtimi i Maine, Touraine, Anzhuit dhe Poitou ishte aq i lehtë në 1204 dhe 1205 sa 'pothuajse si një marshim'; vetëm kështjellat e Loches dhe Chinonit rezistuan edhe një vit.", "e587727d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:1":{"b": ["Touraine (Tours) i kalon kurorës franceze", "220394a0"], "d": ["Pushtimet e Filip Augustit në Loire të 1204-1205 ia lidhën mbretit të Francës Maine, Touraine, Anzhunë dhe Poitou; kështjellat e Loches dhe Chinonit rezistuan një vit.", "c3eaca78"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1214-01-01:0":{"b": ["Pfalci i Rinit i jepet nga Frederiku II Otonit të Vitelsbahut (Kontea e Pfalcit në dinastinë Vitelsbah)", "5f54fd76"], "d": ["Me vdekjen e kontit palatin të Rinit, Henrikut, në 1214, mbreti gjerman Frederiku II ia dha Pfalcin Otonit, djalit të vogël të dukës së Bavarisë Ludwig I (të fejuar me motrën e Henrikut, Agnesin). Që nga vendosja e Konradit në 1155 në kështjellën e Juttenbühelit pranë Heidelbergut, kjo rrethinë konsiderohej kryeqyteti i Pfalcit.", "066e8777"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1218-01-01:0":{"b": ["Simon de Montfort vdes duke rrethuar Tuluzën", "6da05355"], "d": ["Komandanti i Kryqëzatës Albigjeze, Simon de Montfort, hyri në Tuluzë në 1215, por vdiq në 1218 duke rrethuar qytetin. Komanda e kryqtarëve i kaloi të birit, Amaurit; Raymondi VII, i biri i Raymondit VI, në 1222 erdhi në krye të kontesë.", "47aa27de"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1229-01-01:0":{"b": ["Traktati i Parisit (Meaux-Paris): Raymondi VII ia lë kurorës franceze pjesën më të madhe të feudeve të tij", "ef1cb151"], "d": ["Me traktatin e Parisit të 1229, mbreti i Francës e zhveshi dinastinë e Tuluzës nga pjesa më e madhe e feudeve; kontea do t’i kalonte kurorës franceze në 1271 nëpërmjet bijës së Raymondit, Jeanne, dhe bashkëshortit të saj Alphonse (vëllait të Luigjit IX).", "7186cd3b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:0":{"b": ["Mbreti i Norvegjisë ia kalon Skocisë ishullin Man dhe Hebridet kundrejt 4000 markave", "e027acbe"], "d": ["Aleksandri III në 1261 dërgoi të dërguar në Norvegji për kalimin e ishujve; kur nuk pati rezultat, shpalli luftë; në 1263 flota norvegjeze u asgjësua në Largs. Mbreti i Manit, Magnusi, u detyrua të lëshonte të gjithë ishujt përveç Manit. Në 1266 mbreti i Norvegjisë ia kaloi Skocisë ishujt (përfshirë Manin) kundrejt 4000 markave; administrimi skocez në Man u vendos vetëm në 1275, me shpartallimin e banorëve të Manit në Ronaldsway.", "fdf0afa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:1":{"b": ["Mbreti i Norvegjisë ia kalon Skocisë Hebridet kundrejt 4000 markave: Iona (Hebride)", "215cac00"], "d": ["Me fitoren e Aleksandrit III ndaj flotës norvegjeze në Largs (1263), sundimi norvegjez mbi Hebridet u lëkund; në 1266 mbreti i Norvegjisë ia kaloi ishujt Skocisë kundrejt 4000 markave.", "81cc8cf0"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1268-10-29:0":{"b": ["Konradini ekzekutohet në Napoli: shuhet linja mashkullore e Hohenstaufenëve", "55645d01"], "d": ["Përfaqësuesi i fundit i dinastisë Hohenstaufen, Konradini, pasi u mund në Tagliacozzo (23 gusht 1268) nga duka i Anzhuit Karl, u gjykua në Napoli si tradhtar dhe u ekzekutua më 29 tetor bashkë me mikun e tij Frederikun e Badenit (dukën titullar të Austrisë). Linja mashkullore e Hohenstaufenëve u shua.", "d81af0d1"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1271-01-01:0":{"b": ["Alphonse de Poitiers dhe bashkëshortja e tij Jeanne vdesin: trashëgimia e kontesë së Tuluzës i kalon kurorës franceze", "eabc3640"], "d": ["Kur Raymondi VII vdiq në 1249, trashëgimia i mbeti të bijës Joan; Joan ishte e martuar me Alphonsin, vëllain e Luigjit IX. Me vdekjen e të dyve në 1271, trashëgimia e gjerë e kontëve të Tuluzës i kaloi kurorës franceze.", "ee58c39e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1276-11-21:0":{"b": ["Paqja e Vjenës: mbreti i Bohemisë Ottokar II heq dorë nga Austria, Stiria, Karintia dhe Karniola", "db5c2bc4"], "d": ["Pasi Rudolfi Habsburg u zgjodh mbret (1273), e vuri Ottokarin nën ndalimin perandorak dhe në qershor 1276 shpalli luftë; Rudolfi, që e shkëputi dukën e Bavarisë së Poshtme Henrik nga Ottokari, në nëntor 1276 e detyroi mbretin e Bohemisë të lëshonte katër provinca. Ottokari u rifeudalizua vetëm me Bohemi dhe Moravi, i biri Venceslau u fejua me të bijën e Rudolfit; Rudolfi hyri me triumf në Vjenë.", "d79ed14c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0569-09-04:0":{"b": ["Alboini hyri në Milano: Italia Veriore doli nga duart e Bizantit", "b6be0ed6"], "d": ["Alboini hyri në Milano më 4 shtator 569; peshkopi Honoratus iku në Gjenovë. Pavia ra pas një rrethimi të gjatë dhe lugina e Po-së kaloi në masë të madhe te langobardët; Bizanti mbajti vetëm disa qytete bregdetare dhe kështjella.", "c0d39443"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0629-01-01:0":{"b": ["Hazarët pushtuan Tiflisin", "d0847d32"], "d": ["Hazarët, ndërsa ishin vartës të gjokturqve perëndimorë, kaluan Grykën e Derbendit dhe bënë inkursione në Gjeorgji e Azerbajxhan; më 629 u pushtua Tiflisi dhe u nënshtruan disa grupe armene. Kryeqyteti është Belenxheri.", "5027db3b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0640-09-19:0":{"b": ["Hou Junji mori Gaochang-un; në tokat Tang krijoi Xizhou-n", "1a8726a7"], "d": ["Komandanti i përgjithshëm i rrugës Jiaohe Hou Junji pushtoi Gaochang-un (Turfanin) dhe Tang-u krijoi aty provincën Xizhou; mbreti i Gaochang-ut Qu Zhisheng në muajin e 12-të u nxor rob para Taizong-ut dhe ushtria u kthye në Kinë.", "76b4f5c5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0689-01-01:0":{"b": ["Malayu (Xhambi) iu bashkua Sriwijaya-s (mes viteve 689-692, dëshmia e Yijing-ut)", "da0ffb9b"], "d": ["Pelegrini kinez Yijing njofton se Malayu (rajoni i Xhambit), ku u ndal më 671, u përpi nga Shih-li-fo-shih (Sriwijaya) mes viteve 689 dhe 692 (Coedès).", "a25038f0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-01-01:0":{"b": ["U pushtua Tanxheri (Musa b. Nusajr)", "0b579ded"], "d": ["Tanxheri u pushtua më 89 (708); në pranverën e 711 guvernatori i Tanxherit Tarik b. Zijad doli në fushatën e Spanjës.", "a6fd7e17"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-11-20:0":{"b": ["Kutejbe b. Muslimi mori dorëzimin e Buharës", "38427fbf"], "d": ["Kutejbe, pas dy fushatave të dështuara, marshoi drejt Buharës; pas një rrethimi të ashpër mori dorëzimin e qytetit me kusht të ndihmës ushtarake, tatimit dhe vendosjes së një roje myslimane në kështjellë (90/708-709); kjo u bë pikë kthese për pushtimet e Transoksianës.", "6b255806"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0714-01-01:0":{"b": ["Mesleme b. Abdylmeliku pushtoi Grykën e Derbendit", "839bbcf7"], "d": ["Përleshjet e ashpra me hazarët u bënë në kohën e Velidit I; Meslemja më 708 pushtoi disa qytete e kështjella, më 714 pushtoi Grykën e Derbendit; më 717, kur u largua nga rajoni për rrethimin e Stambollit, hazarët kaluan në kundërveprim.", "358cd23d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0747-10-11:0":{"b": ["Harixhiti Ebu Hamza pushtoi Medinën", "36cae3e0"], "d": ["Udhëheqësi harixhit Ebu Hamza esh-Shari, pasi vuri nën kontroll Mekën, pushtoi Medinën në safer 130 (tetor 747).", "b0263b26"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0748-01-15:0":{"b": ["Nasr b. Sejjari ua la rebelëve abasidë Mervin, qendrën e Horasanit", "bc7bee2d"], "d": ["Guvernatori emevit i Horasanit Nasr u detyrua të linte Mervin më 9 xhumadelula 130 (15 janar 748) dhe Nishapurin në qershor; para se të mbaronte viti 749, ushtritë abaside morën nën kontroll gjithë Horasanin.", "dd216140"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0751-01-01:0":{"b": ["Langobardët morën Ravenën: mori fund Eksarkati Bizantin", "f5a42f8f"], "d": ["Mbreti langobard Aistulfi në vitet 750-751 pushtoi Ravenën; kështu ra qendra e vetme e madhe e Bizantit në veri të Apenineve, vetëm Venediku dhe një pjesë e Istrias mbetën të lidhura me perandorinë.", "6debbee9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0756-01-01:0":{"b": ["Pipini ia dhuroi papatit Eksarkatin e Ravenës", "345e02a7"], "d": ["Mbreti frank Pipin, pasi mundi Aistulfin, ia dha papatit Eksarkatin e Ravenës dhe Pentapolin; kështu Ravena iu mor langobardëve dhe iu shtua bërthamës së Shtetit Papnor. Bizanti nuk mundi ta kundërshtonte këtë dhurim.", "285518a8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0757-12-03:0":{"b": ["Ushtria Tang hyri në Luoyang (757): Kryeqyteti Lindor iu rimor rebelëve", "9d80b237"], "d": ["Komandanti rebel An Qingxu dhe përkrahësit e tij, të mundur në vendin Xindian në Shaanxi, ikën në Hebei; Princi Guangping hyri në Luoyang dhe rreshtoi ushtrinë në jug të Urës Tianjin; mbi 300 nëpunës të rremë, si Chen Xilie dhe Zhang Ji, me rroba të bardha prisnin dënimin.", "6194d763"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0761-08-07:0":{"b": ["Komandanti abasid Muhamed b. Esh'ath pushtoi Kajruanin", "40b80c87"], "d": ["Pas emërimit të Abdurrahman b. Rustemit guvernator këtu, qytetin e pushtoi Muhamed b. Esh'ath el-Huzai, që kalifi Mensur e kishte vënë guvernator të Ifrikijës dhe Magribit (xhumadelula 144).", "b5951323"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0764-01-01:0":{"b": ["Ushtria hazare pushtoi Tiflisin", "90eb05a6"], "d": ["Kur princesha hazare me të cilën u martua guvernatori abasid Jezid b. Usejd vdiq në lindje, hakani dërgoi ushtri nën komandën e As-Tarhanit; më 764 u pushtua Tiflisi.", "0f1e9c4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0774-01-01:0":{"b": ["Pavia dorëzohet; Dezideri zihet rob; Karli i Madh merr titullin 'mbret i langobardëve' (mbretëria langobarde merr fund)", "2de54abb"], "d": ["Karli i Madh, me thirrjen e papës Hadrian I, më 773 kaloi Alpet dhe hyri në Mbretërinë Lombarde; në qershor 774 Pavia u dorëzua, mbreti Dezideri u dërgua në manastir. Karli mori titujt 'mbret i langobardëve' dhe 'patric i romakëve'.", "4dbdb9e5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0775-01-01:0":{"b": ["Stela e Ligorit (Nakhon Si Thammarat): mbreti i Sriwijaya-s u vendos në Ligor në Gadishullin Malajz dhe ndërtoi tempuj budistë (775)", "62e97b39"], "d": ["Stela e Wat Sema Muang tregon se mbretëria sumatrane më 775 vuri këmbë në Ligor në Gadishullin Malajz dhe se mbreti i Sriwijaya-s (me gjasë Dharmasetu) ndërtoi një kompleks tempujsh budistë; teksti në faqen e dytë i referohet fisit Sailendra.", "85396e40"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0534-01-01:0":{"b": ["Bizanti rimori Afrikën vandale: Kartagjena ra sërish në duart e Romës Lindore", "ab2096c0"], "d": ["Me fushatën e Belizarit, gjeneralit të Justinianit I, Afrika e Veriut iu mor vandalëve dhe Kartagjena u bë sërish qytet bizantin. Qyteti më vonë do të bëhej qendra e Ekzarkatit të Afrikës.", "319ada36"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0568-01-01:0":{"b": ["Avarët hynë në Panoni: në pellgun e Danubit u vendos Kaganati Avar", "2471607b"], "d": ["Pas shembjes së shtetit gepid, avarët nën udhëheqjen e Bajanit u vendosën në Panoni; pellgu Danub–Tisë u bë qendra e Kaganatit Avar. Kaganati do të rrethonte Stambollin në 626 dhe bashkë me sllavët do të organizonte inkursione në Ballkan.", "7074a5d1"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0568-04-01:0":{"b": ["Langobardët e Alboinit u mblodhën për të marshuar mbi Itali (1 prill 568)", "677663c6"], "d": ["Langobardët e Panonisë, duke ua lënë avarëve atdheun e tyre, u mblodhën më 1 prill 568 nën komandën e Alboinit për të emigruar në Itali me familje e pasuri. Kapërcyen kufirin e Friulit, morën Cividalen dhe shkatërruan Akuileian.", "11d42338"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0582-01-01:0":{"b": ["Mauriku themeloi Ekzarkatin e Afrikës: administrim ushtarako-civil me qendër në Kartagjenë", "b4b43203"], "d": ["Mauriku i dha magister militum-it në Afrikë titullin ‘ekzark’ dhe epërsi mbi administratën civile; ai do të qeveriste nga Kartagjena si zëvendës i perandorit kundër sulmeve berbere.", "52939fe9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0582-01-01:1":{"b": ["Mauriku themeloi Ekzarkatin e Ravenës: tokat bizantine në Itali iu lidhën një guvernatori ushtarak", "6039bf5f"], "d": ["Perandori Mauriku ia dha administratën bizantine në Itali një ‘ekzarku’, të konsideruar zëvendës i perandorit kundër langobardëve; qendra u bë Ravena. Ky rregullim konsiderohet hapi i parë i sistemit të mëvonshëm të ‘themave’.", "543f687c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0610-10-05:0":{"b": ["Herakliu rrëzoi Fokën dhe hipi në fron", "8868d0c0"], "d": ["Herakliu, i biri i ekzarkut të Afrikës, erdhi me flotë në Stamboll; Foka u kap dhe u vra në mëngjesin e 5 tetorit 610 dhe Herakliu u bë perandor. Sundimi i tij mbahet mend për luftën me Iranin, pushtimet arabe dhe bazat e rendit të ‘themave’.", "758b6d64"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0626-07-29:0":{"b": ["Avarët dhe iranianët rrethuan Stambollin", "26f1fc15"], "d": ["Kagani avar dhe fiset e tij vasale ngritën kamp më 29 korrik 626 përpara mureve të Stambollit; edhe ushtria iraniane kishte zbritur në bregun aziatik. Qyteti, me rezistencë të ashpër dhe me suksesin e flotës, e përballoi rrethimin.", "f96ea122"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0674-01-01:0":{"b": ["Flota umajade rrethoi Stambollin nga toka dhe nga deti (674-678)", "6242af3a"], "d": ["Flota e Muavijes, pasi pushtoi gadishullin Kapëdag, filloi në 674 të rrethonte Stambollin nga toka dhe nga deti; sulmi vazhdoi deri në 678.", "9b10c5be"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0717-03-25:0":{"b": ["Leoni III hipi në fron: filloi dinastia izauriane", "a991b678"], "d": ["Pas periudhës anarkike 685-717, strategu me origjinë izauriane Leon u bë perandor më 25 mars 717. Menjëherë pas kësaj Stambolli u detyrua të përgatitej për rrethimin e madh arab.", "7b99e68e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0717-08-15:0":{"b": ["Meslema filloi rrethimin e Stambollit (15 gusht 717)", "ff3c52ac"], "d": ["Komandanti umajad Meslema kaloi ngushticën nga Abidosi dhe, me një ushtri prej rreth 180.000 vetësh dhe një flotë të madhe, rrethoi Stambollin më 15 gusht 717. Hani bullgar Tervel e ndihmoi Bizantin duke sulmuar forcat arabe në Traki.", "1b3e9a30"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0718-08-15:0":{"b": ["Rrethimi i dytë arab i Stambollit u hoq", "ed916ed1"], "d": ["Përballë zisë së bukës, të ftohtit, epidemisë dhe sulmeve bullgare, Meslema pas një viti të plotë, më 15 gusht 718, u tërhoq me urdhrin e kalifit Omer II. Ky sukses e ndaloi përparimin arab në Evropë.", "9a305e2f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0782-01-01:0":{"b": ["Irena bëri paqe me Harun er-Reshidin: Stambolli shpëtoi nga rreziku", "7fcd8ae6"], "d": ["Kur ushtria e komandantit abasid Harun er-Reshid përparoi deri në Kadëkoj, perandoresha Irenë nënshkroi traktat paqeje dhe kryeqyteti shpëtoi nga kërcënimi arab.", "7ffffb25"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0787-09-24:0":{"b": ["Në Iznik u mblodh Koncili VII Ekumenik: ikonoklazmi u dënua", "124c1212"], "d": ["Me thirrjen e perandoreshës Irenë, në kishën e Ajasofjes (Urtësisë së Shenjtë) në Iznik u mblodhën rreth 350 peshkopë dhe dënuan thyerjen e ikonave. Ky është koncili që Kisha ortodokse e konsideron të fundit ekumenik.", "8444f8b3"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0800-12-25:0":{"b": ["Karli u kurorëzua perandor nga papa në Romë; Bizanti nuk e njohu", "5ac5f7a9"], "d": ["Mbreti frank Karl, më 25 dhjetor 800, mori kurorën nga Papa Leoni III dhe u shpall ‘perandor i romakëve’. Kur Bizanti nuk ia njohu Karlit cilësinë perandorake, dualiteti midis shteteve të Lindjes dhe të Perëndimit doli hapur.", "dde987c7"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0813-06-22:0":{"b": ["Beteja e Versinikias: Mihail Rangabe u mund nga Krumi", "cc6f63ec"], "d": ["Mihaili I Rangabe më 22 qershor 813 u mund nga bullgarët në Versinikia pranë Edrenes; disfata duket se u përgatit nga qëndrimi i strategut të Anatolikonit, Leonit armen. Po atë vit Krumi erdhi përpara Stambollit.", "2d3099f5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0814-04-14:0":{"b": ["Hani Krum vdiq: përgatitja për rrethimin e Stambollit mbeti përgjysmë", "1dde895f"], "d": ["Krumi, duke përgatitur kundër Stambollit një ushtri të madhe të pajisur me shumë makina rrethimi, vdiq papritur më 14 prill 814 nga plasja e një ene gjaku. I biri, Omurtagu, lidhi me Bizantin paqe tridhjetëvjeçare.", "e1b684e8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0827-04-02:0":{"b": ["Arabët andaluzianë u vendosën në Kretë: lindi Emirati i Kretës", "2a7c0adc"], "d": ["Arabët andaluzianë të dëbuar pas kryengritjes së Rabazit në Kordovë, nën komandën e Ebu Hafs Omer b. Shuajbit, erdhën në Kretë, e pushtuan ishullin shkallë-shkallë dhe themeluan qytetin Rabazulhandak (Kandije). Pasardhësit e Ebu Hafsit sunduan ishullin deri në 961.", "11e895b0"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0860-06-18:0":{"b": ["Rusët u shfaqën për herë të parë përpara Stambollit", "43b4ec06"], "d": ["Rreth dyqind anije ruse hynë nga Deti i Zi në Bosfor dhe më 18 qershor 860 sulmuan Stambollin; perandori ndodhej me ushtrinë në kufirin arab. Një stuhi e shpërndau flotën ruse.", "6370f840"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0867-01-01:0":{"b": ["Flota aglabide rrethoi Dubrovnikun; qyteti shpëtoi me flotën bizantine", "9ed0c1d7"], "d": ["Një flotë e aglabidëve, zotër të Sicilisë, rrethoi Dubrovnikun në 867; qyteti shpëtoi nga rrethimi pesëmbëdhjetëmujor me ndihmën e flotës bizantine. Me këtë fitore Bizanti përforcoi epërsinë e vet në Adriatik.", "1cbf391c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0904-07-31:0":{"b": ["Flota e Kretës pushtoi dhe plaçkiti Selanikun", "d4ce556a"], "d": ["Flota arabe nën komandën e Leonit tripolitan, të konvertuar, pas një rrethimi treditor mori Selanikun më 31 korrik 904; u kthye pa u ndjekur, me mbi 30.000 robër dhe plaçkë. Kjo ngjarje tregoi dobësinë e flotës bizantine.", "f9cb1530"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0913-01-01:0":{"b": ["Cari bullgar Simeon erdhi përpara mureve të Stambollit", "4e338292"], "d": ["Simeoni, me qëllim të merrte kurorën bizantine, u mbështet te muret e Stambollit; qeveria, duke bërë lëshime të mëdha, u mor vesh me të dhe i dha titullin ‘Basileu i bullgarëve’.", "0cce5551"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0924-01-01:0":{"b": ["Simeoni e rrethoi sërish Stambollin", "452b0447"], "d": ["Simeoni në 924 e rrethoi sërish Stambollin; edhe këtë rrezik e kapërceu diplomacia e Romanit I.", "90de8672"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0926-01-01:0":{"b": ["Mbreti kroat Tomislav shpartalloi ushtrinë bullgare", "21d8e44f"], "d": ["Cari bullgar Simeon sulmoi Kroacinë, aleate të Bizantit, por ushtria e tij u mund nga mbreti kroat Tomislav dhe u shpërnda. Kjo fitore përforcoi autoritetin e mbretërisë kroate mbi qytetet e Dalmacisë.", "60abf25d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0927-05-27:0":{"b": ["Cari Simeon vdiq: mori fund periudha e luftërave të mëdha të Bullgarisë", "ff2c1a5e"], "d": ["Simeoni, i detyruar të kërkonte paqe me ndërmjetësimin e papës, vdiq papritur më 27 maj 927. Vdekja e tij ndryshoi ekuilibrin në Ballkan; Bullgaria për gjashtëdhjetë vjetët pasues nuk luajti rol aktiv në krahinë.", "3e140fec"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0927-09-08:0":{"b": ["Paqja bizantino-bullgare: Petri, i biri i Simeonit, u martua me një princeshë bizantine", "5f781f16"], "d": ["Me paqen e nënshkruar në vjeshtën e 927, pas vdekjes së Simeonit, Petri, i biri dhe pasardhësi i tij, u martua me Maria Lekapenën, mbesën e Romanit I; Bizanti e njohu atë si ‘perandor të bullgarëve’ dhe pranoi edhe Patriarkanën e pavarur Bullgare. Midis dy shteteve filloi një periudhë e gjatë paqeje.", "08bf5989"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0963-08-16:0":{"b": ["Niqifor Foka u bë perandor", "1e752d7a"], "d": ["Niqifori, i shpallur perandor nga ushtria e Kajserisë, hyri në kryeqytet më 14 gusht 963; pas përleshjeve në rrugë me rojat e pallatit, hipi në fron më 16 gusht. Sundimi i tij mbahet mend për pushtimet e Kretës, Kilikisë dhe Antiokisë.", "b34380fd"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0969-12-10:0":{"b": ["Niqifor Foka u vra; Joan Cimiski u bë perandor", "1232f3d1"], "d": ["Gjashtë javë pas pushtimit të Antiokisë, natën midis 10-11 dhjetorit 969, Niqifori II Foka u vra me atentat në pallat; e pasoi Joan Cimiski (969-976).", "485e7a85"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0971-04-23:0":{"b": ["Përpara Dorostolonit (Silistra) Cimiski mundi Svjatosllavin", "692f203b"], "d": ["Cimiski më 23 prill 971, në fushën dymbëdhjetë milje në jug të Dorostolonit, u përfshi në një betejë të madhe me ushtrinë ruse të Svjatosllavit; forcat ruse u shpartalluan dhe në qytet filloi një rrethim tremujor.", "9a082cf5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0986-08-17:0":{"b": ["Beteja e Portës së Trajanit: Vasili II pësoi disfatë të rëndë nga bullgarët", "9060af56"], "d": ["Marshimi i Vasilit II drejt Sardikës (Sofjes), i përgatitur keq dhe me komandantë në grindje, përfundoi me disfatë të rëndë më 17 gusht 986 në grykën e Portës së Trajanit; perandori shpëtoi me vështirësi.", "7c003379"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1001-01-01:0":{"b": ["Vasili II mori Sofjen", "3006324b"], "d": ["Gjatë fushatave vjetore të Vasilit II, Bizanti në 1001 pushtoi Sofjen që mbahej nga shteti bullgar; më pas ranë Vidini, Shkupi dhe kështjellat e tjera.", "52c0acb4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1003-01-01:0":{"b": ["Vidini iu dorëzua Bizantit pas rrethimit tetëmujor", "4394c5b7"], "d": ["Pas shembjes së shtetit bullgar, Vidini u rezistoi forcave bizantine deri në vitin 1003; u pushtua pas një rrethimi tetëmujor. Sundimi bizantin vazhdoi deri në 1185.", "7e2d95ee"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1014-07-29:0":{"b": ["Beteja e Kleidionit: Vasili II asgjësoi ushtrinë bullgare", "c8375830"], "d": ["Më 29 korrik 1014, Niqifor Ksifia, në luginën e Strumës, e anashkaloi nga pas pozicionin bullgar në grykën Kleidion (‘Çelës’) në malet e Bellasicës. Samuili me ndihmën e të birit iku në Prilep; rreth 15.000 ushtarëve bullgarë të zënë robër iu nxorën sytë.", "a7b90e39"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1014-10-06:0":{"b": ["Cari Samuil vdiq", "a71a0c57"], "d": ["Kur Samuili pa ushtarët e verbuar të ushtrisë së tij të shpartalluar në Kleidion, pësoi një krizë dhe dy ditë më vonë, më 6 tetor 1014, vdiq. Kryeqyteti i Perandorisë Perëndimore Bullgare ishte Ohri; rezistenca vazhdoi edhe katër vjet.", "b75e105a"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1018-01-01:0":{"b": ["Të gjitha tokat bullgare iu bashkuan Bizantit: Shteti i Parë Bullgar mori fund", "62e8f992"], "d": ["Pas vrasjes së Ivan Vladislavit përpara Durrësit (Dyrrachion), në fillim të 1018 Vasili II pranoi në dyert e Ohrit dorëzimin e familjes së carit të fundit dhe tokat bullgare deri në Danub u bënë tërësisht provincë bizantine. Kjo gjendje vazhdoi deri në 1186-1187.", "7686035c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1018-01-01:1":{"b": ["Ivan Vladislavi vdiq përpara Durrësit", "75e41587"], "d": ["Cari bullgar Ivan Vladislav (1015-1018), që hipi në fron pasi vrau Gavril Radomirin, u vra në një sulm të kotë ndaj Durrësit (Dyrrachium). Kur lajmi arriti në Stamboll, Vasili II nisi fushatën e fundit dhe në dyert e Ohrit familja e carit të fundit u dorëzua.", "38a7f246"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1040-01-01:0":{"b": ["Kryengritja e Pjetër Deljanit: shumë kështjella, përfshirë Shkupin, ranë në duart e kryengritësve", "7fef5f4f"], "d": ["Pakënaqësia që rritej me kthimin e tatimeve nga natyrë në para u shndërrua në kryengritje nën udhëheqjen e Pjetër Deljanit, nipit të Samuilit. Kryengritësit përparuan nga Beogradi drejt jugut dhe, me përkrahjen e bolarëve vendas, morën shumë kështjella, përfshirë Shkupin.", "86258b6e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1040-01-01:1":{"b": ["Stefan Vojisllavi nisi në Zetë lëvizjen për pavarësi", "ab16166f"], "d": ["Kryengritja e parë e Stefan Vojisllavit në 1036 ishte shtypur dhe ai ishte çuar në Stamboll; me rastin e kryengritjes së Pjetër Deljanit në Maqedoni, ai iku në 1040 dhe u vu në krye të një lëvizjeje të re çlirimtare në Zetë. Edhe pse Bizanti e shtypi Deljanin, nuk arriti ta rinovonte autoritetin mbi Zetën dhe krahina mbeti e pavarur për një kohë të gjatë.", "d1357c04"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1042-01-01:0":{"b": ["Gjergj Maniaku zbriti në Taranto si katepan i Italisë", "6281a936"], "d": ["Gjergj Maniaku, të cilin Mihaili V e nxori nga burgu dhe e bëri ‘magistros dhe katepan’, gjatë pushtetit të përbashkët të Zoes dhe Teodorës arriti në Taranto në fund të prillit 1042; fushatat e tij kundër kryengritësve normanë dhe apulianë mbetën përgjysmë me shkarkimin e tij në shtator 1042.", "926b3102"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1054-07-20:0":{"b": ["Skizma e Kishave Lindore dhe Perëndimore (Skizma e Madhe)", "22d54273"], "d": ["Me prishjen e lidhjeve me Romën nga patriarku Mihail Kerulari, mosmarrëveshja shekullore midis kishave të Romës dhe të Stambollit u shndërrua në ndarje përfundimtare.", "6de367fc"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1059-01-01:0":{"b": ["Sinodi i Melfit: papa miratoi pushtimet normane", "df9797bd"], "d": ["Nikolla II e ktheu për së prapthi politikën lindore dhe në Sinodin e Melfit bëri aleancë me normanët dhe miratoi pushtimet e tyre. Kjo marrëveshje bekoi ngritjen normane që kërcënonte praninë bizantine në Italinë e Jugut.", "456db916"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1071-01-01:0":{"b": ["Bari ra në duart e normanëve: Bizanti humbi Italinë", "75af6d4d"], "d": ["Pas një rrethimi trevjeçar, kështjella e fundit bizantine në Italinë e Jugut, Bari, iu dorëzua normanëve të Robert Guiskardit; kështu Bizanti humbi praninë e vet në Itali.", "03196667"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1071-08-26:0":{"b": ["Beteja e Manzikertit: Alp Arslani mundi ushtrinë bizantine, Romani IV ra rob", "9ed92850"], "d": ["Forcat turke të sulltanit Alp Arslan mundën në Manzikert më 26 gusht 1071 ushtrinë bizantine, të përbërë kryesisht nga mercenarë normanë, frankë, oguzë dhe peçenegë. Perandori Romani IV ra rob; filloi procesi i hapjes së Anadollit për turqit.", "d260a768"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1081-04-01:0":{"b": ["Aleks Komneni hyri në Stamboll: filloi dinastia e Komnenëve", "2c31c531"], "d": ["Njësitë e Aleksit, të cilin aristokratët ushtarakë e shpallën perandor, hynë në Stamboll më 1 prill 1081. Sundimi i Aleksit (1081-1118) kaloi me kërcënimet normane, peçenege dhe kryqtare.", "89144267"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1082-01-01:0":{"b": ["Konstantin Bodini u bë sundimtar i Zetës (Duklës); nënshtroi Rashkën dhe Bosnjën", "4eff1f06"], "d": ["Konstantin Bodini, i biri i Mihailit (rreth 1050-82, që kishte marrë titullin mbret nga Papa Gregori VII dhe kishte ngritur peshkopatën e Barit në kryepeshkopatë), hipi në fron rreth vitit 1082, pushtoi Rashkën dhe Bosnjën dhe vendosi atje kandidatët e vet. Kështu Zeta përfshinte pothuajse të gjitha tokat ku jetonin serbët; shteti u shpërbë shpejt për shkak të grindjeve dinastike.", "813bc53b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1091-01-01:0":{"b": ["Sllavonia iu lidh Hungarisë", "35eb29f1"], "d": ["Në fund të shekullit XI, grindjet e dinastisë kroate çuan në bashkimin me Hungarinë dhe krahina veriore e Sllavonisë iu lidh pjesërisht Hungarisë (1091).", "4e53ab25"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1118-08-16:0":{"b": ["Joani II Komnen mori kurorën", "255f3655"], "d": ["Mes vdekjes së të atit, Aleksit, dhe grindjeve në pallat, Joani më 16 gusht 1118 mori kurorën dhe u bë perandor. Sundimi i tij kaloi me fushata kundër peçenegëve, selxhukëve dhe në Kilikia.", "25043caf"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1122-01-01:0":{"b": ["Joani II mundi përfundimisht peçenegët pranë Zagorës së Vjetër", "3e585237"], "d": ["Peçenegët, që kishin përparuar deri në Traki, në 1122 pësuan një disfatë përfundimtare nga Joani II Komnen; me këtë fitore u sigurua kufiri perëndimor.", "52eb72c6"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1137-01-01:0":{"b": ["Joani II e vuri Kilikian nën sundimin bizantin: u mor Misisi (Mopsuestia)", "e09dfcbc"], "d": ["Joani II Komnen, me fushatën e viteve 1137-1138, nënshtroi fushën e Kilikisë dhe krahinat e Taurit, që ishin në duart e bejlikut armen të rubenidëve; edhe mbi Antiokinë u sigurua pjesërisht epërsia bizantine.", "266b1fc5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1159-01-01:0":{"b": ["Manuel Komneni hyri me ceremoni në Antioki", "6a943bb7"], "d": ["Manuel Komneni, me fushatën e Kilikisë dhe Sirisë 1158-1159, provoi sërish epërsinë bizantine mbi Principatën kryqtare të Antiokisë; hyrja e tij solemne në Antioki konsiderohet kulmi i pushtetit të tij.", "670785eb"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1171-03-12:0":{"b": ["Manuel Komneni urdhëroi arrestimin e të gjithë venedikasve në perandori", "0b1087c4"], "d": ["Manueli, i shqetësuar nga politika e Venedikut në Itali dhe Dalmaci, më 12 mars 1171 urdhëroi arrestimin e të gjithë venedikasve në perandori dhe konfiskimin e pasurisë së tyre. Venediku iu përgjigj duke dërguar flotë.", "01a7fe6d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1172-01-01:0":{"b": ["Manueli mundi Nemanjën dhe e çoi në Stamboll: serbët pranuan epërsinë bizantine", "85c3545e"], "d": ["Kur zhupani i madh i Rashkës (Rascia), Stefan Nemanja, u ngrit kundër Bizantit, Manueli në 1172 e mundi dhe e çoi me triumf në Stamboll; më pas u lirua dhe deri në vdekjen e Manuelit nuk shkaktoi probleme.", "dea0829e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1180-01-01:0":{"b": ["Stefan Nemanja e bëri të pavarur shtetin serb", "8df8e6f5"], "d": ["Duke përfituar nga trazirat që shkaktoi vdekja e Manuelit, Stefan Nemanja, duke e bërë Rashkën (Rascia) bërthamë, hodhi themelet e një shteti të madh serb që përfshinte edhe Zetën dhe Humin; e ruajti titullin ‘Zhupan i Madh’. Dinastia e tij njihet si ‘Nemanjiq’.", "5d62e581"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1180-09-24:0":{"b": ["Manuel Komneni vdiq", "ef8d68b9"], "d": ["Manueli I vdiq më 24 shtator 1180; deri në çastin e fundit kishte refuzuar ta rregullonte regjencën. Vitet 1180-1204 treguan se Perandoria Romake Lindore e humbi epërsinë që kishte pasur në periudhën e mesme bizantine.", "3909f514"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1182-01-01:0":{"b": ["Në Stamboll u masakruan latinët; Androniku Komnen erdhi në pushtet", "cdf8aa39"], "d": ["Me kryengritje popullore mori fund regjenca e vejushës së Manuelit, tregtarët latinë pësuan masakër dhe Androniku Komnen u ngrit në pushtet (1182-1185). Masakra e shtoi armiqësinë e Perëndimit ndaj Bizantit.", "e1babdc2"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-01-01:0":{"b": ["Normanët pushtuan dhe plaçkitën Selanikun", "0389d7b9"], "d": ["Normanët e ardhur nga Sicilia dhe Italia e Jugut, në gusht 1185, me flotë prej 200 anijesh dhe me ushtri sulmuan Selanikun nga toka dhe nga deti; qyteti u plaçkit tmerrësisht. Në kryeqytet ky lajm e përshpejtoi kryengritjen kundër Andronikut.", "f309d689"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-01-01:1":{"b": ["Kryengritja e Petrit dhe Asenit: themeli i Shtetit të Dytë Bullgar rreth Tërnovës", "fca2ce92"], "d": ["Vëllezërit bolarë Petër dhe Asen u ngritën rreth Tërnovës kundër tatimeve bizantine; edhe pse perandori i rimori tokat në 1186, vëllezërit, me ushtrinë që morën nga kumanët përtej Danubit, e rimorën Bullgarinë Veriore dhe në 1187 Bizanti u detyrua të bënte paqe.", "d0471819"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-09-12:0":{"b": ["Isaku II Engjëlli hipi në fron", "e5f6e2dd"], "d": ["Populli i Stambollit, që mësoi se Selaniku ishte marrë nga normanët, u ngrit kundër Andronikut Komnen dhe më 12 shtator 1185 vendosi në fron Isak Engjëllin. Filloi periudha e dinastisë së Engjëllorëve (1185-1204).", "d2f55a2e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1189-01-01:0":{"b": ["Frederik Barbarosa mori Dimotikën dhe masakroi banorët e saj", "d38b78a4"], "d": ["Gjatë Kryqëzatës së Tretë, perandori gjerman Barbarosa në 1189 mori Dimotikën dhe, përveç grave dhe fëmijëve, masakroi gjithë popullsinë (rreth 1500 vetë).", "e843c9c5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1190-01-01:0":{"b": ["Bullgarët mundën Isak Engjëllin", "ab4b84df"], "d": ["Ndërsa sundimtarët serbë dhe bullgarë shpresonin për përkrahje nga Barbarosa që po shkonte në Anadoll, Isak Engjëlli u mund nga bullgarët pranë Zagorës së Vjetër dhe shpëtoi me vështirësi. Bullgarët morën Sofjen dhe i çuan në Tërnovë reliket e Shën Ivan Rilskit.", "87219877"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1197-01-01:0":{"b": ["Kalojani hipi në fronin bullgar", "ad96cfe5"], "d": ["Pas vrasjes së Asenit (1196) dhe Petrit (1197), vëllai i tyre Kalojani (Joanica) në 1197 hipi në fronin bullgar; sundoi deri në 1207, e zgjeroi Bullgarinë dhe lidhi marrëdhënie me Papatin.", "5adc869f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-04-08:0":{"b": ["Bani Kulin dha garanci për besnikëri ndaj besimit katolik (Bilino Polje)", "30e1a588"], "d": ["Kur bani i Bosnjës Kulin (rreth 1180-1204) u akuzua se u jepte strehë patarenëve (bogomilëve), Papa Inocenti III i kërkoi mbretit hungarez t’i pastronte. Më 8 prill 1203, përpara të dërguarit të papës, Kulini dha garanci për besnikëri ndaj doktrinës katolike.", "1bdcf7f6"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-07-17:0":{"b": ["Kryqtarët hynë në Stamboll; Isaku II dhe Aleksi IV u vendosën në fron", "e315ae7a"], "d": ["Ushtritë e Kryqëzatës së Katërt më 17 korrik 1203 sulmuan Stambollin dhe e detyruan Aleksin III të ikte; Isaku II u vendos sërish në fron së bashku me të birin, Aleksin IV. Premtimet që Aleksi u kishte dhënë kryqtarëve më vonë nuk mundën të mbaheshin.", "6742de22"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-08-01:0":{"b": ["Aleksi IV Engjëlli mori kurorën si bashkëperandor", "89f1f57b"], "d": ["Aleksi, nën mbrojtjen e kryqtarëve, më 1 gusht 1203, së bashku me të atin, Isakun II, mori kurorën në Ajasofje si bashkëperandor. Nuk arriti t’i mbante premtimet e dhëna kryqtarëve.", "88f53483"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:0":{"b": ["Athina ra në duart e kryqtarëve: Othon de la Roche u bë zot i Athinës", "b38757d9"], "d": ["Në fushatën e markezit të Montferratit Boniface, burgonjasi Othon de la Roche në fund të tetorit ose në nëntor 1204 u bë zot i Athinës. Athina, si Dukat i Burgonjës (më vonë Dukati i Athinës), u bë pjesë e Greqisë latine; Partenoni u kthye në katedrale katolike.", "47e8140e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:1":{"b": ["Eubea (Euboea) kaloi te latinët", "3ac87cb5"], "d": ["Në fushatën e vjeshtës së 1204 të markezit të Montferratit Boniface, kalorësit latinë kaluan nga Beotia dhe Atika në ishullin Eube; në ndarjen e parë ishulli u nda midis venedikasve dhe kryqtarëve.", "56fb0f97"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:2":{"b": ["Galipoli hyri nën administrimin e latinëve", "e94882ae"], "d": ["Pas Kryqëzatës së Katërt, Galipoli në 1204 hyri nën administrimin e latinëve (venedikasve dhe Perandorisë Latine); në 1235 do të rimerret nga Joan Vataci.", "1561323c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:3":{"b": ["Mihal Engjëlli themeloi Despotatin e Epirit; Janina u bë qendër", "053487d5"], "d": ["Pas Kryqëzatës së Katërt, i afërmi i Isakut II dhe Aleksit III, Mihal Komnen Duka Engjëlli, themeloi një shtet të pavarur grek rreth Artës dhe Janinës; ai shtet është Despotati i Epirit, që do të jetonte deri në 1430. Mihali në fillim u mbajt në këmbë duke u mbështetur në diplomaci me Venedikun dhe Papatin.", "738fe372"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-02-08:0":{"b": ["Aleksi V Murcufli hipi në fron", "1a09c827"], "d": ["Me grusht shteti në pallat, Aleksi IV dhe i ati, Isaku II, u rrëzuan nga froni dhe dhëndri i Aleksit III, Murcufli, u bë perandor me titullin Aleksi V. Kryqtarët e konsideruan këtë sfidë dhe vendosën të pushtonin qytetin.", "a18f3330"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-04-13:0":{"b": ["Kryqëzata e Katërt pushtoi Stambollin", "684dcd71"], "d": ["Një javë pas ndalimit të sulmit të parë më 6 prill, kryqtarët dhe venedikasit më 13 prill 1204 hynë në Stamboll; qyteti u plaçkit tri ditë dhe gjysma e tij u shkatërrua nga zjarret. Perandoria bizantine u copëtua; në Iznik, Trapezundë dhe Epir dolën tri shtetëza bizantine.", "0faa7103"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-05-16:0":{"b": ["Konti i Flandrës Baldwini mori kurorën: u themelua Perandoria Latine", "39f062a5"], "d": ["Kryqtarët, tetë ditë pas zgjedhjes, më 16 maj 1204 e kurorëzuan perandor në Ajasofje kontin e Flandrës dhe të Hainautit, Baldwinin. Si patriark latin u emërua venedikasi Thomas Morosini dhe tokat e perandorisë u ndanë midis kryqtarëve dhe venedikasve.", "c1dcef9e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-11-08:0":{"b": ["Kalojani mori në Tërnovë kurorën mbretërore nga i dërguari i Papatit", "791d9635"], "d": ["Pas bisedimeve me Papën Inocenti III, Kalojani më 8 nëntor 1204 në Tërnovë u kurorëzua mbret (rex) nga i dërguari papal, kardinali Leo, me kurorën e sjellë nga Roma; të nesërmen kryepeshkopi i Tërnovës u shenjtërua si ‘primat’.", "2055a2ef"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1205-04-15:0":{"b": ["Beteja e Edrenes: Kalojani mundi perandorin latin Baldwin dhe e zuri rob", "d320c946"], "d": ["Gjatë kryengritjeve që shpërthyen me rënien e Stambollit në duart e latinëve, ushtria latine përpara Edrenes u shpartallua nga forcat e përbashkëta bizantino-bullgare; perandori Baldwin u zu rob dhe u çua në Tërnovë. Kjo disfatë ishte goditja e parë e madhe për Perandorinë Latine.", "1af0cda8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1205-11-19:0":{"b": ["Principata e Akesë (Moresë): William de Champlitte u përmend si ‘princi i Akesë’", "ef90dab0"], "d": ["Pushtimi i Moresë nga Geoffroi de Villehardouin dhe William de Champlitte (fitorja e Koundourës) në fillim të 1205 ndihmoi që pjesa më e madhe e Greqisë të binte në duart e kryqtarëve. Letra e Inocentit III e datës 19 nëntor 1205 e përmend Champlitte-in me titullin ‘princ’; kështu Principata e Akesë dokumentohet. Villehardouin mori titullin princ para fundit të vitit 1209.", "44588e3a"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1206-01-01:0":{"b": ["Kalojani sulmoi dy herë Dimotikën; muret u shembën", "5a4dd23b"], "d": ["Ushtria bullgare nën komandën e carit Kalojan në fillim të 1206 pushtoi Trakinë dhe sulmoi dy herë Dimotikën; në sulmin e dytë u shembën muret e qytetit të rrethuar. Mbrojtja u ishte besuar njësive greke të Teodor Branës.", "b00f7e1e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1206-08-20:0":{"b": ["Henri de Flandre mori kurorën si perandor latin", "ffd08538"], "d": ["Henriku, vëllai dhe regjenti i Baldwinit të zënë rob, u kurorëzua më 20 gusht 1206 në Ajasofje nga patriarku i ri latin Thomas Morosini. Henriku konsiderohet sundimtari më i aftë i Perandorisë Latine.", "350bed68"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1207-01-01:0":{"b": ["Marco Sanudo themeloi Dukatin e Naksosit (Dukatin e Arkipelagut)", "79faa9e1"], "d": ["Nipi i dozhit venedikas Dandolo, Marco Sanudo, me një grup aventurierësh zbriti në ishujt e Egjeut; shtatëmbëdhjetë ishuj u dorëzuan lehtë, vetëm Naksosi rezistoi dhe dukati i themeluar atje në 1207 zgjati më shumë se tre shekuj. Vetë Sanudo ia kushtoi besnikërinë jo Venedikut, por perandorit latin Henrik.", "02fd4630"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1207-10-08:0":{"b": ["Kalojani vdiq gjatë rrethimit të Selanikut", "d5427396"], "d": ["Cari bullgar Kalojan, duke bërë një sulm të ri ndaj Selanikut, vdiq më 8 tetor 1207 në një mënyrë ende të pashpjeguar. Me këtë vdekje mbylli periudha e ashpër e përleshjeve bullgaro-latine; froni i Tërnovës i kaloi Borilit.", "e6029330"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1210-06-20:0":{"b": ["Despoti i Epirit, Mihali, u lidh me dozhin e Venedikut", "669ad38d"], "d": ["Mihal Duka, përballë kërcënimit të perandorit latin Henrik, më 20 qershor 1210 nënshkroi një marrëveshje me dozhin Pietro Ziani dhe pranoi që Venediku t’i linte atij dhe trashëgimtarëve të tij Epirin, Akarnaninë dhe Etolinë; kështu e ruajti shtetin si vasal i Venedikut.", "5d11e9b1"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1216-06-11:0":{"b": ["Perandori latin Henrik vdiq në Selanik", "929c3cd5"], "d": ["Perandori latin Henrik vdiq papritur në Selanik më 11 qershor 1216, para se të mbushte dyzet vjeç; gjatë sundimit dhjetëvjeçar kishte forcuar Perandorinë Latine. Në korrik të atij viti vdiq edhe Papa Inocenti III; era e Kryqëzatës së Katërt u shua.", "6070f6e0"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1217-04-09:0":{"b": ["Pierre de Courtenay u kurorëzua në Romë perandor latin", "f36d8586"], "d": ["Pierre de Courtenay, i zgjedhur pas vdekjes së Henrikut, u kurorëzua nga Honori III më 9 prill 1217 në Romë në kishën e Shën Lorencit; papa e bëri ceremoninë jashtë mureve të qytetit, që të mos ngatërroheshin titujt e perandorive të Lindjes dhe të Perëndimit. Më pas ai u nis me anije venedikase për në Dyrrachium.", "98fb2727"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1221-03-25:0":{"b": ["Robert de Courtenay mori kurorën në Stamboll", "932b6236"], "d": ["Pas vdekjes së perandoreshës Yolanda në 1219, froni latin i kaloi djalit të saj të dytë Robert de Courtenay; Roberti më 25 mars 1221 u kurorëzua në Stamboll nga patriarku i ri latin Matthew.", "bf2f3298"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1225-01-01:0":{"b": ["Mbretëria latine e Selanikut mori fund: Selaniku i kaloi Epirit", "1ae95078"], "d": ["Mbretëria latine e Selanikut (1205-1225), e themeluar nga Boniface, u shemb kur despoti i Epirit, Teodor Engjëlli, mori Selanikun dhe mori titullin ‘Mbret dhe Perandor i romakëve’. Teodori themeloi Perandorinë e Selanikut dhe hyri në rivalitet me Iznikun për Stambollin.", "fe098325"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1228-01-01:0":{"b": ["Izmiti kaloi sërish nën sundimin bizantin (të Perandorisë së Iznikut)", "249950f8"], "d": ["Izmiti, që për një kohë të gjatë ndërroi duar midis Bizantit dhe latinëve, në 1228 kaloi nën sundimin e Perandorisë së Iznikut.", "a051dabd"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1229-01-01:0":{"b": ["Jean de Brienne u zgjodh perandor latin", "df313398"], "d": ["Me vdekjen e Robertit në More (1228) dhe meqë Baldwini II ishte fëmijë, mbreti i dikurshëm i Jerusalemit, Jean de Brienne, u zgjodh perandor vitin pasues. Jean e mbrojti me heroizëm Stambollin nga rrethimi bullgaro-nikean.", "2316312e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1230-01-01:0":{"b": ["Klokotnica: Ivan Aseni II mundi dhe zuri rob despotin e Epirit Teodor; Dimotika hyri nën sundimin bullgar", "514365f5"], "d": ["Në prill 1230, në Klokotnicë në rrugën Edrene-Filipopojë, cari bullgar Ivan Asen II mundi Teodor Engjëllin dhe e zuri rob; fuqia e Perandorisë së Selanikut u thye, Bullgaria u zgjerua në Traki dhe Maqedoni. Dimotika mbeti nën sundimin bullgar midis viteve 1230-1246.", "40e19d64"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1235-01-01:0":{"b": ["Patriarkana Bullgare u rithemelua", "2390176f"], "d": ["Patriarkana Bullgare u ringjall në 1235.", "d24362c4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1235-01-01:1":{"b": ["Galipoli ra në duart e perandorit të Iznikut Joani III", "3687c283"], "d": ["Galipoli, që që nga 1204 ishte në duart e latinëve, në 1235 u rimor nga Joani (perandori i Iznikut Joan III Vataci).", "623f8bea"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1236-01-01:0":{"b": ["Ushtritë greke dhe bullgare rrethuan Stambollin; e shpëtoi princi i Moresë Geoffroi II", "a07ee4a8"], "d": ["Në 1236 Ivan Aseni dhe Joan Vataci rrethuan sërish Stambollin; latinët ishin në frymën e fundit, por princi i Akesë Geoffroi II de Villehardouin nxitoi nga Moreja, mori pjesë në mbrojtjen e qytetit dhe rrethimi u hoq.", "2c66c5d9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1241-01-01:0":{"b": ["Ivan Aseni II vdiq: filloi prapakthimi i Bullgarisë", "1b1fa198"], "d": ["Cari bullgar Ivan Asen II vdiq në 1241; po atë vit tatarët sulmuan vendin dhe shteti bullgar, për shkak të grindjeve të bojarëve, u dobësua gjithnjë e më shumë.", "6b44149b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1246-01-01:0":{"b": ["Dimotika hyri nën administrimin bizantin (të Perandorisë së Iznikut)", "b0220eb0"], "d": ["Dimotika, që nga 1230 nën sundimin bullgar, në 1246 me fushatën e Joan Vatacit në Traki hyri nën administrimin bizantin.", "50e64103"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1246-01-01:1":{"b": ["Selaniku iu bashkua Perandorisë së Iznikut: Perandoria e Selanikut mori fund", "1f9b3c28"], "d": ["Joan Vataci në 1246 kaloi në Traki dhe pushtoi tokat që kishin zënë bullgarët dhe Selanikun; shteti i Selanikut i djemve të Teodor Engjëllit, Joanit dhe Dhimitrit, u shemb dhe Maqedonia hyri sërish nën sundimin bizantin/të Iznikut.", "26edc699"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1257-01-01:0":{"b": ["Rostislavi mori Vidinin dhe mori titullin car i bullgarëve", "19935b89"], "d": ["Njerku i mbretit hungarez, Rostislavi, në 1257 pushtoi Vidinin dhe mori titullin car i bullgarëve.", "9e6e94f4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1259-01-01:0":{"b": ["Beteja e Pelagonisë: Mihail Paleologu mundi aleancën Epir-Ake-Sicili", "eb3a201d"], "d": ["Mihaili VIII shpartalloi në fushën e Pelagonisë (Maqedonia Perëndimore) ushtrinë e bashkuar të mbretërve të Sicilisë, Epirit, Akesë dhe të serbëve; princi i Akesë William de Villehardouin u zu rob. Fitorja përgatiti fundin e Perandorisë Latine.", "18641aca"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1259-01-01:1":{"b": ["Mihaili VIII Paleolog u shpall perandor në Iznik", "5875ecef"], "d": ["Mihail Paleologu, regjent i të vogëlit Joan IV Laskaris në Perandorinë e Iznikut, më 1 janar 1259 u shpall bashkëperandor; kështu filloi dinastia e Paleologëve (1259-1453).", "3627dde8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-03-13:0":{"b": ["Traktati i Nimfaionit: Gjenova i premtoi Bizantit flotë për rimarrjen e Stambollit", "a094d9f0"], "d": ["Me traktatin e nënshkruar më 13 mars 1261 në Nimfaion midis Mihailit VIII dhe Gjenovës, tregtarët gjenovezë, në rast se rimerrej Stambolli, do të trashëgonin privilegjet e dikurshme të Venedikut.", "6b7cc95c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-07-25:0":{"b": ["Njësitë e Iznikut e rimorën Stambollin: Perandoria Latine mori fund", "2c768188"], "d": ["Njësitë e Iznikut më 25 korrik 1261 dogjën lagjen latine në bregun e Bririt të Artë, hapën nga brenda derën në mur dhe hynë në qytet. Sundimi latin pesëdhjetë e shtatë vjeçar mori fund, Bizanti u rithemelua.", "a7d71b53"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-08-15:0":{"b": ["Mihaili VIII mori kurorën në Ajasofje", "ff8bdbd5"], "d": ["Mihaili VIII hyri në qytet nga Porta e Artë përpara ikonës Hodegetria, marshoi me procesion dhe më 15 gusht 1261 mori kurorën në Ajasofje. Dinastia e Paleologëve qëndroi në pushtet deri në fund të perandorisë.", "8b4dbff9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1265-01-01:0":{"b": ["Mihaili VIII ia imponoi Epirit epërsinë bizantine (Janinë)", "725f54aa"], "d": ["Mihail Paleologu në 1264 mori nga bullgarët një pjesë të Maqedonisë dhe në 1265, duke pushtuar Janinën, ia imponoi Despotatit të Epirit sovranitetin e perandorisë.", "3f3bbd15"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1267-05-24:0":{"b": ["Villehardouin ia lidhi Principatën e Akesë Karlit të Anzhuinëve (Viterbo)", "3c8a26a9"], "d": ["Në Viterbo, më 24 maj 1267, me pëlqimin e perandorit latin Baldwin II, princi i Akesë William de Villehardouin ia kaloi principatën mbretit të Sicilisë Karl d’Anjou; William do të mbetej në principatë gjatë gjithë jetës, ndërsa e bija e tij Izabela do të martohej me të birin e Karlit, Filipin. Nëse nuk do të lindte trashëgimtar mashkull, principata do t’i kalonte dinastisë anzhuine të Napolit; kështu Moreja do të mbrohej nga humbja në favor të Paleologut.", "124a7b0f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1272-01-01:0":{"b": ["Karl d’Anjou pushtoi Durrësin dhe brigjet e Epirit", "64aaba29"], "d": ["Karl d’Anjou në 1267 pushtoi Korfuzin, në 1272 Durrësin dhe brigjet e Epirit; më pas u mor vesh me serbët dhe bullgarët. Ky kërcënim e detyroi Mihailin VIII të bashkonte kishën me Papatin.", "98ea3c00"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1272-01-01:1":{"b": ["Në Vidin mori fund administrimi i vasalit hungarez Jakov Svetosllav", "2cf90f4e"], "d": ["Në qershor 1266 ushtria hungareze mori Vidinin dhe shkatërroi krahinën; Jakov Svetosllavi me origjinë ruse qëndroi në administrim deri në 1272 si vasal i Hungarisë me titullin car i bullgarëve, më pas Vidini u dobësua dhe për një kohë të gjatë nuk u rimëkëmb.", "aeb24b65"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1274-07-06:0":{"b": ["Koncili II i Lionit: Bizanti pranoi epërsinë e papës", "7603205f"], "d": ["Me ultimatumin e Papës Gregori X, logoteti i madh Gjergj Akropoliti më 6 korrik 1274 në Lion pranoi në emër të perandorit epërsinë papale dhe besimin romak. Bashkimi u prish në 1281.", "879a4291"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1278-05-01:0":{"b": ["William de Villehardouin vdiq: Principata e Akesë u kaloi anzhuinëve", "e4eac0d2"], "d": ["Princi i Akesë William vdiq më 1 maj 1278 dhe principata, sipas rregullimit të Viterbos të 1267, u bë drejtpërdrejt e dinastisë anzhuine (deri në 1289). Karl d’Anjou u shtoi titujve të vet edhe atë të princit të Akesë.", "f789577b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-01-01:0":{"b": ["Përpara Beratit ushtria bizantine e theu rrethimin anzhuin", "745cab6e"], "d": ["Në 1281, përpara Beratit, ushtria bizantine korri fitore ndaj forcave anzhuine.", "ccb74513"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-07-03:0":{"b": ["Traktati i Orvietos: Anzhuini, Venediku dhe perandori latin Filip lidhën aleancë kundër Bizantit", "b9000a4a"], "d": ["Nën mbrojtjen e Papës Martin IV, Karl d’Anjou më 3 korrik 1281 në Orvieto lidhi traktat aleance kundër Bizantit me Filipin (i biri i Baldwinit II), që mbante titullin perandor latin, dhe me Republikën e Venedikut. Vespri Sicilian (1282) e ndërpreu këtë plan.", "fe224f07"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-11-18:0":{"b": ["Papa Martini IV shkishëroi Mihailin VIII: bashkimi i Lionit u prish", "c4569aff"], "d": ["Papa francez Martini IV, i zgjedhur më 22 shkurt 1281, nën ndikimin e Karlit d’Anjou, më 18 nëntor 1281 shkishëroi perandorin Mihail VIII Paleolog; kështu u prish bashkimi kishtar i Lionit.", "9a9b275d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1333-01-01:0":{"b": ["Republika e Dubrovnikut bleu nga mbreti serb Dushan Pelješacin bashkë me Stonin", "702474c3"], "d": ["Dubrovniku në 1333 bleu nga mbreti serb Stefan Dushan gadishullin Pelješac bashkë me Stonin; Stoni u bë qyteti i dytë i Republikës me kripore (solana).", "53d8f4b7"]},
"OLAYLAR_ORTACAG_BOZKIR:0567-01-01:0":{"b": ["Istemi Jabgu i dërgoi Bizantit delegacion: aleanca gëktyrko-bizantine", "cef38140"], "d": ["Istemi Jabgu, marrëdhëniet e të cilit me sasanidët u prishën, në 567 dërgoi një delegacion në Stamboll; ky është delegacioni i parë i dërguar nga Azia Qendrore në Stamboll. Edhe bizantinët dërguan të dërguar në qendrën e Istemi Jabgusë; aleanca gëktyrko-bizantine i vuri sasanidët në pozitë të vështirë.", "ba370a65"]},
"OLAYLAR_ORTACAG_BOZKIR:0895-03-02:0":{"b": ["Peçenegët morën nën sundim stepën midis Tenit (Donit) dhe Danubit (282/895)", "9d94d7c8"], "d": ["Peçenegët, duke bërë aleancë me mbretin bullgar Simeon, sulmuan hungarezët dhe i detyruan të emigronin në Panoni (282/895); vunë nën sundim krahinën stepore që shtrihej nga lumi Ten (Don) deri te lumi Danub. Në atlas, stepa Camboyluk, stepa e Donecit dhe Jediçkuli që nga kjo datë janë të shkruara nën Konfederatën Peçenege.", "d5ad9905"]},
"OLAYLAR_ORTACAG_BOZKIR:0922-05-12:0":{"b": ["Delegacioni abasid arriti në selinë e hanit bullgar të Vollgës; Almësh Hani pranoi islamin", "3416fffe"], "d": ["Hani bullgar Almësh, i biri i Shilkejit, duke i dërguar të dërguar kalifit Muktedir-Bil-lah, njoftoi se donte të bëhej mysliman. Delegacioni nën kryesinë e Sevsen er-Ressiut, në të cilin mori pjesë edhe Ibn Fadlani, më 12 muharrem 310 (12 maj 922) arriti në selinë e hanit përgjatë Vollgës; me pranimin zyrtar të islamit nga hani, Shteti Bullgar i Vollgës u bë shtet mysliman vasal i halifatit abasid.", "2bb4aede"]},
"OLAYLAR_ORTACAG_BOZKIR:0965-01-01:0":{"b": ["Bullgarët e Vollgës u çliruan nga epërsia hazare dhe u bënë plotësisht të pavarur", "6425140e"], "d": ["Kur Kaganati Hazar u dobësua si pasojë e inkursioneve peçenege dhe kumano-kipçake dhe e goditjes së rëndë nga rusët, bullgarët e Vollgës në 965 e fituan plotësisht pavarësinë.", "be12b363"]}
});
